begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L3-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالأيون المشترك؟', null, null, '["أيون يدخل في تركيب اثنين أو أكثر من المركبات الأيونية","أيون ينتج من تأين جزيئات الماء في المحلول","أيون يتكون عند ترسب مادة أيونية من محلولها","أيون يرفع ذائبية المركب الأيوني في الماء"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 106 — تأثير الأيون المشترك'),
('mcq', 2, 'ماذا يُسمّى انخفاض ذائبية مادة بسبب وجود أيون مشترك في محلولها؟', null, null, '["ثابت حاصل الذائبية","الحاصل الأيوني","تأثير الأيون المشترك","الاتزان غير المتجانس"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 106 — تأثير الأيون المشترك'),
('mcq', 3, 'يبين المنحنى الآتي ذائبية PbCrO₄ في محاليل K₂CrO₄ مختلفة التركيز عند 298 K. ما التفسير الصحيح لانخفاض المنحنى؟', null, '[{"src":"qimg/chem22/c3-l3b-common-ion.svg","alt":"منحنى بياني يبين ذائبية كرومات الرصاص PbCrO₄ عند 298 K في محاليل كرومات البوتاسيوم K₂CrO₄ مختلفة التركيز. المحور الأفقي تركيز K₂CrO₄ بوحدة mol/L من 0 إلى 0.100، والمحور الرأسي ذائبية PbCrO₄ بوحدة mol/L على مقياس لوغاريتمي من 10⁻¹³ إلى 10⁻⁶. يبدأ المنحنى عند تركيز صفر (ماء نقي) بذائبية 4.8 × 10⁻⁷ mol/L، ثم ينخفض انخفاضًا حادًّا جدًّا عند أول إضافة لـ K₂CrO₄، ثم يستمر في الانخفاض ببطء حتى يصل عند 0.100 M K₂CrO₄ إلى ذائبية 2.3 × 10⁻¹² mol/L."}]'::jsonb, '["أيون K⁺ يتحد مع أيون Pb²⁺ فيقل تركيز Pb²⁺ في المحلول","قيمة Ksp لـ PbCrO₄ تقل كلما زاد تركيز K₂CrO₄ في المحلول","K₂CrO₄ مركب ذائب فيزيد عدد الأيونات فتزداد ذائبية PbCrO₄","أيون CrO₄²⁻ المشترك يزيح اتزان ذوبان PbCrO₄ نحو اليسار فتقل ذائبيته"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 106 — الشكل 20-3 تأثير الأيون المشترك'),
('mcq', 4, 'اعتمادًا على المنحنى الآتي، أيّ الكميات الآتية تبقى ثابتة عند زيادة تركيز K₂CrO₄ من 0 إلى 0.100 M عند 298 K؟', null, '[{"src":"qimg/chem22/c3-l3b-common-ion.svg","alt":"منحنى بياني يبين ذائبية كرومات الرصاص PbCrO₄ عند 298 K في محاليل كرومات البوتاسيوم K₂CrO₄ مختلفة التركيز. المحور الأفقي تركيز K₂CrO₄ بوحدة mol/L من 0 إلى 0.100، والمحور الرأسي ذائبية PbCrO₄ بوحدة mol/L على مقياس لوغاريتمي من 10⁻¹³ إلى 10⁻⁶. يبدأ المنحنى عند تركيز صفر (ماء نقي) بذائبية 4.8 × 10⁻⁷ mol/L، ثم ينخفض انخفاضًا حادًّا جدًّا عند أول إضافة لـ K₂CrO₄، ثم يستمر في الانخفاض ببطء حتى يصل عند 0.100 M K₂CrO₄ إلى ذائبية 2.3 × 10⁻¹² mol/L."}]'::jsonb, '["قيمة Ksp لكرومات الرصاص PbCrO₄","ذائبية PbCrO₄ بوحدة mol/L","تركيز أيونات Pb²⁺ في المحلول المشبع","تركيز أيونات CrO₄²⁻ في المحلول المشبع"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 106 — الشكل 20-3 واختبار الرسم البياني'),
('mcq', 5, 'يبين الشكل الآتي محلولًا مشبعًا من PbCrO₄ قبل إضافة محلول Pb(NO₃)₂ إليه (أ) وبعدها (ب). ما تفسير زيادة كمية المادة الصلبة في (ب)؟', null, '[{"src":"qimg/chem22/c3-l3b-tubes-pbcro4.svg","alt":"أنبوبا اختبار متجاوران. الأنبوب (أ) على اليسار: محلول أصفر فاتح مشبع فوق طبقة رقيقة من مادة صلبة صفراء هي PbCrO₄ في قاع الأنبوب. سهم مكتوب فوقه «إضافة» يتجه من الأنبوب (أ) إلى الأنبوب (ب). الأنبوب (ب) على اليمين: المحلول نفسه بعد إضافة محلول نترات الرصاص Pb(NO₃)₂، وطبقة المادة الصلبة الصفراء في قاعه أسمك بوضوح (أكثر من ضعف سمكها في الأنبوب (أ))."}]'::jsonb, '["أيون NO₃⁻ المضاف يتحد مع CrO₄²⁻ فيتكون راسب أصفر جديد","أيون Pb²⁺ المضاف أيون مشترك، فيُزاح الاتزان نحو اليسار ويترسب مزيد من PbCrO₄","إضافة Pb(NO₃)₂ تزيد قيمة Ksp لـ PbCrO₄ فيترسب مزيد منه","إضافة المحلول تخفف المحلول فتقل ذائبية PbCrO₄ فيه"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 107 — الشكل 21-3 تطبيق مبدأ لوتشاتلييه'),
('mcq', 6, 'في أيّ المحاليل الآتية تكون ذائبية كلوريد الفضة AgCl أقل ما يمكن عند 298 K؟', null, null, '["الماء النقي","0.10 M NaNO₃","0.010 M NaCl","0.10 M NaCl"]'::jsonb, 'تطبيق', 'مقارنة ذائبية', 'صعب', 'الكتاب ص 106 — تأثير الأيون المشترك'),
('mcq', 7, 'تُضاف كبريتات الصوديوم Na₂SO₄ أحيانًا إلى خليط كبريتات الباريوم BaSO₄ الذي يشربه المريض قبل تصوير الجهاز الهضمي بالأشعة السينية. ما سبب ذلك؟', null, null, '["توفر أيون Na⁺ الذي يتحد مع Ba²⁺ فيزيله من المحلول","توفر أيون SO₄²⁻ المشترك فيُزاح الاتزان نحو اليسار ويقل تركيز Ba²⁺ السام","تزيد قيمة Ksp لـ BaSO₄ فيذوب كله ويظهر الجهاز الهضمي","تزيد ذائبية BaSO₄ فتمتصه أنسجة الجهاز الهضمي بسرعة"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'صعب', 'الكتاب ص 107 — الأيون المشترك والأشعة السينية'),
('essay', 1, 'فسّر لماذا تكون ذائبية كرومات الرصاص PbCrO₄ في محلول كرومات البوتاسيوم K₂CrO₄ تركيزه 0.1 M أقل من ذائبيتها في الماء النقي عند درجة الحرارة نفسها. استعن بمعادلة اتزان الذوبان وتعبير Ksp.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 106 — تأثير الأيون المشترك'),
('essay', 2, 'ثابت حاصل الذائبية لكرومات الرصاص PbCrO₄ عند 298 K يساوي 2.3 × 10⁻¹³.
(أ) احسب ذائبيتها المولارية في الماء النقي.
(ب) احسب ذائبيتها المولارية في محلول K₂CrO₄ تركيزه 0.100 M، علمًا بأن [CrO₄²⁻] الناتج من ذوبان PbCrO₄ صغير جدًّا يمكن إهماله مقارنة بـ 0.100 M.
(ج) كم مرة تقل الذائبية؟ وفسّر النتيجة.', null, null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 106 — تأثير الأيون المشترك في PbCrO₄'),
('essay', 3, 'ماذا يعني القول إن لمحلولين أيونًا مشتركًا؟ اذكر مثالًا على محلولين بينهما أيون مشترك، وحدد ذلك الأيون.', null, null, null, 'فهم', 'تفسير مصطلح ومثال', 'سهل', 'الكتاب ص 113 — س58')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L3-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الأيون المشترك أيون يدخل في تركيب اثنين أو أكثر من المركبات الأيونية، مثل CrO₄²⁻ المشترك بين PbCrO₄ وK₂CrO₄.', '["","أيونات تأين الماء ليست هي المقصودة؛ فالأيون المشترك جزء من تركيب مركبين أيونيين أو أكثر في المحلول.","الترسب يُنقص الأيونات في المحلول ولا يُكوّن أيونًا مشتركًا؛ والتعريف يتعلق بأيون يدخل في تركيب أكثر من مركب.","وجود الأيون المشترك يُخفض الذائبية ولا يرفعها، فضلًا عن أن هذا ليس تعريفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-07T17:19:00.522Z"}'::jsonb),
('mcq', 2, 2, 'يُسمّى انخفاض ذائبية المادة بسبب وجود أيون مشترك تأثير الأيون المشترك.', '["ثابت حاصل الذائبية Ksp قيمة ثابتة عند درجة حرارة معينة، وليس اسمًا لانخفاض الذائبية.","الحاصل الأيوني Qsp ناتج ضرب تراكيز الأيونات في أي لحظة، ويُقارن بـ Ksp لتوقع الترسب.","","الاتزان غير المتجانس اتزان تكون فيه المواد في أكثر من حالة فيزيائية، وليس اسمًا لانخفاض الذائبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.522Z"}'::jsonb),
('mcq', 3, 3, 'اتزان الذوبان PbCrO₄(s) ⇌ Pb²⁺(aq) + CrO₄²⁻(aq). محلول K₂CrO₄ يحتوي على CrO₄²⁻ قبل الإذابة، وهو أيون مشترك؛ ولأن [Pb²⁺][CrO₄²⁻] يجب أن يبقى مساويًا لـ Ksp، يُزاح الاتزان نحو اليسار، فتنخفض الذائبية من 4.8 × 10⁻⁷ mol/L في الماء النقي إلى 2.3 × 10⁻¹² mol/L في 0.100 M K₂CrO₄.', '["أيون K⁺ لا يتحد مع Pb²⁺ (كلاهما موجب)، ولا علاقة له باتزان الذوبان؛ الأيون المؤثر هو CrO₄²⁻ المشترك.","Ksp ثابت عند درجة حرارة معينة ولا يتغير بإضافة أيون مشترك؛ الذي يقل هو الذائبية.","المنحنى ينخفض أي إن الذائبية تقل لا تزيد؛ لأن أحد أيونات K₂CrO₄ مشترك مع PbCrO₄.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.522Z"}'::jsonb),
('mcq', 4, 0, 'حاصل ضرب [Pb²⁺][CrO₄²⁻] يبقى ثابتًا: في الماء النقي (4.8 × 10⁻⁷)(4.8 × 10⁻⁷) = 2.3 × 10⁻¹³، وفي 0.100 M K₂CrO₄ (2.3 × 10⁻¹²)(0.100) = 2.3 × 10⁻¹³؛ فقيمة Ksp لا تتغير لأنها تعتمد على درجة الحرارة فقط، بينما تتغير الذائبية وتراكيز الأيونات.', '["","الذائبية تتغير بوضوح في المنحنى: من 4.8 × 10⁻⁷ إلى 2.3 × 10⁻¹² mol/L.","[Pb²⁺] يساوي ذائبية PbCrO₄ في هذه المحاليل، فيقل بزيادة تركيز K₂CrO₄.","[CrO₄²⁻] يزداد بزيادة تركيز K₂CrO₄ المضاف (من 4.8 × 10⁻⁷ إلى 0.100 M تقريبًا)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb),
('mcq', 5, 1, 'في (أ) يوجد الاتزان PbCrO₄(s) ⇌ Pb²⁺(aq) + CrO₄²⁻(aq). إضافة Pb(NO₃)₂ تزيد [Pb²⁺] وهو أيون مشترك بين PbCrO₄ وPb(NO₃)₂، فيصبح ناتج الضرب أكبر من Ksp، ووفق مبدأ لوتشاتلييه يُزاح الاتزان نحو اليسار، فيترسب مزيد من PbCrO₄ الصلب.', '["NO₃⁻ وCrO₄²⁻ أيونان سالبان لا يتحدان؛ والراسب الإضافي هو PbCrO₄ نفسه.","","إضافة مادة لا تغير Ksp؛ فهو ثابت عند درجة حرارة معينة، والذي تغير هو موضع الاتزان.","التخفيف بالماء لا يُرسّب المادة؛ السبب هو زيادة [Pb²⁺] أي وجود أيون مشترك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb),
('mcq', 6, 3, 'AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq). أيون Cl⁻ مشترك بين AgCl وNaCl، وكلما زاد تركيزه أُزيح الاتزان أكثر نحو اليسار؛ فأقل ذائبية تكون في المحلول الأعلى تركيزًا من Cl⁻ وهو 0.10 M NaCl (الذائبية فيه نحو 1.8 × 10⁻⁹ mol/L مقابل 1.3 × 10⁻⁵ mol/L في الماء النقي).', '["لا يوجد في الماء النقي أيون مشترك، فتكون ذائبية AgCl فيه أكبر منها في محاليل كلوريد الصوديوم.","لا يحتوي NaNO₃ على Ag⁺ أو Cl⁻، فلا يوجد أيون مشترك يُخفض ذائبية AgCl.","يحتوي على Cl⁻ مشترك، لكن تركيزه أقل عشر مرات من 0.10 M NaCl، فانخفاض الذائبية فيه أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb),
('mcq', 7, 1, 'BaSO₄(s) ⇌ Ba²⁺(aq) + SO₄²⁻(aq). Na₂SO₄ مركب أيوني ذائب يوفر أيون SO₄²⁻ المشترك، فوفق مبدأ لوتشاتلييه يُزاح الاتزان نحو اليسار لإنتاج مزيد من BaSO₄ الصلب، ويقل عدد أيونات Ba²⁺ الضارة في المحلول.', '["Na⁺ وBa²⁺ أيونان موجبان لا يتحدان؛ والأيون المشترك هنا SO₄²⁻.","","Ksp لا يتغير بإضافة مادة، والمطلوب تقليل ذوبان BaSO₄ لا زيادته لأن Ba²⁺ سام.","وجود الأيون المشترك يُقلل الذائبية، وامتصاص أيونات الباريوم ضار وليس هدفًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb),
('essay', 1, null::int, null, null, 'معادلة الاتزان: PbCrO₄(s) ⇌ Pb²⁺(aq) + CrO₄²⁻(aq)، وتعبير ثابت حاصل الذائبية: Ksp = [Pb²⁺][CrO₄²⁻] = 2.3 × 10⁻¹³، وهو ثابت عند درجة الحرارة المعطاة.
محلول K₂CrO₄ يحتوي على أيونات CrO₄²⁻ قبل إذابة PbCrO₄، فـ CrO₄²⁻ أيون مشترك بين المركبين. ولأن ناتج ضرب [Pb²⁺][CrO₄²⁻] يجب أن يبقى مساويًا لـ Ksp، فإن زيادة [CrO₄²⁻] تجعل [Pb²⁺] الممكن أقل.
وبعبارة مبدأ لوتشاتلييه: الأيون المشترك جهد على الاتزان، فيُزاح نحو اليسار (نحو تكوين PbCrO₄ الصلب)، فتذوب كمية أقل؛ وهذا هو تأثير الأيون المشترك.', '["كتابة معادلة اتزان الذوبان","كتابة تعبير Ksp وأنه ثابت","تحديد CrO₄²⁻ أيونًا مشتركًا","زيادة [CrO₄²⁻] تُقلل [Pb²⁺] لبقاء الناتج = Ksp (إزاحة الاتزان نحو اليسار)"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الاتزان","marks":1},{"element":"تعبير Ksp وثباته","marks":1},{"element":"تحديد الأيون المشترك","marks":1},{"element":"تفسير انخفاض الذائبية بإزاحة الاتزان أو ثبات Ksp","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلة والتعبير صحيحان، والأيون المشترك محدد، والتفسير مكتمل"},{"level":"2–3 درجات","description":"تحديد الأيون المشترك مع تفسير ناقص أو خطأ في المعادلة أو التعبير"},{"level":"1 درجة","description":"ذكر أن الذائبية تقل دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Ksp يقل في محلول K₂CrO₄","عدّ K⁺ هو الأيون المؤثر","إدخال PbCrO₄(s) في تعبير Ksp"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Ksp = [Pb²⁺][CrO₄²⁻] = s × s = s²، إذن s = √(2.3 × 10⁻¹³) = 4.8 × 10⁻⁷ mol/L.
(ب) [CrO₄²⁻] ≈ 0.100 M، و[Pb²⁺] = s، إذن s × 0.100 = 2.3 × 10⁻¹³، ومنه s = 2.3 × 10⁻¹² mol/L.
(ج) 4.8 × 10⁻⁷ ÷ 2.3 × 10⁻¹² ≈ 2.1 × 10⁵ مرة. السبب أن CrO₄²⁻ أيون مشترك، يُزيح اتزان الذوبان نحو اليسار فتقل الذائبية بينما يبقى Ksp ثابتًا.', '["s = √Ksp في الماء النقي","s = 4.8 × 10⁻⁷ mol/L","s = Ksp ÷ 0.100 في محلول K₂CrO₄","s = 2.3 × 10⁻¹² mol/L","النسبة نحو 2.1 × 10⁵ مع التفسير بالأيون المشترك"]'::jsonb, '["Ksp = [Pb²⁺][CrO₄²⁻] = s²","s = √(2.3 × 10⁻¹³) = 4.8 × 10⁻⁷ mol/L","في 0.100 M K₂CrO₄: Ksp = s × 0.100","s = 2.3 × 10⁻¹³ ÷ 0.100 = 2.3 × 10⁻¹² mol/L","النسبة = 4.8 × 10⁻⁷ ÷ 2.3 × 10⁻¹² ≈ 2.1 × 10⁵"]'::jsonb, '[{"element":"حساب الذائبية في الماء النقي","marks":2},{"element":"حساب الذائبية في محلول K₂CrO₄","marks":2},{"element":"النسبة والتفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاثة صحيحة مع تفسير سليم"},{"level":"3–4 درجات","description":"حسابان صحيحان أو خطأ في النسبة أو التفسير"},{"level":"1–2 درجة","description":"كتابة تعبير Ksp أو حساب جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال s² في الجزء (ب) بدل s × 0.100","إضافة s إلى 0.100 دون إهمال","قلب النسبة في الجزء (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يعني أن هناك أيونًا يدخل في تركيب المركبين الأيونيين المذابين في المحلولين. مثال: محلول PbCrO₄ ومحلول K₂CrO₄، والأيون المشترك CrO₄²⁻. (ومن الأمثلة الأخرى: BaSO₄ وNa₂SO₄ والأيون المشترك SO₄²⁻، أو PbCrO₄ وPb(NO₃)₂ والأيون المشترك Pb²⁺).', '["الأيون المشترك يدخل في تركيب المركبين","مثال صحيح لمركبين","تحديد الأيون المشترك في المثال"]'::jsonb, '[]'::jsonb, '[{"element":"المعنى","marks":1},{"element":"مثال صحيح","marks":1},{"element":"تحديد الأيون المشترك","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"المعنى والمثال والأيون صحيحة"},{"level":"1–2 درجة","description":"المعنى صحيح دون مثال أو مثال دون تحديد صحيح للأيون"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مركبين لا يشتركان في أي أيون مثل NaCl وKNO₃","الخلط بين الأيون المشترك والأيون الناتج من تأين الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.523Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
