('mcq', 1, 1, 'Ag₃PO₄(s) ⇌ 3Ag⁺(aq) + PO₄³⁻(aq)، فـ Ksp = [Ag⁺]³[PO₄³⁻]؛ كل تركيز مرفوع لأس يساوي معامله، ولا تُكتب المادة الصلبة.', '["أُهمل المعامل 3؛ فكل وحدة Ag₃PO₄ تعطي ثلاثة أيونات Ag⁺، فيُرفع تركيزها للأس 3.","","المعامل يُكتب أسًّا للتركيز لا معاملًا داخل القوس.","المادة الصلبة النقية لا تُكتب في تعبير Ksp لأن تركيزها ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('mcq', 2, 3, 'Mg(OH)₂(s) ⇌ Mg²⁺(aq) + 2OH⁻(aq)، ويبين الشكل أيوني OH⁻ لكل أيون Mg²⁺، فـ Ksp = [Mg²⁺][OH⁻]² دون المادة الصلبة.', '["عدد أيونات OH⁻ في المحلول ضعف عدد Mg²⁺ (المعامل 2)، فيُرفع [OH⁻] للأس 2.","قُلبت الأسس؛ معامل Mg²⁺ هو 1 ومعامل OH⁻ هو 2.","Mg(OH)₂ الصلب لا يُكتب في التعبير لأن تركيزه ثابت عند درجة حرارة معينة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('mcq', 3, 0, 'عدد أيونات B⁻ ثلاثة أمثال A³⁺ (وتتعادل الشحنات: 3+ مع 3 × 1−)، فالصيغة AB₃ ومعادلة الذوبان AB₃(s) ⇌ A³⁺(aq) + 3B⁻(aq)، وتعبير Ksp = [A³⁺][B⁻]³.', '["","أُهملت نسبة الأيونات؛ فالمركب AB₃ يعطي ثلاثة أيونات B⁻ لكل أيون A³⁺.","قُلبت الأسس؛ الشحنة 3+ لا تعني أن معامل A³⁺ هو 3، بل إن معامل B⁻ هو 3 لموازنة الشحنة.","المادة الصلبة النقية لا تُكتب في تعبير Ksp."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('mcq', 4, 2, 'يتفكك Ca₃(PO₄)₂ إلى 3 أيونات Ca²⁺ و2 أيون PO₄³⁻ (الشحنة: 3 × 2+ = 6+ و2 × 3− = 6−)، ومنها Ksp = [Ca²⁺]³[PO₄³⁻]².', '["بُدّلت المعاملات بالشحنات؛ أيون الكالسيوم Ca²⁺ وأيون الفوسفات PO₄³⁻.","المعادلة غير موزونة لا في الذرات ولا في الشحنات؛ تنتج 3 أيونات Ca²⁺ و2 PO₄³⁻.","","الأيون المتعدد الذرات PO₄³⁻ يبقى وحدة واحدة عند الذوبان ولا يتفكك إلى ذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('mcq', 5, 2, 'تركيز المادة الصلبة النقية يعبر عن كثافتها بوحدة mol/L ويكون ثابتًا عند درجة حرارة محددة، لذلك تُحذف المواد الصلبة والسوائل النقية من تعابير ثوابت الاتزان غير المتجانس.', '["BaSO₄ يذوب بقدر قليل جدًّا ([Ba²⁺] = 1.0 × 10⁻⁵ M عند الاتزان)، ولولا ذلك ما وُجدت أيونات في التعبير.","يجب أن توجد مادة صلبة عند الاتزان مهما كانت كميتها، وكميتها لا تؤثر في Ksp؛ السبب ثبات تركيزها لا صغرها.","","المحلول المشبع في حالة اتزان مع المادة الصلبة، فلا بد أن يبقى منها شيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('mcq', 6, 1, 'الأسس هي المعاملات في معادلة الذوبان: Pb₃(AsO₄)₂(s) ⇌ 3Pb²⁺(aq) + 2AsO₄³⁻(aq)، والشحنة متعادلة (3 × 2+ = 6+، 2 × 3− = 6−)، فالمركب زرنيخات الرصاص II Pb₃(AsO₄)₂.', '["بُدّلت الأرقام؛ الأس 3 لـ Pb²⁺ يعني ثلاثة أيونات رصاص، والأس 2 لـ AsO₄³⁻ يعني مجموعتين.","","هذه الصيغة غير متعادلة الشحنة (2+ مع 3−) ولا تطابق الأسس 3 و2.","عدد مجموعات AsO₄³⁻ اثنتان حسب الأس 2، وإلا لم تتعادل الشحنة (6+ مع 3−)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('mcq', 7, 3, 'Ag₂CO₃(s) ⇌ 2Ag⁺(aq) + CO₃²⁻(aq)، فـ Ksp = [Ag⁺]²[CO₃²⁻]، وكل تعبير من الأخرى فيه أسس لا تطابق معاملات معادلة الذوبان.', '["يعطي PbI₂ أيوني I⁻ لكل Pb²⁺، فالصحيح [Pb²⁺][I⁻]².","قُلبت الأسس؛ الصحيح [Al³⁺][OH⁻]³.","قُلبت الأسس؛ الصحيح [Ca²⁺]³[PO₄³⁻]².",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.524Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Ag₂CrO₄(s) ⇌ 2Ag⁺(aq) + CrO₄²⁻(aq)، ويؤكد الشكل أن عدد أيونات Ag⁺ ضعف عدد أيونات CrO₄²⁻.
(ب) Ksp = [Ag⁺]²[CrO₄²⁻].
(ج) لأن تركيز المادة الصلبة النقية ثابت عند درجة حرارة معينة، فلا يُكتب في تعابير ثوابت الاتزان.', '["معادلة الذوبان بالمعاملين 2 و1 والحالات الفيزيائية","Ksp = [Ag⁺]²[CrO₄²⁻]","تركيز المادة الصلبة ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الذوبان","marks":1},{"element":"تعبير Ksp","marks":1},{"element":"تفسير حذف المادة الصلبة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"المعادلة والتعبير والتفسير صحيحة"},{"level":"1–2 درجة","description":"التعبير صحيح مع خطأ في المعادلة أو غياب التفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة [2Ag⁺] بدل [Ag⁺]²","كتابة الأس 2 على CrO₄²⁻","إدخال المادة الصلبة في المقام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.525Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) PbCrO₄(s) ⇌ Pb²⁺(aq) + CrO₄²⁻(aq)؛ Ksp = [Pb²⁺][CrO₄²⁻]
(ب) ScF₃(s) ⇌ Sc³⁺(aq) + 3F⁻(aq)؛ Ksp = [Sc³⁺][F⁻]³
(ج) Pb₃(AsO₄)₂(s) ⇌ 3Pb²⁺(aq) + 2AsO₄³⁻(aq)؛ Ksp = [Pb²⁺]³[AsO₄³⁻]²', '["معادلة PbCrO₄ وتعبيرها","معادلة ScF₃ وتعبيرها","معادلة Pb₃(AsO₄)₂ وتعبيرها"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة (أ)","marks":1},{"element":"تعبير (أ)","marks":1},{"element":"معادلة (ب)","marks":1},{"element":"تعبير (ب)","marks":1},{"element":"معادلة (ج)","marks":1},{"element":"تعبير (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات الثلاث والتعابير الثلاثة صحيحة"},{"level":"3–5 درجات","description":"أخطاء في معاملات أو أسس مركب أو اثنين"},{"level":"1–2 درجة","description":"مركب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة F₃⁻ بدل 3F⁻","تفكيك AsO₄³⁻ إلى ذرات","إدخال المادة الصلبة في التعبير","إهمال الحالات الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.525Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأخطاء: (1) كُتبت المعاملات 3 و2 داخل الأقواس معاملات، والصحيح أن تُرفع التراكيز لأسس تساوي المعاملات. (2) كُتبت المادة الصلبة Ca₃(PO₄)₂ في المقام، والمادة الصلبة النقية لا تُكتب لأن تركيزها ثابت.
المعادلة: Ca₃(PO₄)₂(s) ⇌ 3Ca²⁺(aq) + 2PO₄³⁻(aq)
التعبير الصحيح: Ksp = [Ca²⁺]³[PO₄³⁻]²', '["خطأ كتابة المعاملات داخل الأقواس بدل الأسس","خطأ كتابة المادة الصلبة في المقام","المعادلة الصحيحة","Ksp = [Ca²⁺]³[PO₄³⁻]²"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ المعاملات","marks":1},{"element":"تحديد خطأ المادة الصلبة","marks":1},{"element":"المعادلة الصحيحة","marks":1},{"element":"التعبير الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطآن محددان، والمعادلة والتعبير صحيحان"},{"level":"2–3 درجات","description":"خطأ واحد محدد مع تعبير صحيح، أو الخطآن دون تصحيح كامل"},{"level":"1 درجة","description":"التعبير الصحيح فقط دون تحديد الأخطاء"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح خطأ واحد فقط","قلب الأسس عند التصحيح","كتابة Ca³⁺ أو PO₄²⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.525Z"}'::jsonb)
