from (values
('mcq', 1, 2, 'CaCO₃(s) ⇌ Ca²⁺(aq) + CO₃²⁻(aq)؛ [Ca²⁺] = [CO₃²⁻] = s، فـ s² = 3.4 × 10⁻⁹ ومنه s = √(3.4 × 10⁻⁹) = 5.8 × 10⁻⁵ mol/L.', '["قُسمت قيمة Ksp على 2 بدل أخذ جذرها التربيعي.","أُخذ الجذر التكعيبي لـ Ksp، والعلاقة هنا Ksp = s² فيلزم الجذر التربيعي.","","عُدّت قيمة Ksp نفسها تركيزًا للأيون، وهي ناتج ضرب تركيزين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-07T17:19:00.525Z"}'::jsonb),
('mcq', 2, 0, 'Ksp = [Mg²⁺][OH⁻]² = x(2x)² = 4x³ = 5.6 × 10⁻¹²، ومنه x³ = 1.4 × 10⁻¹² وx = [Mg²⁺] = 1.1 × 10⁻⁴ mol/L، و[OH⁻] = 2x = 2.2 × 10⁻⁴ mol/L.', '["","هذه قيمة [Mg²⁺]؛ ولم تُضرب في 2 للحصول على [OH⁻].","أُخذ الجذر التربيعي لـ Ksp كأن المركب يعطي أيونين بنسبة 1:1.","أُخذ الجذر التكعيبي لـ Ksp مباشرة دون القسمة على 4 (أي كُتب x³ بدل 4x³)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.525Z"}'::jsonb),
('mcq', 3, 1, 'CaF₂(s) ⇌ Ca²⁺(aq) + 2F⁻(aq)؛ [Ca²⁺] = 2.1 × 10⁻⁴ mol/L و[F⁻] = 2 × 2.1 × 10⁻⁴ = 4.2 × 10⁻⁴ mol/L، فـ Ksp = (2.1 × 10⁻⁴)(4.2 × 10⁻⁴)² = 3.7 × 10⁻¹¹.', '["حُسب s³ فقط، أي عُدّ [F⁻] مساويًا لـ [Ca²⁺] بدل ضعفه.","","حُسب [F⁻]² على أنه 2s² بدل (2s)² = 4s².","عومل المركب كأنه يعطي أيونين بنسبة 1:1 فحُسب s²."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.525Z"}'::jsonb),
('mcq', 4, 3, 'الذائبية = 1.86 × 10⁻⁴ g لكل 0.100 L = 1.86 × 10⁻³ g/L؛ s = 1.86 × 10⁻³ ÷ 143.32 = 1.30 × 10⁻⁵ mol/L. AgCl(s) ⇌ Ag⁺ + Cl⁻، فـ Ksp = s² = (1.30 × 10⁻⁵)² = 1.7 × 10⁻¹⁰.', '["لم يُحوَّل 100 mL إلى 1 L؛ فقُسمت الكتلة على الكتلة المولية مباشرة فنتجت ذائبية أصغر عشر مرات.","لم تُحوَّل الكتلة إلى مولات؛ فرُبّعت الذائبية بوحدة g/L.","هذه الذائبية المولارية s، ولم تُربَّع للحصول على Ksp = s².",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.526Z"}'::jsonb),
('mcq', 5, 1, 'Ag₂CrO₄(s) ⇌ 2Ag⁺(aq) + CrO₄²⁻(aq)؛ Ksp = (2s)²(s) = 4s³ = 1.1 × 10⁻¹²، ومنه s = 6.5 × 10⁻⁵ mol/L، و[Ag⁺] = 2s = 1.3 × 10⁻⁴ mol/L.', '["هذه الذائبية المولارية s وتساوي [CrO₄²⁻]، ولم تُضرب في 2 للحصول على [Ag⁺].","","أُخذ الجذر التربيعي لـ Ksp كأن النسبة 1:1.","كُتب التعبير 2s³ بدل (2s)²s = 4s³؛ أي لم يُربَّع المعامل 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-07T17:19:00.526Z"}'::jsonb),
('mcq', 6, 2, 'AB₂(s) ⇌ A²⁺(aq) + 2B⁻(aq)؛ [A²⁺] = s و[B⁻] = 2s، فـ Ksp = (s)(2s)² = 4s³.', '["هذه العلاقة لمركب يعطي أيونين بنسبة 1:1 مثل AB.","لم يُربَّع المعامل 2؛ فـ [B⁻] = 2s و[B⁻]² = 4s².","","أُهمل الأس على تركيز B وضُرب s في 2s فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.526Z"}'::jsonb),
('mcq', 7, 0, 'للمركبات 1:1: s = √Ksp، فـ AgCl: 1.3 × 10⁻⁵، وBaSO₄: 1.0 × 10⁻⁵، وAgBr: 7.3 × 10⁻⁷ mol/L. أما Ag₂CrO₄ فـ Ksp = 4s³ ومنه s = ∛(1.1 × 10⁻¹² ÷ 4) = 6.5 × 10⁻⁵ mol/L، وهي الأكبر رغم أن Ksp له ليس الأكبر.', '["","Ksp له أكبر قيمة في الجدول، لكن ذائبيته √(1.8 × 10⁻¹⁰) = 1.3 × 10⁻⁵ mol/L فقط؛ ولا تصح مقارنة Ksp مباشرة لمركبات تختلف نسب أيوناتها.","ذائبيته √(1.1 × 10⁻¹⁰) = 1.0 × 10⁻⁵ mol/L، وهي أقل من ذائبية Ag₂CrO₄.","ذائبيته √(5.4 × 10⁻¹³) = 7.3 × 10⁻⁷ mol/L، وهي الأقل بين الأربعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.526Z"}'::jsonb),
('essay', 1, null::int, null, null, 'PbI₂(s) ⇌ Pb²⁺(aq) + 2I⁻(aq)؛ Ksp = [Pb²⁺][I⁻]².
نفرض [Pb²⁺] = x، فيكون [I⁻] = 2x، وKsp = x(2x)² = 4x³ = 9.8 × 10⁻⁹.
x³ = 2.45 × 10⁻⁹، ومنه x = 1.3 × 10⁻³ mol/L.
الذائبية المولارية = [Pb²⁺] = 1.3 × 10⁻³ mol/L، و[I⁻] = 2x = 2.7 × 10⁻³ mol/L.', '["المعادلة وتعبير Ksp","Ksp = 4x³","x = 1.3 × 10⁻³ mol/L = الذائبية = [Pb²⁺]","[I⁻] = 2.7 × 10⁻³ mol/L"]'::jsonb, '["PbI₂(s) ⇌ Pb²⁺(aq) + 2I⁻(aq)","Ksp = [Pb²⁺][I⁻]² = x(2x)² = 4x³","x³ = 9.8 × 10⁻⁹ ÷ 4 = 2.45 × 10⁻⁹","x = ∛(2.45 × 10⁻⁹) = 1.3 × 10⁻³ mol/L","[I⁻] = 2 × 1.35 × 10⁻³ = 2.7 × 10⁻³ mol/L"]'::jsonb, '[{"element":"المعادلة وتعبير Ksp","marks":1},{"element":"الربط 4x³","marks":1},{"element":"حساب x","marks":2},{"element":"حساب [I⁻]","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الخطوات والقيم الثلاث صحيحة"},{"level":"3–4 درجات","description":"إعداد صحيح مع خطأ حسابي أو نسيان مضاعفة [I⁻]"},{"level":"1–2 درجة","description":"كتابة المعادلة أو التعبير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Ksp = x² ","كتابة x(2x)² = 2x³","إعطاء [I⁻] مساويًا لـ [Pb²⁺]"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.526Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الذائبية المولارية s = 1.1 g/L ÷ 175.33 g/mol = 6.3 × 10⁻³ mol/L.
BaF₂(s) ⇌ Ba²⁺(aq) + 2F⁻(aq)، فـ [Ba²⁺] = 6.3 × 10⁻³ mol/L و[F⁻] = 2s = 1.3 × 10⁻² mol/L.
Ksp = [Ba²⁺][F⁻]² = (6.27 × 10⁻³)(1.25 × 10⁻²)² = 4s³ = 9.9 × 10⁻⁷.', '["تحويل g/L إلى mol/L","s = 6.3 × 10⁻³ mol/L","[F⁻] = 2s","Ksp = 4s³ = 9.9 × 10⁻⁷"]'::jsonb, '["s = 1.1 ÷ 175.33 = 6.27 × 10⁻³ mol/L","[Ba²⁺] = 6.3 × 10⁻³ mol/L، [F⁻] = 2 × 6.27 × 10⁻³ = 1.25 × 10⁻² mol/L","Ksp = [Ba²⁺][F⁻]² = (6.27 × 10⁻³)(1.25 × 10⁻²)²","Ksp = 9.9 × 10⁻⁷"]'::jsonb, '[{"element":"التحويل إلى mol/L","marks":1},{"element":"تركيزا الأيونين","marks":2},{"element":"تعبير Ksp والتعويض","marks":1},{"element":"قيمة Ksp","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التحويل والتراكيز وقيمة Ksp صحيحة"},{"level":"3–4 درجات","description":"خطأ في مضاعفة [F⁻] أو في تربيعه"},{"level":"1–2 درجة","description":"التحويل إلى mol/L فقط أو كتابة التعبير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب Ksp من g/L دون تحويل إلى mol/L","كتابة Ksp = s(2s) = 7.9 × 10⁻⁵","كتابة Ksp = s³ = 2.5 × 10⁻⁷"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.526Z"}'::jsonb),
('essay', 3, null::int, null, null, 'ZnCO₃(s) ⇌ Zn²⁺(aq) + CO₃²⁻(aq)؛ Ksp = [Zn²⁺][CO₃²⁻] = s × s = s².
s = √(1.5 × 10⁻¹⁰) = 1.2 × 10⁻⁵ mol/L، إذن [Zn²⁺] = 1.2 × 10⁻⁵ mol/L.', '["تعبير Ksp = s²","[Zn²⁺] = 1.2 × 10⁻⁵ mol/L"]'::jsonb, '["Ksp = [Zn²⁺][CO₃²⁻] = s²","s = √(1.5 × 10⁻¹⁰) = 1.2 × 10⁻⁵ mol/L"]'::jsonb, '[{"element":"المعادلة وتعبير Ksp","marks":1},{"element":"الحساب والإجابة بوحدتها","marks":2}]'::jsonb, '[{"level":"3 درجات","description":"التعبير والحساب صحيحان مع الوحدة"},{"level":"1–2 درجة","description":"التعبير صحيح مع خطأ في الجذر أو الوحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة Ksp على 2","أخذ الجذر التكعيبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-07T17:19:00.527Z"}'::jsonb)
