from (values
('mcq', 1, 'ما المادة التي تُشكّل نحو 98% من مينا الأسنان؟', null, null, '["الفلوروأباتيت Ca₅(PO₄)₃F","فلوريد الصوديوم NaF","فوسفات الكالسيوم Ca₃(PO₄)₂","هيدروكسي الأباتيت Ca₅(PO₄)₃OH"]'::jsonb, 'تذكر', 'تذكر معلومة', 'سهل', 'الكتاب ص 108 — مختبر حل المشكلات: الفلوريد وتسوس الأسنان'),
('mcq', 2, 'يذوب هيدروكسي الأباتيت في مينا الأسنان وفق الاتزان: Ca₅(PO₄)₃OH(s) ⇌ 5Ca²⁺(aq) + 3PO₄³⁻(aq) + OH⁻(aq). ما الذي يُسرّع ذوبانه في الفم؟', null, null, '["وجود أيونات الفلوريد F⁻ من معجون الأسنان في اللعاب","وجود أحماض في اللعاب تتفاعل مع أيونات OH⁻","زيادة تركيز أيونات Ca²⁺ الذائبة في اللعاب","تكوّن طبقة من الفلوروأباتيت على سطح المينا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 108 — مختبر حل المشكلات: الفلوريد وتسوس الأسنان'),
('mcq', 3, 'يبين المخطط الآتي قيمتي Ksp لمكوّنين قد يوجدان في مينا الأسنان. لماذا تقل قابلية الأسنان للتسوس عندما يتكون الفلوروأباتيت في المينا؟', null, '[{"src":"qimg/chem22/c3-l3b-apatite-ksp.svg","alt":"تدريج رأسي لوغاريتمي لقيم ثابت حاصل الذائبية Ksp من 10⁻³⁰ في الأعلى إلى 10⁻⁶⁵ في الأسفل. عليه نقطتان: الأولى (زرقاء) قرب الأعلى لهيدروكسي الأباتيت Ca₅(PO₄)₃OH وقيمتها Ksp = 6.8 × 10⁻³⁷، والثانية (خضراء) قرب الأسفل للفلوروأباتيت Ca₅(PO₄)₃F وقيمتها Ksp = 1 × 10⁻⁶⁰."}]'::jsonb, '["لأن الفلوروأباتيت أكبر ذائبية، فيذوب ويعوّض المينا المفقودة","لأن Ksp الأكبر للفلوروأباتيت يعني أنه يترسب على السن بسرعة","لأن الفلوروأباتيت أقل ذائبية بكثير من هيدروكسي الأباتيت، فيقاوم الذوبان","لأن أيون الفلوريد يزيد قيمة Ksp لهيدروكسي الأباتيت"]'::jsonb, 'فهم', 'تفسير اعتمادًا على بيانات', 'متوسط', 'الكتاب ص 108 — مختبر حل المشكلات: الفلوريد وتسوس الأسنان'),
('mcq', 4, 'في تفاعل الإحلال المزدوج الذي يحدث بين هيدروكسي الأباتيت ومحلول فلوريد الصوديوم، أيّ أيون يحل محل أيّ أيون؟', null, null, '["يحل أيون F⁻ محل أيون OH⁻","يحل أيون F⁻ محل أيون PO₄³⁻","يحل أيون Na⁺ محل أيون Ca²⁺","يحل أيون OH⁻ محل أيون F⁻"]'::jsonb, 'فهم', 'تفسير تفاعل', 'سهل', 'الكتاب ص 108 — مختبر حل المشكلات: الفلوريد وتسوس الأسنان'),
('mcq', 5, 'ما تعبير ثابت حاصل الذائبية لهيدروكسي الأباتيت Ca₅(PO₄)₃OH؟', null, null, '["Ksp = [Ca²⁺]⁵[PO₄³⁻]³","Ksp = [Ca²⁺]⁵[PO₄³⁻]³[OH⁻]","Ksp = [Ca²⁺][PO₄³⁻][OH⁻]","Ksp = [Ca²⁺]⁵[PO₄³⁻]³[OH⁻] / [Ca₅(PO₄)₃OH]"]'::jsonb, 'تطبيق', 'كتابة تعبير Ksp', 'صعب', 'الكتاب ص 108 — التفكير الناقد 1'),
('mcq', 6, 'الذائبية المولارية لهيدروكسي الأباتيت في الماء نحو 2.7 × 10⁻⁵ mol/L، وللفلوروأباتيت نحو 6.1 × 10⁻⁸ mol/L. ما الاستنتاج الصحيح؟', null, null, '["ذائبية هيدروكسي الأباتيت أكبر بنحو 440 مرة، فالمينا المحتوية على الفلوريد أشد مقاومة للذوبان","ذائبية الفلوروأباتيت أكبر بنحو 440 مرة، فهو يذوب ويعوّض المينا المفقودة","ذائبية هيدروكسي الأباتيت أكبر بنحو 6.8 × 10²³ مرة، وهي نسبة قيمتي Ksp","الذائبيتان متقاربتان لأن للمركبين الصيغة العامة نفسها Ca₅(PO₄)₃X"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 108 — التفكير الناقد 3'),
('mcq', 7, 'أيّ زوج من المركبات الآتية تحتوي عليه أغلب أنواع معجون الأسنان لوقاية الأسنان من التسوس؟', null, null, '["فلوريد الكالسيوم وفلوريد الماغنسيوم","كلوريد الصوديوم وكلوريد القصدير II","فلوريد الصوديوم وفلوريد القصدير II","هيدروكسي الأباتيت والفلوروأباتيت"]'::jsonb, 'تذكر', 'تذكر معلومة', 'سهل', 'الكتاب ص 108 — مختبر حل المشكلات: الفلوريد وتسوس الأسنان'),
('essay', 1, 'فسّر كيف تمنع أيونات الفلوريد تسوس الأسنان، مستعينًا بمفهوم الذائبية وبمعادلة التفاعل الذي يحدث في المينا.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 108 — مختبر حل المشكلات: الفلوريد وتسوس الأسنان'),
('essay', 2, '(أ) اكتب معادلة ذوبان هيدروكسي الأباتيت Ca₅(PO₄)₃OH وتعبير ثابت حاصل ذائبيته.
