insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C3-L3-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي خلط محلولين. ما تركيز أيونات Pb²⁺ في الخليط مباشرة بعد الخلط وقبل حدوث أي تفاعل؟', null, '[{"src":"qimg/chem22/c3-l3b-mix-pbcl2.svg","alt":"رسم لخلط محلولين: كأس فيها 50.0 mL من محلول Pb(NO₃)₂ تركيزه 0.040 M، وعلامة +، وكأس فيها 50.0 mL من محلول NaCl تركيزه 0.020 M، ثم سهم يشير إلى كأس ثالثة كُتب تحتها «الخليط» وحجمه 100.0 mL."}]'::jsonb, '["0.040 M","0.020 M","0.010 M","0.060 M"]'::jsonb, 'تطبيق', 'حساب تركيز أيون بعد الخلط', 'سهل', 'الكتاب ص 104 — حساب تراكيز الأيونات (الجدول 3-4)'),
('mcq', 2, 'يبين الشكل الآتي خلط محلولين. إذا كان Ksp لـ PbCl₂ يساوي 1.7 × 10⁻⁵، فما قيمة الحاصل الأيوني Qsp في الخليط، وهل يتكون راسب من PbCl₂؟', null, '[{"src":"qimg/chem22/c3-l3b-mix-pbcl2.svg","alt":"رسم لخلط محلولين: كأس فيها 50.0 mL من محلول Pb(NO₃)₂ تركيزه 0.040 M، وعلامة +، وكأس فيها 50.0 mL من محلول NaCl تركيزه 0.020 M، ثم سهم يشير إلى كأس ثالثة كُتب تحتها «الخليط» وحجمه 100.0 mL."}]'::jsonb, '["Qsp = 2.0 × 10⁻⁶، ولا يتكون راسب","Qsp = 2.0 × 10⁻⁴، ويتكون راسب","Qsp = 1.6 × 10⁻⁵، ولا يتكون راسب","Qsp = 2.0 × 10⁻⁶، ويتكون راسب"]'::jsonb, 'تطبيق', 'حساب Qsp ومقارنته بـ Ksp', 'متوسط', 'الكتاب ص 105 — المثال 3-7 توقع تكوّن راسب'),
('mcq', 3, 'يبين الشكل الآتي خلط محلولين. ما تركيز أيونات Cl⁻ في الخليط مباشرة بعد الخلط؟', null, '[{"src":"qimg/chem22/c3-l3b-mix-baso4.svg","alt":"رسم لخلط محلولين: كأس فيها 100.0 mL من محلول BaCl₂ تركيزه 0.0020 M، وعلامة +، وكأس فيها 100.0 mL من محلول Na₂SO₄ تركيزه 0.0010 M، ثم سهم يشير إلى كأس ثالثة كُتب تحتها «الخليط» وحجمه 200.0 mL."}]'::jsonb, '["0.0010 M","0.0040 M","0.0030 M","0.0020 M"]'::jsonb, 'تطبيق', 'حساب تركيز أيون بعد الخلط', 'متوسط', 'الكتاب ص 104 — حساب تراكيز الأيونات (الجدول 3-4)'),
('mcq', 4, 'يبين الشكل الآتي خلط حجمين غير متساويين من محلولين. ما تركيزا أيونات Ag⁺ وCl⁻ في الخليط مباشرة بعد الخلط وقبل الترسب؟', null, '[{"src":"qimg/chem22/c3-l3b-mix-unequal.svg","alt":"رسم لخلط محلولين: كأس فيها 75.0 mL من محلول AgNO₃ تركيزه 0.080 M، وعلامة +، وكأس فيها 25.0 mL من محلول NaCl تركيزه 0.040 M، ثم سهم يشير إلى كأس ثالثة كُتب تحتها «الخليط» وحجمه 100.0 mL."}]'::jsonb, '["[Ag⁺] = 0.040 M، [Cl⁻] = 0.020 M","[Ag⁺] = 0.080 M، [Cl⁻] = 0.040 M","[Ag⁺] = 0.060 M، [Cl⁻] = 0.010 M","[Ag⁺] = 0.060 M، [Cl⁻] = 0.030 M"]'::jsonb, 'تطبيق', 'حساب تراكيز الأيونات بعد خلط حجوم مختلفة', 'صعب', 'الكتاب ص 103–105 — حساب تراكيز الأيونات (المسألة 26)'),
('mcq', 5, 'عند خلط حجمين متساويين من محلولين أيونيين، ماذا يحدث لتركيز كل أيون في الخليط مقارنة بتركيزه في محلوله الأصلي؟', null, null, '["يصبح نصف تركيزه في محلوله الأصلي","يصبح ضعف تركيزه في محلوله الأصلي","يبقى مساويًا لتركيزه في محلوله الأصلي","يصبح مجموع تركيزيه في المحلولين معًا"]'::jsonb, 'فهم', 'تفسير قاعدة', 'سهل', 'الكتاب ص 104 — حساب تراكيز الأيونات (الجدول 3-4)'),
('mcq', 6, 'يبين الشكل الآتي خلط محلولين. إذا كان Ksp لـ CaSO₄ يساوي 4.9 × 10⁻⁵، فما التوقع الصحيح؟', null, '[{"src":"qimg/chem22/c3-l3b-mix-caso4.svg","alt":"رسم لخلط محلولين: كأس فيها 25.0 mL من محلول CaCl₂ تركيزه 0.020 M، وعلامة +، وكأس فيها 25.0 mL من محلول Na₂SO₄ تركيزه 0.020 M، ثم سهم يشير إلى كأس ثالثة كُتب تحتها «الخليط» وحجمه 50.0 mL."}]'::jsonb, '["لا يتكون راسب لأن Qsp = 2.5 × 10⁻⁵ أقل من Ksp","يتكون راسب لأن Qsp = 4.0 × 10⁻⁴ أكبر من Ksp","لا يتكون راسب لأن Qsp يساوي Ksp فالمحلول مشبع","يتكون راسب لأن Qsp = 1.0 × 10⁻⁴ أكبر من Ksp"]'::jsonb, 'تطبيق', 'حساب Qsp ومقارنته بـ Ksp', 'متوسط', 'الكتاب ص 105 — المثال 3-7 توقع تكوّن راسب'),
('mcq', 7, 'خُلط حجمان متساويان من محلول FeCl₃ تركيزه 0.20 M ومحلول K₄[Fe(CN)₆] تركيزه 0.20 M. ما تركيز أيونات Cl⁻ في الخليط مباشرة بعد الخلط؟', null, null, '["0.10 M","0.60 M","0.30 M","0.40 M"]'::jsonb, 'تطبيق', 'حساب تركيز أيون بعد الخلط', 'صعب', 'الكتاب ص 104 — حساب تراكيز الأيونات (الجدول 3-4)'),
('essay', 1, 'أُضيف 200.0 mL من محلول MgCl₂ تركيزه 0.10 M إلى 300.0 mL من محلول NaOH تركيزه 0.0050 M.
(أ) احسب تركيز كل من الأيونات Mg²⁺ وCl⁻ وNa⁺ وOH⁻ في الخليط مباشرة بعد الخلط.
(ب) هل يتكون راسب من Mg(OH)₂؟ علمًا بأن Ksp لـ Mg(OH)₂ يساوي 5.6 × 10⁻¹². وضّح إجابتك.', null, null, null, 'تطبيق', 'حساب التراكيز بعد الخلط وتوقع الترسب', 'صعب', 'الكتاب ص 105 — المسألة 26'),
('essay', 2, 'خُلط حجمان متساويان من محلول Pb(NO₃)₂ تركيزه 0.050 M ومحلول NaF تركيزه 0.010 M.
(أ) احسب تراكيز الأيونات Pb²⁺ وNO₃⁻ وNa⁺ وF⁻ في الخليط مباشرة بعد الخلط.
(ب) توقع إن كان سيتكون راسب من PbF₂، علمًا بأن Ksp له يساوي 3.3 × 10⁻⁸.', null, null, null, 'تطبيق', 'حساب التراكيز بعد الخلط وتوقع الترسب', 'متوسط', 'الكتاب ص 105 — المسألة 25'),
('essay', 3, 'يبين الشكل الآتي خلط محلولين. احسب تركيزي أيوني Ba²⁺ وSO₄²⁻ في الخليط مباشرة بعد الخلط، وفسّر لماذا يقل تركيز كل منهما إلى النصف.', null, '[{"src":"qimg/chem22/c3-l3b-mix-baso4.svg","alt":"رسم لخلط محلولين: كأس فيها 100.0 mL من محلول BaCl₂ تركيزه 0.0020 M، وعلامة +، وكأس فيها 100.0 mL من محلول Na₂SO₄ تركيزه 0.0010 M، ثم سهم يشير إلى كأس ثالثة كُتب تحتها «الخليط» وحجمه 200.0 mL."}]'::jsonb, null, 'فهم', 'حساب وتفسير', 'سهل', 'الكتاب ص 104 — حساب تراكيز الأيونات (الجدول 3-4)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C3-L3-O11') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'عدد مولات Pb²⁺ لا يتغير بالخلط، لكن الحجم يتضاعف من 50.0 إلى 100.0 mL، فيقل التركيز إلى النصف: 0.040 ÷ 2 = 0.020 M.', '["هذا تركيز Pb²⁺ في المحلول الأصلي؛ ولم يُراعَ تضاعف الحجم بعد الخلط.","","قُسم التركيز على 4 بدل 2؛ فالحجم تضاعف مرة واحدة فقط (من 50.0 إلى 100.0 mL).","جُمع تركيزا المحلولين، مع أن NaCl لا يحتوي على أيونات Pb²⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (69%)"}],"at":"2026-11-07T17:19:00.529Z"}'::jsonb),
('mcq', 2, 0, 'بعد الخلط: [Pb²⁺] = 0.040 ÷ 2 = 0.020 M و[Cl⁻] = 0.020 ÷ 2 = 0.010 M. Qsp = [Pb²⁺][Cl⁻]² = (0.020)(0.010)² = 2.0 × 10⁻⁶، وهو أقل من Ksp = 1.7 × 10⁻⁵، فالمحلول غير مشبع ولا يتكون راسب.', '["","لم يُربَّع [Cl⁻]؛ فـ Qsp = [Pb²⁺][Cl⁻]² لا [Pb²⁺][Cl⁻].","استُعمل التركيزان الأصليان 0.040 M و0.020 M دون قسمتهما على 2 بعد الخلط.","القيمة صحيحة لكن المقارنة خاطئة؛ Qsp أقل من Ksp فالمحلول غير مشبع ولا يتكون راسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-07T17:19:00.529Z"}'::jsonb),
('mcq', 3, 3, 'في محلول BaCl₂ الأصلي: [Cl⁻] = 2 × 0.0020 = 0.0040 M. وبعد خلط حجمين متساويين يتضاعف الحجم (200.0 mL) فيقل التركيز إلى النصف: [Cl⁻] = 0.0040 ÷ 2 = 0.0020 M.', '["قُسم تركيز BaCl₂ على 2 دون مراعاة أن كل وحدة BaCl₂ تعطي أيوني Cl⁻.","هذا تركيز Cl⁻ في محلول BaCl₂ الأصلي؛ ولم يُقسم على 2 بعد تضاعف الحجم.","جُمع تركيزا المحلولين، مع أن Na₂SO₄ لا يحتوي على أيونات Cl⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (69%)"}],"at":"2026-11-07T17:19:00.529Z"}'::jsonb),
('mcq', 4, 2, 'التركيز الجديد = التركيز الأصلي × (الحجم الأصلي ÷ الحجم الكلي). [Ag⁺] = 0.080 × 75.0 ÷ 100.0 = 0.060 M، و[Cl⁻] = 0.040 × 25.0 ÷ 100.0 = 0.010 M.', '["قُسم كل تركيز على 2 كأن الحجمين متساويان، والحجمان هنا 75.0 mL و25.0 mL.","هذان التركيزان الأصليان؛ ولم يُراعَ التخفيف إلى الحجم الكلي 100.0 mL.","","ضُرب تركيز NaCl في 75.0/100.0 أيضًا، والصحيح ضربه في حجمه هو 25.0/100.0."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-07T17:19:00.529Z"}'::jsonb),
('mcq', 5, 0, 'عند خلط حجمين متساويين يبقى عدد مولات كل أيون كما هو، لكنه يذوب في ضعف الحجم الأصلي، فيقل التركيز بمقدار النصف.', '["","الحجم هو الذي يتضاعف لا عدد المولات، فيقل التركيز ولا يزيد.","عدد المولات ثابت لكنه يتوزع على ضعف الحجم، فيقل التركيز.","الأيون موجود غالبًا في أحد المحلولين فقط، والتركيز يقل بالتخفيف لا يُجمع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.529Z"}'::jsonb),
('mcq', 6, 3, 'بعد الخلط يتضاعف الحجم (50.0 mL): [Ca²⁺] = 0.020 ÷ 2 = 0.010 M و[SO₄²⁻] = 0.020 ÷ 2 = 0.010 M. Qsp = (0.010)(0.010) = 1.0 × 10⁻⁴ > Ksp = 4.9 × 10⁻⁵، فيتكون راسب من CaSO₄ حتى يصبح ناتج الضرب مساويًا لـ Ksp.', '["قُسم كل تركيز على 4 بدل 2؛ والتركيز الصحيح لكل أيون 0.010 M.","النتيجة صحيحة لكن Qsp حُسب من التركيزين الأصليين 0.020 M دون مراعاة التخفيف.","Qsp = 1.0 × 10⁻⁴ لا يساوي Ksp = 4.9 × 10⁻⁵؛ بل هو أكبر منه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-07T17:19:00.529Z"}'::jsonb),
('mcq', 7, 2, 'في محلول FeCl₃ الأصلي: [Cl⁻] = 3 × 0.20 = 0.60 M، لأن نسبة Cl⁻ إلى FeCl₃ هي 3:1. وبعد خلط حجمين متساويين يقل التركيز إلى النصف: 0.60 ÷ 2 = 0.30 M.', '["قُسم تركيز FeCl₃ على 2 دون ضربه في 3؛ فكل وحدة FeCl₃ تعطي ثلاثة أيونات Cl⁻.","هذا تركيز Cl⁻ في محلول FeCl₃ الأصلي (3 × 0.20)؛ ولم يُقسم على 2 بعد الخلط.","","استُعملت نسبة أيونات K⁺ إلى K₄[Fe(CN)₆] (4:1) بدل نسبة Cl⁻ إلى FeCl₃ (3:1)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.530Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحجم الكلي = 200.0 + 300.0 = 500.0 mL.
(أ) [Mg²⁺] = 0.10 × 200.0 ÷ 500.0 = 0.040 M؛ [Cl⁻] = 2 × 0.10 × 200.0 ÷ 500.0 = 0.080 M؛ [Na⁺] = [OH⁻] = 0.0050 × 300.0 ÷ 500.0 = 0.0030 M.
(ب) Mg(OH)₂(s) ⇌ Mg²⁺(aq) + 2OH⁻(aq)؛ Qsp = [Mg²⁺][OH⁻]² = (0.040)(0.0030)² = 3.6 × 10⁻⁷.
Qsp (3.6 × 10⁻⁷) > Ksp (5.6 × 10⁻¹²)، فيتكون راسب من Mg(OH)₂.', '["الحجم الكلي 500.0 mL","[Mg²⁺] = 0.040 M و[Cl⁻] = 0.080 M","[Na⁺] = [OH⁻] = 0.0030 M","Qsp = 3.6 × 10⁻⁷","Qsp > Ksp فيتكون راسب"]'::jsonb, '["الحجم الكلي = 200.0 mL + 300.0 mL = 500.0 mL","[Mg²⁺] = 0.10 × (200.0 ÷ 500.0) = 0.040 M","[Cl⁻] = 2 × 0.040 = 0.080 M","[OH⁻] = [Na⁺] = 0.0050 × (300.0 ÷ 500.0) = 0.0030 M","Qsp = (0.040)(0.0030)² = 3.6 × 10⁻⁷","3.6 × 10⁻⁷ > 5.6 × 10⁻¹² ← يتكون راسب"]'::jsonb, '[{"element":"الحجم الكلي ونسبة التخفيف","marks":1},{"element":"تراكيز الأيونات الأربعة","marks":2},{"element":"حساب Qsp","marks":2},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"التراكيز وQsp والاستنتاج صحيحة"},{"level":"3–5 درجات","description":"خطأ في تركيز أو أكثر مع منهجية سليمة لـ Qsp والمقارنة"},{"level":"1–2 درجة","description":"حساب الحجم الكلي أو تركيز واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة كل تركيز على 2 كأن الحجمين متساويان","نسيان ضرب [Cl⁻] في 2","عدم تربيع [OH⁻] في Qsp"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-07T17:19:00.530Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) خلط حجمين متساويين يُقلل كل تركيز إلى النصف: [Pb²⁺] = 0.050 ÷ 2 = 0.025 M؛ [NO₃⁻] = (2 × 0.050) ÷ 2 = 0.050 M؛ [Na⁺] = [F⁻] = 0.010 ÷ 2 = 0.0050 M.
(ب) PbF₂(s) ⇌ Pb²⁺(aq) + 2F⁻(aq)؛ Qsp = [Pb²⁺][F⁻]² = (0.025)(0.0050)² = 6.3 × 10⁻⁷.
Qsp (6.3 × 10⁻⁷) > Ksp (3.3 × 10⁻⁸)، فيتكون راسب من PbF₂.', '["[Pb²⁺] = 0.025 M","[NO₃⁻] = 0.050 M","[Na⁺] = [F⁻] = 0.0050 M","Qsp = 6.3 × 10⁻⁷ > Ksp فيتكون راسب"]'::jsonb, '["[Pb²⁺] = 0.050 ÷ 2 = 0.025 M","[NO₃⁻] = 2 × 0.050 ÷ 2 = 0.050 M","[F⁻] = [Na⁺] = 0.010 ÷ 2 = 0.0050 M","Qsp = (0.025)(0.0050)² = 6.25 × 10⁻⁷ ≈ 6.3 × 10⁻⁷","6.3 × 10⁻⁷ > 3.3 × 10⁻⁸ ← يتكون راسب"]'::jsonb, '[{"element":"تراكيز الأيونات","marks":2},{"element":"كتابة Qsp وحسابه","marks":2},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التراكيز وQsp والتوقع صحيحة"},{"level":"3–4 درجات","description":"خطأ في تركيز NO₃⁻ أو في تربيع [F⁻] مع استنتاج متسق"},{"level":"1–2 درجة","description":"تراكيز صحيحة دون حساب Qsp"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم قسمة التراكيز على 2","عدّ [NO₃⁻] = 0.025 M","حساب Qsp = [Pb²⁺][F⁻] دون تربيع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('essay', 3, null::int, null, null, '[Ba²⁺] = 0.0020 ÷ 2 = 0.0010 M، و[SO₄²⁻] = 0.0010 ÷ 2 = 5.0 × 10⁻⁴ M.
التفسير: عدد مولات كل أيون لا يتغير بالخلط، لكنه يتوزع في حجم يساوي ضعف حجم محلوله الأصلي (200.0 mL بدل 100.0 mL)، فيقل تركيزه بمقدار النصف.', '["[Ba²⁺] = 0.0010 M","[SO₄²⁻] = 5.0 × 10⁻⁴ M","عدد المولات ثابت والحجم يتضاعف"]'::jsonb, '["[Ba²⁺] = 0.0020 M ÷ 2 = 0.0010 M","[SO₄²⁻] = 0.0010 M ÷ 2 = 5.0 × 10⁻⁴ M"]'::jsonb, '[{"element":"[Ba²⁺]","marks":1},{"element":"[SO₄²⁻]","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التركيزان والتفسير صحيحة"},{"level":"1–2 درجة","description":"تركيز واحد صحيح أو التفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم قسمة التراكيز على 2","القول إن عدد المولات يقل إلى النصف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C3-L3-O11') and x.type = v.type and x.number = v.number
