insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما التعريف الصحيح للمركب العضوي؟', null, null, '["مركب لا يمكن إنتاجه إلا داخل أجسام المخلوقات الحية","مركب يحتوي على الكربون، ما عدا أكاسيد الكربون والكربيدات والكربونات","أي مركب يحتوي على عنصر الكربون دون استثناء","مركب يتكون من عنصري الكربون والهيدروجين فقط"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)'),
('mcq', 2, 'أيّ المواد المرقمة في الشكل الآتي تُصنَّف مركبات عضوية؟', null, '[{"src":"qimg/chem22/c4-l1a-carbon-compounds.svg","alt":"أربع مواد مرقمة: (1) صيغة بنائية O=C=O: ذرة C في الوسط بينها وبين كل ذرة O رابطة ثنائية. (2) صيغة بنائية: ذرة C ترتبط بثلاث ذرات H وبذرة O، وترتبط ذرة O بذرة H. (3) الصيغة CaCO₃ مكتوبة فقط. (4) صيغة بنائية: ذرة C ترتبط برابطة ثنائية بذرة O، وبرابطة أحادية بكل من مجموعتي NH₂."}]'::jsonb, '["(1) و(3) فقط","(1) و(2) و(4)","(2) فقط","(2) و(4) فقط"]'::jsonb, 'تطبيق', 'تصنيف مواد من صيغها', 'متوسط', 'الكتاب ص 121، ص 159 — تعريف المركب العضوي، واليوريا (س46)'),
('mcq', 3, 'أيّ المركبات الآتية يُعدّ مركبًا غير عضوي رغم احتوائه على الكربون؟', null, null, '["CaCO₃","CH₃OH","C₂H₆","C₆H₁₂O₆"]'::jsonb, 'تذكر', 'تطبيق التعريف على مثال', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)'),
('mcq', 4, 'لماذا يُصنَّف ثاني أكسيد الكربون CO₂ مركبًا غير عضوي مع أنه يحتوي على الكربون؟', null, null, '["لأن جزيئه لا يحتوي على ذرات هيدروجين","لأنه يوجد في الحالة الغازية في الظروف العادية","لأنه من أكاسيد الكربون المستثناة من تعريف المركب العضوي","لأنه لا ينتج مطلقًا عن المخلوقات الحية"]'::jsonb, 'تذكر', 'تفسير', 'متوسط', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)'),
('mcq', 5, 'ما العنصر الذي تشترك في احتوائه المركبات العضوية جميعها؟', null, null, '["الهيدروجين","الأكسجين","النيتروجين","الكربون"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)'),
('mcq', 6, 'أيّ المجموعات الآتية تتكون من مركبات عضوية جميعها؟', null, null, '["CO ، CH₄ ، C₂H₅OH","CH₄ ، C₂H₅OH ، CCl₄","CaC₂ ، C₃H₈ ، CH₃OH","C₂H₆ ، K₂CO₃ ، CH₃Cl"]'::jsonb, 'تطبيق', 'تصنيف مجموعة مركبات', 'صعب', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)'),
('mcq', 7, 'يمكن تحضير الإيثانول C₂H₅OH في المختبر من مواد غير عضوية، ويمكن أن تنتجه أيضًا مخلوقات حية. كيف يُصنَّف الإيثانول وفق التعريف الحديث للمركب العضوي؟', null, null, '["عضوي إذا أنتجته مخلوقات حية، وغير عضوي إذا حُضّر في المختبر","غير عضوي في الحالتين؛ لأنه يحتوي على ذرة أكسجين","عضوي في الحالتين؛ لأن التصنيف يعتمد على تركيبه لا على مصدره","عضوي إذا حُضّر في المختبر فقط؛ لأن تركيبه يكون أنقى"]'::jsonb, 'فهم', 'تطبيق التعريف على حالة', 'متوسط', 'الكتاب ص 120–121 — المركبات العضوية ودحض فكرة القوة الحيوية'),
('essay', 1, 'عرّف المركب العضوي، ثم اذكر الفئات الثلاث من مركبات الكربون التي لا تُعدّ مركبات عضوية، ومثّل لكل فئة بمثال واحد.', null, null, null, 'تذكر', 'تعريف وتمثيل', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)'),
('essay', 2, 'صنّف كل مادة من المواد المرقمة في الشكل الآتي إلى مركب عضوي أو غير عضوي، مع تعليل كل تصنيف.', null, '[{"src":"qimg/chem22/c4-l1a-carbon-compounds.svg","alt":"أربع مواد مرقمة: (1) صيغة بنائية O=C=O: ذرة C في الوسط بينها وبين كل ذرة O رابطة ثنائية. (2) صيغة بنائية: ذرة C ترتبط بثلاث ذرات H وبذرة O، وترتبط ذرة O بذرة H. (3) الصيغة CaCO₃ مكتوبة فقط. (4) صيغة بنائية: ذرة C ترتبط برابطة ثنائية بذرة O، وبرابطة أحادية بكل من مجموعتي NH₂."}]'::jsonb, null, 'تطبيق', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 121، ص 159 — تعريف المركب العضوي، واليوريا'),
('essay', 3, 'قال طالب: «كل مركب عضوي يحتوي على الهيدروجين، وكل مركب يحتوي على الكربون مركب عضوي». قوّم كل جزء من العبارة، مدعّمًا رأيك بمثال.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 121 — الكيمياء العضوية (تعريف المركب العضوي)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يُطلق مصطلح المركب العضوي اليوم على المركبات التي تحتوي على الكربون، ما عدا أكاسيد الكربون والكربيدات والكربونات؛ إذ تُعد هذه الفئات الثلاث مركبات غير عضوية.', '["هذه فكرة القوة الحيوية القديمة، وقد ثبت بطلانها بعد أن حُضّرت مركبات عضوية في المختبر.","","التعريف يستثني أكاسيد الكربون والكربيدات والكربونات، فليس كل مركب كربوني عضويًّا.","هذا تعريف الهيدروكربونات، وهي جزء فقط من المركبات العضوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('mcq', 2, 3, 'المادة (1) هي CO₂ وهي من أكاسيد الكربون، والمادة (3) هي CaCO₃ وهي من الكربونات، فكلتاهما غير عضوية. أما (2) فهي CH₃OH، و(4) هي اليوريا CO(NH₂)₂، وكلتاهما تحتوي على الكربون وليست من الفئات المستثناة؛ لذا فالمركبان العضويان هما (2) و(4) فقط.', '["(1) من أكاسيد الكربون و(3) من الكربونات، وهما الفئتان المستثناتان من المركبات العضوية.","(1) هي CO₂، وأكاسيد الكربون مستثناة من المركبات العضوية رغم احتوائها على الكربون.","أُغفلت اليوريا (4)، وهي مركب عضوي يحتوي على الكربون وليست من الفئات المستثناة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('mcq', 3, 0, 'CaCO₃ (كربونات الكالسيوم) من الكربونات، والكربونات مستثناة من المركبات العضوية مع أكاسيد الكربون والكربيدات؛ لذا فهو مركب غير عضوي رغم احتوائه على الكربون.', '["","CH₃OH يحتوي على الكربون وليس من الأكاسيد أو الكربيدات أو الكربونات، فهو عضوي.","C₂H₆ هيدروكربون، والهيدروكربونات أبسط المركبات العضوية.","C₆H₁₂O₆ (الجلوكوز) يحتوي على الكربون وليس من الفئات المستثناة، فهو عضوي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('mcq', 4, 2, 'يستثني تعريف المركب العضوي أكاسيد الكربون والكربيدات والكربونات، وCO₂ من أكاسيد الكربون؛ لذلك يُصنَّف مركبًا غير عضوي لأنه من أكاسيد الكربون المستثناة.', '["خلو المركب من الهيدروجين ليس معيار التصنيف؛ فبعض المركبات العضوية لا تحتوي على هيدروجين، مثل CCl₄.","الحالة الفيزيائية لا تحدد كون المركب عضويًّا؛ فالميثان غاز وهو مركب عضوي.","","CO₂ ينتج عن تنفس المخلوقات الحية، ومع ذلك فهو غير عضوي؛ فالمصدر ليس معيار التصنيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('mcq', 5, 3, 'المركب العضوي بحسب تعريفه مركب يحتوي على الكربون؛ لذا فالعنصر المشترك في المركبات العضوية جميعها هو الكربون.', '["كثير من المركبات العضوية يحتوي على الهيدروجين، لكن ليس جميعها؛ فالمركب CCl₄ عضوي ولا يحتوي على هيدروجين.","الأكسجين يوجد في بعض المركبات العضوية فقط، والهيدروكربونات مثلًا تخلو منه.","النيتروجين يوجد في بعض المركبات العضوية كاليوريا، لكنه ليس شرطًا في تعريفها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('mcq', 6, 1, 'المركبات CH₄ وC₂H₅OH وCCl₄ تحتوي كلها على الكربون وليس بينها أكسيد كربون ولا كربيد ولا كربونات؛ فهي عضوية جميعها، مع أن CCl₄ لا يحتوي على هيدروجين.', '["CO (أول أكسيد الكربون) من أكاسيد الكربون، فهو غير عضوي.","","CaC₂ (كربيد الكالسيوم) من الكربيدات، فهو غير عضوي.","K₂CO₃ (كربونات البوتاسيوم) من الكربونات، فهو غير عضوي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.531Z"}'::jsonb),
('mcq', 7, 2, 'التعريف الحديث يعتمد على التركيب: المركب العضوي يحتوي على الكربون وليس من أكاسيده أو الكربيدات أو الكربونات. والإيثانول كذلك مهما كان مصدره؛ فهو عضوي في الحالتين لأن التصنيف يعتمد على تركيبه لا على مصدره.', '["ربط التصنيف بالمصدر هو فكرة القوة الحيوية القديمة التي ثبت بطلانها.","وجود الأكسجين لا يجعل المركب غير عضوي؛ فكثير من المركبات العضوية يحتوي على الأكسجين.","","درجة النقاوة لا علاقة لها بكون المركب عضويًّا؛ والتصنيف لا يتغير بتغير طريقة التحضير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المركب العضوي: مركب يحتوي على الكربون، ما عدا أكاسيد الكربون والكربيدات والكربونات. والفئات المستثناة: أكاسيد الكربون مثل CO₂ أو CO، والكربيدات مثل كربيد الكالسيوم CaC₂، والكربونات مثل كربونات الكالسيوم CaCO₃.', '["المركب العضوي يحتوي على الكربون","استثناء أكاسيد الكربون مع مثال (CO₂ أو CO)","استثناء الكربيدات مع مثال (CaC₂)","استثناء الكربونات مع مثال (CaCO₃)"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف: مركب يحتوي على الكربون مع ذكر الاستثناءات","marks":1},{"element":"أكاسيد الكربون مع مثال","marks":1},{"element":"الكربيدات مع مثال","marks":1},{"element":"الكربونات مع مثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تعريف صحيح مع ذكر فئة أو فئتين مستثناتين وأمثلتهما"},{"level":"1 درجة","description":"ذكر أن المركب العضوي يحتوي على الكربون دون الاستثناءات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المركب العضوي بأنه كل مركب يحتوي على الكربون دون استثناء","الخلط بين تعريف المركب العضوي وتعريف الهيدروكربون","التمثيل للكربونات بمركب عضوي مثل الجلوكوز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) CO₂: غير عضوي؛ لأنه من أكاسيد الكربون المستثناة. (2) CH₃OH: عضوي؛ لأنه يحتوي على الكربون وليس من الأكاسيد أو الكربيدات أو الكربونات. (3) CaCO₃: غير عضوي؛ لأنه من الكربونات. (4) اليوريا CO(NH₂)₂: عضوي؛ لأنه يحتوي على الكربون وليس من الفئات المستثناة.', '["(1) غير عضوي: أكسيد كربون","(2) عضوي: يحتوي على الكربون وليس مستثنى","(3) غير عضوي: كربونات","(4) عضوي: يحتوي على الكربون وليس مستثنى"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (1) وتعليله","marks":1},{"element":"تصنيف (2) وتعليله","marks":1},{"element":"تصنيف (3) وتعليله","marks":1},{"element":"تصنيف (4) وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تصنيف صحيح لمادتين أو ثلاث مع التعليل"},{"level":"1 درجة","description":"تصنيف صحيح لمادة واحدة، أو تصنيفات صحيحة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CO₂ مركبًا عضويًّا لاحتوائه على الكربون","عدّ اليوريا غير عضوية لأنها لا تحتوي على روابط C–H كثيرة أو لاحتوائها على النيتروجين","عدّ CaCO₃ عضويًّا لأنه يوجد في الأصداف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزء الأول غير صحيح: تعريف المركب العضوي لا يشترط وجود الهيدروجين، فرابع كلوريد الكربون CCl₄ مركب عضوي لا يحتوي على هيدروجين. والجزء الثاني غير صحيح أيضًا: فأكاسيد الكربون والكربيدات والكربونات تحتوي على الكربون لكنها غير عضوية، مثل CO₂ وCaCO₃. والعبارة الصحيحة: المركب العضوي مركب يحتوي على الكربون، ما عدا أكاسيد الكربون والكربيدات والكربونات.', '["الجزء الأول خاطئ مع مثال (CCl₄)","الجزء الثاني خاطئ مع مثال (CO₂ أو CaCO₃ أو CaC₂)","صياغة التعريف الصحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الجزء الأول ومثاله","marks":2},{"element":"الحكم على الجزء الثاني ومثاله","marks":2},{"element":"كتابة التعريف الصحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3–4 درجات","description":"حكم صحيح على الجزأين مع نقص في الأمثلة أو التعريف"},{"level":"1–2 درجة","description":"حكم صحيح على جزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الجزء الأول بحجة أن الميثان وغيره تحتوي على الهيدروجين","تقديم مثال عضوي يحتوي على الهيدروجين لنقض الجزء الأول","إغفال الاستثناءات الثلاث عند نقض الجزء الثاني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb)
