('mcq', 5, 'ما مصدر كل من الحرارة والضغط اللذين حوّلا بقايا المخلوقات الحية إلى نفط؟', null, null, '["الحرارة من باطن الأرض، والضغط من الرواسب المتراكمة فوق البقايا","الحرارة من أشعة الشمس، والضغط من الغلاف الجوي","الحرارة من احتراق البقايا، والضغط من مياه الأمطار","الحرارة من البراكين فقط، والضغط من حركة الأمواج"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 123 — تنقية الهيدروكربونات (تكوّن النفط)'),
('mcq', 6, 'تكوّن النفط الموجود اليوم من بقايا مخلوقات حية عاشت في المحيطات قبل ملايين السنين، ويُضخ منه من باطن الأرض نحو 75 مليون برميل يوميًّا. أيّ الاستنتاجات الآتية تدعمه هذه المعلومات؟', null, null, '["يتكوّن نفط جديد خلال سنوات قليلة فيعوّض الكميات المستهلكة","توقف تكوّن النفط نهائيًّا لانقراض المخلوقات البحرية جميعها","يتكوّن النفط في الغلاف الجوي ثم يترسب في قاع المحيط","النفط المستهلك لا يُعوَّض في المدى القريب؛ لأن تكوّنه يستغرق ملايين السنين"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 118، ص 123 — حقائق كيميائية، وتكوّن النفط'),
('mcq', 7, 'ماذا يحدث للنفط بعد تكوّنه في باطن الأرض؟', null, null, '["يبقى ممزوجًا بالطين في قاع المحيط دون أن يتحرك","يطفو مباشرة إلى سطح البحر ويتبخر في الهواء","ينفذ عبر صخور ذات مسامات ويتجمع في برك في أعماق القشرة الأرضية","يتحول كله إلى غاز طبيعي يتسرب إلى الغلاف الجوي"]'::jsonb, 'فهم', 'وصف عملية', 'صعب', 'الكتاب ص 123 — تنقية الهيدروكربونات (تكوّن النفط)'),
('essay', 1, 'اشرح بالتسلسل كيف تكوّن النفط في باطن الأرض.', null, null, null, 'فهم', 'شرح عملية متسلسلة', 'متوسط', 'الكتاب ص 123 — تنقية الهيدروكربونات (تكوّن النفط)'),
('essay', 2, 'يبين المخطط الآتي مراحل تكوّن النفط. اكتب المرحلة التي تمثلها علامة الاستفهام، ثم وضّح دور كل من الحرارة والضغط فيها، ومصدر كل منهما.', null, '[{"src":"qimg/chem22/c4-l1a-oil-formation.svg","alt":"مخطط تتابعي بعنوان «مراحل تكوّن النفط عبر ملايين السنين» من أربعة مربعات تصل بينها أسهم من اليمين إلى اليسار: المربع الأول «بقايا مخلوقات حية عاشت في المحيطات»، والثاني «كوّنت بقاياها في قاع المحيط طبقات سميكة من رواسب شبه طينية»، والثالث فيه علامة استفهام (؟) فقط، والرابع «ينفذ النفط عبر صخور ذات مسامات ويتجمع في برك بالقشرة الأرضية»."}]'::jsonb, null, 'تطبيق', 'إكمال مخطط وتفسير', 'متوسط', 'الكتاب ص 123 — تنقية الهيدروكربونات (تكوّن النفط)'),
('essay', 3, 'فسّر ما يأتي: (أ) يُسمّى النفط والغاز الطبيعي وقودًا أحفوريًّا. (ب) يوجد الغاز الطبيعي عادة مصاحبًا لترسبات النفط. (ج) لا يمكن تعويض النفط المستهلك بنفط جديد يتكوّن في زمن قصير، علمًا بأن النفط الموجود اليوم تكوّن من مخلوقات عاشت قبل ملايين السنين.', null, null, null, 'تحليل', 'تفسير ظواهر', 'صعب', 'الكتاب ص 118، ص 123 — تكوّن النفط والغاز الطبيعي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
