from (values
('mcq', 1, 0, 'تكوّن النفط من بقايا المخلوقات الحية التي عاشت في المحيطات منذ ملايين السنين، بعد أن دُفنت وتحولت بفعل الحرارة والضغط.', '["","النفط مادة عضوية أصلها مخلوقات حية، وليس من صهارة الصخور.","النفط لم يتكون في الغلاف الجوي، بل في القشرة الأرضية من بقايا مخلوقات حية.","تكوّن النفط استغرق ملايين السنين، لا سنوات قليلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('mcq', 2, 2, 'بعد أن كوّنت البقايا طبقات سميكة من رواسب شبه طينية، تحولت بفعل الحرارة المنبعثة من باطن الأرض والضغط الهائل من الرواسب الكثيرة إلى صخر زيتي وغاز طبيعي، ثم نفذ النفط عبر الصخور ذات المسامات. فالمرحلة الناقصة هي تحول البقايا بفعل حرارة باطن الأرض والضغط الهائل للرواسب.', '["البقايا مدفونة في قاع المحيط تحت الرواسب، فلا تصلها أشعة الشمس، والنفط لا يتكون بالتبخر والتكثف.","التحول إلى CO₂ يعني فقدان المادة العضوية، وهذا لا ينتج نفطًا يحتوي على الهيدروكربونات.","","التحول حدث بالتسخين من باطن الأرض والضغط، لا بالتبريد والتجمد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('mcq', 3, 3, 'الوقود الأحفوري وقود أصله بقايا مخلوقات حية عاشت قديمًا ثم دُفنت وتحولت عبر ملايين السنين؛ والنفط تكوّن من بقايا مخلوقات حية قديمة مدفونة في القشرة الأرضية، لذا سُمّي وقودًا أحفوريًّا.', '["طريقة الاستخراج بالحفر لا تحدد التسمية؛ فالمياه الجوفية تُستخرج بالحفر وليست وقودًا أحفوريًّا.","إطلاق الطاقة عند الاحتراق صفة لكل وقود، ولا يفسر وصف «أحفوري».","النفط خليط معقد قد يحتوي على مواد أخرى، والتسمية مرتبطة بأصله لا بعناصره.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('mcq', 4, 1, 'يوجد الغاز الطبيعي عادة مصاحبًا لترسبات النفط؛ لأنهما يتشكلان معًا في الوقت نفسه وبالطريقة نفسها من بقايا المخلوقات الحية بفعل الحرارة والضغط.', '["النفط لا يحترق داخل الأرض لغياب الأكسجين، والغاز الطبيعي تكوّن مع النفط لا من احتراقه.","","الغاز الطبيعي لا يأتي من الهواء الجوي، بل تكوّن في باطن الأرض مع النفط.","هذا ليس سبب وجودهما معًا في الطبيعة؛ فوجودهما معًا سابق لأي استخراج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('mcq', 5, 0, 'تحولت البقايا بفعل الحرارة المنبعثة من باطن الأرض والضغط الهائل الناتج عن الرواسب الكثيرة المتراكمة فوقها؛ فالحرارة من باطن الأرض والضغط من الرواسب.', '["","البقايا مدفونة عميقًا فلا تصلها أشعة الشمس، وضغط الغلاف الجوي صغير جدًّا مقارنة بضغط الرواسب.","البقايا لم تحترق؛ إذ لو احترقت لتحولت إلى CO₂ وماء ولم يتكون النفط.","حرارة باطن الأرض لا تقتصر على البراكين، وحركة الأمواج لا تولد الضغط الهائل في أعماق القشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.532Z"}'::jsonb),
('mcq', 6, 3, 'تحوّلت بقايا المخلوقات الحية إلى نفط ببطء بفعل الحرارة والضغط عبر ملايين السنين، في حين يُستهلك منه نحو 75 مليون برميل يوميًّا؛ لذا فالنفط المستهلك لا يُعوَّض في المدى القريب لأن تكوّنه يستغرق ملايين السنين.', '["المعطيات تبين أن النفط الموجود تكوّن عبر ملايين السنين، فلا يمكن أن يتكوّن نفط جديد يعوّض الاستهلاك في سنوات قليلة.","المعطيات لا تدل على توقف تكوّن النفط، والمخلوقات الحية ما زالت تعيش في المحيطات؛ المشكلة في طول زمن التكوّن.","النفط لا يتكوّن في الغلاف الجوي، بل من بقايا المخلوقات المدفونة في قاع المحيط بفعل الحرارة والضغط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('mcq', 7, 2, 'بعد تكوّن النفط ينفذ من خلال أنواع معينة من الصخور ذات المسامات، ويتجمع في أعماق القشرة الأرضية في صورة برك؛ ومن هناك يُستخرج بحفر الآبار.', '["النفط لا يبقى في مكان تكوّنه، بل يتحرك عبر الصخور ذات المسامات.","النفط يتجمع في أعماق القشرة الأرضية، ولذلك يُستخرج بحفر الآبار.","","لا يتحول النفط كله إلى غاز؛ فالنفط والغاز الطبيعي يوجدان معًا في الترسبات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) عاشت مخلوقات حية في المحيطات منذ ملايين السنين. 2) بعد موتها كوّنت بقاياها في قاع المحيط طبقات سميكة من رواسب شبه طينية. 3) تحولت هذه البقايا بفعل الحرارة المنبعثة من باطن الأرض والضغط الهائل من الرواسب الكثيرة إلى صخر زيتي وغاز طبيعي. 4) نفذ النفط عبر أنواع معينة من الصخور ذات المسامات، وتجمع في أعماق القشرة الأرضية في صورة برك.', '["الأصل: بقايا مخلوقات حية في المحيطات","تكوّن طبقات من رواسب شبه طينية في القاع","التحول بفعل حرارة باطن الأرض وضغط الرواسب","نفاذ النفط عبر صخور ذات مسامات وتجمعه في برك"]'::jsonb, '[]'::jsonb, '[{"element":"أصل النفط","marks":1},{"element":"تكوّن الرواسب في القاع","marks":1},{"element":"دور الحرارة والضغط","marks":1},{"element":"نفاذ النفط وتجمعه في برك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"ذكر معظم المراحل مع خلل في التسلسل أو نقص مرحلة"},{"level":"1 درجة","description":"ذكر أصل النفط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال دور الحرارة والضغط","القول إن النفط تكوّن في سنوات قليلة","القول إن النفط يبقى في مكان تكوّنه في الرواسب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المرحلة الناقصة: تحولت بقايا المخلوقات المدفونة إلى صخر زيتي وغاز طبيعي. والحرارة مصدرها باطن الأرض، والضغط الهائل مصدره الرواسب الكثيرة المتراكمة فوق البقايا؛ وهما معًا يحولان البقايا ببطء عبر ملايين السنين إلى النفط والغاز الطبيعي.', '["المرحلة: تحول البقايا إلى صخر زيتي وغاز طبيعي","الحرارة من باطن الأرض","الضغط من الرواسب المتراكمة","التحول بطيء عبر ملايين السنين"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة المرحلة الناقصة","marks":1},{"element":"مصدر الحرارة ودورها","marks":1},{"element":"مصدر الضغط ودوره","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"كتابة المرحلة مع ذكر مصدر عامل واحد فقط"},{"level":"1 درجة","description":"كتابة المرحلة دون توضيح الحرارة والضغط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الحرارة إلى أشعة الشمس","نسبة الضغط إلى الغلاف الجوي أو ماء البحر","وصف المرحلة بأنها احتراق للبقايا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لأنهما تكوّنا من بقايا مخلوقات حية عاشت في المحيطات منذ ملايين السنين ثم دُفنت وتحولت في القشرة الأرضية. (ب) لأنهما يتشكلان معًا في الوقت نفسه وبالطريقة نفسها من هذه البقايا بفعل حرارة باطن الأرض وضغط الرواسب. (ج) لأن تحول البقايا إلى نفط يستغرق ملايين السنين، في حين يُستهلك النفط بكميات هائلة يوميًّا.', '["أصلهما بقايا مخلوقات حية قديمة","يتكونان معًا بالطريقة نفسها وفي الوقت نفسه","تكوّن النفط يستغرق ملايين السنين والاستهلاك سريع"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير (أ)","marks":1},{"element":"تفسير (ب)","marks":1},{"element":"تفسير (ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تفسير صحيح لجزأين"},{"level":"1 درجة","description":"تفسير صحيح لجزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير «أحفوري» بأنه يُستخرج بالحفر","القول إن الغاز الطبيعي ينتج من احتراق النفط","إغفال المقارنة بين زمن التكوّن وسرعة الاستهلاك في (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
