('mcq', 2, 'من أيّ المصدرين الرئيسين للهيدروكربونات يُحصل على الجازولين والديزل اللذين يُستخدمان في تسيير السيارات؟', null, null, '["من النفط بفصله إلى مكوّناته","من الغاز الطبيعي بتسييله","من الفحم الحجري بتسخينه","من الغاز الحيوي بضغطه"]'::jsonb, 'تذكر', 'ربط منتج بمصدره', 'متوسط', 'الكتاب ص 120، ص 123–124 — الربط مع الحياة، والتقطير التجزيئي'),
('mcq', 3, 'ما الذي يشترك فيه المصدران الرئيسان للهيدروكربونات من حيث أصل تكوّنهما؟', null, null, '["كلاهما تكوّن من تفاعل غازات الغلاف الجوي","كلاهما تكوّن من بقايا مخلوقات حية بفعل الحرارة والضغط","كلاهما يتجدد خلال سنوات قليلة في المحيطات","كلاهما تكوّن من صهارة البراكين بعد تبريدها"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 123 — تكوّن النفط والغاز الطبيعي'),
('mcq', 4, 'يبين الجدول الآتي وصف عينتين من مصدرين طبيعيين للهيدروكربونات. ما اسم كل عينة؟', '{"headers":["العينة","الوصف"],"rows":[["(س)","يتكون بصورة أساسية من الميثان، مع كميات ضئيلة من هيدروكربونات تحتوي على 2 إلى 5 ذرات كربون"],["(ص)","خليط معقد يحتوي على أكثر من ألف مركب، وقليلًا ما يُستخدم في صورته الخام، ويُفصل بالتقطير التجزيئي"]]}'::jsonb, null, '["(س) نفط، و(ص) غاز طبيعي","(س) و(ص) نفط كلتاهما","(س) غاز طبيعي، و(ص) نفط","(س) و(ص) غاز طبيعي كلتاهما"]'::jsonb, 'تطبيق', 'تعرّف من بيانات', 'متوسط', 'الكتاب ص 123 — الغاز الطبيعي والتقطير التجزيئي'),
('mcq', 5, 'أيّ العبارات الآتية تقارن مقارنة صحيحة بين المصدرين الرئيسين للهيدروكربونات؟', null, null, '["الغاز الطبيعي خليط أعقد تركيبًا من النفط الذي يغلب عليه الميثان","النفط خليط أعقد تركيبًا من الغاز الطبيعي الذي يغلب عليه الميثان","النفط والغاز الطبيعي مادتان نقيتان لكل منهما صيغة جزيئية واحدة","الغاز الطبيعي خليط من أكثر من ألف مركب يُفصل بالتقطير التجزيئي"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 123 — الغاز الطبيعي والتقطير التجزيئي'),
('mcq', 6, 'مصدر طبيعي رئيس للهيدروكربونات يوجد عادة مصاحبًا لترسبات النفط، ويتكوّن بصورة أساسية من الميثان. ما هذا المصدر؟', null, null, '["الكيروسين","الجازولين","النفط الخام","الغاز الطبيعي"]'::jsonb, 'تذكر', 'تذكر استخدامات', 'سهل', 'الكتاب ص 123، ص 125 — الغاز الطبيعي، والخلاصة'),
('mcq', 7, 'أيّ زوجي المنتجات الآتيين يُحصل عليهما كليهما من المصدرين الرئيسين للهيدروكربونات؟', null, null, '["غاز الطهي في المنازل، وجازولين السيارات","الخشب، والفحم النباتي","الغاز الحيوي من المخلفات، والخشب","الكحول من قصب السكر، والفحم النباتي"]'::jsonb, 'تطبيق', 'ربط منتجات بمصادرها', 'صعب', 'الكتاب ص 121، ص 123، ص 155 — الميثان، وتنقية الهيدروكربونات، وجهاز هضم الميثان'),
('essay', 1, 'سمِّ المصدرين الرئيسين للهيدروكربونات، واذكر استخدامًا واحدًا لكل منهما.', null, null, null, 'تذكر', 'تسمية وتمثيل', 'سهل', 'الكتاب ص 125، ص 157 — الخلاصة: المصدران الرئيسان للهيدروكربونات'),
('essay', 2, 'قارن بين المصدرين الرئيسين للهيدروكربونات من حيث: التركيب، وطريقة التكوّن، والحاجة إلى الفصل قبل الاستعمال.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 123، ص 125 — الغاز الطبيعي والتقطير التجزيئي'),
('essay', 3, 'قال طالب: «بما أن المركبات العضوية مصدرها المخلوقات الحية، فإن النباتات والحيوانات الحية هي المصدر الرئيس للهيدروكربونات التي نستخدمها اليوم وقودًا». قوّم هذه العبارة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 120، ص 123، ص 125 — المركبات العضوية وتكوّن النفط والخلاصة')
