from (values
('mcq', 1, 3, 'المصدران الرئيسان للهيدروكربونات هما النفط والغاز الطبيعي، ومنهما يُحصل على الوقود والمواد الخام لكثير من الصناعات.', '["الهواء ومياه البحار لا يحتويان على الهيدروكربونات بكميات تجعلهما مصدرًا لها.","المخلوقات الحية تنتج مركبات عضوية، لكن الهيدروكربونات تُستخرج أساسًا من النفط والغاز الطبيعي.","الصخور الجيرية كربونات (مواد غير عضوية)، والرمال لا تحتوي على الكربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('mcq', 2, 0, 'الجازولين والديزل من مشتقات النفط التي تُفصل عنه بالتقطير التجزيئي؛ فالنفط خليط معقد يحتوي على هيدروكربونات كبيرة الجزيئات، أما الغاز الطبيعي فيتكون أساسًا من الميثان مع كميات ضئيلة من هيدروكربونات تحتوي على 2 إلى 5 ذرات كربون.', '["","الغاز الطبيعي يتكون أساسًا من الميثان وهيدروكربونات صغيرة (2 إلى 5 ذرات كربون)، والجازولين يحتوي على 5 إلى 12 ذرة كربون.","الفحم الحجري ليس أحد المصدرين الرئيسين للهيدروكربونات.","الغاز الحيوي خليط من الميثان وثاني أكسيد الكربون، ولا يُنتج منه الجازولين أو الديزل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('mcq', 3, 1, 'النفط والغاز الطبيعي يتشكلان معًا في الوقت نفسه وبالطريقة نفسها من بقايا المخلوقات الحية التي عاشت في المحيطات، بفعل حرارة باطن الأرض وضغط الرواسب؛ فكلاهما وقود أحفوري.', '["المصدران تكوّنا في القشرة الأرضية من بقايا مخلوقات حية، لا من غازات الهواء.","","تكوّنهما استغرق ملايين السنين، فلا يتجددان خلال سنوات قليلة.","أصلهما عضوي من بقايا المخلوقات الحية، لا من الصهارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.533Z"}'::jsonb),
('mcq', 4, 2, 'العينة (س) يغلب عليها الميثان مع كميات ضئيلة من هيدروكربونات تحتوي على 2 إلى 5 ذرات كربون، وهذا وصف الغاز الطبيعي. أما (ص) فخليط معقد من أكثر من ألف مركب يُفصل بالتقطير التجزيئي، وهذا وصف النفط. إذن (س) غاز طبيعي و(ص) نفط.', '["عُكس الوصفان؛ فالخليط المعقد من أكثر من ألف مركب هو النفط، لا العينة (س).","العينة (س) يغلب عليها الميثان، وهذا وصف الغاز الطبيعي لا النفط.","","العينة (ص) خليط معقد من أكثر من ألف مركب يُفصل بالتقطير التجزيئي، وهذا وصف النفط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('mcq', 5, 1, 'الغاز الطبيعي يتكون أساسًا من الميثان مع كميات ضئيلة من هيدروكربونات صغيرة، أما النفط فخليط معقد يحتوي على أكثر من ألف مركب؛ لذا فالنفط أعقد تركيبًا من الغاز الطبيعي الذي يغلب عليه الميثان.', '["عُكست المقارنة؛ فالنفط هو الخليط المعقد، والغاز الطبيعي هو الذي يغلب عليه الميثان.","","كلاهما خليط من هيدروكربونات متعددة، وليس أي منهما مادة نقية.","الخليط الذي يضم أكثر من ألف مركب ويُفصل بالتقطير التجزيئي هو النفط، أما الغاز الطبيعي فيغلب عليه الميثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('mcq', 6, 3, 'المصدران الرئيسان للهيدروكربونات هما النفط والغاز الطبيعي. والغاز الطبيعي يوجد عادة مصاحبًا لترسبات النفط، ويتكوّن بصورة أساسية من الميثان؛ فالمصدر المقصود هو الغاز الطبيعي.', '["الكيروسين من مشتقات النفط التي تُفصل بالتقطير التجزيئي، وليس مصدرًا طبيعيًّا قائمًا بذاته، ولا يغلب عليه الميثان.","الجازولين من مشتقات النفط (هيدروكربونات من 5 إلى 12 ذرة كربون)، وليس مصدرًا طبيعيًّا يغلب عليه الميثان.","النفط الخام خليط معقد من أكثر من ألف مركب، والمصدر الذي يصاحبه ويغلب عليه الميثان هو الغاز الطبيعي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('mcq', 7, 0, 'غاز الطهي في المنازل يُحصل عليه من الغاز الطبيعي (ومكوّنه الرئيس الميثان من أجود أنواع الوقود) أو من الغازات الخفيفة المفصولة من النفط، والجازولين يُفصل من النفط؛ فكلاهما من المصدرين الرئيسين للهيدروكربونات: النفط والغاز الطبيعي.', '["","الخشب والفحم النباتي مصدرهما الأشجار، لا النفط أو الغاز الطبيعي.","الغاز الحيوي يُنتج من المخلفات العضوية بفعل البكتيريا، والخشب من الأشجار.","الكحول من قصب السكر مصدره نباتي، والفحم النباتي من الخشب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المصدران الرئيسان هما النفط والغاز الطبيعي. ومن استخدامات النفط: الحصول على الجازولين والديزل لتسيير السيارات (أو الكيروسين أو زيوت التزييت أو المواد الخام للبلاستيك). ومن استخدامات الغاز الطبيعي: وقود للطهي والتدفئة في المنازل.', '["النفط","الغاز الطبيعي","استخدام صحيح للنفط","استخدام صحيح للغاز الطبيعي"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية النفط","marks":1},{"element":"تسمية الغاز الطبيعي","marks":1},{"element":"استخدام لكل منهما","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"تسمية المصدرين دون استخدامات صحيحة"},{"level":"1 درجة","description":"تسمية مصدر واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الفحم الحجري أو الخشب مصدرًا رئيسًا","ذكر المخلوقات الحية مصدرًا رئيسًا للهيدروكربونات في الصناعة","ذكر استخدام للنفط على أنه للغاز الطبيعي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التركيب: الغاز الطبيعي يتكون بصورة أساسية من الميثان مع كميات ضئيلة من هيدروكربونات تحتوي على 2 إلى 5 ذرات كربون، أما النفط فخليط معقد يحتوي على أكثر من ألف مركب. طريقة التكوّن: يتشكلان معًا في الوقت نفسه وبالطريقة نفسها من بقايا مخلوقات حية بفعل حرارة باطن الأرض وضغط الرواسب. الفصل: النفط قليلًا ما يُستخدم في صورته الخام، ويُفصل إلى مكوّنات أبسط بالتقطير التجزيئي، بينما يغلب على الغاز الطبيعي مكوّن واحد هو الميثان.', '["تركيب الغاز الطبيعي: ميثان أساسًا","تركيب النفط: خليط معقد من أكثر من ألف مركب","التكوّن: معًا وبالطريقة نفسها من بقايا مخلوقات حية","النفط يُفصل بالتقطير التجزيئي"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة التركيب","marks":2},{"element":"طريقة التكوّن","marks":1},{"element":"الفصل قبل الاستعمال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانبين"},{"level":"1 درجة","description":"مقارنة صحيحة في جانب واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس التركيب بين النفط والغاز الطبيعي","القول إن الغاز الطبيعي ميثان نقي تمامًا","القول إن لكل منهما طريقة تكوّن مختلفة تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. فالمصدران الرئيسان للهيدروكربونات اليوم هما النفط والغاز الطبيعي. صحيح أن أصلهما بقايا مخلوقات حية، لكنها مخلوقات عاشت في المحيطات منذ ملايين السنين ثم تحولت بفعل الحرارة والضغط إلى نفط وغاز طبيعي، لا مخلوقات حية حاضرة. كما أن المركبات العضوية لا يقتصر مصدرها على المخلوقات الحية؛ فهي تُحضّر أيضًا في المختبر منذ تجربة فوهلر.', '["الحكم: العبارة غير صحيحة","المصدران الرئيسان: النفط والغاز الطبيعي","أصلهما بقايا مخلوقات قديمة تحولت عبر ملايين السنين","المركبات العضوية تُحضّر في المختبر أيضًا"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة","marks":1},{"element":"تسمية المصدرين الرئيسين","marks":1},{"element":"توضيح أصلهما القديم","marks":1},{"element":"نقض فكرة أن مصدر المركبات العضوية المخلوقات الحية فقط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"حكم صحيح مع تسمية المصدرين وتعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة لأن النفط أصله مخلوقات حية","إغفال الفرق بين المخلوقات الحية الحاضرة والبقايا القديمة","عدم تسمية المصدرين الرئيسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb)
