from (values
('mcq', 1, 2, 'يتكون الغاز الطبيعي بصورة أساسية من الميثان CH₄، أبسط الهيدروكربونات، مع كميات ضئيلة من هيدروكربونات أخرى تحتوي على 2 إلى 5 ذرات كربون.', '["البروبان (3 ذرات كربون) من الهيدروكربونات الموجودة بكميات ضئيلة في الغاز الطبيعي.","البيوتان (4 ذرات كربون) يوجد بكميات ضئيلة فقط في الغاز الطبيعي.","","الإيثان (ذرتا كربون) يوجد بكميات ضئيلة، والمكوّن الرئيس هو الميثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-07T17:19:00.534Z"}'::jsonb),
('mcq', 2, 1, 'في النموذج كرة سوداء واحدة (ذرة كربون) ترتبط بأربع كرات بيضاء (ذرات هيدروجين)؛ فالصيغة الجزيئية CH₄، وهو الميثان، المكوّن الرئيس للغاز الطبيعي.', '["في النموذج ذرة كربون واحدة لا ذرتان؛ فالإيثان C₂H₆ يحتاج إلى كرتين سوداوين.","","الصيغة CH₄ صحيحة لكن اسمها الميثان؛ أما الإيثان فصيغته C₂H₆.","في النموذج ذرة كربون واحدة وأربع ذرات هيدروجين، أما الإيثين C₂H₄ ففيه ذرتا كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('mcq', 3, 0, 'يتكوّن الغاز الطبيعي بصورة أساسية من الميثان، لكنه يحتوي أيضًا على كميات ضئيلة من أنواع أخرى من الهيدروكربونات تحتوي على 2 إلى 5 ذرات كربون.', '["","الميثان هو الغالب، والهيدروكربونات الأخرى موجودة بكميات ضئيلة لا بنسب متساوية.","الغاز الطبيعي ليس ميثانًا نقيًّا؛ ففيه كميات ضئيلة من هيدروكربونات أخرى.","الهيدروكربونات التي تحتوي على 5 إلى 12 ذرة كربون هي مكونات الجازولين لا الغاز الطبيعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('mcq', 4, 2, 'المكوّن الرئيس للغاز الطبيعي هو الميثان CH₄، ويتكون جزيئه من ذرة كربون واحدة متحدة بأربع ذرات هيدروجين؛ فالعدد 4.', '["ذرة الكربون تكوّن أربع روابط تساهمية، فترتبط في الميثان بأربع ذرات هيدروجين لا باثنتين.","ثلاث ذرات هيدروجين لا تكمل الروابط الأربع لذرة الكربون في الميثان.","","6 هو عدد ذرات الهيدروجين في الإيثان C₂H₆ لا في الميثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('mcq', 5, 0, 'الغاز الطبيعي يتكون بصورة أساسية من الميثان مع كميات ضئيلة من هيدروكربونات تحتوي على 2 إلى 5 ذرات كربون، وهذا يطابق العينة (1). فالعينة (1) هي الأرجح أن تكون غازًا طبيعيًّا.', '["","العينة (2) هي الهواء الجوي تقريبًا (نيتروجين وأكسجين) ولا تحتوي على هيدروكربونات.","العينة (3) يغلب عليها CO₂ مع الميثان، وهذا أقرب إلى الغاز الحيوي الناتج من المخلفات، لا الغاز الطبيعي.","العينة (4) أبخرة هيدروكربونات من 5 إلى 12 ذرة كربون، وهي مكونات الجازولين لا الغاز الطبيعي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('mcq', 6, 3, 'يُعدّ جزيء الميثان CH₄ أبسط جزيء هيدروكربوني؛ لأن جزيئه يحتوي على ذرة كربون واحدة فقط متحدة بأربع ذرات هيدروجين، ولا يوجد هيدروكربون بعدد ذرات أقل.', '["الهيدروجين H₂ أخف من الميثان، والبساطة هنا تتعلق بتركيب الجزيء لا بخفته.","ذرة الكربون في الميثان ترتبط بأربع روابط تساهمية مع ذرات الهيدروجين.","الميثان يحترق، وهو من أجود أنواع الوقود؛ فهذه العبارة خاطئة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('mcq', 7, 1, 'المكوّن الرئيس للغاز الطبيعي هو الميثان CH₄، وهو أبسط الهيدروكربونات، ويتكوّن جزيئه من ذرة كربون واحدة متحدة بأربع ذرات هيدروجين، ويُعدّ من أجود أنواع الوقود.', '["المكوّن الرئيس هو الميثان، وهو مركب عضوي (هيدروكربون)؛ والحالة الفيزيائية لا تحدد كون المركب عضويًّا.","","الميثان فيه ذرة كربون واحدة فقط، فلا توجد فيه رابطة بين ذرتي كربون أصلًا.","الهيدروكربونات من 5 إلى 12 ذرة كربون مكونات الجازولين، أما المكوّن الرئيس للغاز الطبيعي فهو الميثان CH₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المكوّن الرئيس للغاز الطبيعي هو الميثان، وصيغته الجزيئية CH₄. صيغته البنائية: ذرة C في الوسط ترتبط بخط واحد (رابطة تساهمية أحادية) بكل من أربع ذرات H. ويُعدّ أبسط الهيدروكربونات لأن جزيئه يتكون من ذرة كربون واحدة فقط متحدة بأربع ذرات هيدروجين.', '["الاسم: الميثان","الصيغة الجزيئية CH₄","الصيغة البنائية: C مرتبطة بأربع ذرات H بروابط أحادية","التفسير: ذرة كربون واحدة وأربع ذرات هيدروجين"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم","marks":1},{"element":"الصيغة الجزيئية","marks":1},{"element":"الصيغة البنائية","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"الاسم والصيغة الجزيئية صحيحان مع نقص في الصيغة البنائية أو التفسير"},{"level":"1 درجة","description":"ذكر الاسم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة CH₂ أو C₂H₆","رسم الصيغة البنائية بروابط ثنائية","تفسير البساطة بأن الميثان أخف الغازات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المكوّن الرئيس هو الميثان، وصيغته الجزيئية CH₄. (ب) لأن الغاز الطبيعي يتكوّن بصورة أساسية من الميثان، لكنه يحتوي أيضًا على كميات ضئيلة من أنواع أخرى من الهيدروكربونات تحتوي على 2 إلى 5 ذرات كربون؛ فهو خليط لا مادة نقية. (ج) مثل C₂H₆ (ذرتا كربون)، أو C₃H₈ (3 ذرات كربون)، أو C₄H₁₀ (4 ذرات كربون)؛ أي هيدروكربون فيه من 2 إلى 5 ذرات كربون.', '["الاسم: الميثان","الصيغة الجزيئية CH₄","الغاز الطبيعي خليط: ميثان أساسًا مع هيدروكربونات من 2 إلى 5 ذرات كربون","صيغة صحيحة لهيدروكربون من 2 إلى 5 ذرات كربون"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم والصيغة الجزيئية","marks":2},{"element":"تعليل أن الغاز الطبيعي ليس مادة نقية","marks":1},{"element":"صيغة هيدروكربون آخر وعدد ذرات الكربون فيه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"الاسم والصيغة صحيحان مع نقص في التعليل أو في الجزء (ج)"},{"level":"1 درجة","description":"ذكر الاسم أو الصيغة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الغاز الطبيعي ميثان نقي تمامًا","كتابة صيغة هيدروكربون من مكونات الجازولين (5 إلى 12 ذرة كربون) مثل C₈H₁₈","كتابة الصيغة CH₂ أو C₂H₆ للميثان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المكوّن المشترك: الميثان CH₄، وهو الذي يحترق فيزوّد بالطاقة في كليهما. المصدر: الغاز الطبيعي وقود أحفوري تكوّن في باطن الأرض مع النفط من بقايا مخلوقات حية عبر ملايين السنين، أما الغاز الحيوي فتنتجه البكتيريا غير الهوائية من تحليل المخلفات العضوية في جهاز الهضم. المكوّن الآخر: في الغاز الطبيعي كميات ضئيلة من هيدروكربونات تحتوي على 2 إلى 5 ذرات كربون، وفي الغاز الحيوي ثاني أكسيد الكربون CO₂ الذي لا يحترق.', '["الميثان مكوّن مشترك يجعلهما وقودًا","مصدر الغاز الطبيعي: أحفوري في باطن الأرض","مصدر الغاز الحيوي: تحليل المخلفات بالبكتيريا","المكوّن الآخر: هيدروكربونات C2–C5 مقابل CO₂"]'::jsonb, '[]'::jsonb, '[{"element":"المكوّن المشترك","marks":1},{"element":"مقارنة المصدر","marks":2},{"element":"مقارنة المكوّن الآخر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تحديد الميثان مع مقارنة صحيحة في جانب واحد آخر"},{"level":"1 درجة","description":"تحديد الميثان مكوّنًا مشتركًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن CO₂ في الغاز الحيوي يحترق ويزوّد بالطاقة","عدّ الغاز الحيوي وقودًا أحفوريًّا","القول إن الغاز الطبيعي ميثان نقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.535Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
