('mcq', 2, 'ما المركب العضوي الذي حضّره فوهلر في المختبر لأول مرة؟', null, null, '["الميثان","الجلوكوز","اليوريا","حمض الطرطريك"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 159 — س46 (اليوريا)'),
