('mcq', 4, 'ما أهمية تجربة فوهلر في تاريخ الكيمياء العضوية؟', null, null, '["أثبتت أن المركبات العضوية لا تحتوي على عنصر الكربون","أثبتت إمكان تحضير مركب عضوي في المختبر، فمهّدت لدحض فكرة القوة الحيوية","أثبتت أن ذرة الكربون تكوّن أربع روابط تساهمية فقط","أكدت أن المركبات العضوية لا تُحضَّر إلا داخل المخلوقات الحية"]'::jsonb, 'فهم', 'تفسير أهمية', 'متوسط', 'الكتاب ص 120 — دحض فكرة القوة الحيوية (فوهلر)'),
('mcq', 5, 'يبين الشكل الآتي الصيغة البنائية لمركب عضوي. ما اسم هذا المركب، ومَن العالم الذي كان أول من حضّره في المختبر؟', null, '[{"src":"qimg/chem22/c4-l1a-urea.svg","alt":"صيغة بنائية لجزيء: ذرة C في الوسط ترتبط برابطة ثنائية بذرة O في الأعلى، وبرابطة أحادية بمجموعة H₂N على اليسار، وبرابطة أحادية بمجموعة NH₂ على اليمين."}]'::jsonb, '["الميثان، وحضّره فريدريك فوهلر","اليوريا، وحضّره جون دالتون","اليوريا، وحضّره فريدريك فوهلر","الجلوكوز، وحضّره فريدريك فوهلر"]'::jsonb, 'تذكر', 'قراءة صيغة بنائية', 'متوسط', 'الكتاب ص 159 — س46 (الشكل 4-29)'),
('mcq', 6, 'أيّ العبارات الآتية تصف بدقة ما حدث لفكرة القوة الحيوية بعد تجربة فوهلر؟', null, null, '["تخلّى عنها العلماء جميعًا في اليوم الذي أُعلنت فيه نتيجة التجربة","رفض العلماء التجربة فبقيت الفكرة مقبولة علميًّا حتى اليوم","أكدت التجربة صحة الفكرة فتوقف العلماء عن محاولة تحضير المركبات العضوية","لم تُدحض فورًا، لكن التجربة حثّت كيميائيين آخرين على تجارب مشابهة حتى ثبت بطلانها"]'::jsonb, 'فهم', 'وصف تطور فكرة علمية', 'صعب', 'الكتاب ص 120 — دحض فكرة القوة الحيوية (فوهلر)'),
('mcq', 7, 'أيّ مما يأتي يصف العالم فريدريك فوهلر وصفًا صحيحًا؟', null, null, '["عالم كيمياء فرنسي عاش بين عامي 1822 و1895م","عالم كيمياء ألماني عاش بين عامي 1800 و1882م","عالم كيمياء إنجليزي عاش بين عامي 1766 و1844م","مستثمر أمريكي حفر أول بئر نفط عام 1859م"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'صعب', 'الكتاب ص 120 — دحض فكرة القوة الحيوية (فوهلر)'),
('essay', 1, 'مَن أول عالم حضّر مركبًا عضويًّا في المختبر؟ وما المركب الذي حضّره؟ وفي أيّ عام؟', null, null, null, 'تذكر', 'استرجاع حقائق', 'سهل', 'الكتاب ص 120، ص 159 — فوهلر واليوريا'),
('essay', 2, 'يبين الشكل الآتي الصيغة البنائية لأول مركب عضوي حُضّر في المختبر. (أ) ما اسم المركب، ومَن حضّره؟ (ب) هل يُعدّ هذا المركب عضويًّا وفق التعريف الحديث؟ فسّر إجابتك.', null, '[{"src":"qimg/chem22/c4-l1a-urea.svg","alt":"صيغة بنائية لجزيء: ذرة C في الوسط ترتبط برابطة ثنائية بذرة O في الأعلى، وبرابطة أحادية بمجموعة H₂N على اليسار، وبرابطة أحادية بمجموعة NH₂ على اليمين."}]'::jsonb, null, 'فهم', 'تعرّف وتفسير', 'متوسط', 'الكتاب ص 121، ص 159 — تعريف المركب العضوي، وس46'),
