from (values
('mcq', 1, 3, 'كان فريدريك فوهلر (1800–1882م)، عالم الكيمياء الألماني، أول من قام بتحضير مركب عضوي في المختبر.', '["دالتون صاحب النظرية الذرية في بداية القرن التاسع عشر، ولم يحضّر مركبًا عضويًّا.","باستور درس بلورات حمض الطرطريك والكيرالية، ولم يكن أول من حضّر مركبًا عضويًّا.","إدوين دريك حفر أول بئر نفط عام 1859م، ولا علاقة له بتحضير المركبات العضوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('mcq', 2, 2, 'حضّر فريدريك فوهلر اليوريا في المختبر لأول مرة عام 1828م، فكانت أول مركب عضوي يُحضَّر في المختبر.', '["الميثان هو المكوّن الرئيس للغاز الطبيعي، وليس المركب الذي حضّره فوهلر.","الجلوكوز مركب عضوي لكنه ليس المركب الذي حضّره فوهلر.","","حمض الطرطريك درس باستور بلوراته، ولم يحضّره فوهلر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('mcq', 3, 0, 'حضّر فريدريك فوهلر اليوريا لأول مرة عام 1828م.', '["","1848م عام دراسة لويس باستور بلورات حمض الطرطريك.","1859م عام حفر إدوين دريك أول بئر نفط.","1882م عام وفاة فوهلر، وهو أيضًا عام اختراع إديسون المصباح الكهربائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('mcq', 4, 1, 'كان يُعتقد أن تصنيع المركبات العضوية يحتاج إلى قوة حيوية لا توجد إلا في المخلوقات الحية؛ فلما حضّر فوهلر مركبًا عضويًّا في المختبر أثبت إمكان ذلك، ومهّد لدحض فكرة القوة الحيوية.', '["المركبات العضوية تحتوي على الكربون، وتجربة فوهلر لم تتناول هذا.","","تكوين الكربون أربع روابط يُفسَّر بإلكترونات تكافئه الأربعة، وليس هو ما أثبتته تجربة فوهلر.","هذه هي فكرة القوة الحيوية نفسها، وتجربة فوهلر ناقضتها لا أكدتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('mcq', 5, 2, 'في الشكل ذرة C ترتبط برابطة ثنائية بذرة O وبمجموعتي NH₂، وهذه صيغة اليوريا، وهي أول مركب عضوي حُضّر في المختبر؛ حضّرها العالم الألماني فريدريك فوهلر عام 1828م.', '["الميثان CH₄ لا يحتوي على أكسجين أو نيتروجين، أما المركب في الشكل ففيه C=O ومجموعتا NH₂.","المركب هو اليوريا، لكن دالتون صاحب النظرية الذرية لم يحضّرها؛ حضّرها فوهلر.","","الجلوكوز لا يحتوي على نيتروجين، والمركب في الشكل فيه مجموعتا NH₂؛ فهو اليوريا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('mcq', 6, 3, 'لم تدحض تجربة فوهلر على الفور فكرة القوة الحيوية، لكنها حثّت كيميائيين أوروبيين آخرين على القيام بسلسلة من التجارب المشابهة، وأخيرًا ثبت بطلان الفكرة القائلة إن تحضير المركبات العضوية يحتاج إلى قوة حيوية.', '["الفكرة لم تُدحض على الفور، بل احتاج ذلك إلى سلسلة من التجارب اللاحقة.","فكرة القوة الحيوية ثبت بطلانها، والعلماء اليوم يحضّرون ملايين المركبات العضوية.","التجربة ناقضت الفكرة ولم تؤكدها، وتبعتها تجارب أخرى لتحضير المركبات العضوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('mcq', 7, 1, 'فريدريك فوهلر (1800–1882م) عالم الكيمياء الألماني الذي كان أول من حضّر مركبًا عضويًّا في المختبر.', '["هذا وصف ينطبق على لويس باستور الفرنسي، لا على فوهلر الألماني.","","هذا وصف ينطبق على جون دالتون الإنجليزي صاحب النظرية الذرية.","هذا وصف إدوين دريك الذي حفر أول بئر نفط في بنسلفانيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العالم الألماني فريدريك فوهلر (1800–1882م)، حضّر اليوريا عام 1828م.', '["فريدريك فوهلر","اليوريا","عام 1828م"]'::jsonb, '[]'::jsonb, '[{"element":"اسم العالم","marks":1},{"element":"اسم المركب","marks":1},{"element":"العام","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابتان صحيحتان من ثلاث"},{"level":"1 درجة","description":"إجابة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر دالتون أو باستور بدل فوهلر","ذكر الميثان بدل اليوريا","ذكر عام 1882م (عام وفاة فوهلر) بدل 1828م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المركب هو اليوريا، وحضّره العالم الألماني فريدريك فوهلر عام 1828م. (ب) نعم، اليوريا مركب عضوي؛ لأنها تحتوي على الكربون، وليست من أكاسيد الكربون ولا الكربيدات ولا الكربونات.', '["اسم المركب: اليوريا","من حضّره: فوهلر","الحكم: عضوي","التفسير: يحتوي على الكربون وليس من الفئات المستثناة"]'::jsonb, '[]'::jsonb, '[{"element":"اسم المركب","marks":1},{"element":"اسم العالم","marks":1},{"element":"الحكم والتفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تسمية صحيحة مع حكم دون تفسير كامل"},{"level":"1 درجة","description":"إجابة صحيحة لجزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ اليوريا غير عضوية لاحتوائها على الأكسجين أو النيتروجين","عدّها كربونات لوجود C=O","ذكر عالم آخر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قبل تجربة فوهلر كان كثير من العلماء يعتقدون خطأً أن عجزهم عن تصنيع المركبات العضوية عائد إلى القوة الحيوية؛ أي أن المخلوقات الحية وحدها لها قوة غامضة تمكّنها من تركيب مركبات الكربون. وعندما حضّر فوهلر اليوريا في المختبر عام 1828م أثبت إمكان تحضير مركب عضوي خارج المخلوقات الحية. لم تُدحض الفكرة فورًا، لكن التجربة حثّت كيميائيين آخرين على تجارب مشابهة حتى ثبت بطلانها، فأدرك العلماء أن باستطاعتهم تحضير المركبات العضوية؛ وهكذا تطورت الكيمياء العضوية، وأصبح الكيميائيون يحضّرون مزيدًا من المركبات كل يوم.', '["فكرة القوة الحيوية قبل التجربة","تحضير اليوريا في المختبر أثبت الإمكان","الدحض لم يكن فوريًّا بل عبر تجارب لاحقة","أدرك العلماء قدرتهم على التحضير فتطورت الكيمياء العضوية"]'::jsonb, '[]'::jsonb, '[{"element":"شرح فكرة القوة الحيوية","marks":1},{"element":"ما أثبتته تجربة فوهلر","marks":1},{"element":"التجارب اللاحقة وبطلان الفكرة","marks":1},{"element":"أثر ذلك في تطور الكيمياء العضوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"شرح صحيح لمعظم العناصر مع نقص في عنصر"},{"level":"1 درجة","description":"ذكر أن فوهلر حضّر مركبًا عضويًّا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفكرة دُحضت فورًا","عدم ذكر فكرة القوة الحيوية","الخلط بين فوهلر ودالتون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.536Z"}'::jsonb)
