from (values
('mcq', 1, 'كم إلكترون تكافؤ لذرة الكربون؟ وما أثر ذلك في الروابط التي تكوّنها؟', null, null, '["إلكترونا تكافؤ؛ فتكوّن رابطتين تساهميتين","ستة إلكترونات تكافؤ؛ فتكوّن ست روابط تساهمية","أربعة إلكترونات تكافؤ؛ فتكوّن أربع روابط تساهمية","أربعة إلكترونات تكافؤ؛ فتفقدها مكوّنة أيونًا موجبًا"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)'),
('mcq', 2, 'ما خاصية الكربون التي يوضحها الشكل الآتي؟', null, '[{"src":"qimg/chem22/c4-l1a-chains.svg","alt":"ثلاثة هياكل مرقمة لذرات الكربون فقط (ذرات الهيدروجين غير مرسومة)، وكل الروابط بين ذرات الكربون مفردة. (1) خمس ذرات C متصلة في خط واحد متتابع. (2) أربع ذرات C متصلة في خط أفقي، وتتصل بالذرة الثانية من اليسار ذرة C إضافية من أعلى، وتتصل بالذرة الثالثة من اليسار ذرة C إضافية من أسفل؛ فمجموع ذرات الكربون ست. (3) ست ذرات C متصلة على هيئة شكل سداسي مغلق."}]'::jsonb, '["ارتباط ذرات الكربون بعضها ببعض في سلاسل مستقيمة ومتفرعة وحلقات","تكوين ذرات الكربون أيونات موجبة تتجاذب مع أيونات سالبة","ارتباط ذرة الكربون بذرات الهالوجينات والنيتروجين","تكوين ذرات الكربون روابط ثنائية وثلاثية فيما بينها"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)'),
('mcq', 3, 'يبين الشكل الآتي ثلاث طرائق لارتباط ذرتي كربون. ما عدد الإلكترونات المشتركة بين ذرتي الكربون في الجزء (3)؟', null, '[{"src":"qimg/chem22/c4-l1a-bonds.svg","alt":"ثلاثة أجزاء مرقمة، في كل منها ذرتا كربون متجاورتان مرسومتان بطريقتين: في الصف العلوي بالنقاط (النقاط السوداء إلكترونات ذرة الكربون اليسرى، والنقاط الزرقاء إلكترونات ذرة الكربون اليمنى)، وفي الصف السفلي بالخطوط. (1) بين الذرتين نقطة سوداء ونقطة زرقاء، ولكل ذرة ثلاث نقاط أخرى منفردة؛ وبالخطوط: خط واحد بين الذرتين وثلاثة خطوط أخرى من كل ذرة. (2) بين الذرتين نقطتان سوداوان ونقطتان زرقاوان، ولكل ذرة نقطتان أخريان؛ وبالخطوط: خطان متوازيان بين الذرتين وخطان آخران من كل ذرة. (3) بين الذرتين ثلاث نقاط سوداء وثلاث نقاط زرقاء، ولكل ذرة نقطة أخرى واحدة؛ وبالخطوط: ثلاثة خطوط متوازية بين الذرتين وخط آخر واحد من كل ذرة."}]'::jsonb, '["2","3","4","6"]'::jsonb, 'تطبيق', 'قراءة تمثيل لويس', 'متوسط', 'الكتاب ص 122، ص 159 — الروابط المضاعفة بين ذرات الكربون (الشكل 4-5، س45)'),
('mcq', 4, 'ما الذي يدل عليه التوزيع الإلكتروني لذرة الكربون 1s²2s²2p² فيما يتعلق بتكوين مركباتها؟', null, null, '["أنها تكتسب أربعة إلكترونات فتكوّن أيونًا سالبًا","أنها تشارك دائمًا بإلكترونات تكافئها الأربعة في روابط تساهمية","أنها تفقد إلكترونَي 2s فقط فتكوّن أيونًا موجبًا","أنها لا تكوّن روابط لأن مستوى طاقتها الخارجي ممتلئ"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)'),
('mcq', 5, 'في المركبات العضوية، تتحد ذرات الكربون مع ذرات الهيدروجين، وكذلك مع ذرات عناصر أخرى قريبة منها في الجدول الدوري، وخصوصًا:', null, null, '["الصوديوم والبوتاسيوم والمغنيسيوم والكالسيوم","الهيليوم والنيون والأرجون والكريبتون","الحديد والنحاس والخارصين والفضة","النيتروجين والأكسجين والكبريت والفوسفور والهالوجينات"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)'),
('mcq', 6, 'لماذا تستطيع ذرات الكربون تكوين سلاسل طويلة متصلة، في حين لا تستطيع ذرات الهيدروجين ذلك؟', null, null, '["لأن ذرة الهيدروجين أكبر حجمًا من ذرة الكربون","لأن الهيدروجين يكوّن روابط أيونية فقط مع العناصر الأخرى","لأن ذرة الكربون تكوّن أربع روابط، وذرة الهيدروجين تكوّن رابطة واحدة فقط","لأن ذرة الهيدروجين لها أربعة إلكترونات تكافؤ كالكربون"]'::jsonb, 'فهم', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)'),
('mcq', 7, 'في التركيب (2) من الشكل الآتي، كم ذرة هيدروجين يلزم ربطها بذرة الكربون الثانية من اليسار (المرتبطة بالفرع العلوي) لتكمل روابطها الأربع، علمًا أن جميع الروابط أحادية؟', null, '[{"src":"qimg/chem22/c4-l1a-chains.svg","alt":"ثلاثة هياكل مرقمة لذرات الكربون فقط (ذرات الهيدروجين غير مرسومة)، وكل الروابط بين ذرات الكربون مفردة. (1) خمس ذرات C متصلة في خط واحد متتابع. (2) أربع ذرات C متصلة في خط أفقي، وتتصل بالذرة الثانية من اليسار ذرة C إضافية من أعلى، وتتصل بالذرة الثالثة من اليسار ذرة C إضافية من أسفل؛ فمجموع ذرات الكربون ست. (3) ست ذرات C متصلة على هيئة شكل سداسي مغلق."}]'::jsonb, '["0","1","2","3"]'::jsonb, 'تطبيق', 'تطبيق قاعدة الروابط الأربع', 'صعب', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)'),
('essay', 1, 'ما خواص عنصر الكربون المسؤولة عن التنوع الهائل في المركبات العضوية؟ اذكر ثلاثًا منها مع توضيح أثر كل منها.', null, null, null, 'فهم', 'تعداد وتوضيح', 'متوسط', 'الكتاب ص 121–122، ص 159 — خواص الكربون، وس40'),
('essay', 2, 'يبين الشكل الآتي ثلاث طرائق لارتباط ذرتي كربون. اكتب لكل جزء: نوع الرابطة بين ذرتي الكربون، وعدد الإلكترونات المشتركة بينهما، وعدد الروابط الأخرى التي يمكن أن تكوّنها كل ذرة كربون مع ذرات أخرى.', null, '[{"src":"qimg/chem22/c4-l1a-bonds.svg","alt":"ثلاثة أجزاء مرقمة، في كل منها ذرتا كربون متجاورتان مرسومتان بطريقتين: في الصف العلوي بالنقاط (النقاط السوداء إلكترونات ذرة الكربون اليسرى، والنقاط الزرقاء إلكترونات ذرة الكربون اليمنى)، وفي الصف السفلي بالخطوط. (1) بين الذرتين نقطة سوداء ونقطة زرقاء، ولكل ذرة ثلاث نقاط أخرى منفردة؛ وبالخطوط: خط واحد بين الذرتين وثلاثة خطوط أخرى من كل ذرة. (2) بين الذرتين نقطتان سوداوان ونقطتان زرقاوان، ولكل ذرة نقطتان أخريان؛ وبالخطوط: خطان متوازيان بين الذرتين وخطان آخران من كل ذرة. (3) بين الذرتين ثلاث نقاط سوداء وثلاث نقاط زرقاء، ولكل ذرة نقطة أخرى واحدة؛ وبالخطوط: ثلاثة خطوط متوازية بين الذرتين وخط آخر واحد من كل ذرة."}]'::jsonb, null, 'تطبيق', 'قراءة تمثيل وحساب', 'متوسط', 'الكتاب ص 122، ص 159 — الشكل 4-5، وس45'),
('essay', 3, 'استعن بالتراكيب الثلاثة في الشكل الآتي لتوضيح كيف تؤدي قدرة الكربون على تكوين السلاسل والتفرعات والحلقات إلى تعدد المركبات. احسب عدد ذرات الهيدروجين اللازمة لإكمال روابط الكربون في كل تركيب (جميع الروابط أحادية)، واكتب الصيغة الجزيئية لكل منها.', null, '[{"src":"qimg/chem22/c4-l1a-chains.svg","alt":"ثلاثة هياكل مرقمة لذرات الكربون فقط (ذرات الهيدروجين غير مرسومة)، وكل الروابط بين ذرات الكربون مفردة. (1) خمس ذرات C متصلة في خط واحد متتابع. (2) أربع ذرات C متصلة في خط أفقي، وتتصل بالذرة الثانية من اليسار ذرة C إضافية من أعلى، وتتصل بالذرة الثالثة من اليسار ذرة C إضافية من أسفل؛ فمجموع ذرات الكربون ست. (3) ست ذرات C متصلة على هيئة شكل سداسي مغلق."}]'::jsonb, null, 'تحليل', 'تحليل تراكيب وحساب', 'صعب', 'الكتاب ص 121 — الكيمياء العضوية (خواص ذرة الكربون)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L1-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الكربون في المجموعة 14، وتوزيعه الإلكتروني 1s²2s²2p²؛ فله أربعة إلكترونات تكافؤ (2s²2p²) يشارك بها دائمًا، فيكوّن أربع روابط تساهمية.', '["عُدّت إلكترونات 2p فقط، مع أن إلكترونات التكافؤ تشمل 2s و2p (أربعة).","6 هو عدد إلكترونات ذرة الكربون كلها، لا إلكترونات التكافؤ.","","الكربون يشارك بإلكتروناته الأربعة في روابط تساهمية، ولا يفقدها مكوّنًا أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('mcq', 2, 0, 'يبين الشكل ذرات كربون مرتبطة بعضها ببعض في سلسلة مستقيمة (1)، وسلسلة متفرعة (2)، وحلقة (3)؛ وهذه الخاصية من أسباب تكوين الكربون عددًا هائلًا من المركبات.', '["","الروابط في الشكل تساهمية بين ذرات الكربون، ولا توجد أيونات.","الشكل لا يحتوي إلا على ذرات كربون، فلا يوضح ارتباطه بالهالوجينات أو النيتروجين.","جميع الروابط في الشكل أحادية، فهو لا يوضح الروابط الثنائية أو الثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('mcq', 3, 3, 'في الجزء (3) ثلاثة أزواج من الإلكترونات بين ذرتي الكربون (رابطة ثلاثية)، وكل زوج إلكترونان؛ فعدد الإلكترونات المشتركة 3 × 2 = 6.', '["2 هو عدد الإلكترونات في الرابطة الأحادية (1)، لا الثلاثية.","3 هو عدد الأزواج المشتركة (عدد خطوط الرابطة)، لا عدد الإلكترونات.","4 هو عدد الإلكترونات في الرابطة الثنائية (2)، لا الثلاثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('mcq', 4, 1, 'يظهر من التوزيع الإلكتروني 1s²2s²2p² أن للكربون أربعة إلكترونات تكافؤ، وأنه يشارك بإلكتروناته دائمًا؛ فيكوّن أربع روابط تساهمية مع ذرات أخرى.', '["الكربون لا يكوّن أيونات سالبة في مركباته العضوية، بل يشارك بإلكتروناته.","","الكربون لا يفقد إلكتروناته في مركباته العضوية، بل يكوّن روابط تساهمية.","مستوى الطاقة الخارجي للكربون غير ممتلئ (أربعة إلكترونات من ثمانية)، لذا يكوّن روابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('mcq', 5, 3, 'تتحد ذرات الكربون في المركبات العضوية مع ذرات الهيدروجين، أو ذرات عناصر أخرى قريبة من الكربون في الجدول الدوري، وخصوصًا النيتروجين والأكسجين والكبريت والفوسفور والهالوجينات.', '["هذه فلزات نشطة تكوّن مركبات أيونية، ولا يرتبط بها الكربون عادة في المركبات العضوية.","هذه غازات نبيلة لا تكوّن روابط في الظروف العادية.","هذه فلزات انتقالية، وليست من العناصر التي يرتبط بها الكربون عادة في المركبات العضوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('mcq', 6, 2, 'لتكوين سلسلة يجب أن ترتبط الذرة بذرتين على الأقل من نوعها. وذرة الكربون تكوّن أربع روابط تساهمية فترتبط بذرات كربون أخرى وتبقى لها روابط إضافية، أما ذرة الهيدروجين فلها إلكترون واحد وتكوّن رابطة واحدة فقط، فلا تستطيع الارتباط بذرتين لتكوين سلسلة.', '["ذرة الهيدروجين أصغر من ذرة الكربون، والحجم ليس سبب عدم تكوين السلاسل.","الهيدروجين يكوّن روابط تساهمية مع الكربون في الهيدروكربونات.","","لذرة الهيدروجين إلكترون واحد فقط، لا أربعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('mcq', 7, 1, 'ذرة الكربون الثانية في السلسلة الأفقية ترتبط بثلاث ذرات كربون: الأولى والثالثة وذرة الفرع العلوي؛ أي ثلاث روابط. وتحتاج ذرة الكربون إلى أربع روابط، فيلزمها 4 − 3 = 1 ذرة هيدروجين.', '["0 يعني أن ذرة الكربون مرتبطة بأربع ذرات كربون، لكنها مرتبطة بثلاث ذرات كربون فقط.","","2 هو عدد ذرات الهيدروجين لذرة كربون مرتبطة بذرتي كربون فقط؛ أي أُغفل الفرع العلوي.","3 هو عدد ذرات الهيدروجين لذرة كربون طرفية مرتبطة بذرة كربون واحدة، وهذه الذرة مرتبطة بثلاث ذرات كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.537Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) لذرة الكربون أربعة إلكترونات تكافؤ (1s²2s²2p²، المجموعة 14) تشارك بها دائمًا، فتكوّن أربع روابط تساهمية مع ذرات أخرى. 2) ترتبط ذرات الكربون بعضها ببعض مكوّنة سلاسل تتراوح أطوالها بين ذرتين وآلاف الذرات، وتكون مستقيمة أو متفرعة أو حلقية أو شبيهة بالأقفاص. 3) ترتبط ذرات الكربون فيما بينها بروابط أحادية أو ثنائية أو ثلاثية، وترتبط أيضًا بذرات الهيدروجين والنيتروجين والأكسجين والكبريت والفوسفور والهالوجينات. وكل ذلك يتيح احتمالات ربط كثيرة جدًّا، فتنتج ملايين المركبات.', '["أربعة إلكترونات تكافؤ وأربع روابط تساهمية","تكوين سلاسل مستقيمة ومتفرعة وحلقات","روابط أحادية وثنائية وثلاثية أو الارتباط بعناصر أخرى","ربط هذه الخواص بتعدد المركبات"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى وأثرها","marks":1},{"element":"الخاصية الثانية وأثرها","marks":1},{"element":"الخاصية الثالثة وأثرها","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"ذكر خاصيتين صحيحتين مع أثرهما"},{"level":"1 درجة","description":"ذكر خاصية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكربون يكوّن روابط أيونية","عدّ الإلكترونات الكلية (6) إلكترونات تكافؤ","ذكر الخواص دون ربطها بتنوع المركبات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) رابطة تساهمية أحادية: إلكترونان مشتركان (زوج واحد)، وتكوّن كل ذرة كربون 3 روابط أخرى. (2) رابطة تساهمية ثنائية: 4 إلكترونات (زوجان)، وتكوّن كل ذرة رابطتين أخريين. (3) رابطة تساهمية ثلاثية: 6 إلكترونات (ثلاثة أزواج)، وتكوّن كل ذرة رابطة واحدة أخرى. وفي كل حالة يبقى مجموع روابط ذرة الكربون أربعًا.', '["(1) أحادية، 2 إلكترون، 3 روابط أخرى","(2) ثنائية، 4 إلكترونات، رابطتان أخريان","(3) ثلاثية، 6 إلكترونات، رابطة أخرى واحدة"]'::jsonb, '["عدد الإلكترونات المشتركة = عدد الأزواج × 2","(1): 1 × 2 = 2؛ (2): 2 × 2 = 4؛ (3): 3 × 2 = 6","الروابط الأخرى = 4 − عدد أزواج الرابطة: 3، 2، 1"]'::jsonb, '[{"element":"الجزء (1)","marks":1},{"element":"الجزء (2)","marks":1},{"element":"الجزء (3)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لجزأين"},{"level":"1 درجة","description":"إجابة صحيحة لجزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأزواج بدل الإلكترونات (3 بدل 6)","نسيان أن مجموع روابط الكربون أربع","تسمية الرابطة الثلاثية رابطة أيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) سلسلة مستقيمة من 5 ذرات كربون: الذرتان الطرفيتان تحتاج كل منهما 3 ذرات H، والذرات الوسطى الثلاث تحتاج كل منها 2؛ فالمجموع 2 × 3 + 3 × 2 = 12، والصيغة C₅H₁₂. (2) تركيب متفرع من 6 ذرات كربون: الذرتان المرتبطتان بثلاث ذرات كربون تحتاج كل منهما ذرة H واحدة، والذرات الطرفية الأربع تحتاج كل منها 3؛ فالمجموع 2 × 1 + 4 × 3 = 14، والصيغة C₆H₁₄. (3) حلقة من 6 ذرات كربون: كل ذرة ترتبط بذرتي كربون فتحتاج 2؛ فالمجموع 6 × 2 = 12، والصيغة C₆H₁₂. وهكذا فإن ترتيب ذرات الكربون نفسها في سلاسل مستقيمة أو متفرعة أو حلقات يعطي مركبات مختلفة؛ فالتركيبان (2) و(3) فيهما 6 ذرات كربون لكن صيغتيهما مختلفتان، وهذا يفسر وجود ملايين المركبات العضوية.', '["C₅H₁₂ للتركيب (1)","C₆H₁₄ للتركيب (2)","C₆H₁₂ للتركيب (3)","الربط بين تنوع الترتيب وتعدد المركبات"]'::jsonb, '["لكل ذرة كربون: عدد ذرات H = 4 − عدد ذرات الكربون المرتبطة بها","(1): 2 × 3 + 3 × 2 = 12 ← C₅H₁₂","(2): 2 × 1 + 4 × 3 = 14 ← C₆H₁₄","(3): 6 × 2 = 12 ← C₆H₁₂"]'::jsonb, '[{"element":"الصيغة الجزيئية للتركيب (1)","marks":1},{"element":"الصيغة الجزيئية للتركيب (2)","marks":1},{"element":"الصيغة الجزيئية للتركيب (3)","marks":1},{"element":"الاستنتاج حول تعدد المركبات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"صيغتان صحيحتان مع استنتاج ناقص"},{"level":"1 درجة","description":"صيغة صحيحة واحدة أو استنتاج دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال ذرات الكربون في الفروع عند العد","إعطاء ذرات الحلقة 3 ذرات H كالسلسلة الطرفية","عدم الربط بين اختلاف الترتيب واختلاف المركبات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
