('mcq', 1, 0, 'الهيدروكربونات أبسط المركبات العضوية، وتحتوي على عنصري الكربون والهيدروجين فقط.', '["","وجود الأكسجين يُخرج المركب من الهيدروكربونات، فهي من الكربون والهيدروجين فقط.","هذا قريب من تعريف المركب العضوي عمومًا، لا الهيدروكربونات.","الهيدروكربونات لا بد أن تحتوي على الكربون، ولا تحتوي على الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb),
('mcq', 2, 3, 'الجزيء (1) يحتوي على C وH فقط، والجزيء (3) يحتوي على C وH فقط (برابطة ثنائية)؛ فهما هيدروكربونان. أما (2) ففيه أكسجين، و(4) فيه كلور، فليسا هيدروكربونين. الإجابة: (1) و(3) فقط.', '["الجزيء (2) يحتوي على ذرة أكسجين، فليس هيدروكربونًا.","الجزيء (3) يحتوي على C وH فقط؛ فوجود الرابطة الثنائية لا يُخرجه من الهيدروكربونات.","الجزيئان (2) و(4) يحتويان على O وCl، فهما مركبان عضويان لكنهما ليسا هيدروكربونين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb),
('mcq', 3, 2, 'C₃H₈ يتكون من الكربون والهيدروجين فقط، فهو هيدروكربون (البروبان).', '["CH₃OH يحتوي على الأكسجين، فهو مركب عضوي لكنه ليس هيدروكربونًا.","C₆H₁₂O₆ يحتوي على الأكسجين، فليس هيدروكربونًا.","","CH₃Cl يحتوي على الكلور، فليس هيدروكربونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb),
('mcq', 4, 1, 'الهيدروكربونات تحتوي على الكربون وليست من المستثنيات، فهي مركبات عضوية؛ لكن المركبات العضوية قد تحتوي على عناصر أخرى كالأكسجين والنيتروجين والهالوجينات فلا تكون هيدروكربونات. إذن كل هيدروكربون مركب عضوي، وليس كل مركب عضوي هيدروكربونًا.', '["عُكست العلاقة؛ فالمركبات العضوية أعم من الهيدروكربونات، مثل CH₃OH عضوي وليس هيدروكربونًا.","","الهيدروكربونات أبسط المركبات العضوية، والأكسجين ليس شرطًا في المركب العضوي.","المصطلحان مختلفان؛ فالمركب العضوي قد يحتوي على عناصر غير الكربون والهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.538Z"}'::jsonb),
('mcq', 5, 3, 'تتكون الهيدروكربونات من عنصري الكربون والهيدروجين فقط؛ ولذلك اشتُق اسمها من اسمي هذين العنصرين: الهيدروجين والكربون.', '["أول مركب عضوي حُضّر في المختبر هو اليوريا، ولا علاقة لاسمها بالتسمية.","التسمية لا تعود إلى اسم عالم، بل إلى العنصرين المكوّنين لها.","«هيدرو» في الاسم مأخوذة من الهيدروجين، أحد العنصرين المكوّنين للهيدروكربونات، ولا علاقة لها بالماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('mcq', 6, 0, 'في النموذج كرتان سوداوان (ذرتا كربون) وست كرات بيضاء (ذرات هيدروجين)، ولا توجد ذرات أخرى؛ فهو هيدروكربون صيغته الجزيئية C₂H₆ (الإيثان).', '["","عُكس العددان؛ فذرات الكربون اثنتان وذرات الهيدروجين ست.","CH₃ نصف الجزيء فقط؛ والصيغة الجزيئية تُكتب بعدد الذرات الكلي في الجزيء.","الرابطة C–C لا تمنع كون المركب هيدروكربونًا؛ فالمعيار هو احتواؤه على C وH فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('mcq', 7, 1, 'قد يُظن أن عدد المركبات الممكن تكوينها من عنصرين فقط قليل، لكن توجد آلاف الهيدروكربونات المعروفة التي تتكون من عنصري الكربون والهيدروجين فقط؛ بفضل قدرة الكربون على تكوين سلاسل وتفرعات وحلقات وروابط متعددة.', '["هذا ظن شائع خاطئ؛ فقدرة الكربون على تكوين السلاسل والحلقات تتيح آلاف الهيدروكربونات.","","الميثان أبسط الهيدروكربونات فقط، وهناك آلاف غيره.","عدد الهيدروكربونات غير محدود بعشرة؛ فالسلاسل قد تصل إلى آلاف الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الهيدروكربونات: مركبات عضوية تتكون من عنصري الكربون والهيدروجين فقط. ومن أمثلتها الميثان CH₄ والإيثان C₂H₆ (أو البروبان C₃H₈). وتُعدّ مركبات عضوية لأنها تحتوي على الكربون، وليست من أكاسيد الكربون أو الكربيدات أو الكربونات.', '["التعريف: كربون وهيدروجين فقط","مثالان صحيحان بصيغهما","التعليل: تحتوي على الكربون وليست من المستثنيات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"مثالان بصيغتيهما","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"عنصران صحيحان من ثلاثة"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة الأكسجين إلى تعريف الهيدروكربونات","التمثيل بمركب يحتوي على الأكسجين كالإيثانول","التعليل بأنها تأتي من المخلوقات الحية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('essay', 2, null::int, null, null, 'هيدروكربونات: C₄H₁₀ وC₂H₂؛ لأنهما يتكونان من الكربون والهيدروجين فقط. مركبات عضوية ليست هيدروكربونات: C₂H₅OH (فيه أكسجين) وCH₂Cl₂ (فيه كلور)؛ فهي تحتوي على الكربون وليست من المستثنيات لكنها تحتوي على عناصر غير C وH. مركبات غير عضوية: CO₂ (من أكاسيد الكربون) وNa₂CO₃ (من الكربونات).', '["C₄H₁₀ وC₂H₂ هيدروكربونات","C₂H₅OH وCH₂Cl₂ عضوية وليست هيدروكربونات","CO₂ وNa₂CO₃ غير عضوية","تعليل كل فئة"]'::jsonb, '[]'::jsonb, '[{"element":"فئة الهيدروكربونات","marks":1},{"element":"فئة العضوية غير الهيدروكربونية","marks":1},{"element":"فئة غير العضوية","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تصنيف صحيح لفئتين مع تعليل"},{"level":"1 درجة","description":"تصنيف صحيح لفئة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ C₂H₅OH هيدروكربونًا لاحتوائه على C وH","عدّ CO₂ أو Na₂CO₃ مركبًا عضويًّا","عدّ C₂H₂ غير هيدروكربون لقلة ذرات الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) (1) C₂H₆، (2) CH₄O (أي CH₃OH)، (3) C₂H₄، (4) CH₃Cl. (ب) الهيدروكربونات: (1) و(3)؛ لأنهما يتكونان من الكربون والهيدروجين فقط. أما (2) فيحتوي على الأكسجين، و(4) يحتوي على الكلور؛ فكلاهما مركب عضوي (يحتوي على الكربون وليس من المستثنيات) لكنه ليس هيدروكربونًا لاحتوائه على عنصر غير الكربون والهيدروجين.', '["الصيغ الجزيئية الأربع","(1) و(3) هيدروكربونات","(2) فيه O و(4) فيه Cl فليسا هيدروكربونين","كلاهما عضوي"]'::jsonb, '["عدّ ذرات كل عنصر في كل صيغة بنائية","(1): C = 2، H = 6؛ (2): C = 1، H = 4، O = 1؛ (3): C = 2، H = 4؛ (4): C = 1، H = 3، Cl = 1"]'::jsonb, '[{"element":"الصيغ الجزيئية","marks":2},{"element":"تحديد الهيدروكربونات","marks":1},{"element":"تفسير (2) و(4)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"صيغ صحيحة مع خطأ في التحديد أو التفسير"},{"level":"1 درجة","description":"تحديد الهيدروكربونات دون صيغ أو تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان ذرة H المرتبطة بالأكسجين في (2)","عدّ (3) غير هيدروكربون بسبب الرابطة الثنائية","القول إن (2) و(4) غير عضويين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
