from (values
('mcq', 1, 'أيّ التمثيلات المرقمة في الشكل الآتي هو نموذج الكرة والعصا؟', null, '[{"src":"qimg/chem22/c4-l1a-methane-models.svg","alt":"أربعة تمثيلات مرقمة لجزيء واحد. (1) الرمز CH₄ مكتوبًا فقط. (2) رسم مسطح فيه ذرة C في الوسط ترتبط بخط مستقيم واحد بكل ذرة من أربع ذرات H موزعة أعلاها وأسفلها ويمينها ويسارها في مستوى الورقة. (3) كرة سوداء في الوسط تتصل بعصي بأربع كرات بيضاء أصغر موزعة في اتجاهات مختلفة في الفراغ. (4) كرة داكنة تتداخل معها أربع كرات زرقاء متلاصقة دون أي عصي، فيبدو الجزيء كتلة واحدة متماسكة."}]'::jsonb, '["(1)","(2)","(3)","(4)"]'::jsonb, 'تذكر', 'تعرّف نموذج', 'سهل', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('mcq', 2, 'أيّ طرائق التمثيل الآتية لا تعطي أي معلومات عن الشكل الهندسي للجزيء؟', null, null, '["الصيغة البنائية","الصيغة الجزيئية","نموذج الكرة والعصا","النموذج الفراغي"]'::jsonb, 'فهم', 'مقارنة نماذج', 'متوسط', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('mcq', 3, 'ماذا يمثل كل خط مستقيم في الصيغة البنائية للميثان؟', null, null, '["رابطة تساهمية أحادية يشترك فيها زوج من الإلكترونات","إلكترونًا واحدًا تفقده ذرة الكربون","رابطة أيونية بين ذرتي الكربون والهيدروجين","المسافة الحقيقية بين نواتي الذرتين"]'::jsonb, 'فهم', 'تفسير رمز', 'سهل', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('mcq', 4, 'يرغب معلم في عرض صورة لجزيء الميثان أقرب ما تكون إلى شكله الحقيقي لو أمكن رؤيته. أيّ التمثيلات في الشكل الآتي يختار؟', null, '[{"src":"qimg/chem22/c4-l1a-methane-models.svg","alt":"أربعة تمثيلات مرقمة لجزيء واحد. (1) الرمز CH₄ مكتوبًا فقط. (2) رسم مسطح فيه ذرة C في الوسط ترتبط بخط مستقيم واحد بكل ذرة من أربع ذرات H موزعة أعلاها وأسفلها ويمينها ويسارها في مستوى الورقة. (3) كرة سوداء في الوسط تتصل بعصي بأربع كرات بيضاء أصغر موزعة في اتجاهات مختلفة في الفراغ. (4) كرة داكنة تتداخل معها أربع كرات زرقاء متلاصقة دون أي عصي، فيبدو الجزيء كتلة واحدة متماسكة."}]'::jsonb, '["(1)","(2)","(3)","(4)"]'::jsonb, 'فهم', 'اختيار نموذج مناسب', 'متوسط', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('mcq', 5, 'ما الصيغة الجزيئية للمركب الممثَّل بالصيغة البنائية الآتية؟', null, '[{"src":"qimg/chem22/c4-l1a-propane-struct.svg","alt":"صيغة بنائية: ثلاث ذرات C متصلة في سلسلة مستقيمة بخطوط مفردة. ترتبط كل ذرة C طرفية بثلاث ذرات H (أعلاها وأسفلها وعند طرف السلسلة)، وترتبط ذرة C الوسطى بذرتي H (أعلاها وأسفلها). جميع الروابط خطوط مفردة."}]'::jsonb, '["C₃H₈","C₃H₆","C₈H₃","C₃H₁₀"]'::jsonb, 'تطبيق', 'استخراج صيغة جزيئية من بنائية', 'متوسط', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('mcq', 6, 'يريد طالب أن يوضح لزملائه الشكل الهندسي لجزيء الميثان واتجاهات الروابط في الفراغ بوضوح. أيّ التمثيلات الآتية أنسب لذلك، ولماذا؟', null, null, '["الصيغة البنائية؛ لأنها تبين الشكل الثلاثي الأبعاد الدقيق","نموذج الكرة والعصا؛ لأنه يُظهر الشكل الهندسي واتجاهات الروابط بوضوح","الصيغة الجزيئية؛ لأنها تبين عدد الذرات في الجزيء","النموذج الفراغي؛ لأنه يُظهر الروابط عصيًّا واضحة"]'::jsonb, 'تحليل', 'اختيار وتعليل', 'صعب', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('mcq', 7, 'أيّ العبارات الآتية تصف ما تُظهره الصيغة البنائية للجزيء؟', null, null, '["تُظهر عدد الذرات فقط، ولا تبين كيف ترتبط بعضها ببعض","تُظهر الشكل الهندسي الثلاثي الأبعاد الدقيق وأحجام الذرات الحقيقية","تُظهر الترتيب العام للذرات، لكنها لا تعطي الشكل الهندسي الثلاثي الأبعاد الدقيق","تُظهر صورة واقعية للجزيء كما يبدو لو أمكن رؤيته"]'::jsonb, 'فهم', 'وصف نموذج', 'صعب', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('essay', 1, 'يبين الشكل الآتي أربعة تمثيلات لجزيء الميثان. سمِّ كل تمثيل، واذكر المعلومات التي يركّز عليها كل منها.', null, '[{"src":"qimg/chem22/c4-l1a-methane-models.svg","alt":"أربعة تمثيلات مرقمة لجزيء واحد. (1) الرمز CH₄ مكتوبًا فقط. (2) رسم مسطح فيه ذرة C في الوسط ترتبط بخط مستقيم واحد بكل ذرة من أربع ذرات H موزعة أعلاها وأسفلها ويمينها ويسارها في مستوى الورقة. (3) كرة سوداء في الوسط تتصل بعصي بأربع كرات بيضاء أصغر موزعة في اتجاهات مختلفة في الفراغ. (4) كرة داكنة تتداخل معها أربع كرات زرقاء متلاصقة دون أي عصي، فيبدو الجزيء كتلة واحدة متماسكة."}]'::jsonb, null, 'فهم', 'تسمية ووصف', 'متوسط', 'الكتاب ص 122، ص 125 — الشكل 4-4، وتقويم 4-1 (س3)'),
('essay', 2, 'يمثل الشكل الآتي نموذج الكرة والعصا لجزيء هيدروكربون. (أ) اكتب صيغته الجزيئية. (ب) ارسم صيغته البنائية بالرموز والخطوط. (ج) اذكر معلومة يُظهرها النموذج المرسوم ولا تُظهرها الصيغة الجزيئية.', null, '[{"src":"qimg/chem22/c4-l1a-ethane-bs.svg","alt":"نموذج جزيء: كرتان سوداوان متصلتان معًا بعصا واحدة، وتتصل كل كرة سوداء بعصي بثلاث كرات بيضاء، فيكون في النموذج كرتان سوداوان وست كرات بيضاء. مفتاح الرسم: الكرة السوداء ذرة كربون، والكرة البيضاء ذرة هيدروجين."}]'::jsonb, null, 'تطبيق', 'تحويل بين التمثيلات', 'متوسط', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)'),
('essay', 3, 'رسم طالب الصيغة البنائية للميثان على الورقة، فاستنتج أن جزيء الميثان مسطح وأن ذرات الهيدروجين الأربع تقع مع ذرة الكربون في مستوى واحد. بيّن الخطأ في استنتاجه، واقترح تمثيلين أنسب لمعرفة شكل الجزيء الحقيقي، مع ذكر ما يقدمه كل منهما.', null, null, null, 'تقويم', 'تصحيح مفهوم خاطئ', 'صعب', 'الكتاب ص 122 — النماذج والهيدروكربونات (الشكل 4-4)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
