from (values
('mcq', 1, 2, 'نموذج الكرة والعصا يمثل الذرات بكرات والروابط بعصي تصل بينها، وهذا ما يظهر في (3): كرة سوداء (C) تتصل بعصي بأربع كرات بيضاء (H).', '["(1) هو الصيغة الجزيئية؛ تبين عدد الذرات فقط.","(2) هو الصيغة البنائية؛ الذرات فيها رموز والروابط خطوط في مستوى الورقة.","","(4) هو النموذج الفراغي؛ الكرات فيه متداخلة ولا توجد عصي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('mcq', 2, 1, 'الصيغة الجزيئية مثل CH₄ تبين نوع الذرات وعددها فقط، ولا تعطي أي معلومات عن الشكل الهندسي للجزيء.', '["الصيغة البنائية تُظهر الترتيب العام للذرات، وإن لم تعطِ الشكل الثلاثي الأبعاد الدقيق.","","نموذج الكرة والعصا يُظهر الشكل الهندسي للجزيء بوضوح.","النموذج الفراغي يعطي صورة واقعية عن شكل الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('mcq', 3, 0, 'في الصيغة البنائية تُمثَّل الرابطة المشتركة (التساهمية) بخط واحد مستقيم، ويرمز الخط إلى تشارك إلكترونين (زوج من الإلكترونات).', '["","الخط يمثل زوجًا مشتركًا من الإلكترونات، والكربون لا يفقد إلكتروناته.","الروابط في الميثان تساهمية لا أيونية.","الصيغة البنائية لا تبين الأبعاد الحقيقية؛ فالخط يرمز إلى الرابطة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.539Z"}'::jsonb),
('mcq', 4, 3, 'النموذج الفراغي يعطي صورة أكثر واقعية عن الكيفية التي يبدو فيها الجزيء لو أمكن رؤيته حقيقة؛ والتمثيل (4) هو النموذج الفراغي، إذ تتداخل فيه الكرات دون عصي.', '["(1) الصيغة الجزيئية لا تعطي أي معلومات عن الشكل.","(2) الصيغة البنائية مسطحة، ولا تعطي الشكل الثلاثي الأبعاد.","(3) نموذج الكرة والعصا؛ يبين الشكل الهندسي بوضوح، لكن العصي لا تمثل شكل الجزيء الحقيقي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.540Z"}'::jsonb),
('mcq', 5, 0, 'في الصيغة البنائية 3 ذرات C، و8 ذرات H (3 لكل ذرة طرفية × 2 + 2 للذرة الوسطى)؛ فالصيغة الجزيئية C₃H₈.', '["","عُدّت ذرات الهيدروجين أعلى ذرات الكربون وأسفلها فقط (6)، وأُغفلت ذرتا الطرفين.","عُكس العددان؛ والصيغة الجزيئية تُكتب بعدد ذرات C ثم عدد ذرات H.","أُعطيت كل ذرة كربون ثلاث ذرات H بما فيها الوسطى، مع أن الوسطى ترتبط بذرتي H فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.540Z"}'::jsonb),
('mcq', 6, 1, 'يُظهر نموذج الكرة والعصا الشكل الهندسي للجزيء بوضوح؛ لأن العصي تبين اتجاهات الروابط في الفراغ، فهو الأنسب لهذا الغرض.', '["الصيغة البنائية تُظهر الترتيب العام للذرات، لكنها لا تعطي الشكل الهندسي الثلاثي الأبعاد الدقيق.","","الصيغة الجزيئية لا تعطي أي معلومات عن الشكل الهندسي.","النموذج الفراغي لا يحتوي على عصي؛ فالكرات متداخلة فلا تظهر اتجاهات الروابط بوضوح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.540Z"}'::jsonb),
('mcq', 7, 2, 'تُظهر الصيغة البنائية الترتيب العام للذرات في الجزيء وكيف ترتبط، لكنها لا تعطي الشكل الهندسي الثلاثي الأبعاد الدقيق.', '["هذا وصف الصيغة الجزيئية لا البنائية.","الصيغة البنائية مسطحة ولا تبين الشكل الثلاثي الأبعاد الدقيق ولا أحجام الذرات.","","هذا وصف النموذج الفراغي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.540Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) الصيغة الجزيئية CH₄: تبين نوع الذرات وعددها فقط، ولا تعطي معلومات عن الشكل. (2) الصيغة البنائية: تُظهر الترتيب العام للذرات والروابط (كل خط زوج مشترك من الإلكترونات)، لكنها لا تعطي الشكل الثلاثي الأبعاد الدقيق. (3) نموذج الكرة والعصا: يُظهر الشكل الهندسي للجزيء بوضوح واتجاهات الروابط. (4) النموذج الفراغي: يعطي صورة أكثر واقعية عن شكل الجزيء لو أمكن رؤيته.', '["(1) الصيغة الجزيئية: نوع الذرات وعددها","(2) الصيغة البنائية: الترتيب العام للذرات","(3) الكرة والعصا: الشكل الهندسي بوضوح","(4) الفراغي: صورة واقعية للجزيء"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية التمثيلات الأربعة","marks":2},{"element":"المعلومات التي يركّز عليها كل تمثيل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"تسمية صحيحة مع نقص في المعلومات المصاحبة"},{"level":"1 درجة","description":"تسمية تمثيلين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين نموذج الكرة والعصا والنموذج الفراغي","القول إن الصيغة البنائية تعطي الشكل الثلاثي الأبعاد الدقيق","القول إن الصيغة الجزيئية تبين ترتيب الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.540Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في النموذج ذرتا كربون وست ذرات هيدروجين، فالصيغة الجزيئية C₂H₆. (ب) الصيغة البنائية: ذرتا C مرتبطتان بخط واحد (C–C)، وترتبط كل ذرة C بثلاث ذرات H بخطوط مفردة (H₃C–CH₃ مرسومة بكامل الروابط). (ج) يُظهر نموذج الكرة والعصا الشكل الهندسي للجزيء واتجاهات الروابط في الفراغ وكيفية ارتباط الذرات، أما الصيغة الجزيئية فتبين عدد الذرات فقط.', '["C₂H₆","صيغة بنائية صحيحة: C–C مع ثلاث ذرات H على كل كربون","النموذج يُظهر الشكل الهندسي وارتباط الذرات"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغة الجزيئية","marks":1},{"element":"الصيغة البنائية","marks":1},{"element":"المعلومة الإضافية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"جزآن صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة CH₃ بدل C₂H₆","رسم رابطة ثنائية بين ذرتي الكربون","القول إن الصيغة الجزيئية تبين الشكل الهندسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.540Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ: الصيغة البنائية تُظهر الترتيب العام للذرات وكيف ترتبط، لكنها لا تعطي الشكل الهندسي الثلاثي الأبعاد الدقيق؛ فرسمها مسطحًا على الورقة لا يعني أن الجزيء مسطح. والتمثيلان الأنسب: نموذج الكرة والعصا، الذي يُظهر الشكل الهندسي للجزيء بوضوح واتجاهات الروابط في الفراغ؛ والنموذج الفراغي، الذي يعطي صورة أكثر واقعية عن الكيفية التي يبدو فيها الجزيء لو أمكن رؤيته.', '["الصيغة البنائية لا تعطي الشكل الثلاثي الأبعاد الدقيق","نموذج الكرة والعصا يُظهر الشكل الهندسي بوضوح","النموذج الفراغي يعطي صورة أكثر واقعية"]'::jsonb, '[]'::jsonb, '[{"element":"بيان الخطأ","marks":2},{"element":"نموذج الكرة والعصا وما يقدمه","marks":1},{"element":"النموذج الفراغي وما يقدمه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2–3 درجات","description":"بيان الخطأ مع اقتراح تمثيل واحد مناسب"},{"level":"1 درجة","description":"اقتراح تمثيل مناسب دون بيان الخطأ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح الصيغة الجزيئية لمعرفة الشكل","قبول استنتاج الطالب","عدم التمييز بين ما يقدمه كل من النموذجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.541Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L1-O08') and x.type = v.type and x.number = v.number
