insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L1-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الهيدروكربون المشبع؟', null, null, '["هيدروكربون يحتوي على رابطة ثنائية أو ثلاثية واحدة على الأقل","هيدروكربون يحتوي على روابط تساهمية أحادية فقط","هيدروكربون مذاب في محلول مشبع لا يذيب مزيدًا منه","هيدروكربون ترتبط فيه كل ذرة كربون بأربع ذرات هيدروجين"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 2, 'أيّ الهيدروكربونات المرقمة في الشكل الآتي غير مشبعة؟', null, '[{"src":"qimg/chem22/c4-l1b-sat-unsat.svg","alt":"أربع صيغ بنائية مرقمة لهيدروكربونات، الذرات رموز (C وH) والروابط خطوط. (1) سلسلة من ثلاث ذرات كربون: بين الأولى والثانية خطان متوازيان، وبين الثانية والثالثة خط واحد؛ ترتبط بالكربون الأول ذرتا هيدروجين، وبالثاني ذرة واحدة، وبالثالث ثلاث ذرات. (2) سلسلة من أربع ذرات كربون بينها خطوط مفردة فقط؛ ترتبط بكل كربون طرفي ثلاث ذرات هيدروجين، وبكل كربون أوسط ذرتان. (3) سلسلة من ثلاث ذرات كربون: بين الأولى والثانية ثلاثة خطوط متوازية، وبين الثانية والثالثة خط واحد؛ ترتبط بالكربون الأول ذرة هيدروجين واحدة، ولا يرتبط بالثاني أي هيدروجين، وبالثالث ثلاث ذرات. (4) سلسلة من ثلاث ذرات كربون بينها خطوط مفردة فقط؛ ترتبط بكل كربون طرفي ثلاث ذرات هيدروجين، وبالكربون الأوسط ذرتان."}]'::jsonb, '["(2) و(4)","(1) فقط","(3) و(4)","(1) و(3)"]'::jsonb, 'فهم', 'قراءة صيغ بنائية', 'متوسط', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة (الشكل 4-5)'),
('mcq', 3, 'أيّ الصيغ البنائية المكثفة الآتية تمثل هيدروكربونًا مشبعًا؟', null, null, '["CH₃CH₂CH₃","CH₂=CHCH₃","HC≡CH","CH₂=CH₂"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 4, 'يحتوي جزيء هيدروكربون على عدة روابط أحادية بين ذرات الكربون، وعلى رابطة ثنائية واحدة فقط. كيف يُصنّف هذا الهيدروكربون؟', null, null, '["مشبع؛ لأن معظم الروابط بين ذرات الكربون فيه أحادية","مشبع؛ لأن كل ذرة كربون فيه تكوّن أربع روابط","غير مشبع؛ لأن فيه رابطة ثنائية واحدة على الأقل","لا يُصنّف مشبعًا ولا غير مشبع؛ لأنه يجمع النوعين من الروابط"]'::jsonb, 'تطبيق', 'استنتاج', 'متوسط', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 5, 'قارن بين الهيدروكربونين (1) و(2) في الشكل الآتي. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c4-l1b-butane-butene.svg","alt":"صيغتان بنائيتان مرقمتان. (1) سلسلة مستقيمة من أربع ذرات كربون بينها خطوط مفردة فقط؛ ترتبط بكل كربون طرفي ثلاث ذرات هيدروجين، وبكل كربون أوسط ذرتا هيدروجين. (2) سلسلة مستقيمة من أربع ذرات كربون: بين الكربون الأول والثاني خطان متوازيان، وبين بقية الذرات خطوط مفردة؛ ترتبط بالكربون الأول ذرتا هيدروجين، وبالثاني ذرة واحدة، وبالثالث ذرتان، وبالرابع ثلاث ذرات."}]'::jsonb, '["(1) غير مشبع وفيه 10 ذرات هيدروجين، و(2) مشبع وفيه 8 ذرات هيدروجين","كلاهما مشبع؛ لأن في كل منهما أربع ذرات كربون","(1) مشبع وفيه 8 ذرات هيدروجين، و(2) غير مشبع وفيه 10 ذرات هيدروجين","(1) مشبع وفيه 10 ذرات هيدروجين، و(2) غير مشبع وفيه 8 ذرات هيدروجين"]'::jsonb, 'تحليل', 'مقارنة صيغ بنائية', 'صعب', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 6, 'يحتوي كل من البروبان CH₃CH₂CH₃ والبروبين CH₂=CHCH₃ على ثلاث ذرات كربون، لكن عدد ذرات الهيدروجين في البروبان 8 وفي البروبين 6. ما سبب ذلك؟', null, null, '["البروبين يفقد ذرتي هيدروجين عندما يتفاعل مع البروم","الرابطة الثنائية تشغل روابط إضافية من ذرتي الكربون، فتقل الروابط المتاحة لذرات الهيدروجين","ذرة الكربون في الهيدروكربون غير المشبع تكوّن ثلاث روابط فقط","ذرات الهيدروجين لا ترتبط بذرات الكربون التي بينها رابطة ثنائية"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 121–122 — روابط الكربون والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 7, 'أيّ الهيدروكربونين الآتيين أعلى نشاطًا كيميائيًّا: الإيثان CH₃CH₃ أم الإيثين CH₂=CH₂؟', null, null, '["الإيثين؛ لأنه غير مشبع يحتوي على رابطة ثنائية","الإيثان؛ لأنه مشبع يحتوي على روابط أحادية فقط","الإيثان؛ لأنه يحتوي على عدد أكبر من ذرات الهيدروجين","متساويان؛ لأن في كل منهما ذرتي كربون"]'::jsonb, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 122، ص 157 — الهيدروكربونات غير المشبعة ونشاطها'),
('essay', 1, 'قارن بين الهيدروكربونات المشبعة والهيدروكربونات غير المشبعة من حيث: (أ) أنواع الروابط بين ذرات الكربون. (ب) التفاعل مع البروم. (ج) مثال لكل منهما بصيغته البنائية المكثفة.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة'),
('essay', 2, 'صنّف الهيدروكربونات الأربعة المرقمة في الشكل الآتي إلى مشبعة وغير مشبعة، وحدّد في كل هيدروكربون غير مشبع نوع الرابطة التي جعلته كذلك، ثم اكتب عدد ذرات الهيدروجين في كل جزيء.', null, '[{"src":"qimg/chem22/c4-l1b-sat-unsat.svg","alt":"أربع صيغ بنائية مرقمة لهيدروكربونات، الذرات رموز (C وH) والروابط خطوط. (1) سلسلة من ثلاث ذرات كربون: بين الأولى والثانية خطان متوازيان، وبين الثانية والثالثة خط واحد؛ ترتبط بالكربون الأول ذرتا هيدروجين، وبالثاني ذرة واحدة، وبالثالث ثلاث ذرات. (2) سلسلة من أربع ذرات كربون بينها خطوط مفردة فقط؛ ترتبط بكل كربون طرفي ثلاث ذرات هيدروجين، وبكل كربون أوسط ذرتان. (3) سلسلة من ثلاث ذرات كربون: بين الأولى والثانية ثلاثة خطوط متوازية، وبين الثانية والثالثة خط واحد؛ ترتبط بالكربون الأول ذرة هيدروجين واحدة، ولا يرتبط بالثاني أي هيدروجين، وبالثالث ثلاث ذرات. (4) سلسلة من ثلاث ذرات كربون بينها خطوط مفردة فقط؛ ترتبط بكل كربون طرفي ثلاث ذرات هيدروجين، وبالكربون الأوسط ذرتان."}]'::jsonb, null, 'تحليل', 'تصنيف وقراءة صيغ بنائية', 'متوسط', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة'),
('essay', 3, 'قال طالب: «الإيثان CH₃CH₃ والإيثين CH₂=CH₂ متماثلان في التشبع؛ لأن في كل منهما ذرتي كربون فقط». قوّم عبارة الطالب، مدعّمًا إجابتك بنوع الرابطة بين ذرتي الكربون وعدد ذرات الهيدروجين في كل منهما، وبسلوك كل منهما مع البروم.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 122 — الهيدروكربونات المشبعة وغير المشبعة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
