from (values
('mcq', 1, 1, 'الهيدروكربون المشبع هو الذي يحتوي على روابط تساهمية أحادية فقط، أي: هيدروكربون يحتوي على روابط تساهمية أحادية فقط.', '["هذا تعريف الهيدروكربون غير المشبع.","","خلط بين معنى «مشبع» في الهيدروكربونات ومعنى المحلول المشبع؛ التسمية مأخوذة منه تشبيهًا فقط.","هذا لا يصح إلا للميثان؛ ففي الإيثان مثلًا ترتبط كل ذرة كربون بثلاث ذرات هيدروجين وذرة كربون، وهو مشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-07T17:19:00.541Z"}'::jsonb),
('mcq', 2, 3, 'في (1) خطان متوازيان بين ذرتي كربون (رابطة ثنائية)، وفي (3) ثلاثة خطوط (رابطة ثلاثية)، فكلاهما غير مشبع؛ أما (2) و(4) فروابطهما أحادية فقط. الإجابة: (1) و(3).', '["(2) و(4) فيهما روابط أحادية فقط بين ذرات الكربون، فهما مشبعان.","(3) أيضًا غير مشبع لاحتوائه على رابطة ثلاثية (ثلاثة خطوط) بين ذرتي كربون.","(4) مشبع؛ كل روابطه أحادية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.541Z"}'::jsonb),
('mcq', 3, 0, 'CH₃CH₂CH₃ هو الصيغة الوحيدة التي تحتوي على روابط أحادية فقط بين ذرات الكربون، فهي تمثل هيدروكربونًا مشبعًا؛ والصيغ الأخرى فيها رابطة ثنائية أو ثلاثية.', '["","فيه رابطة ثنائية بين ذرتي كربون، فهو غير مشبع.","فيه رابطة ثلاثية بين ذرتي الكربون، فهو غير مشبع.","فيه رابطة ثنائية بين ذرتي الكربون، فهو غير مشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.541Z"}'::jsonb),
('mcq', 4, 2, 'الهيدروكربون غير المشبع هو الذي يحتوي على رابطة ثنائية أو ثلاثية واحدة على الأقل؛ فوجود رابطة ثنائية واحدة يكفي لتصنيفه غير مشبع مهما كثرت روابطه الأحادية.', '["العبرة ليست بأغلبية الروابط؛ فوجود رابطة ثنائية واحدة يكفي ليكون الهيدروكربون غير مشبع.","ذرة الكربون تكوّن أربع روابط في جميع الهيدروكربونات، مشبعة كانت أو غير مشبعة.","","الهيدروكربون إما مشبع (روابط أحادية فقط) وإما غير مشبع (رابطة ثنائية أو ثلاثية واحدة على الأقل)، ولا توجد فئة ثالثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.541Z"}'::jsonb),
('mcq', 5, 3, '(1) روابطه أحادية فقط، وعدد ذرات الهيدروجين فيه 3 + 2 + 2 + 3 = 10، فهو مشبع. (2) فيه رابطة ثنائية بين الكربونين الأول والثاني، وعدد ذرات الهيدروجين 2 + 1 + 2 + 3 = 8، فهو غير مشبع.', '["عُكس التصنيف: (1) روابطه أحادية فقط فهو مشبع، و(2) فيه رابطة ثنائية فهو غير مشبع.","عدد ذرات الكربون لا يحدد التشبع؛ بل نوع الروابط بين ذرات الكربون.","عُكس عدد ذرات الهيدروجين: الرابطة الثنائية في (2) تقلل عدد ذرات الهيدروجين المرتبطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.541Z"}'::jsonb),
('mcq', 6, 1, 'تكوّن كل ذرة كربون أربع روابط؛ وفي البروبين تستهلك الرابطة الثنائية رابطتين من كل من ذرتي الكربون بدل رابطة واحدة، فيقل عدد الروابط المتاحة للهيدروجين بمقدار رابطتين (8 − 2 = 6)؛ أي أن الرابطة الثنائية تشغل روابط إضافية فتقل ذرات الهيدروجين.', '["عدد ذرات الهيدروجين صفة لتركيب الجزيء نفسه قبل أي تفاعل.","","ذرة الكربون تكوّن أربع روابط دائمًا؛ والرابطة الثنائية تُحسب رابطتين.","في CH₂=CHCH₃ ترتبط بذرتي الكربون المرتبطتين بالرابطة الثنائية ثلاث ذرات هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.542Z"}'::jsonb),
('mcq', 7, 0, 'الهيدروكربونات غير المشبعة (الألكينات والألكاينات) ذات نشاط كيميائي أعلى من المشبعة (الألكانات)، والإيثين فيه رابطة ثنائية فهو أنشط من الإيثان.', '["","الهيدروكربونات المشبعة أقل نشاطًا كيميائيًّا من غير المشبعة.","كثرة ذرات الهيدروجين علامة على التشبع، والمشبع أقل نشاطًا.","تساوي عدد ذرات الكربون لا يعني تساوي النشاط؛ نوع الرابطة بين ذرتي الكربون هو المؤثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.542Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المشبعة تحتوي على روابط تساهمية أحادية فقط، أما غير المشبعة فتحتوي على رابطة ثنائية أو ثلاثية واحدة على الأقل. (ب) المشبعة لا تتفاعل مع البروم، وغير المشبعة تتفاعل معه. (ج) مثال المشبع: الإيثان CH₃CH₃ أو البروبان CH₃CH₂CH₃؛ ومثال غير المشبع: الإيثين CH₂=CH₂ أو الإيثاين HC≡CH.', '["المشبع: روابط أحادية فقط","غير المشبع: رابطة ثنائية أو ثلاثية على الأقل","المشبع لا يتفاعل مع البروم","غير المشبع يتفاعل مع البروم","مثال صحيح لمشبع","مثال صحيح لغير مشبع"]'::jsonb, '[]'::jsonb, '[{"element":"أنواع الروابط في كل منهما","marks":2},{"element":"التفاعل مع البروم لكل منهما","marks":2},{"element":"مثال صحيح لكل منهما","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"5 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 5 من 6، مع نقص أو خطأ في الباقي"},{"level":"4 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 4 من 6، مع نقص أو خطأ في الباقي"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 6، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 6، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 6، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المشبع يحتوي على رابطة ثنائية","عكس نتيجة التفاعل مع البروم","إعطاء مثال يحتوي على عنصر غير الكربون والهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.542Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) غير مشبع؛ فيه رابطة ثنائية بين ذرتي كربون، وعدد ذرات الهيدروجين 2 + 1 + 3 = 6. (2) مشبع؛ روابطه أحادية فقط، وعدد ذرات الهيدروجين 3 + 2 + 2 + 3 = 10. (3) غير مشبع؛ فيه رابطة ثلاثية بين ذرتي كربون، وعدد ذرات الهيدروجين 1 + 0 + 3 = 4. (4) مشبع؛ روابطه أحادية فقط، وعدد ذرات الهيدروجين 3 + 2 + 3 = 8.', '["(1) غير مشبع، رابطة ثنائية","(2) مشبع","(3) غير مشبع، رابطة ثلاثية","(4) مشبع","أعداد H: 6، 10، 4، 8"]'::jsonb, '["عدّ ذرات الهيدروجين المرتبطة بكل ذرة كربون ثم جمعها","(1): 2 + 1 + 3 = 6","(2): 3 + 2 + 2 + 3 = 10","(3): 1 + 0 + 3 = 4","(4): 3 + 2 + 3 = 8"]'::jsonb, '[{"element":"تصنيف الأربعة صحيحًا","marks":2},{"element":"نوع الرابطة في (1) و(3)","marks":1},{"element":"أعداد ذرات الهيدروجين الأربعة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"4 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 4 من 5، مع نقص أو خطأ في الباقي"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 5، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 5، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 5، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الرابطة الثلاثية رابطة ثنائية","نسيان ذرات الهيدروجين الطرفية الأفقية عند العدّ","تصنيف (4) غير مشبع لقصر سلسلته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.542Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالتشبع لا يتحدد بعدد ذرات الكربون، بل بنوع الروابط بينها. في الإيثان رابطة أحادية بين ذرتي الكربون، وترتبط به 6 ذرات هيدروجين، فهو مشبع ولا يتفاعل مع البروم. وفي الإيثين رابطة ثنائية بين ذرتي الكربون، وترتبط به 4 ذرات هيدروجين فقط، فهو غير مشبع ويتفاعل مع البروم.', '["الحكم: العبارة خاطئة","معيار التشبع نوع الروابط لا عدد ذرات الكربون","الإيثان: رابطة أحادية و6 ذرات H، لا يتفاعل مع البروم","الإيثين: رابطة ثنائية و4 ذرات H، يتفاعل مع البروم"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع ذكر المعيار الصحيح","marks":1},{"element":"وصف الإيثان","marks":1},{"element":"وصف الإيثين","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","القول إن الإيثين يحتوي على هيدروجين أكثر من الإيثان","عكس سلوكهما مع البروم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.542Z"}'::jsonb)
