('mcq', 3, 'لماذا يُسخَّن النفط الخام في الفرن قبل إدخاله إلى برج التجزئة؟', null, null, '["لتكسير جزيئاته الكبيرة إلى جزيئات أصغر قبل الفصل","لحرق الشوائب الموجودة فيه وتحويلها إلى غازات","لجعل جميع مكوناته تتكثف عند درجة حرارة واحدة","لتحويل مكوناته إلى بخار يصعد داخل البرج ثم يتكثف على ارتفاعات مختلفة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 123 — التقطير التجزيئي (الشكل 4-6)'),
('mcq', 4, 'ما الخاصية الفيزيائية التي يعتمد عليها فصل مكونات النفط في برج التجزئة؟', null, null, '["اختلاف ألوان المكونات","اختلاف درجات غليان المكونات","اختلاف تفاعل المكونات مع البروم","اختلاف ذائبية المكونات في الماء"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 123، ص 159 — التقطير التجزيئي، س42'),
('mcq', 5, 'كيف تتغير درجة الحرارة داخل برج التجزئة في أثناء التقطير التجزيئي؟', null, null, '["تكون قريبة من 400°C في أعلى البرج، وتنخفض تدريجيًّا في اتجاه أسفله","تبقى ثابتة عند 400°C في جميع أجزاء البرج","تكون قريبة من 400°C في أسفل البرج، وتنخفض تدريجيًّا في اتجاه أعلاه","تكون أعلى ما يمكن في منتصف البرج، وتنخفض في اتجاه طرفيه"]'::jsonb, 'فهم', 'وصف', 'متوسط', 'الكتاب ص 123 — التقطير التجزيئي (الشكل 4-6)'),
('mcq', 6, 'عندما يصعد بخار أحد مكونات النفط داخل برج التجزئة ويصل إلى منطقة درجة حرارتها أقل من درجة غليانه، فإنه:', null, null, '["يتكثف إلى سائل ويُسحب من المخرج الموجود عند ذلك الارتفاع","يستمر في الصعود حتى يخرج مع الغازات من قمة البرج","يتكسر إلى جزيئات أصغر تصعد إلى أعلى البرج","يعود إلى الفرن ليُسخَّن مرة أخرى"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 123 — التقطير التجزيئي (الشكل 4-6)'),
('mcq', 7, 'لماذا لا تكفي عملية التقطير التجزيئي وحدها لتلبية حاجة السوق من الجازولين؟', null, null, '["لأنها تحوّل الجازولين إلى زيوت ثقيلة في أثناء التسخين في الفرن","لأنها تُنتج جازولين أقل من حاجة السوق، وزيوتًا ثقيلة تفوق حاجته","لأن الجازولين لا يتكثف داخل البرج فيخرج مع الغازات من قمته","لأنها تنتج جازولين نقيًّا من مركب واحد لا يصلح وقودًا للسيارات"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 124 — حدود التقطير التجزيئي'),
('essay', 1, 'اشرح بالتسلسل آلية فصل مكونات النفط الخام في برج التقطير التجزيئي، بدءًا من الفرن حتى سحب المكونات من البرج.', null, null, null, 'فهم', 'شرح إجراء', 'متوسط', 'الكتاب ص 123 — التقطير التجزيئي (الشكل 4-6)'),
('essay', 2, 'يبين الشكل الآتي برجًا للتقطير التجزيئي. أجب عما يأتي: (أ) من أين يدخل بخار النفط إلى البرج؟ ولماذا يدخل من هذا الموضع؟ (ب) لماذا تتكثف مكونات مختلفة عند المخارج من (1) إلى (5)؟ (ج) لماذا تبقى المخلفات عند المخرج (6)؟', null, '[{"src":"qimg/chem22/c4-l1b-tower-numbered.svg","alt":"برج تجزئة رأسي بداخله أطباق أفقية، وعلى يمينه فرن يدخله النفط الخام، ويخرج من أعلى الفرن أنبوب ينقل البخار إلى الجزء السفلي من البرج. على يسار البرج ستة مخارج مرقمة من الأعلى إلى الأسفل: المخرج (1) عند قمة البرج، ثم (2) و(3) و(4) و(5) على ارتفاعات متناقصة، والمخرج (6) عند قاع البرج. لا تظهر في الشكل أسماء المكونات ولا درجات الحرارة."}]'::jsonb, null, 'تطبيق', 'تفسير مخطط', 'متوسط', 'الكتاب ص 123 — التقطير التجزيئي (الشكل 4-6)'),
('essay', 3, 'ما الخاصية الفيزيائية لمركبات النفط التي تُستعمل لفصلها بالتقطير التجزيئي؟ ثم فسّر لماذا لا يمكن فصل النفط إلى مكوناته بتسخينه إلى درجة حرارة واحدة ثابتة فقط.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 123، ص 159 — التقطير التجزيئي، س42')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
