insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'التقطير التجزيئي عملية تتضمن تبخير النفط عند درجة الغليان، ثم تجميع المشتقات (المكونات) المختلفة في أثناء تكثفها عند درجات حرارة متباينة.', '["هذا تعريف التكسير الحراري، وهو عملية كيميائية تغيّر الجزيئات، لا تفصلها.","الاحتراق يستهلك النفط ولا يفصل مكوناته.","","اختبار البروم يميّز المشبع من غير المشبع، وليس طريقة لفصل مكونات النفط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.542Z"}'::jsonb),
('mcq', 2, 0, 'يدخل البخار الساخن من الفرن إلى أسفل البرج حيث تكون درجة الحرارة قريبة من 400°C، ثم تنخفض تدريجيًّا كلما ارتفعنا؛ فأعلى درجة حرارة عند المخرج السفلي (6).', '["","(1) عند قمة البرج، وهي أبرد منطقة فيه.","(3) في منتصف البرج؛ درجة الحرارة عنده متوسطة.","(5) أسخن من المخارج فوقه، لكن (6) عند القاع أسخن منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('mcq', 3, 3, 'يُسخَّن النفط الخام حتى الغليان فتتحول مكوناته إلى بخار ينتقل إلى البرج ويصعد فيه، فيتكثف كل مكوّن عند الارتفاع الذي تناسب درجة حرارته درجة غليانه؛ أي: لتحويل مكوناته إلى بخار يصعد ثم يتكثف على ارتفاعات مختلفة.', '["تكسير الجزيئات هو التكسير الحراري، ويحتاج إلى عامل مساعد وغياب الأكسجين، وليس هدف التسخين في التقطير.","التسخين في الفرن يهدف إلى الغليان والتبخير، لا إلى الحرق.","عكس المطلوب: الفصل يعتمد على أن المكونات تتكثف عند درجات حرارة مختلفة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('mcq', 4, 1, 'يعتمد التقطير التجزيئي على اختلاف درجات غليان المكونات؛ فكل مكوّن يتكثف عند درجة حرارة مختلفة فيُسحب من ارتفاع مختلف.', '["اللون لا يؤثر في موضع تكثف المكوّن في البرج.","","التفاعل مع البروم خاصية كيميائية تميّز المشبع من غير المشبع، ولا علاقة لها بالتقطير.","لا يُستعمل الماء مذيبًا في برج التجزئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('mcq', 5, 2, 'يُتحكم في درجة الحرارة داخل البرج فتكون قريبة من 400°C في أسفله حيث يدخل البخار، وتنخفض تدريجيًّا في اتجاه أعلى البرج.', '["عكس الواقع: البخار الساخن يدخل من الأسفل، والقمة أبرد منطقة.","لو ثبتت درجة الحرارة لما تكثفت المكونات على ارتفاعات مختلفة، ولما حدث الفصل.","","البخار يدخل من أسفل البرج، فالأسفل هو الأسخن لا المنتصف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('mcq', 6, 0, 'إذا انخفضت درجة الحرارة عن درجة غليان المكوّن تحوّل بخاره إلى سائل (تكثف)، فيُسحب من المخرج عند ذلك الارتفاع.', '["","المكوّن يتكثف عندما تنخفض درجة الحرارة عن درجة غليانه، فلا يصل إلى القمة إلا ما كانت درجة غليانه أقل من 40°C.","التكسير يحتاج إلى عامل مساعد وغياب الأكسجين، ولا يحدث في أثناء التكثف.","المكونات المتكثفة تُسحب من البرج، ولا تعود إلى الفرن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('mcq', 7, 1, 'أبراج التقطير لا تنتج المكونات بالنسب التي نحتاج إليها؛ فنادرًا ما يُنتج التقطير الكمية المرغوبة من الجازولين، ويُنتج في المقابل زيوتًا ثقيلة بكميات تفوق حاجة السوق؛ أي أنها تُنتج جازولين أقل من حاجة السوق، وزيوتًا ثقيلة تفوق حاجته.', '["التقطير عملية فصل لا تغيّر الجزيئات، فلا يتحول فيها مكوّن إلى آخر.","","الجازولين يتكثف بين 40 و100°C ويُسحب من مخرج تحت قمة البرج.","الجازولين خليط من هيدروكربونات كثيرة، وليس مادة نقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) يُسخَّن النفط الخام في الفرن حتى الغليان فتتحول مكوناته إلى بخار. 2) ينتقل البخار إلى الجزء السفلي من برج التجزئة حيث درجة الحرارة قريبة من 400°C. 3) يصعد البخار في البرج، ودرجة الحرارة تنخفض تدريجيًّا في اتجاه أعلاه. 4) عندما يصل كل مكوّن إلى ارتفاع تقل فيه درجة الحرارة عن درجة غليانه يتكثف ويُسحب من المخرج عند ذلك الارتفاع؛ فالمكونات ذات درجات الغليان المنخفضة (الغازات والجازولين) تُسحب من أعلى البرج، والمكونات ذات درجات الغليان المرتفعة (زيوت التزييت والتشحيم) تُسحب من الأسفل، وتبقى المخلفات في قاع البرج.', '["التسخين في الفرن حتى الغليان وتكوّن البخار","دخول البخار أسفل البرج (نحو 400°C)","انخفاض درجة الحرارة تدريجيًّا إلى أعلى","تكثف كل مكوّن عند درجة حرارة أقل من درجة غليانه وسحبه، مع ترتيب المكونات"]'::jsonb, '[]'::jsonb, '[{"element":"التسخين والتبخير","marks":1},{"element":"دخول البخار أسفل البرج","marks":1},{"element":"تدرج درجة الحرارة","marks":1},{"element":"التكثف والسحب وترتيب المكونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 4، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 4، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 4، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البرج أسخن في أعلاه","الخلط بين التقطير التجزيئي والتكسير الحراري","إهمال ذكر أن الفصل يعتمد على درجة الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يدخل البخار من الفرن عبر الأنبوب إلى الجزء السفلي من البرج، وهو أسخن منطقة فيه (نحو 400°C)، فيبقى معظم النفط بخارًا ويصعد. (ب) لأن درجة الحرارة تنخفض تدريجيًّا كلما ارتفعنا في البرج، ولكل مكوّن درجة غليان مختلفة؛ فيتكثف كل مكوّن عند الارتفاع الذي تقل فيه درجة الحرارة عن درجة غليانه. (ج) لأن درجات غليان المخلفات أعلى من درجة الحرارة حتى في قاع البرج، فلا تتبخر ولا تصعد، وتُسحب من القاع.', '["(أ) من أسفل البرج حيث أعلى درجة حرارة","(ب) تدرج درجة الحرارة واختلاف درجات الغليان","(ج) درجات غليان المخلفات أعلى ما يمكن فتبقى في القاع"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البخار يدخل من قمة البرج","تفسير بقاء المخلفات بأنها أخف المكونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخاصية هي درجة الغليان؛ إذ تختلف درجات غليان مكونات النفط باختلاف كتلها الجزيئية (عدد ذرات الكربون)، فكلما زادت الكتلة الجزيئية ارتفعت درجة الغليان. ولو سُخّن النفط إلى درجة حرارة واحدة ثابتة لتبخرت معًا جميع المكونات التي درجات غليانها أقل من تلك الدرجة وخرجت خليطًا واحدًا، وبقيت المكونات الأعلى منها خليطًا آخر؛ لذا يلزم تدرّج درجة الحرارة داخل البرج ليتكثف كل مكوّن عند درجة حرارة مختلفة فيُفصل وحده.', '["الخاصية: درجة الغليان","ارتباط درجة الغليان بالكتلة الجزيئية","درجة حرارة واحدة تنتج خليطين فقط","الحاجة إلى تدرج درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخاصية وربطها بالكتلة الجزيئية","marks":1},{"element":"تفسير عدم كفاية درجة حرارة واحدة","marks":1},{"element":"ذكر دور تدرج درجة الحرارة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الكثافة أو اللون بدل درجة الغليان","القول إن درجة الحرارة الواحدة تكسر الجزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.543Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
