select (select id from public.objectives where code = 'K22-C4-L1-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما التكسير الحراري؟', null, null, '["فصل مكونات النفط بتبخيره ثم تجميعها في أثناء تكثفها عند درجات حرارة متباينة داخل برج التجزئة","تحويل الجزيئات الصغيرة إلى جزيئات كبيرة بتسخينها في وجود الأكسجين وعامل مساعد","حرق المكونات الثقيلة في الأكسجين لإنتاج الطاقة اللازمة لتسخين النفط الخام في الفرن","تحويل المكونات الثقيلة إلى جازولين بتكسير الجزيئات الكبيرة إلى جزيئات أصغر عند غياب الأكسجين ووجود عامل مساعد"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 124 — التكسير الحراري'),
('mcq', 2, 'ما اسم العملية التي يمثلها الشكل الآتي؟', null, '[{"src":"qimg/chem22/c4-l1b-cracking-q.svg","alt":"سلسلة طويلة من 16 كرة متصلة تمثل ذرات الكربون في الجزيء C₁₆H₃₄، يليها سهم فوقه علامة استفهام، ثم ناتجان بينهما علامة +: سلسلة من 8 كرات متصلة بروابط مفردة كُتب تحتها C₈H₁₈، وسلسلة من 8 كرات بين الكرتين الأوليين فيها رابطة ثنائية كُتب تحتها C₈H₁₆. ذرات الهيدروجين غير مرسومة."}]'::jsonb, '["التقطير التجزيئي","التكسير الحراري","الاحتراق الكامل","اختبار البروم"]'::jsonb, 'تذكر', 'تعرّف عملية من شكل', 'سهل', 'الكتاب ص 124 — التكسير الحراري'),
('mcq', 3, 'في أيّ الظروف تحدث عملية التكسير الحراري؟', null, null, '["عند غياب الأكسجين ووجود عامل مساعد","عند وجود الأكسجين بوفرة ودون عامل مساعد","عند وجود الأكسجين ووجود عامل مساعد","عند درجة حرارة الغرفة وفي وجود محلول البروم"]'::jsonb, 'تذكر', 'تذكر شروط', 'سهل', 'الكتاب ص 124 — التكسير الحراري'),
('mcq', 4, 'ما الهدف الرئيس من إجراء عملية التكسير الحراري في صناعة تكرير النفط؟', null, null, '["فصل الغازات عن الجازولين في قمة برج التجزئة","تحويل الجازولين إلى زيوت تزييت ثقيلة","زيادة إنتاج الجازولين من المكونات الثقيلة التي تزيد على حاجة السوق","رفع درجة حرارة النفط الخام قبل دخوله برج التجزئة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 124 — التكسير الحراري'),
('mcq', 5, 'تحترق الهيدروكربونات عند تسخينها في وجود الأكسجين فتتحول إلى ثاني أكسيد الكربون وماء. في ضوء ذلك، لماذا تُجرى عملية التكسير الحراري في غياب الأكسجين؟', null, null, '["لأن الأكسجين يحوّل الجزيئات الصغيرة إلى جزيئات كبيرة","لمنع احتراق الهيدروكربونات عند تسخينها","لأن الأكسجين يزيد درجة غليان النواتج","لأن الأكسجين يتفاعل مع الجازولين فيحوّله إلى زيوت ثقيلة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 124 — التكسير الحراري'),
('mcq', 6, 'أيّ المعادلات الآتية تمثل عملية تكسير حراري؟', null, null, '["C₈H₁₈ + C₈H₁₆ → C₁₆H₃₄","CH₄ + 2O₂ → CO₂ + 2H₂O","C₂H₄ + Br₂ → C₂H₄Br₂","C₁₆H₃₄ → C₈H₁₈ + C₈H₁₆"]'::jsonb, 'تطبيق', 'تمييز معادلة', 'متوسط', 'الكتاب ص 124 — التكسير الحراري'),
('mcq', 7, 'إضافة إلى الجازولين، تُنتج عملية التكسير الحراري أيضًا:', null, null, '["النفط الخام والغاز الطبيعي من جديد","الأكسجين اللازم لاحتراق الوقود في المحركات","مواد أولية لصناعة البلاستيك والألياف الصناعية","اليوريا التي لا تُحضَّر إلا من المخلوقات الحية"]'::jsonb, 'تذكر', 'تذكر', 'متوسط', 'الكتاب ص 124 — التكسير الحراري'),
('essay', 1, 'عرّف التكسير الحراري، واذكر شرطي حدوثه، والغرض منه في صناعة تكرير النفط.', null, null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 124 — التكسير الحراري'),
('essay', 2, 'يمثل الشكل الآتي عملية تُجرى على أحد مكونات النفط الثقيلة. (أ) سمِّ العملية، واذكر ظروف حدوثها. (ب) تحقّق من أن عدد ذرات الكربون وعدد ذرات الهيدروجين متساويان في طرفي العملية. (ج) علمًا أن معظم جزيئات الجازولين تتكون من 5 إلى 12 ذرة كربون، هل يصلح الناتجان مكوّنين للجازولين؟ فسّر.', null, '[{"src":"qimg/chem22/c4-l1b-cracking-q.svg","alt":"سلسلة طويلة من 16 كرة متصلة تمثل ذرات الكربون في الجزيء C₁₆H₃₄، يليها سهم فوقه علامة استفهام، ثم ناتجان بينهما علامة +: سلسلة من 8 كرات متصلة بروابط مفردة كُتب تحتها C₈H₁₈، وسلسلة من 8 كرات بين الكرتين الأوليين فيها رابطة ثنائية كُتب تحتها C₈H₁₆. ذرات الهيدروجين غير مرسومة."}]'::jsonb, null, 'فهم', 'تفسير شكل وحساب', 'متوسط', 'الكتاب ص 124 — التكسير الحراري'),
('essay', 3, 'قارن بين التقطير التجزيئي والتكسير الحراري من حيث: (أ) ما يحدث لجزيئات الهيدروكربونات في كل منهما. (ب) نوع التغير (فيزيائي أم كيميائي). (ج) الغرض من كل منهما.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 123–124 — التقطير التجزيئي والتكسير الحراري')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
