from (values
('mcq', 1, 3, 'التكسير الحراري عملية تحوّل فيها المكونات الثقيلة إلى جازولين عن طريق تكسير الجزيئات الكبيرة إلى جزيئات أصغر، وتحدث عند غياب الأكسجين ووجود عامل مساعد.', '["هذا تعريف التقطير التجزيئي، وهو فصل فيزيائي لا يغيّر الجزيئات.","عُكس الاتجاه والظروف: التكسير يحوّل الكبيرة إلى صغيرة، ويحدث في غياب الأكسجين.","الحرق في الأكسجين احتراق، والتكسير يحدث في غياب الأكسجين ولا يُقصد به إنتاج الطاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('mcq', 2, 1, 'يبين الشكل جزيئًا كبيرًا C₁₆H₃₄ يتكسر إلى جزيئين أصغر C₈H₁₈ وC₈H₁₆، وتحويل الجزيئات الكبيرة إلى أصغر هو التكسير الحراري.', '["التقطير يفصل المكونات دون أن يغيّر جزيئاتها، أما الشكل فيبين جزيئًا كبيرًا ينقسم إلى جزيئين أصغر.","","الاحتراق يحتاج إلى أكسجين وينتج ثاني أكسيد الكربون والماء، لا هيدروكربونات أصغر.","اختبار البروم يميّز المشبع من غير المشبع ولا يكسر السلاسل الكربونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('mcq', 3, 0, 'تحدث عملية التكسير الحراري عند غياب الأكسجين ووجود عامل مساعد.', '["","وجود الأكسجين بوفرة يؤدي إلى احتراق الهيدروكربونات، والعامل المساعد شرط للتكسير.","العامل المساعد صحيح، لكن التكسير يحدث في غياب الأكسجين.","التكسير «حراري» يحتاج إلى تسخين، والبروم يُستخدم في التمييز بين المشبع وغير المشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('mcq', 4, 2, 'التقطير التجزيئي نادرًا ما يُنتج الكمية المرغوبة من الجازولين، وينتج زيوتًا ثقيلة تفوق الحاجة؛ فطُوّر التكسير الحراري لتحويل هذه المكونات الثقيلة إلى جازولين، أي لزيادة إنتاج الجازولين.', '["فصل المكونات وظيفة التقطير التجزيئي، لا التكسير.","عكس الهدف: التكسير يحوّل الثقيل إلى جازولين.","","تسخين النفط الخام يتم في الفرن جزءًا من التقطير التجزيئي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('mcq', 5, 1, 'بحسب المعطى تحترق الهيدروكربونات عند تسخينها في وجود الأكسجين؛ فإجراء التكسير في غياب الأكسجين يمنع احتراقها، فتتكسر جزيئاتها الكبيرة إلى جزيئات أصغر بدل أن تتحول إلى ثاني أكسيد الكربون وماء.', '["الأكسجين لا يبني سلاسل كربونية أطول؛ بل يحرق الهيدروكربونات.","","لا علاقة للأكسجين بدرجة غليان النواتج؛ خطره في إحراق الهيدروكربونات.","الأكسجين يحرق الهيدروكربونات إلى ثاني أكسيد الكربون وماء، لا إلى زيوت ثقيلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('mcq', 6, 3, 'التكسير الحراري تحويل جزيء كبير إلى جزيئات أصغر، والمعادلة C₁₆H₃₄ → C₈H₁₈ + C₈H₁₆ تبين جزيئًا من 16 ذرة كربون يتكسر إلى جزيئين في كل منهما 8 ذرات كربون (ذرات C: 16 = 8 + 8، وذرات H: 34 = 18 + 16).', '["هذه عكس التكسير: جزيئان صغيران يتحدان في جزيء كبير.","هذا احتراق للميثان في الأكسجين، والتكسير يحدث في غياب الأكسجين.","هذا تفاعل هيدروكربون غير مشبع مع البروم، ولا تتكسر فيه السلسلة الكربونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('mcq', 7, 2, 'إضافة إلى تكسير الهيدروكربونات الثقيلة إلى جزيئات بالحجم المطلوب في الجازولين، تنتج هذه العملية المواد الأولية لصناعة كثير من المنتجات، منها البلاستيك وأفلام التصوير والألياف الصناعية.', '["النفط والغاز الطبيعي تكوّنا عبر ملايين السنين في باطن الأرض، ولا تنتجهما عملية التكسير.","التكسير يحدث في غياب الأكسجين ولا ينتجه؛ نواتجه هيدروكربونات.","","اليوريا ليست ناتجًا للتكسير، وقد حُضّرت في المختبر من مواد غير عضوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التكسير الحراري: عملية تُحوَّل فيها المكونات الثقيلة إلى جازولين عن طريق تكسير الجزيئات الكبيرة إلى جزيئات أصغر. شرطاه: غياب الأكسجين، ووجود عامل مساعد. والغرض منه زيادة إنتاج الجازولين المطلوب، لأن التقطير التجزيئي يُنتج جازولين أقل من الحاجة وزيوتًا ثقيلة أكثر منها، كما يُنتج المواد الأولية لصناعة البلاستيك وأفلام التصوير والألياف الصناعية.', '["التعريف: تكسير الجزيئات الكبيرة إلى أصغر لتحويل الثقيل إلى جازولين","الشرطان: غياب الأكسجين ووجود عامل مساعد","الغرض: زيادة إنتاج الجازولين"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الشرطان","marks":1},{"element":"الغرض","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التكسير الحراري والتقطير التجزيئي","القول إنه يحدث في وجود الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) التكسير الحراري، ويحدث عند غياب الأكسجين ووجود عامل مساعد. (ب) ذرات الكربون: 16 في المتفاعل، و8 + 8 = 16 في الناتجين. ذرات الهيدروجين: 34 في المتفاعل، و18 + 16 = 34 في الناتجين؛ فالعددان متساويان في الطرفين. (ج) نعم؛ لأن في كل ناتج 8 ذرات كربون، وهو عدد يقع ضمن المدى 5 – 12؛ فالتكسير حوّل جزيئًا ثقيلًا (16 ذرة كربون) إلى جزيئات بحجم جزيئات الجازولين.', '["(أ) التكسير الحراري: غياب الأكسجين + عامل مساعد","(ب) C: 16 = 8 + 8","(ب) H: 34 = 18 + 16","(ج) نعم، 8 ذرات كربون ضمن 5 – 12"]'::jsonb, '["عدد ذرات C في الناتجين: 8 + 8 = 16","عدد ذرات H في الناتجين: 18 + 16 = 34","مقارنة كل منهما بالمتفاعل C₁₆H₃₄"]'::jsonb, '[{"element":"(أ) الاسم والظروف","marks":1},{"element":"(ب) التحقق من C وH","marks":2},{"element":"(ج) الحكم مع التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 4، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 4، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 4، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية العملية تقطيرًا تجزيئيًّا","جمع ذرات الهيدروجين خطأً (18 + 16 = 32)","القول إن C₈ خارج مدى الجازولين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.544Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في التقطير التجزيئي تبقى الجزيئات كما هي، وتُفصل بحسب درجات غليانها بالتبخير ثم التكثف؛ أما في التكسير الحراري فتتكسر الجزيئات الكبيرة إلى جزيئات أصغر. (ب) التقطير التجزيئي تغير فيزيائي (تبخر وتكثف دون تكوّن مواد جديدة)، والتكسير الحراري تغير كيميائي (تتكون مواد جديدة). (ج) الغرض من التقطير فصل النفط إلى مكونات (مشتقات) قابلة للاستعمال، والغرض من التكسير تحويل المكونات الثقيلة الفائضة إلى جازولين ومواد أولية للصناعة.', '["(أ) التقطير يفصل دون تغيير الجزيئات، والتكسير يكسرها إلى أصغر","(ب) التقطير فيزيائي، والتكسير كيميائي","(ج) التقطير للفصل، والتكسير لزيادة الجازولين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التقطير التجزيئي تغيرًا كيميائيًّا","القول إن التقطير يكسر الجزيئات الكبيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb)
