('mcq', 1, 'لماذا خُصّص فرع كامل من الكيمياء لدراسة المركبات العضوية، سُمّي الكيمياء العضوية؟', null, null, '["لوجود عدد هائل من المركبات العضوية يحتاج إلى دراسة خاصة","لأن المركبات العضوية لا تُحضَّر إلا داخل المخلوقات الحية","لأن المركبات العضوية تشمل جميع مركبات الكربون دون استثناء","لأن المركبات العضوية تتكون من الكربون والهيدروجين فقط"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 121 — الكيمياء العضوية'),
('mcq', 2, 'لماذا أطلق الكيميائيون في بداية القرن التاسع عشر اسم «المركبات العضوية» على مركبات الكربون التي تنتجها النباتات والحيوانات؟', null, null, '["لأنها تحتوي على عنصري الكربون والهيدروجين فقط","لأنهم استطاعوا تحضيرها بسهولة في المختبر","لأنها ناتجة عن مخلوقات حية (عضوية)","لأنها تُستخلص من النفط والغاز الطبيعي"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 120 — المركبات العضوية وفكرة القوة الحيوية'),
('mcq', 3, 'ما المقصود بفكرة القوة الحيوية؟', null, null, '["أن ذرة الكربون تكوّن أربع روابط تساهمية قوية مع ذرات أخرى","أن للمخلوقات الحية قوة غامضة تمكّنها وحدها من تركيب مركبات الكربون","أن المركبات العضوية يمكن تحضيرها في المختبر من مواد غير عضوية","أن المخلوقات الحية تحتاج إلى الطاقة لتنمو وتتكاثر"]'::jsonb, 'فهم', 'توضيح مفهوم', 'متوسط', 'الكتاب ص 120 — المركبات العضوية وفكرة القوة الحيوية'),
('mcq', 4, 'يبين المخطط الآتي تطوّر فهم العلماء للمركبات العضوية. ماذا تمثل علامة الاستفهام؟', null, '[{"src":"qimg/chem22/c4-l1b-vitalism.svg","alt":"مخطط تتابعي من اليمين إلى اليسار بعنوان «تطوّر فهم العلماء للمركبات العضوية في القرن التاسع عشر»، فيه أربع مراحل تربطها أسهم: المرحلة الأولى: مركبات تُستخلص من المخلوقات الحية فقط، فسُمّيت «عضوية». المرحلة الثانية: عجز العلماء عن تحضيرها في المختبر. المرحلة الثالثة: علامة استفهام. المرحلة الرابعة: تحضير مركبات عضوية في المختبر من مواد غير عضوية."}]'::jsonb, '["اكتشاف العلماء أن الكربون يقع في المجموعة 14 من الجدول الدوري","تصنيف العلماء الهيدروكربونات إلى مشبعة وغير مشبعة","تحضير فوهلر مركبًا عضويًّا في المختبر","استنتاج العلماء أن تحضير المركبات العضوية يحتاج إلى قوة حيوية"]'::jsonb, 'فهم', 'إكمال مخطط تتابعي', 'متوسط', 'الكتاب ص 120 — المركبات العضوية وفكرة القوة الحيوية'),
('mcq', 5, 'وُصف استنتاج العلماء القائل بالقوة الحيوية بأنه خطأ. ما الخطأ في الاستدلال الذي بُني عليه؟', null, null, '["أنهم فسّروا عجزهم عن تحضير المركبات العضوية بوجود قوة غامضة، ثم تبيّن أن تحضيرها ممكن","أنهم لم يكونوا يعرفون أن المركبات العضوية تحتوي على عنصر الكربون","أنهم حضّروا مركبات عضوية كثيرة في المختبر ثم أنكروا ذلك","أنهم اعتقدوا أن المخلوقات الحية تحتوي على مركبات عضوية"]'::jsonb, 'تحليل', 'تحليل استدلال', 'صعب', 'الكتاب ص 120 — المركبات العضوية وفكرة القوة الحيوية'),
('mcq', 6, 'بعد قبول نظرية دالتون الذرية في بداية القرن التاسع عشر، ما الذي فهمه الكيميائيون عن المركبات التي تصنعها المخلوقات الحية؟', null, null, '["أنها تتكون من مادة حيوية خاصة لا تتألف من ذرات","أنها مركبات لا تحتوي على عنصر الكربون","أنها تتألف -كغيرها من المركبات- من ذرات مرتبة ومرتبطة معًا بتراكيب محددة","أنها تُحضَّر جميعها في المختبر بسهولة من مواد غير عضوية"]'::jsonb, 'فهم', 'توضيح سياق تاريخي', 'متوسط', 'الكتاب ص 120 — المركبات العضوية وفكرة القوة الحيوية'),
('mcq', 7, 'ما الذي تغيّر في أساس تصنيف المركب على أنه عضوي بعد بطلان فكرة القوة الحيوية؟', null, null, '["أصبح التصنيف يعتمد على مصدر المركب (مخلوق حي) لا على تركيبه","أصبح التصنيف يعتمد على قدرة المركب على التفاعل مع البروم","أصبح التصنيف يعتمد على احتواء المركب على الأكسجين","أصبح التصنيف يعتمد على تركيب المركب (احتوائه على الكربون) لا على مصدره"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 120–121 — المركبات العضوية والكيمياء العضوية'),
('essay', 1, 'وضّح المقصود بالكيمياء العضوية، ثم بيّن أصل تسمية المركبات العضوية بهذا الاسم.', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 120–121 — المركبات العضوية والكيمياء العضوية'),
('essay', 2, 'يبين المخطط الآتي تطوّر فهم العلماء للمركبات العضوية في القرن التاسع عشر. (أ) ماذا تمثل علامة الاستفهام؟ (ب) ما العلاقة بين المرحلتين الثانية والثالثة؟ (ج) قبل المرحلة الثانية كان الكيميائيون قد قبلوا نظرية دالتون الذرية؛ فماذا فهموا منها عن المركبات التي تصنعها المخلوقات الحية؟ ولماذا لم يمنعهم هذا الفهم من الوصول إلى الاستنتاج الذي تمثله علامة الاستفهام؟', null, '[{"src":"qimg/chem22/c4-l1b-vitalism.svg","alt":"مخطط تتابعي من اليمين إلى اليسار بعنوان «تطوّر فهم العلماء للمركبات العضوية في القرن التاسع عشر»، فيه أربع مراحل تربطها أسهم: المرحلة الأولى: مركبات تُستخلص من المخلوقات الحية فقط، فسُمّيت «عضوية». المرحلة الثانية: عجز العلماء عن تحضيرها في المختبر. المرحلة الثالثة: علامة استفهام. المرحلة الرابعة: تحضير مركبات عضوية في المختبر من مواد غير عضوية."}]'::jsonb, null, 'تحليل', 'تفسير مخطط تتابعي', 'متوسط', 'الكتاب ص 120 — المركبات العضوية وفكرة القوة الحيوية'),
('essay', 3, 'قال طالب: «الكيمياء العضوية هي الكيمياء التي تدرس المواد المستخلصة من المخلوقات الحية فقط». قوّم عبارة الطالب في ضوء أصل التسمية والتعريف الحديث، مدعّمًا رأيك بمثالين: مركب عضوي يُحضَّر في المصانع، ومركب من مركبات الكربون تنتجه المخلوقات الحية ولا يُعد عضويًّا.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 120–121 — المركبات العضوية والكيمياء العضوية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
