select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'نظرًا إلى وجود الكثير جدًّا من المركبات العضوية (يعرف الكيميائيون الملايين منها، ويحضّرون المزيد كل يوم) خُصّص فرع كامل من الكيمياء لدراستها سُمّي الكيمياء العضوية، وهو يدرس المركبات التي تحتوي على الكربون ما عدا أكاسيده والكربيدات والكربونات. أي أن السبب وجود عدد هائل من المركبات العضوية يحتاج إلى دراسة خاصة.', '["","هذه فكرة القوة الحيوية التي ثبت بطلانها؛ فالمركبات العضوية تُحضَّر في المختبر والمصانع.","أكاسيد الكربون والكربيدات والكربونات مستثناة من المركبات العضوية.","هذا وصف الهيدروكربونات وحدها؛ وكثير من المركبات العضوية يحتوي على عناصر أخرى كالأكسجين والنيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb),
('mcq', 2, 2, 'أشار الكيميائيون إلى المركبات التي تنتجها النباتات والحيوانات بالمركبات العضوية لأنها ناتجة عن مخلوقات حية (عضوية).', '["كثير من هذه المركبات يحتوي على عناصر أخرى كالأكسجين والنيتروجين؛ والمركبات المكونة من C وH فقط هي الهيدروكربونات.","عكس الحقيقة: لم يتمكن العلماء آنذاك من تحضيرها في المختبر.","","التسمية ارتبطت بالمخلوقات الحية مباشرة، لا بالنفط والغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb),
('mcq', 3, 1, 'وفقًا لمبدأ القوة الحيوية، فإن للمخلوقات الحية (العضوية) «قوة حيوية» غامضة تمكّنها من تركيب مركبات الكربون، ولا يمكن تحضيرها بدونها.', '["هذه خاصية من خواص الكربون، ولا علاقة لها بفكرة القوة الحيوية.","","هذه الحقيقة هي التي أبطلت فكرة القوة الحيوية، لا مضمونها.","حاجة المخلوقات إلى الطاقة حقيقة عامة، أما القوة الحيوية فادعاء بقوة غامضة لازمة لتركيب المركبات العضوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb),
('mcq', 4, 3, 'بعد عجز العلماء عن تحضير المركبات العضوية استنتج كثيرون منهم -خطأً- أن ذلك عائد إلى القوة الحيوية، ثم جاء تحضير مركبات عضوية في المختبر فأبطل الفكرة؛ فعلامة الاستفهام تمثل استنتاج الحاجة إلى قوة حيوية.', '["موقع الكربون في الجدول الدوري لا علاقة له بتفسير عجز العلماء عن تحضير المركبات العضوية.","التصنيف إلى مشبعة وغير مشبعة جاء من اختبار البروم، لا من تفسير العجز عن التحضير.","تحضير المركبات العضوية في المختبر هو المرحلة الأخيرة في المخطط، وهو الذي أبطل الفكرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb),
('mcq', 5, 0, 'لم يتمكن العلماء من تصنيع المركبات العضوية، فاستنتج كثيرون منهم -خطأً- أن ذلك عائد إلى قوة حيوية؛ ثم ثبت بتحضير مركبات عضوية في المختبر أن تحضيرها لا يحتاج إلى قوة حيوية.', '["","كانوا يعرفون أن المركبات العضوية من مركبات الكربون؛ الخطأ في تفسير عجزهم عن تحضيرها.","لم يتمكنوا من تحضيرها أصلًا في تلك المرحلة، ولذلك افترضوا القوة الحيوية.","هذا اعتقاد صحيح؛ فأجسام المخلوقات الحية تحتوي فعلًا على مركبات عضوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb),
('mcq', 6, 2, 'عندما قُبلت نظرية دالتون بدأ الكيميائيون يفهمون أن المركبات -بما فيها تلك المصنّعة من المخلوقات الحية- تتألف من ذرات مرتبة ومرتبطة معًا بتراكيب محددة، ومع ذلك لم يتمكنوا من تصنيع المركبات العضوية.', '["نظرية دالتون أوضحت أن المركبات جميعها، ومنها ما تصنعه المخلوقات الحية، تتألف من ذرات.","المركبات التي تصنعها المخلوقات الحية مركبات كربون أساسًا.","","لم يتمكن العلماء آنذاك من تصنيع المركبات العضوية رغم فهمهم أنها تتألف من ذرات؛ ومن هنا نشأت فكرة القوة الحيوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.545Z"}'::jsonb),
('mcq', 7, 3, 'قبل ذلك كان المركب العضوي يُعرف بأنه ناتج عن مخلوق حي؛ وبعد أن حُضّرت مركبات عضوية في المختبر أصبح يُعرف بتركيبه: مركب يحتوي على الكربون (ما عدا أكاسيده والكربيدات والكربونات).', '["عُكس التغيّر: المصدر كان أساس التصنيف القديم.","التفاعل مع البروم يميّز الهيدروكربونات المشبعة من غير المشبعة، ولا يحدد كون المركب عضويًّا.","العنصر المميز للمركبات العضوية هو الكربون، وكثير منها لا يحتوي على الأكسجين كالهيدروكربونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.546Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكيمياء العضوية فرع من الكيمياء يختص بدراسة المركبات العضوية، وهي المركبات التي تحتوي على الكربون ما عدا أكاسيده والكربيدات والكربونات. وأصل التسمية أن الكيميائيين في بداية القرن التاسع عشر أطلقوا اسم «العضوية» على مركبات الكربون التي تنتجها النباتات والحيوانات لأنها ناتجة عن مخلوقات حية (عضوية)، واعتقد كثير منهم أن تحضيرها يحتاج إلى قوة حيوية لا تملكها إلا المخلوقات الحية.', '["الكيمياء العضوية: دراسة مركبات الكربون","استثناء أكاسيد الكربون والكربيدات والكربونات","أصل التسمية: مركبات ناتجة عن مخلوقات حية"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكيمياء العضوية","marks":1},{"element":"الاستثناءات","marks":1},{"element":"أصل التسمية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الكيمياء العضوية بأنها دراسة مركبات المخلوقات الحية فقط","إهمال الاستثناءات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.546Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تمثل فكرة القوة الحيوية: استنتاج العلماء أن المخلوقات الحية لها قوة غامضة تمكّنها وحدها من تركيب المركبات العضوية. (ب) المرحلة الثالثة تفسير (خاطئ) للمرحلة الثانية؛ إذ عزا العلماء عجزهم عن تحضير المركبات العضوية إلى الحاجة إلى قوة حيوية. (ج) فهموا أن هذه المركبات -كغيرها من المركبات- تتألف من ذرات مرتبة ومرتبطة معًا بتراكيب محددة؛ لكن هذا الفهم النظري لم يمكّنهم من تصنيعها فعلًا، فبقي عجزهم العملي قائمًا، ففسّروه -خطأً- بقوة حيوية غامضة، إلى أن ثبت بالتجارب إمكان تحضيرها في المختبر.', '["(أ) فكرة القوة الحيوية","(ب) الثالثة تفسير خاطئ للعجز في الثانية","(ج) المركبات تتألف من ذرات مرتبة بتراكيب محددة، لكن العجز العملي عن تصنيعها بقي ففُسّر بالقوة الحيوية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل علامة الاستفهام تحضيرًا مخبريًّا","القول إن نظرية دالتون أثبتت الحاجة إلى قوة حيوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.546Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة اليوم، وإن كانت تعبّر عن أصل التسمية؛ فقد سُمّيت المركبات عضوية في الأصل لأنها كانت تُستخلص من المخلوقات الحية، واعتُقد أن تحضيرها يحتاج إلى قوة حيوية. لكن بعد تحضير مركبات عضوية في المختبر أصبح المركب العضوي يُعرَّف بتركيبه: مركب يحتوي على الكربون ما عدا أكاسيده والكربيدات والكربونات، أيًّا كان مصدره. مثال الأول: الجازولين أو منتجات البلاستيك التي تُنتج في المصافي والمصانع (أو اليوريا المحضّرة في المختبر). مثال الثاني: ثاني أكسيد الكربون CO₂ الذي تطلقه المخلوقات الحية في التنفس، وهو غير عضوي لأنه من أكاسيد الكربون.', '["الحكم: العبارة غير صحيحة وفق التعريف الحديث","ربطها بأصل التسمية القديم","التعريف الحديث المعتمد على التركيب","مثال مركب عضوي مُصنَّع","مثال CO₂ أو نحوه"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم مع ربطه بأصل التسمية","marks":1},{"element":"التعريف الحديث","marks":1},{"element":"المثالان الصحيحان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 4، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 4، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 4، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","عدّ CO₂ مركبًا عضويًّا لأنه يحتوي على الكربون","إعطاء مثال لمادة لا تحتوي على الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.546Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L1-O12') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L1-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'على أيّ أساس يميّز اختبار البروم بين الهيدروكربونات المشبعة والهيدروكربونات غير المشبعة؟', null, null, '["المشبعة تتفاعل مع البروم، أما غير المشبعة فلا تتفاعل معه","غير المشبعة تتفاعل مع البروم، أما المشبعة فلا تتفاعل معه","المشبعة تذيب البروم، أما غير المشبعة فلا تذيبه","كلتاهما تتفاعل مع البروم، لكن المشبعة أسرع تفاعلًا"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 2, 'محلول البروم بنيّ محمرّ، ويزول لونه عندما يتفاعل البروم مع الهيدروكربون. أُضيف قليل من محلول البروم إلى هيدروكربونين X وY، فكانت النتيجة كما في الشكل الآتي. أيّ الهيدروكربونين غير مشبع؟ ولماذا؟', null, '[{"src":"qimg/chem22/c4-l1b-bromine-tubes.svg","alt":"أنبوبا اختبار بعد إضافة كمية قليلة من محلول البروم البني المحمر إلى كل منهما. الأنبوب X يحتوي على الهيدروكربون X، وبقي لون السائل فيه بنيًّا محمرًّا. الأنبوب Y يحتوي على الهيدروكربون Y، وأصبح السائل فيه عديم اللون."}]'::jsonb, '["Y؛ لأن البروم تفاعل معه فزال لونه","X؛ لأن لون البروم بقي فيه","X وY معًا؛ لأن كليهما خُلط بالبروم","Y؛ لأنه لم يتفاعل مع البروم"]'::jsonb, 'تطبيق', 'تفسير نتيجة تجربة', 'متوسط', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 3, 'لماذا أطلق الكيميائيون اسم «غير المشبعة» على الهيدروكربونات التي تفاعلت مع البروم؟', null, null, '["لأنها لا تذوب في محلول البروم المشبع مهما زادت كميتها","لأنها تحتوي على أكبر عدد ممكن من ذرات الهيدروجين المرتبطة بالكربون","تشبيهًا بالمحلول غير المشبع الذي يذيب مزيدًا من المذاب، فهي تتفاعل مع مزيد من البروم","تشبيهًا بالمحلول المشبع، فهي لا تتفاعل مع أي كمية من البروم"]'::jsonb, 'فهم', 'تفسير تسمية', 'متوسط', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 4, 'يبين المخطط الآتي مقدار البروم الذي تفاعل مع كميات متساوية من أربعة هيدروكربونات. أيّ الهيدروكربونات مشبعة؟', null, '[{"src":"qimg/chem22/c4-l1b-bromine-bars.svg","alt":"مخطط أعمدة: المحور الأفقي أربعة هيدروكربونات A وB وC وD أُخذت منها كميات متساوية، والمحور الرأسي مقدار البروم المتفاعل. A: صفر (لا يوجد عمود). B: عمود متوسط الارتفاع. C: عمود ارتفاعه ضعف ارتفاع عمود B. D: صفر (لا يوجد عمود)."}]'::jsonb, '["B وC","C فقط","A وB","A وD"]'::jsonb, 'تحليل', 'قراءة مخطط أعمدة', 'سهل', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 5, 'أيّ الهيدروكربونات الآتية لا يتفاعل مع البروم؟', null, null, '["CH₂=CHCH₃","CH₃CH₂CH₂CH₃","HC≡CCH₃","CH₂=CHCH₂CH₃"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 6, 'كيف يفسّر الكيميائيون اليوم نتائج اختبار البروم الذي أُجري قبل أكثر من مئة وسبعين عامًا؟', null, null, '["التي تفاعلت مع البروم تحتوي على روابط أحادية فقط، والتي لم تتفاعل تحتوي على روابط ثنائية أو ثلاثية","التي تفاعلت مع البروم تحتوي على ذرات أكسجين، والتي لم تتفاعل لا تحتوي عليها","التي تفاعلت مع البروم تحتوي على روابط ثنائية أو ثلاثية، والتي لم تتفاعل تحتوي على روابط أحادية فقط","التي تفاعلت مع البروم جزيئاتها أكبر كتلة من جزيئات التي لم تتفاعل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('mcq', 7, 'محلول البروم بنيّ محمرّ، ويزول لونه عندما يتفاعل البروم مع الهيدروكربون. أُضيف محلول البروم إلى هيدروكربون مجهول، فبقي اللون البني المحمر دون تغيّر. أيّ الاستنتاجات الآتية صحيح؟', null, null, '["الهيدروكربون مشبع، وجميع الروابط بين ذرات الكربون فيه أحادية","الهيدروكربون غير مشبع، وفيه رابطة ثنائية واحدة على الأقل","الهيدروكربون غير مشبع، وفيه رابطة ثلاثية فقط","الهيدروكربون تفاعل مع كمية كبيرة من البروم"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('essay', 1, 'فسّر كيف يُستعمل اختبار البروم للتمييز بين الهيدروكربونات المشبعة وغير المشبعة، موضّحًا: (أ) ما يحدث لكل نوع عند خلطه بالبروم. (ب) تفسير ذلك بدلالة أنواع الروابط. (ج) أصل تسمية كل من المصطلحين.', null, null, null, 'فهم', 'تفسير إجراء', 'سهل', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('essay', 2, 'يبين المخطط الآتي مقدار البروم الذي تفاعل مع كميات متساوية من أربعة هيدروكربونات A وB وC وD. (أ) صنّف الهيدروكربونات الأربعة إلى مشبعة وغير مشبعة. (ب) فسّر تصنيفك بدلالة أنواع الروابط بين ذرات الكربون. (ج) علمًا أن مقدار البروم الذي يتفاعل مع كمية معينة من هيدروكربون غير مشبع يزداد بزيادة عدد الروابط الثنائية والثلاثية فيه، أيّ الهيدروكربونين B وC يحتوي على روابط مضاعفة أكثر؟ فسّر.', null, '[{"src":"qimg/chem22/c4-l1b-bromine-bars.svg","alt":"مخطط أعمدة: المحور الأفقي أربعة هيدروكربونات A وB وC وD أُخذت منها كميات متساوية، والمحور الرأسي مقدار البروم المتفاعل. A: صفر (لا يوجد عمود). B: عمود متوسط الارتفاع. C: عمود ارتفاعه ضعف ارتفاع عمود B. D: صفر (لا يوجد عمود)."}]'::jsonb, null, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة'),
('essay', 3, 'محلول البروم بنيّ محمرّ، ويزول لونه عندما يتفاعل البروم مع الهيدروكربون. لديك قارورتان غير معنونتين، في إحداهما الهكسان CH₃CH₂CH₂CH₂CH₂CH₃، وفي الأخرى 1-هكسين CH₂=CHCH₂CH₂CH₂CH₃. صِف كيف تستعمل محلول البروم للتمييز بينهما، واذكر النتيجة المتوقعة لكل قارورة مع التفسير.', null, null, null, 'تطبيق', 'تصميم اختبار', 'متوسط', 'الكتاب ص 122 — اختبار البروم والهيدروكربونات المشبعة وغير المشبعة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L1-O13') and x.type = v.type and x.number = v.number);
