from (values
('mcq', 1, 1, 'الهيدروكربونات المشبعة لا تتفاعل مع البروم، أما غير المشبعة فتتفاعل معه؛ وعلى هذا الأساس يميّز الاختبار بينهما.', '["عُكست النتيجة: المشبعة هي التي لا تتفاعل مع البروم.","","الاختبار يعتمد على حدوث تفاعل كيميائي مع البروم، لا على الإذابة.","المشبعة لا تتفاعل مع البروم أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.546Z"}'::jsonb),
('mcq', 2, 0, 'زوال لون البروم في الأنبوب Y يدل على أن البروم تفاعل مع Y، والهيدروكربونات التي تتفاعل مع البروم غير مشبعة؛ أما X فبقي اللون فيه فهو مشبع.', '["","بقاء اللون يعني أن البروم لم يتفاعل، فـ X مشبع.","مجرد الخلط لا يكفي؛ المعيار حدوث التفاعل، ولم يتفاعل إلا Y.","Y غير مشبع فعلًا، لكن التعليل خاطئ: زوال اللون دليل على أنه تفاعل مع البروم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('mcq', 3, 2, 'أطلق الكيميائيون على الهيدروكربونات التي تفاعلت مع البروم اسم غير المشبعة متأثرين بمفهوم أن المحلول المائي غير المشبع قادر على إذابة المزيد من المذاب؛ فهي قادرة على التفاعل مع مزيد من البروم.', '["التسمية لا علاقة لها بالذوبان في محلول البروم، بل بقدرتها على التفاعل مع مزيد منه.","عكس الحقيقة: الروابط المضاعفة فيها تجعل عدد ذرات الهيدروجين أقل من أكبر عدد ممكن.","","هذا وصف الهيدروكربونات المشبعة، وهي التي لم تتفاعل مع البروم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('mcq', 4, 3, 'الهيدروكربونات المشبعة لا تتفاعل مع البروم، والمخطط يبين أن مقدار البروم المتفاعل مع A ومع D صفر؛ فهما مشبعان.', '["B وC تفاعلا مع البروم، فهما غير مشبعين.","C تفاعل مع أكبر مقدار من البروم، فهو غير مشبع.","B تفاعل مع البروم، فهو غير مشبع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('mcq', 5, 1, 'CH₃CH₂CH₂CH₃ روابطه أحادية فقط، فهو مشبع، والهيدروكربونات المشبعة لا تتفاعل مع البروم.', '["فيه رابطة ثنائية، فهو غير مشبع ويتفاعل مع البروم.","","فيه رابطة ثلاثية، فهو غير مشبع ويتفاعل مع البروم.","فيه رابطة ثنائية، فهو غير مشبع ويتفاعل مع البروم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('mcq', 6, 2, 'يفسّر الكيميائيون اليوم النتائج بأن الهيدروكربونات التي تفاعلت مع البروم تحتوي على روابط تساهمية ثنائية أو ثلاثية، أما التي لم تتفاعل فتحتوي على روابط تساهمية أحادية فقط.', '["عُكس التفسير: الروابط المضاعفة هي سبب التفاعل مع البروم.","الهيدروكربونات تتكون من الكربون والهيدروجين فقط، فلا تحتوي على الأكسجين.","","الكتلة الجزيئية لا تحدد التفاعل مع البروم؛ نوع الروابط بين ذرات الكربون هو المحدد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('mcq', 7, 0, 'بقاء لون البروم دليل على عدم حدوث تفاعل، والهيدروكربون الذي لا يتفاعل مع البروم مشبع، أي أن جميع الروابط بين ذرات الكربون فيه أحادية.', '["","لو كان غير مشبع لتفاعل مع البروم وزال اللون.","الرابطة الثلاثية تجعله غير مشبع فيتفاعل مع البروم ويزول اللون.","بقاء اللون يعني أنه لم يتفاعل مع البروم إطلاقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) يُخلط الهيدروكربون بالبروم: الهيدروكربونات غير المشبعة تتفاعل معه، أما المشبعة فلا تتفاعل معه. (ب) غير المشبعة تحتوي على رابطة ثنائية أو ثلاثية على الأقل بين ذرات الكربون، فتتفاعل مع البروم؛ والمشبعة تحتوي على روابط أحادية فقط فلا تتفاعل معه. (ج) سُمّيت التي تفاعلت «غير مشبعة» تشبيهًا بالمحلول غير المشبع القادر على إذابة مزيد من المذاب، فهي قادرة على التفاعل مع مزيد من البروم؛ وسُمّيت التي لم تتفاعل «مشبعة» تشبيهًا بالمحلول المشبع الذي لا يذيب مزيدًا من المذاب.', '["(أ) غير المشبعة تتفاعل والمشبعة لا تتفاعل","(ب) الروابط المضاعفة مقابل الأحادية","(ج) التشبيه بالمحلول المشبع وغير المشبع"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس نتيجة الاختبار","تفسير التسمية بعدد ذرات الهيدروجين دون ذكر المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.547Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) A وD مشبعان، وB وC غير مشبعين. (ب) A وD لم يتفاعلا مع البروم، فروابطهما بين ذرات الكربون أحادية فقط؛ أما B وC فتفاعلا معه، ففي كل منهما رابطة ثنائية أو ثلاثية على الأقل. (ج) C؛ لأنه تفاعل مع مقدار من البروم أكبر من B (عموده أعلى)، وبحسب المعطى يدل ذلك على أنه يحتوي على روابط ثنائية أو ثلاثية أكثر من B.', '["(أ) A وD مشبعان، B وC غير مشبعين","(ب) لا تفاعل ← روابط أحادية؛ تفاعل ← روابط مضاعفة","(ج) C، لأنه تفاعل مع بروم أكثر فروابطه المضاعفة أكثر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 4، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 4، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 4، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ C مشبعًا لأنه أعلى عمود","الاكتفاء في (ج) بالقول إن C غير مشبع دون مقارنته بـ B"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.548Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نضيف كمية قليلة من محلول البروم إلى عينة من كل قارورة ونرجّها. القارورة التي يزول فيها لون البروم البني المحمر تحتوي على 1-هكسين، لأنه غير مشبع (فيه رابطة ثنائية) فيتفاعل مع البروم. والقارورة التي يبقى فيها اللون البني المحمر تحتوي على الهكسان، لأنه مشبع (روابطه أحادية فقط) فلا يتفاعل مع البروم.', '["إضافة قليل من محلول البروم إلى عينة من كل قارورة","زوال اللون ← 1-هكسين غير مشبع","بقاء اللون ← الهكسان مشبع"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات الاختبار","marks":1},{"element":"نتيجة 1-هكسين وتفسيرها","marks":1},{"element":"نتيجة الهكسان وتفسيرها","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس النتيجتين","إغفال التفسير بنوع الرابطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.548Z"}'::jsonb)
