('mcq', 3, 'استنادًا إلى المنحنى الآتي، أيّ العبارات الآتية تربط ربطًا صحيحًا بين عدد ذرات الكربون وموقع تكثف المكوّن في برج التجزئة؟', null, '[{"src":"qimg/chem22/c4-l1b-bp-graph.svg","alt":"منحنى خطي: المحور الأفقي عدد ذرات الكربون في الجزيء (من 0 إلى 9)، والمحور الرأسي درجة الغليان بوحدة °C (من −200 إلى 150)، مع خط أفقي متقطع عند 0°C. النقاط: ميثان (1 ذرة كربون، −161.7°C)، وبروبان (3، −42.1°C)، وبيوتان (4، −0.5°C)، وهكسان (6، 68.7°C)، وأوكتان (8، 125.7°C). يرتفع المنحنى باستمرار من اليسار إلى اليمين."}]'::jsonb, '["كلما زاد عدد ذرات الكربون ارتفعت درجة الغليان، فيتكثف المكوّن في مستوى أدنى من البرج","كلما زاد عدد ذرات الكربون انخفضت درجة الغليان، فيتكثف المكوّن في مستوى أعلى من البرج","كلما زاد عدد ذرات الكربون ارتفعت درجة الغليان، فيتكثف المكوّن في مستوى أعلى من البرج","لا علاقة بين عدد ذرات الكربون ودرجة الغليان، فتتكثف المكونات عشوائيًّا"]'::jsonb, 'تحليل', 'تفسير منحنى', 'متوسط', 'الكتاب ص 123، ص 159 — الشكل 4-6، الجدول 4-7'),
('mcq', 4, 'يبين الجدول الآتي درجات غليان بعض الهيدروكربونات. أيّ ترتيب يبين مواقع تكثفها في برج التجزئة من الأعلى إلى الأسفل؟', '{"headers":["المركب","درجة الغليان (°C)"],"rows":[["الهكسان","68.7"],["الميثان","−161.7"],["الأوكتان","125.7"],["البيوتان","−0.5"],["البروبان","−42.1"]]}'::jsonb, null, '["الأوكتان، الهكسان، البيوتان، البروبان، الميثان","الميثان، البروبان، البيوتان، الهكسان، الأوكتان","البيوتان، البروبان، الميثان، الهكسان، الأوكتان","الميثان، البروبان، البيوتان، الأوكتان، الهكسان"]'::jsonb, 'تطبيق', 'ترتيب بيانات', 'صعب', 'الكتاب ص 159 — س44، الجدول 4-7'),
('mcq', 5, 'يبين الشكل الآتي برج تجزئة مرقمة مخارجه. تُسحب من المخرج (1) المكونات التي تتكثف عند أقل من 40°C، ومن المخرج (2) المكونات التي تتكثف بين 40 و100°C، أما المخارج من (3) إلى (5) فتُسحب منها مكونات تتكثف عند درجات حرارة أعلى من 100°C. من أيّ مخرج يُسحب الهكسان الذي درجة غليانه 68.7°C؟', null, '[{"src":"qimg/chem22/c4-l1b-tower-numbered.svg","alt":"برج تجزئة رأسي بداخله أطباق أفقية، وعلى يمينه فرن يدخله النفط الخام، ويخرج من أعلى الفرن أنبوب ينقل البخار إلى الجزء السفلي من البرج. على يسار البرج ستة مخارج مرقمة من الأعلى إلى الأسفل: المخرج (1) عند قمة البرج، ثم (2) و(3) و(4) و(5) على ارتفاعات متناقصة، والمخرج (6) عند قاع البرج. لا تظهر في الشكل أسماء المكونات ولا درجات الحرارة."}]'::jsonb, '["(1)","(3)","(5)","(2)"]'::jsonb, 'تطبيق', 'ربط بيانات بمخطط', 'سهل', 'الكتاب ص 123 — برج التجزئة (الشكل 4-6)'),
('mcq', 6, 'مكوّنان من مكونات النفط X وY، يُسحب X من مخرج أعلى في برج التجزئة من مخرج Y. أيّ العبارات الآتية صحيحة؟', null, null, '["درجة غليان X أعلى من درجة غليان Y، وجزيئاته أكبر كتلة","درجة غليان X أقل من درجة غليان Y، وجزيئاته أصغر كتلة","درجة غليان X أقل من درجة غليان Y، وجزيئاته أكبر كتلة","درجتا غليان X وY متساويتان، لأنهما يُسحبان من البرج نفسه"]'::jsonb, 'تحليل', 'استنتاج', 'متوسط', 'الكتاب ص 123 — تكثف المكونات مع انخفاض الكتلة الجزيئية'),
('mcq', 7, 'اعتمادًا على الشكل الآتي، وعلمًا أن الجازولين سائل خفيف قليل اللزوجة عند درجة حرارة الغرفة، في حين أن زيوت التزييت والشحوم مواد كثيفة لزجة، ما العلاقة بين عدد ذرات الكربون ولزوجة مكونات النفط عند تبريدها إلى درجة حرارة الغرفة؟', null, '[{"src":"qimg/chem22/c4-l1b-tower-full.svg","alt":"برج تجزئة رأسي تتدرج ألوانه من البرتقالي في الأسفل إلى الأزرق الفاتح في الأعلى، وبداخله أطباق أفقية. على يمينه فرن يدخله النفط الخام، ويخرج من أعلى الفرن أنبوب ينقل البخار إلى الجزء السفلي من البرج، حيث كُتبت درجة الحرارة 400°C. على يسار البرج ستة مخارج، وهي من الأعلى إلى الأسفل: غازات، من CH₄ إلى C₄H₁₀؛ ثم الجازولين، من C₅H₁₂ إلى C₁₂H₂₆؛ ثم الكيروسين، من C₁₂H₂₆ إلى C₁₆H₃₄؛ ثم زيت التسخين، من C₁₅H₃₂ إلى C₁₈H₃₈؛ ثم زيت التزييت والتشحيم، من C₁₇H₃₆ إلى C₂₂H₄₆؛ ثم المخلفات عند قاع البرج."}]'::jsonb, '["تقل اللزوجة بزيادة عدد ذرات الكربون؛ فالجازولين أكثر لزوجة من زيت التزييت والتشحيم","لا يؤثر عدد ذرات الكربون في اللزوجة؛ فجميع المكونات السائلة متساوية اللزوجة","تزداد اللزوجة بزيادة عدد ذرات الكربون؛ فزيت التزييت والتشحيم أكثر لزوجة من الجازولين","الكيروسين أكثر لزوجة من زيت التزييت والتشحيم؛ لأنه يُسحب من مخرج أعلى منه"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 123، ص 125 — الشكل 4-6، التقويم 4-1 س7'),
('essay', 1, 'يبين المنحنى الآتي العلاقة بين عدد ذرات الكربون ودرجة الغليان لخمسة هيدروكربونات. (أ) صِف العلاقة التي يبينها المنحنى. (ب) أيّ المركبات الخمسة غازات عند 25°C؟ فسّر. (ج) استنتج من أي جزء من برج التجزئة يُسحب كل من الميثان والأوكتان، معلّلًا إجابتك.', null, '[{"src":"qimg/chem22/c4-l1b-bp-graph.svg","alt":"منحنى خطي: المحور الأفقي عدد ذرات الكربون في الجزيء (من 0 إلى 9)، والمحور الرأسي درجة الغليان بوحدة °C (من −200 إلى 150)، مع خط أفقي متقطع عند 0°C. النقاط: ميثان (1 ذرة كربون، −161.7°C)، وبروبان (3، −42.1°C)، وبيوتان (4، −0.5°C)، وهكسان (6، 68.7°C)، وأوكتان (8، 125.7°C). يرتفع المنحنى باستمرار من اليسار إلى اليمين."}]'::jsonb, null, 'تحليل', 'تفسير منحنى', 'متوسط', 'الكتاب ص 123، ص 159 — الشكل 4-6، الجدول 4-7'),
('essay', 2, 'ادرس الشكل الآتي، ثم أجب: (أ) ما العلاقة بين عدد ذرات الكربون في جزيئات المكوّن وارتفاع المخرج الذي يُسحب منه؟ استشهد بمكوّنين من الشكل. (ب) فسّر لماذا تُسحب المخلفات من قاع البرج. (ج) رتّب الجازولين والكيروسين وزيت التسخين حسب ارتفاع درجات غليانها، واربط ذلك بمواقع مخارجها.', null, '[{"src":"qimg/chem22/c4-l1b-tower-full.svg","alt":"برج تجزئة رأسي تتدرج ألوانه من البرتقالي في الأسفل إلى الأزرق الفاتح في الأعلى، وبداخله أطباق أفقية. على يمينه فرن يدخله النفط الخام، ويخرج من أعلى الفرن أنبوب ينقل البخار إلى الجزء السفلي من البرج، حيث كُتبت درجة الحرارة 400°C. على يسار البرج ستة مخارج، وهي من الأعلى إلى الأسفل: غازات، من CH₄ إلى C₄H₁₀؛ ثم الجازولين، من C₅H₁₂ إلى C₁₂H₂₆؛ ثم الكيروسين، من C₁₂H₂₆ إلى C₁₆H₃₄؛ ثم زيت التسخين، من C₁₅H₃₂ إلى C₁₈H₃₈؛ ثم زيت التزييت والتشحيم، من C₁₇H₃₆ إلى C₂₂H₄₆؛ ثم المخلفات عند قاع البرج."}]'::jsonb, null, 'تحليل', 'تفسير مخطط', 'صعب', 'الكتاب ص 123 — برج التجزئة (الشكل 4-6)'),
('essay', 3, 'درجة غليان الهكسان C₆H₁₄ هي 68.7°C، ودرجة غليان الهبتان C₇H₁₆ هي 98.5°C. (أ) أيّ المركبين يتكثف في مستوى أدنى من برج التجزئة؟ فسّر. (ب) علمًا أن مخرج الجازولين تُسحب منه المكونات التي تتكثف بين 40 و100°C، فسّر لماذا يُسحب المركبان معًا من المخرج نفسه، ولماذا يكون ما يُسحب من هذا المخرج خليطًا لا مادة نقية.', null, null, null, 'تحليل', 'استنتاج', 'متوسط', 'الكتاب ص 123–124، ص 164 — برج التجزئة، تصنيف الجازولين، جدول بيانات الهيدروكربونات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
