from (values
('mcq', 1, 3, 'الكيروسين يضم الهيدروكربونات من C₁₂H₂₆ إلى C₁₆H₃₄، والعدد 14 يقع ضمن هذا المدى فقط؛ فيُسحب الجزيء مع الكيروسين.', '["الجازولين يضم جزيئات من C₅ إلى C₁₂، و14 أكبر من 12.","زيت التسخين يبدأ من C₁₅، و14 أقل من 15.","زيت التزييت والتشحيم يضم جزيئات من C₁₇ إلى C₂₂، أي أثقل بكثير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.548Z"}'::jsonb),
('mcq', 2, 2, 'درجات غليان الغازات أقل من 40°C، فلا تتكثف في المناطق الساخنة، وتستمر في الصعود حتى قمة البرج حيث تُسحب. أي لأن درجات غليانها منخفضة جدًّا، فتبقى بخارًا حتى أبرد منطقة في البرج.', '["المكونات ذات درجات الغليان المرتفعة تتكثف في أسفل البرج لا في قمته.","جزيئات الغازات هي الأصغر كتلة (1 إلى 4 ذرات كربون).","","لا يحدث تكسير في برج التجزئة؛ التكسير عملية مستقلة تحتاج إلى عامل مساعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.549Z"}'::jsonb),
('mcq', 3, 0, 'المنحنى يرتفع من الميثان (−161.7°C) إلى الأوكتان (125.7°C)؛ فدرجة الغليان تزداد بزيادة عدد ذرات الكربون، والمكوّن ذو درجة الغليان الأعلى يتكثف في منطقة أسخن، أي في مستوى أدنى من البرج.', '["","المنحنى صاعد: درجة الغليان ترتفع بزيادة عدد ذرات الكربون، لا تنخفض.","العلاقة الأولى صحيحة، لكن المكوّن ذا درجة الغليان المرتفعة يتكثف في المنطقة الأسخن، وهي أسفل البرج.","المنحنى يبين علاقة منتظمة واضحة، وموقع التكثف يحدده هذا الترتيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.549Z"}'::jsonb),
('mcq', 4, 1, 'المكوّن الأقل درجة غليان يصعد أعلى: الميثان (−161.7) ثم البروبان (−42.1) ثم البيوتان (−0.5) ثم الهكسان (68.7) ثم الأوكتان (125.7).', '["هذا ترتيب من الأسفل إلى الأعلى؛ الأوكتان أعلى درجة غليان فيتكثف في الأسفل.","","رُتّبت درجات الغليان السالبة بحسب قيمتها دون الإشارة؛ والصحيح أن −161.7°C أقل من −42.1°C وأقل من −0.5°C.","الهكسان (68.7°C) أقل درجة غليان من الأوكتان (125.7°C)، فيتكثف أعلى منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.549Z"}'::jsonb),
('mcq', 5, 3, 'درجة غليان الهكسان 68.7°C تقع في المدى 40 – 100°C، وهو مدى المخرج (2)؛ فيتكثف الهكسان ويُسحب منه.', '["المخرج (1) للمكونات التي تتكثف عند أقل من 40°C، والهكسان يتكثف عند درجة أعلى.","المخرج (3) للمكونات التي تتكثف عند درجات أعلى من 100°C، و68.7°C أقل من ذلك.","المخرج (5) للمكونات الأثقل التي تتكثف عند درجات أعلى من 100°C، فهو أدنى من مخرج الهكسان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.549Z"}'::jsonb),
('mcq', 6, 1, 'تنخفض درجة الحرارة في اتجاه أعلى البرج، فما يُسحب من الأعلى يتكثف عند درجة حرارة أقل، أي درجة غليانه أقل؛ ودرجة الغليان تنخفض مع انخفاض الكتلة الجزيئية، فجزيئات X أصغر كتلة.', '["عُكست العلاقة: المكوّن الذي يُسحب أعلى يتكثف في منطقة أبرد، فدرجة غليانه أقل.","","الجزء الأول صحيح، لكن درجة الغليان تنخفض مع انخفاض الكتلة الجزيئية، فجزيئات X أصغر.","المكونات تُسحب من مخارج مختلفة لأن درجات غليانها مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.549Z"}'::jsonb),
('mcq', 7, 2, 'يبين الشكل أن عدد ذرات الكربون يزداد من C₅ – C₁₂ في الجازولين إلى C₁₇ – C₂₂ في زيت التزييت والتشحيم؛ وبما أن الجازولين قليل اللزوجة والزيوت والشحوم لزجة، فاللزوجة تزداد بزيادة عدد ذرات الكربون.', '["عكس المعطى: الجازولين (C₅ – C₁₂) قليل اللزوجة، وزيت التزييت والتشحيم (C₁₇ – C₂₂) لزج.","المعطى يبين أن الجازولين قليل اللزوجة والزيوت والشحوم لزجة، فاللزوجة تتغير بتغير عدد ذرات الكربون.","","الكيروسين أقل عددًا في ذرات الكربون (C₁₂ – C₁₆) من زيت التزييت (C₁₇ – C₂₂)، فهو أقل لزوجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.550Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) كلما زاد عدد ذرات الكربون ارتفعت درجة الغليان. (ب) الميثان (−161.7°C) والبروبان (−42.1°C) والبيوتان (−0.5°C)؛ لأن درجات غليانها أقل من 25°C، فتكون غازات عند هذه الدرجة؛ أما الهكسان (68.7°C) والأوكتان (125.7°C) فسائلان. (ج) الميثان أقل درجة غليان، فيبقى بخارًا حتى أبرد منطقة ويُسحب من قمة البرج مع الغازات؛ والأوكتان أعلى درجة غليان منه بكثير، فيتكثف في منطقة أسخن، أي في مستوى أدنى من الميثان في البرج.', '["(أ) علاقة طردية بين عدد ذرات الكربون ودرجة الغليان","(ب) الميثان والبروبان والبيوتان غازات لأن درجات غليانها أقل من 25°C","(ج) الميثان في القمة، والأوكتان أدنى منه مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 4، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 4، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 4، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ البيوتان سائلًا لأن درجة غليانه قريبة من الصفر","القول إن الأوكتان يُسحب من القمة لأن جزيئاته أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.550Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كلما زاد عدد ذرات الكربون في جزيئات المكوّن سُحب من مخرج أدنى في البرج؛ فالغازات (CH₄ – C₄H₁₀) تُسحب من القمة، وزيت التزييت والتشحيم (C₁₇H₃₆ – C₂₂H₄₆) يُسحب من مخرج قريب من القاع. (ب) لأن المخلفات أثقل المكونات (أكبر كتلة جزيئية) وأعلاها درجة غليان، فلا تصعد في البرج وتبقى في قاعه، وهو أسخن منطقة فيه (نحو 400°C). (ج) الجازولين أقل درجة غليان، ثم الكيروسين، ثم زيت التسخين أعلاها؛ لأن عدد ذرات الكربون (والكتلة الجزيئية) يزداد بهذا الترتيب (C₅ – C₁₂ ثم C₁₂ – C₁₆ ثم C₁₅ – C₁₈)؛ لذا يُسحب الجازولين من أعلى المخارج الثلاثة، ثم الكيروسين، ثم زيت التسخين في الأسفل، لأن المكوّن الأعلى درجة غليان يتكثف في منطقة أسخن أدنى من البرج.', '["(أ) زيادة عدد ذرات الكربون ← مخرج أدنى، مع مثالين","(ب) المخلفات أثقل وأعلى درجة غليان فتبقى في القاع","(ج) الترتيب والربط بموقع المخرج"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الربط العكسي بين عدد ذرات الكربون وارتفاع المخرج","الربط العكسي بين درجة الغليان وارتفاع المخرج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.550Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الهبتان؛ لأن عدد ذرات الكربون فيه أكبر ودرجة غليانه أعلى (98.5°C > 68.7°C)، فيتكثف في منطقة أسخن، أي في مستوى أدنى من البرج. (ب) لأن درجتي غليانهما (68.7°C و98.5°C) تقعان كلتاهما ضمن المدى 40 – 100°C، والمخرج الواحد يجمع كل ما يتكثف ضمن هذا المدى من درجات الحرارة، فيُسحبان معًا. ولأن هيدروكربونات كثيرة مختلفة تقع درجات غليانها ضمن المدى نفسه، يكون ما يُسحب من المخرج خليطًا منها لا مادة نقية؛ ولذلك يُعد الجازولين خليطًا من الهيدروكربونات.', '["(أ) الهبتان أدنى لأن درجة غليانه أعلى","(ب) كلاهما ضمن مدى 40 – 100°C فيُسحبان معًا","(ب) المخرج يجمع كل ما يغلي ضمن المدى، فما يُسحب منه خليط"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) سحبهما معًا","marks":1},{"element":"(ب) الجازولين خليط","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار الهكسان لأن جزيئاته أخف","الظن أن كل مخرج يعطي مركبًا واحدًا نقيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.550Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L1-O14') and x.type = v.type and x.number = v.number
