insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L1-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالفرقعة في محرك السيارة؟', null, null, '["احتراق خليط الوقود والهواء احتراقًا تامًّا في اللحظة المناسبة بعد اشتعال شمعة الاحتراق","تكسير الجزيئات الكبيرة في الوقود إلى جزيئات أصغر داخل أسطوانة المحرك","اشتعال خليط الوقود والهواء مبكرًا قبل أن يصل المكبس إلى الموضع الصحيح وقبل اشتعال شمعة الاحتراق","تكثف بخار الوقود داخل الأسطوانة قبل أن يختلط بالهواء ويشتعل"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 124 — الفرقعة في محركات السيارات'),
('mcq', 2, 'أيّ الأسطوانتين في الشكل الآتي تمثل حدوث الفرقعة؟ ولماذا؟', null, '[{"src":"qimg/chem22/c4-l1b-knock.svg","alt":"أسطوانتا محرك مرقمتان، في أعلى كل منهما شمعة احتراق، وفي داخل كل منهما مكبس يتحرك إلى أعلى (سهم أزرق). الأسطوانة (1): المكبس ما زال في أسفل الأسطوانة، ولا تنطلق شرارة من الشمعة، ومع ذلك يظهر اشتعال (نجمة برتقالية) في خليط الوقود والهواء. الأسطوانة (2): المكبس في أعلى موضعه، وتنطلق شرارة (خطوط صفراء) من الشمعة، ولا يظهر اشتعال قبلها."}]'::jsonb, '["(2)؛ لأن الشرارة انطلقت والمكبس في أعلى موضعه","(1) و(2) معًا؛ لأن الخليط اشتعل في كلتيهما","(2)؛ لأن المكبس يتحرك فيها إلى أعلى","(1)؛ لأن الخليط اشتعل مبكرًا قبل انطلاق الشرارة"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 124 — الفرقعة في محركات السيارات'),
('mcq', 3, 'ماذا يعني أن يكون رقم الأوكتان لجازولين ما مرتفعًا؟', null, null, '["أنه يحتوي على نسبة أكبر من الهيدروكربونات المستقيمة السلسلة","أن قدرته على منع الفرقعة أكبر","أن جميع جزيئاته تحتوي على 8 ذرات كربون","أنه يحترق قبل اشتعال شمعة الاحتراق بسهولة أكبر"]'::jsonb, 'فهم', 'توضيح مفهوم', 'متوسط', 'الكتاب ص 125 — رقم الأوكتان (الشكل 4-8)'),
('mcq', 4, 'ما رقما الأوكتان لنوعي الجازولين في المملكة العربية السعودية؟', null, null, '["91 و95","89 و91","95 و100","100 و110"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'الكتاب ص 125 — رقم الأوكتان (الشكل 4-8)'),
('mcq', 5, 'يبين الشكل الآتي أرقام الأوكتان لأنواع مختلفة من الوقود. أيّها أكثر مقاومة للفرقعة؟', null, '[{"src":"qimg/chem22/c4-l1b-octane-scale.svg","alt":"خط أعداد أفقي بعنوان رقم الأوكتان، وعليه نقاط: 89 (جازولين متوسط الدرجة)، و91 و95 (نوعا الجازولين في المملكة العربية السعودية)، و100 (وقود الطائرات)، و110 (وقود سيارات السباق)."}]'::jsonb, '["الجازولين المتوسط الدرجة","الجازولين 95","وقود سيارات السباق","وقود الطائرات"]'::jsonb, 'فهم', 'قراءة مخطط', 'سهل', 'الكتاب ص 125 — رقم الأوكتان (الشكل 4-8)'),
('mcq', 6, 'ما نتائج حدوث الاشتعال قبل الموعد المناسب أو بعده في محرك السيارة؟', null, null, '["خسارة كثير من الطاقة، وانخفاض فاعلية الوقود، وفقدان كفاءة المحرك","زيادة الطاقة الناتجة من الوقود، وارتفاع كفاءة المحرك","تحوّل الجازولين إلى زيوت ثقيلة داخل أسطوانة المحرك","توقف الاحتراق تمامًا فلا ينتج المحرك أي طاقة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 124 — الفرقعة في محركات السيارات'),
('mcq', 7, 'لماذا يُسبّب الجازولين الغني بالهيدروكربونات ذات السلاسل المستقيمة (غير المتفرعة) حدوث الفرقعة؟', null, null, '["لأن هذه الهيدروكربونات لا تشتعل إطلاقًا داخل أسطوانة المحرك","لأن درجات غليانها أعلى من 300°C فلا تتبخر داخل المحرك","لأنها تتكسر داخل المحرك إلى جزيئات أصغر تحتاج إلى أكسجين أكثر","لأن معظم هذه الهيدروكربونات لا يحترق تمامًا، ويميل إلى الاشتعال المبكر بفعل الحرارة والضغط"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 124 — الفرقعة في محركات السيارات'),
('essay', 1, 'وضّح المقصود بكل من: الفرقعة، ورقم الأوكتان، ثم بيّن العلاقة بينهما.', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 124–125 — الفرقعة ورقم الأوكتان'),
('essay', 2, 'يوصي دليل إحدى السيارات باستخدام الجازولين 95، فملأ صاحبها خزانها بالجازولين 91. (أ) أيّ النوعين أكثر مقاومة للفرقعة؟ (ب) توقّع أثر ذلك في أداء المحرك، وفسّر. (ج) اذكر عاملين يحددان رقم الأوكتان الذي تحتاج إليه السيارة.', null, null, null, 'تطبيق', 'تنبؤ وتفسير', 'متوسط', 'الكتاب ص 124–125 — الفرقعة ورقم الأوكتان'),
('essay', 3, 'قارن بين الأسطوانتين (1) و(2) في الشكل الآتي من حيث: (أ) موضع المكبس عند اشتعال الخليط. (ب) سبب الاشتعال. (ج) أثر ذلك في الطاقة الناتجة وكفاءة المحرك. ثم (د) اقترح كيف يمكن منع الحالة غير المرغوب فيها.', null, '[{"src":"qimg/chem22/c4-l1b-knock.svg","alt":"أسطوانتا محرك مرقمتان، في أعلى كل منهما شمعة احتراق، وفي داخل كل منهما مكبس يتحرك إلى أعلى (سهم أزرق). الأسطوانة (1): المكبس ما زال في أسفل الأسطوانة، ولا تنطلق شرارة من الشمعة، ومع ذلك يظهر اشتعال (نجمة برتقالية) في خليط الوقود والهواء. الأسطوانة (2): المكبس في أعلى موضعه، وتنطلق شرارة (خطوط صفراء) من الشمعة، ولا يظهر اشتعال قبلها."}]'::jsonb, null, 'تحليل', 'مقارنة واقتراح', 'صعب', 'الكتاب ص 124–125 — الفرقعة ورقم الأوكتان')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
