from (values
('mcq', 1, 2, 'الفرقعة احتراق مبكر يحدث عندما يشتعل خليط الوقود والهواء بفعل الحرارة والضغط قبل أن يصبح المكبس في الموضع الصحيح وقبل اشتعال شمعة الاحتراق.', '["هذا هو الاحتراق المطلوب في المحرك، وليس الفرقعة.","تكسير الجزيئات يحدث في مصافي النفط بوجود عامل مساعد، وليس هو الفرقعة.","","الفرقعة اشتعال مبكر، لا تكثف للبخار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.551Z"}'::jsonb),
('mcq', 2, 3, 'في (1) يشتعل الخليط دون شرارة والمكبس ما زال في أسفل الأسطوانة، أي أن الخليط اشتعل مبكرًا قبل انطلاق الشرارة وقبل الموضع الصحيح للمكبس، وهذا هو الاحتراق المبكر المسمى فرقعة.', '["هذا هو الاشتعال الصحيح في اللحظة المناسبة.","الاشتعال يحدث في كل محرك؛ الفرقعة هي الاشتعال المبكر فقط، كما في (1).","المكبس يتحرك إلى أعلى في الأسطوانتين؛ والفارق في توقيت الاشتعال.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.551Z"}'::jsonb),
('mcq', 3, 1, 'تُستخدم تصنيفات الأوكتان لإعطاء قيم منع الفرقعة؛ فكلما ارتفع رقم الأوكتان زادت قدرة الجازولين على منع الفرقعة.', '["الهيدروكربونات المستقيمة السلسلة هي التي تميل إلى الفرقعة، فكثرتها تخفض قدرة الوقود على منعها.","","الجازولين خليط من هيدروكربونات من 5 إلى 12 ذرة كربون؛ رقم الأوكتان تصنيف لمنع الفرقعة لا عدد ذرات.","هذا وصف الفرقعة نفسها، والرقم المرتفع يعني مقاومتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('mcq', 4, 0, 'في المملكة العربية السعودية صُنّف رقم الأوكتان على مضخات الجازولين إلى نوعين: 91 و95.', '["","89 رقم الجازولين المتوسط الدرجة عمومًا، وليس من نوعي الجازولين في المملكة.","100 هو رقم وقود الطائرات.","هذان رقما وقود الطائرات (100) ووقود سيارات السباق (110)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('mcq', 5, 2, 'كلما ارتفع رقم الأوكتان زادت قيمة منع الفرقعة، وأعلى رقم في الشكل 110 لوقود سيارات السباق؛ فهو الأكثر مقاومة للفرقعة.', '["رقمه 89، وهو الأقل بين الأنواع في الشكل، فهو الأقل مقاومة.","رقمه 95، وهو أقل من 100 و110.","","رقمه 100، وهو أقل من رقم وقود سيارات السباق 110."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('mcq', 6, 0, 'إذا حدث الاشتعال قبل الموعد المناسب أو بعده أدى ذلك إلى خسارة الكثير من الطاقة، وانخفاض فاعلية الوقود، وفقدان كفاءة المحرك.', '["","عكس الحقيقة: الاشتعال في غير موعده يهدر الطاقة.","لا تتكون زيوت ثقيلة؛ المشكلة في توقيت الاشتعال وما يسببه من خسارة للطاقة.","الاحتراق يحدث لكن في توقيت غير مناسب، فتُهدر الطاقة دون أن تنعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('mcq', 7, 3, 'لا تحترق معظم الهيدروكربونات ذات السلاسل المستقيمة تمامًا، وتميل بفعل الحرارة والضغط إلى الاشتعال المبكر قبل أن يصبح المكبس في الموضع الصحيح وقبل اشتعال الشمعة، وهذا الاحتراق المبكر هو الفرقعة.', '["هي تشتعل، لكن في وقت مبكر قبل اشتعال الشمعة.","مكونات الجازولين تتكثف بين 40 و100°C، فهي سهلة التبخر.","التكسير يحتاج إلى عامل مساعد وغياب الأكسجين، ولا يحدث في المحرك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفرقعة: احتراق مبكر يحدث عندما يشتعل خليط الوقود والهواء في أسطوانة المحرك بفعل الحرارة والضغط قبل أن يصبح المكبس في الموضع الصحيح وقبل اشتعال شمعة الاحتراق. رقم الأوكتان: نظام لتصنيف الجازولين أُنشئ في أواخر العشرينيات يعطي قيمة قدرته على منع الفرقعة. العلاقة: كلما ارتفع رقم الأوكتان زادت قدرة الجازولين على منع الفرقعة.', '["تعريف الفرقعة","تعريف رقم الأوكتان","العلاقة: الرقم الأعلى يمنع الفرقعة أكثر"]'::jsonb, '[]'::jsonb, '[{"element":"الفرقعة","marks":1},{"element":"رقم الأوكتان","marks":1},{"element":"العلاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف رقم الأوكتان بأنه عدد ذرات الكربون في الجازولين","عكس العلاقة بين الرقم والفرقعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الجازولين 95؛ لأن رقم الأوكتان الأعلى يعني قدرة أكبر على منع الفرقعة. (ب) يزداد احتمال حدوث الفرقعة، أي اشتعال الخليط مبكرًا قبل أن يصل المكبس إلى الموضع الصحيح وقبل اشتعال الشمعة، فيؤدي ذلك إلى خسارة كثير من الطاقة وانخفاض فاعلية الوقود وفقدان كفاءة المحرك. (ج) ضغط المكبس على خليط الوقود والهواء، ودفع السيارة.', '["(أ) 95 أكثر مقاومة","(ب) احتمال الفرقعة يزداد مع خسارة الطاقة والكفاءة","(ج) ضغط المكبس على الخليط، ودفع السيارة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 3، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 3، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرقم 91 أكثر مقاومة لأنه أصغر","ذكر لون الوقود أو سعره عاملًا محددًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في (1) يشتعل الخليط والمكبس ما زال في أسفل الأسطوانة (قبل الموضع الصحيح)، وفي (2) يشتعل والمكبس في أعلى موضعه (الموضع الصحيح). (ب) في (1) يشتعل الخليط بفعل الحرارة والضغط قبل انطلاق الشرارة (احتراق مبكر = فرقعة)، وفي (2) يشتعل بشرارة شمعة الاحتراق في اللحظة المناسبة. (ج) في (1) تُخسر كمية كبيرة من الطاقة وتنخفض فاعلية الوقود وكفاءة المحرك، وفي (2) يحترق الخليط تمامًا في اللحظة المناسبة فيُستفاد من طاقته. (د) استعمال جازولين برقم أوكتان مناسب للسيارة (91 أو 95 بحسب دليلها)، لأن رقم الأوكتان الأعلى يعني قدرة أكبر على منع الفرقعة.', '["(أ) (1) قبل الموضع الصحيح، (2) في الموضع الصحيح","(ب) (1) الحرارة والضغط قبل الشرارة، (2) الشرارة","(ج) (1) خسارة الطاقة والكفاءة","(د) جازولين برقم أوكتان مناسب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة تستوفي جميع العناصر المطلوبة بدقة"},{"level":"3 درجات","description":"إجابة صحيحة لعناصر مجموع درجاتها 3 من 4، مع نقص أو خطأ في الباقي"},{"level":"2 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 2 من 4، مع نقص أو خطأ في الباقي"},{"level":"1 درجة","description":"إجابة صحيحة لعناصر مجموع درجاتها 1 من 4، مع نقص أو خطأ في الباقي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (2) هي الفرقعة لظهور الشرارة","اقتراح استعمال جازولين برقم أوكتان أقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.552Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
