select (select id from public.objectives where code = 'K22-C4-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ العبارات الآتية تعرّف الجازولين تعريفًا صحيحًا؟', null, null, '["مركب نقي واحد صيغته الجزيئية C₈H₁₈ يُفصل من النفط الخام","خليط من هيدروكربونات معظم جزيئاتها بروابط تساهمية أحادية وفيها 5–12 ذرة كربون","خليط من غازات هيدروكربونية فيها 1–4 ذرات كربون تُسحب من أعلى برج التجزئة","خليط من هيدروكربونات معظم جزيئاتها بروابط ثلاثية وفيها 17–22 ذرة كربون"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 124 — تصنيف الجازولين'),
('mcq', 2, 'يمثل الشكل الآتي برج تقطير تجزيئي مبسطًا للنفط الخام، وبجانب كل مخرج مدى درجات الحرارة التي يُسحب عندها المشتق. من أيّ المخارج يُسحب الجازولين؟', null, '[{"src":"qimg/chem22/c4-l2a-tower.svg","alt":"رسم مبسط لبرج تقطير تجزيئي: عمود رأسي مقسم بخطوط متقطعة، ومكتوب فوقه «أعلى البرج: أبرد»، وتحته «أسفل البرج: الأسخن». يدخل سهم «بخار النفط الخام» إلى أسفل البرج من الجهة اليسرى. وتخرج من الجهة اليمنى أربعة أسهم مرمزة من الأعلى إلى الأسفل: المخرج (أ) عند أقل من 40°C، والمخرج (ب) عند 40 – 100°C، والمخرج (ج) عند 105 – 275°C، والمخرج (د) عند درجات حرارة فوق 300°C، ثم سهم أخير في أسفل البرج مكتوب عنده «المخلفات»."}]'::jsonb, '["المخرج (أ)","المخرج (ب)","المخرج (ج)","المخرج (د)"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 123 — الشكل 6-4 برج التجزئة (مدى الجازولين 40 – 100°C)'),
('mcq', 3, 'لماذا لا يُعد الجازولين الناتج عن تكرير النفط الخام مادة نقية؟', null, null, '["لأن جزيئاته جميعها تحتوي على روابط ثنائية بين ذرات الكربون","لأنه سائل يتبخر بسهولة عند درجة حرارة الغرفة","لأنه ناتج عن تكسير المكونات الثقيلة في غياب الأكسجين","لأنه خليط من عدد من الهيدروكربونات المختلفة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 124 — تصنيف الجازولين'),
('mcq', 4, 'أيّ الصيغ الجزيئية الآتية يمكن أن تكون لأحد مكونات الجازولين؟', null, null, '["C₄H₁₀","C₁₆H₃₄","C₈H₁₈","C₂₀H₄₂"]'::jsonb, 'تطبيق', 'تطبيق معلومة على صيغ', 'متوسط', 'الكتاب ص 123–124 — مكونات الجازولين (C₅H₁₂ إلى C₁₂H₂₆)'),
('mcq', 5, 'ما الذي يدل عليه رقم الأوكتان المكتوب على مضخات الجازولين؟', null, null, '["قدرة الجازولين على منع الفرقعة في المحرك","عدد ذرات الكربون في معظم جزيئات الجازولين","درجة الحرارة التي يُسحب عندها الجازولين من البرج","كمية الطاقة الناتجة عن احتراق لتر من الجازولين"]'::jsonb, 'تذكر', 'تذكر مفهوم', 'سهل', 'الكتاب ص 125 — رقم الأوكتان'),
('mcq', 6, 'ماذا تُسمّى ظاهرة اشتعال خليط الجازولين والهواء في أسطوانة المحرك قبل أن يصبح المكبس في الموضع الصحيح وقبل اشتعال شمعة الاحتراق؟', null, null, '["التكسير الحراري","التقطير التجزيئي","الفرقعة","الاحتراق الكامل"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'متوسط', 'الكتاب ص 124 — الفرقعة (knocking)'),
('mcq', 7, 'أيّ أنواع الهيدروكربونات الموجودة في الجازولين يميل أكثر من غيره إلى الاشتعال المبكر في المحرك فيسبب الفرقعة؟', null, null, '["الهيدروكربونات الغازية التي فيها 1–4 ذرات كربون","الهيدروكربونات ذات السلاسل المستقيمة (غير المتفرعة)","الهيدروكربونات ذات السلاسل المتفرعة","الهيدروكربونات التي تغلي فوق 300°C"]'::jsonb, 'فهم', 'ربط سبب بنتيجة', 'صعب', 'الكتاب ص 124 — احتراق الهيدروكربونات المستقيمة والفرقعة'),
('essay', 1, 'عرّف الجازولين، ثم فسّر لماذا لا يُعد مادة نقية، واذكر نوع الروابط في معظم جزيئاته ومدى عدد ذرات الكربون فيها.', null, null, null, 'فهم', 'تعريف وتفسير', 'متوسط', 'الكتاب ص 124 — تصنيف الجازولين'),
('essay', 2, 'في محطة وقود في المملكة العربية السعودية مضختان للجازولين، كُتب على إحداهما 91 وعلى الأخرى 95. ما المقصود بهذين الرقمين؟ وأيّ النوعين أكثر مقاومة للفرقعة؟ ثم وضّح المقصود بالفرقعة، وما نتائجها على المحرك، وأيّ الهيدروكربونات يميل إلى إحداثها.', null, null, null, 'تحليل', 'تفسير موقف حياتي', 'صعب', 'الكتاب ص 124–125 — الفرقعة ورقم الأوكتان'),
('essay', 3, 'صف كيف يُفصل الجازولين عن النفط الخام في برج التجزئة، ثم وضّح لماذا تلجأ المصافي إلى التكسير الحراري، وكيف تزيد هذه العملية كمية الجازولين المنتجة.', null, null, null, 'فهم', 'وصف عملية', 'صعب', 'الكتاب ص 123–124 — التقطير التجزيئي والتكسير الحراري')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
