select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الجازولين ليس مادة نقية، بل خليط من الهيدروكربونات، ومعظم جزيئاته تحتوي على روابط تساهمية أحادية وعلى 5–12 ذرة كربون؛ فالتعريف الصحيح: خليط من هيدروكربونات معظم جزيئاتها بروابط تساهمية أحادية وفيها 5–12 ذرة كربون.', '["الجازولين خليط من هيدروكربونات كثيرة وليس مركبًا نقيًّا واحدًا؛ والأوكتان أحد مكوناته فقط.","","هذا وصف مشتق الغازات (من CH₄ إلى C₄H₁₀) الذي يُسحب عند أقل من 40°C، وليس الجازولين.","معظم جزيئات الجازولين بروابط أحادية لا ثلاثية، والمدى 17–22 ذرة كربون هو مدى زيت التزييت والتشحيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('mcq', 2, 1, 'يُسحب الجازولين من برج التجزئة عند مدى درجات الحرارة 40 – 100°C، وهو مدى المخرج (ب)؛ لذا يُسحب الجازولين من المخرج (ب).', '["المخرج (أ) عند أقل من 40°C في أعلى البرج، وتُسحب منه الغازات (من CH₄ إلى C₄H₁₀) ذات درجات الغليان الأقل.","","المدى 105 – 275°C هو مدى الكيروسين، وجزيئاته أكبر من جزيئات الجازولين (من C₁₂H₂₆ إلى C₁₆H₃₄).","المخرج (د) فوق 300°C قرب أسفل البرج، ويُسحب منه زيت التزييت والتشحيم ذو الجزيئات الكبيرة (من C₁₇H₃₆ إلى C₂₂H₄₆)، وهي أعلى كثيرًا في درجة الغليان من الجازولين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('mcq', 3, 3, 'المادة النقية تتكون من نوع واحد من المواد، أما الجازولين فخليط من هيدروكربونات مختلفة (معظمها بروابط أحادية وفيها 5–12 ذرة كربون)؛ لذلك لا يُعد مادة نقية لأنه خليط من عدد من الهيدروكربونات المختلفة.', '["معظم جزيئات الجازولين بروابط أحادية لا ثنائية، ونوع الروابط لا يحدد هل المادة نقية أم خليط.","سهولة التبخر خاصية فيزيائية لا تحدد نقاء المادة؛ فكثير من المواد النقية سهلة التبخر.","مصدر الإنتاج لا يحدد النقاء، كما أن جزءًا من الجازولين يُفصل مباشرة بالتقطير التجزيئي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('mcq', 4, 2, 'معظم جزيئات الجازولين فيها 5–12 ذرة كربون (من C₅H₁₂ إلى C₁₂H₂₆)، والصيغة C₈H₁₈ فيها 8 ذرات كربون وروابط أحادية فقط، فهي ضمن هذا المدى؛ لذا يمكن أن تكون C₈H₁₈ أحد مكونات الجازولين.', '["C₄H₁₀ فيها 4 ذرات كربون فقط، فهي من الغازات التي تُسحب عند أقل من 40°C.","C₁₆H₃₄ فيها 16 ذرة كربون، أي أكثر من 12؛ فهي خارج مدى الجازولين، ومن المكونات الأثقل كالكيروسين (من C₁₂H₂₆ إلى C₁₆H₃₄).","","C₂₀H₄₂ فيها 20 ذرة كربون، أي أكثر كثيرًا من 12؛ فهي من المكونات الثقيلة التي تتكثف قرب أسفل البرج، لا من الجازولين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('mcq', 5, 0, 'رقم الأوكتان نظام تصنيف للجازولين يعطي قيم منع الفرقعة؛ فكلما ارتفع رقم الأوكتان زادت قدرة الجازولين على منع الفرقعة في المحرك.', '["","رقم الأوكتان (89 أو 91 أو 95 مثلًا) لا يمثل عدد ذرات الكربون؛ فمعظم جزيئات الجازولين فيها 5–12 ذرة كربون فقط.","الجازولين يُسحب عند 40 – 100°C، ورقم الأوكتان لا علاقة له بدرجة الحرارة في البرج.","رقم الأوكتان يصنف مقاومة الوقود للفرقعة، لا كمية الطاقة الناتجة عن احتراقه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('mcq', 6, 2, 'الاحتراق المبكر لخليط الجازولين والهواء قبل أن يصبح المكبس في الموضع الصحيح وقبل اشتعال شمعة الاحتراق يكون مصحوبًا بصوت، ويُسمّى الفرقعة (knocking).', '["التكسير الحراري عملية صناعية تُكسَّر فيها الجزيئات الكبيرة إلى جزيئات أصغر، لا اشتعال داخل المحرك.","التقطير التجزيئي عملية فصل مكونات النفط حسب درجات غليانها، ولا يحدث في أسطوانة المحرك.","","الاحتراق الكامل في اللحظة المناسبة هو المطلوب في المحرك، أما الاشتعال المبكر فهو الفرقعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('mcq', 7, 1, 'معظم الهيدروكربونات ذات السلاسل المستقيمة (غير المتفرعة) لا تحترق احتراقًا سلسًا، وتميل بفعل الحرارة والضغط إلى الاشتعال المبكر قبل أن يصبح المكبس في الموضع الصحيح؛ فهي التي تسبب الفرقعة.', '["الهيدروكربونات التي فيها 1–4 ذرات كربون غازات تُسحب في أعلى البرج، وليست من مكونات الجازولين.","","السلاسل المتفرعة تحترق احتراقًا أكثر سلاسة، والمشكلة في السلاسل المستقيمة.","الهيدروكربونات التي تغلي فوق 300°C مكونات ثقيلة (زيوت التزييت والمخلفات) وليست في الجازولين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجازولين خليط من الهيدروكربونات يُفصل من النفط الخام. لا يُعد مادة نقية لأنه يتكون من عدد من الهيدروكربونات المختلفة وليس من نوع واحد من الجزيئات. ومعظم جزيئاته تحتوي على روابط تساهمية أحادية فقط، وفي كل منها 5–12 ذرة كربون (من C₅H₁₂ إلى C₁₂H₂₆).', '["الجازولين خليط من الهيدروكربونات","ليس مادة نقية لأنه يتكون من هيدروكربونات مختلفة","معظم جزيئاته بروابط تساهمية أحادية","في معظم جزيئاته 5–12 ذرة كربون"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الجازولين بأنه خليط من الهيدروكربونات","marks":1},{"element":"تفسير عدم نقائه","marks":1},{"element":"ذكر الروابط الأحادية","marks":1},{"element":"ذكر المدى 5–12 ذرة كربون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وتفسير لعدم النقاء، وذكر نوع الروابط ومدى عدد ذرات الكربون"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص عنصر أو عنصرين من التفسير أو نوع الروابط أو المدى"},{"level":"1 درجة","description":"ذكر أن الجازولين خليط فقط أو ذكر المدى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف الجازولين بأنه مركب نقي هو الأوكتان","ذكر مدى عدد ذرات كربون خاطئ مثل 1–4 أو 17–22","القول إن معظم جزيئاته تحتوي على روابط ثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.553Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الرقمان 91 و95 هما رقما الأوكتان، وهو نظام تصنيف يعطي قيم منع الفرقعة للجازولين. الجازولين 95 أكثر مقاومة للفرقعة من 91 لأن رقم الأوكتان فيه أعلى. والفرقعة اشتعال مبكر لخليط الجازولين والهواء في أسطوانة المحرك قبل أن يصبح المكبس في الموضع الصحيح وقبل اشتعال شمعة الاحتراق، ويكون مصحوبًا بصوت. ويؤدي الاشتعال قبل الموعد المناسب أو بعده إلى خسارة كثير من الطاقة، وانخفاض فاعلية الوقود، وفقدان كفاءة المحرك. وتميل الهيدروكربونات ذات السلاسل المستقيمة (غير المتفرعة) إلى الاشتعال المبكر بفعل الحرارة والضغط؛ لأنها لا تحترق احتراقًا سلسًا.', '["91 و95 رقما أوكتان يدلان على قيمة منع الفرقعة","الجازولين 95 أكثر مقاومة للفرقعة","الفرقعة اشتعال مبكر للخليط قبل وصول المكبس إلى موضعه الصحيح","نتائجها: خسارة الطاقة وانخفاض فاعلية الوقود وكفاءة المحرك","السلاسل المستقيمة تميل إلى الاشتعال المبكر"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير الرقمين بأنهما رقما أوكتان لمنع الفرقعة","marks":1},{"element":"تحديد أن 95 أكثر مقاومة للفرقعة","marks":1},{"element":"تعريف الفرقعة","marks":1},{"element":"ذكر نتائجها على المحرك","marks":1},{"element":"ذكر أن السلاسل المستقيمة تسببها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة تشمل معنى الرقمين، والمقارنة، وتعريف الفرقعة، ونتائجها، ونوع الهيدروكربونات المسببة لها"},{"level":"3–4 درجات","description":"معنى الرقمين والمقارنة صحيحان مع نقص في تعريف الفرقعة أو نتائجها أو سببها"},{"level":"1–2 درجة","description":"ذكر أن الرقم الأعلى أفضل دون تفسير علمي كافٍ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير رقم الأوكتان بأنه عدد ذرات الكربون","القول إن الجازولين 91 أكثر مقاومة للفرقعة","نسبة الفرقعة إلى السلاسل المتفرعة بدلًا من المستقيمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يُسخَّن النفط الخام حتى الغليان، فتكون درجة الحرارة قريبة من 400°C في أسفل البرج، وتنخفض تدريجيًّا في اتجاه أعلاه. تتصاعد الأبخرة داخل البرج، وتتكثف المكونات عند درجات حرارة مختلفة حسب درجات غليانها التي تنخفض بانخفاض الكتلة الجزيئية؛ فيُسحب الجازولين عند 40 – 100°C. لكن التقطير التجزيئي لا يُنتج المكونات بالنسب المطلوبة؛ إذ يُنتج كمية من الجازولين أقل من حاجة السوق، وكمية من الزيوت الثقيلة أكبر منها. لذا يُلجأ إلى التكسير الحراري، وفيه تُكسَّر الجزيئات الكبيرة في المكونات الثقيلة إلى جزيئات أصغر في غياب الأكسجين وبوجود عامل مساعد، فتنتج جزيئات بحجم جزيئات الجازولين وتزيد كميته.', '["تسخين النفط حتى الغليان (نحو 400°C في أسفل البرج)","انخفاض درجة الحرارة نحو أعلى البرج وتكثف المكونات حسب درجات غليانها","سحب الجازولين عند 40 – 100°C","التقطير لا يُنتج الجازولين بالكمية المطلوبة","التكسير الحراري يكسر الجزيئات الكبيرة إلى أصغر في غياب الأكسجين وبوجود عامل مساعد"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تسخين النفط وتصاعد الأبخرة في البرج","marks":1},{"element":"ربط التكثف بدرجات الغليان والكتلة الجزيئية","marks":1},{"element":"ذكر مدى سحب الجازولين 40 – 100°C","marks":1},{"element":"سبب اللجوء إلى التكسير الحراري","marks":1},{"element":"وصف التكسير الحراري وشروطه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح للفصل في البرج وسبب التكسير الحراري وآليته وشروطه"},{"level":"3–4 درجات","description":"وصف صحيح للفصل في البرج مع نقص في سبب التكسير أو شروطه"},{"level":"1–2 درجة","description":"ذكر أن النفط يُسخَّن ويُفصل دون ربط بدرجات الغليان أو دون ذكر التكسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المكونات الخفيفة تتكثف في أسفل البرج","وصف التكسير الحراري بأنه احتراق بوجود الأكسجين","الخلط بين التقطير التجزيئي والتكسير الحراري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
