('mcq', 5, 'تُعد الألكانات سلسلة متماثلة. ما المقصود بالسلسلة المتماثلة؟', null, null, '["مركبات لها الصيغة الجزيئية نفسها وتختلف في صيغها البنائية","مركبات تحتوي جميعها على حلقة كربونية واحدة","سلسلة مركبات يختلف بعضها عن بعض في عدد الوحدة المتكررة –CH₂–","مركبات يختلف بعضها عن بعض في عدد الروابط الثنائية فقط"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'متوسط', 'الكتاب ص 127–128 — السلسلة المتماثلة'),
('mcq', 6, 'تُصنَّف الألكانات ضمن الهيدروكربونات المشبعة؛ ما سبب ذلك؟', null, null, '["لأنها تتفاعل مع كميات كبيرة من البروم","لأن جميع الروابط بين ذرات الكربون فيها أحادية","لأن جزيئاتها تحتوي على أكبر عدد ممكن من ذرات الكربون","لأنها تذوب في الماء حتى يصبح محلولها مشبعًا"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 122 و126 — الهيدروكربون المشبع والألكانات'),
('mcq', 7, 'بأيّ مقطع تنتهي أسماء الألكانات، مثل البروبان والهكسان؟', null, null, '["«يل»","«ين»","«اين»","«ان»"]'::jsonb, 'تذكر', 'تذكر قاعدة', 'سهل', 'الكتاب ص 127 — تسمية الألكانات ذات السلاسل المستقيمة'),
('essay', 1, 'عرّف الألكانات، واكتب صيغتها العامة، ثم استخدمها لكتابة الصيغة الجزيئية لألكان يحتوي على 6 ذرات كربون، وفسّر لماذا تُعد الألكانات هيدروكربونات مشبعة.', null, null, null, 'فهم', 'تعريف وتطبيق', 'متوسط', 'الكتاب ص 126 و128 — الألكانات والصيغة العامة'),
('essay', 2, 'يبين الجدول الآتي الصيغ الجزيئية لستة مركبات. حدّد المركبات التي تُعد ألكانات، وبرّر استبعاد كل مركب من المركبات الأخرى.', '{"headers":["المركب","الصيغة الجزيئية"],"rows":[["1","C₄H₁₀"],["2","C₄H₈"],["3","C₇H₁₆"],["4","C₆H₆"],["5","C₁₀H₂₂"],["6","C₂H₆O"]]}'::jsonb, null, null, 'تحليل', 'تصنيف وتبرير', 'صعب', 'الكتاب ص 126 و128 — تعريف الألكانات والصيغة العامة'),
