from (values
('mcq', 1, 2, 'الألكانات هيدروكربونات (مركبات من الكربون والهيدروجين فقط) تحتوي فقط على روابط أحادية؛ فالتعريف الصحيح: هيدروكربونات تحتوي فقط على روابط أحادية.', '["الهيدروكربونات التي تحتوي على رابطة ثنائية واحدة على الأقل هي الألكينات لا الألكانات.","الهيدروكربونات التي تحتوي على رابطة ثلاثية واحدة على الأقل هي الألكاينات لا الألكانات.","","الألكانات هيدروكربونات تتكون من الكربون والهيدروجين فقط، ولا تحتوي على الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('mcq', 2, 1, 'الألكان هيدروكربون فيه روابط أحادية فقط. المركب (ب) يتكون من الكربون والهيدروجين فقط، وكل روابطه أحادية (C₃H₈ يحقق CₙH₂ₙ₊₂ عند n = 3)؛ لذا فالمركب (ب) ألكان.', '["المركب (أ) فيه رابطة ثنائية بين ذرتي الكربون، فهو ليس ألكانًا.","","المركب (ج) فيه رابطة ثلاثية بين ذرتي الكربون، فهو ليس ألكانًا.","المركب (د) يحتوي على ذرة أكسجين، فهو ليس هيدروكربونًا أصلًا رغم أن روابطه أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('mcq', 3, 3, 'الصيغة العامة للألكانات CₙH₂ₙ₊₂؛ فعند n = 5 يكون عدد ذرات الهيدروجين 2(5) + 2 = 12، أي أن الصيغة C₅H₁₂ تمثل ألكانًا.', '["C₅H₁₀ تحقق CₙH₂ₙ لا CₙH₂ₙ₊₂؛ فينقصها ذرتا هيدروجين عن الألكان.","C₅H₈ ينقصها أربع ذرات هيدروجين عن الألكان C₅H₁₂؛ فهي لا تحقق CₙH₂ₙ₊₂.","الألكان ذو ست ذرات كربون يحتاج إلى 14 ذرة هيدروجين (C₆H₁₄)، وفي C₆H₆ ست ذرات هيدروجين فقط، فهي لا تمثل ألكانًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('mcq', 4, 0, 'يُعد الميثان CH₄ أصغر مركب في سلسلة الهيدروكربونات المعروفة بالألكانات، إذ يحتوي على ذرة كربون واحدة.', '["","الإيثان C₂H₆ هو المركب الثاني في سلسلة الألكانات، وقبله الميثان.","البروبان C₃H₈ هو المركب الثالث في السلسلة.","البيوتان C₄H₁₀ هو المركب الرابع في السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('mcq', 5, 2, 'السلسلة المتماثلة سلسلة مركبات يختلف بعضها عن بعض في عدد الوحدة المتكررة –CH₂–، ولها صيغة رقمية ثابتة؛ فالبنتان مثلًا يزيد على البيوتان بوحدة –CH₂– واحدة.', '["هذا وصف المتشكلات (البنائية)، لا السلسلة المتماثلة؛ فأفراد السلسلة المتماثلة تختلف صيغها الجزيئية.","هذا وصف الهيدروكربونات الحلقية، والسلسلة المتماثلة لا يُشترط فيها وجود حلقة.","","أفراد سلسلة الألكانات المتماثلة كلها بروابط أحادية، وتختلف في عدد وحدات –CH₂– لا في الروابط الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('mcq', 6, 1, 'الهيدروكربون المشبع هو الذي يحتوي على روابط أحادية فقط، والألكانات كل روابطها أحادية؛ لذا تُصنف ضمن الهيدروكربونات المشبعة لأن جميع الروابط بين ذرات الكربون فيها أحادية.', '["العكس هو الصحيح؛ فالهيدروكربونات التي سُميت مشبعة هي التي لم تتفاعل مع البروم، أما المتفاعلة معه فهي غير المشبعة.","","التشبع لا يتعلق بعدد ذرات الكربون، بل بنوع الروابط بينها؛ والميثان ذو الذرة الواحدة مشبع أيضًا.","الألكانات غير قطبية ولا تذوب في الماء، والتشبع هنا يتعلق بالروابط لا بالذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('mcq', 7, 3, 'تنتهي أسماء الألكانات بالمقطع «ان»، كما في الميثان والبروبان والهكسان والديكان.', '["المقطع «يل» تنتهي به أسماء مجموعات الألكيل (مثل ميثيل وإيثيل)، وهي مجموعات بديلة لا ألكانات.","المقطع «ين» تنتهي به أسماء الألكينات التي تحتوي على رابطة ثنائية.","المقطع «اين» تنتهي به أسماء الألكاينات التي تحتوي على رابطة ثلاثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.554Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الألكانات هيدروكربونات تحتوي فقط على روابط أحادية. صيغتها العامة CₙH₂ₙ₊₂، حيث n عدد ذرات الكربون. عند n = 6 يكون عدد ذرات الهيدروجين 2(6) + 2 = 14، فالصيغة الجزيئية C₆H₁₄ (الهكسان). وتُعد الألكانات هيدروكربونات مشبعة لأنها تحتوي على روابط تساهمية أحادية فقط.', '["الألكانات هيدروكربونات تحتوي فقط على روابط أحادية","الصيغة العامة CₙH₂ₙ₊₂","الصيغة الجزيئية C₆H₁₄","مشبعة لاحتوائها على روابط أحادية فقط"]'::jsonb, '["n = 6","عدد ذرات H = 2n + 2 = 2(6) + 2 = 14","الصيغة الجزيئية: C₆H₁₄"]'::jsonb, '[{"element":"تعريف الألكانات","marks":1},{"element":"كتابة الصيغة العامة","marks":1},{"element":"استنتاج C₆H₁₄","marks":1},{"element":"تفسير التشبع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وصيغة عامة صحيحة، وصيغة جزيئية صحيحة، وتفسير صحيح للتشبع"},{"level":"2–3 درجات","description":"ثلاثة عناصر أو عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة العامة CₙH₂ₙ أو CₙH₂ₙ₊₁","حساب عدد ذرات الهيدروجين 12 بدلًا من 14","ربط التشبع بالذوبان أو بعدد ذرات الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الألكانات هيدروكربونات صيغتها العامة CₙH₂ₙ₊₂. المركب 1: C₄H₁₀، عند n = 4 يكون 2(4) + 2 = 10، فهو ألكان (البيوتان). المركب 3: C₇H₁₆، عند n = 7 يكون 16، فهو ألكان (الهبتان). المركب 5: C₁₀H₂₂، عند n = 10 يكون 22، فهو ألكان (الديكان). أما المركب 2: C₄H₈ فعدد ذرات الهيدروجين فيه 8 لا 10، والمركب 4: C₆H₆ فيه 6 لا 14؛ فلا يحققان الصيغة العامة للألكانات. والمركب 6: C₂H₆O يحتوي على الأكسجين، فهو ليس هيدروكربونًا أصلًا، لذا ليس ألكانًا.', '["المركب 1 (C₄H₁₀) ألكان","المركب 3 (C₇H₁₆) ألكان","المركب 5 (C₁₀H₂₂) ألكان","المركبان 2 و4 لا يحققان CₙH₂ₙ₊₂","المركب 6 ليس هيدروكربونًا لاحتوائه على الأكسجين"]'::jsonb, '["C₄H₁₀: 2(4) + 2 = 10 ✓","C₄H₈: 2(4) + 2 = 10 ≠ 8 ✗","C₇H₁₆: 2(7) + 2 = 16 ✓","C₆H₆: 2(6) + 2 = 14 ≠ 6 ✗","C₁₀H₂₂: 2(10) + 2 = 22 ✓","C₂H₆O: يحتوي على O فليس هيدروكربونًا ✗"]'::jsonb, '[{"element":"تحديد C₄H₁₀ ألكانًا مع التبرير","marks":1},{"element":"تحديد C₇H₁₆ ألكانًا مع التبرير","marks":1},{"element":"تحديد C₁₀H₂₂ ألكانًا مع التبرير","marks":1},{"element":"تبرير استبعاد C₄H₈ وC₆H₆","marks":1},{"element":"تبرير استبعاد C₂H₆O","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الألكانات الثلاثة وتبرير استبعاد المركبات الثلاثة الأخرى تبريرًا صحيحًا"},{"level":"3–4 درجات","description":"تحديد الألكانات صحيح مع نقص في تبرير الاستبعاد"},{"level":"1–2 درجة","description":"تحديد ألكان أو اثنين فقط، أو تحديد دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ C₂H₆O ألكانًا لأن عدد ذرات الهيدروجين فيه يحقق 2n + 2","عدّ C₄H₈ ألكانًا باستخدام الصيغة CₙH₂ₙ","إغفال شرط أن يكون المركب هيدروكربونًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb),
('essay', 3, null::int, null, null, 'البيوتان: CH₃CH₂CH₂CH₃، والبنتان: CH₃CH₂CH₂CH₂CH₃. السلسلة المتماثلة سلسلة مركبات يختلف بعضها عن بعض في عدد الوحدة المتكررة –CH₂–، ولها صيغة رقمية ثابتة (CₙH₂ₙ₊₂ في الألكانات). فالبنتان يزيد على البيوتان بوحدة –CH₂– واحدة (C₄H₁₀ ثم C₅H₁₂). والمركب الذي يلي البنتان يزيد عليه بوحدة –CH₂– أخرى، فهو الهكسان C₆H₁₄.', '["البيوتان CH₃CH₂CH₂CH₃","البنتان CH₃CH₂CH₂CH₂CH₃","تعريف السلسلة المتماثلة بالوحدة المتكررة –CH₂–","الفرق بين البيوتان والبنتان وحدة –CH₂– واحدة","المركب التالي الهكسان C₆H₁₄"]'::jsonb, '[]'::jsonb, '[{"element":"صيغة البيوتان المكثفة","marks":1},{"element":"صيغة البنتان المكثفة","marks":1},{"element":"تعريف السلسلة المتماثلة","marks":1},{"element":"توضيح الفرق بوحدة –CH₂–","marks":1},{"element":"الصيغة الجزيئية C₆H₁₄","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الصيغتان صحيحتان، والتعريف صحيح ومرتبط بالمثال، والصيغة الجزيئية للمركب التالي صحيحة"},{"level":"3–4 درجات","description":"الصيغتان والتعريف صحيحة مع نقص في الربط أو في المركب التالي"},{"level":"1–2 درجة","description":"كتابة صيغة واحدة صحيحة أو تعريف ناقص"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة البنتان بأربع ذرات كربون","جعل الوحدة المتكررة –CH₃ بدلًا من –CH₂–","كتابة صيغة المركب التالي C₆H₁₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
