('mcq', 2, 'يمثل الشكل الآتي ألكانًا ذا سلسلة مستقيمة. أيّ الصيغ الآتية تمثله بصيغة بنائية مكثفة تُكتب فيها وحدات –CH₂– المتكررة بين قوسين؟', null, '[{"src":"qimg/chem22/c4-l2a-pentane-full.svg","alt":"صيغة بنائية كاملة: خمس ذرات كربون C في صف أفقي، تتصل كل ذرتين متجاورتين برابطة أحادية (خط). ترتبط كل ذرة كربون بذرة هيدروجين H فوقها وذرة هيدروجين تحتها، وترتبط ذرة الكربون الأولى من اليسار أيضًا بذرة هيدروجين إلى يسارها، وذرة الكربون الأخيرة من اليمين بذرة هيدروجين إلى يمينها. لا توجد أي تفرعات."}]'::jsonb, '["CH₃(CH₂)₂CH₃","CH₃(CH₂)₄CH₃","CH₃(CH₂)₅CH₃","CH₃(CH₂)₃CH₃"]'::jsonb, 'تطبيق', 'تحويل صيغة بنائية إلى مكثفة', 'متوسط', 'الكتاب ص 126–128 — الجدولان 1-4 و2-4'),
('mcq', 3, 'عُدَّ ذرات الكربون والهيدروجين في الجزيء المتفرع المرسوم أدناه. ما صيغته الجزيئية؟', null, '[{"src":"qimg/chem22/c4-l2a-methylbutane-full.svg","alt":"صيغة بنائية كاملة: أربع ذرات كربون C في صف أفقي متصلة بروابط أحادية، وترتبط ذرة الكربون الثانية من اليسار بخط رأسي طويل بذرة كربون خامسة أسفلها. ذرة الكربون الأولى (اليسرى) ترتبط بثلاث ذرات هيدروجين: فوقها وتحتها وإلى يسارها. ذرة الكربون الثانية ترتبط بذرة هيدروجين واحدة فوقها. ذرة الكربون الثالثة ترتبط بذرة هيدروجين فوقها وأخرى تحتها. ذرة الكربون الرابعة (اليمنى) ترتبط بثلاث ذرات هيدروجين: فوقها وتحتها وإلى يمينها. ذرة الكربون الخامسة (أسفل الثانية) ترتبط بثلاث ذرات هيدروجين: إلى يسارها وإلى يمينها وتحتها."}]'::jsonb, '["C₅H₁₂","C₄H₁₀","C₅H₁₀","C₅H₁₄"]'::jsonb, 'تطبيق', 'استنتاج صيغة جزيئية من صيغة بنائية', 'متوسط', 'الكتاب ص 128 — الألكانات ذات السلاسل المتفرعة'),
('mcq', 4, 'رسم أربعة طلاب الصيغ البنائية الآتية للبروبان C₃H₈. أيّها صحيحة؟', null, '[{"src":"qimg/chem22/c4-l2a-propane-four.svg","alt":"أربع صيغ بنائية في شبكة من صفين وعمودين. (أ) في أعلى اليمين: ثلاث ذرات كربون في صف متصلة بروابط أحادية، فوق كل ذرة كربون ذرة هيدروجين وتحتها ذرة هيدروجين، وإلى يمين ذرة الكربون الأخيرة ذرة هيدروجين، ولا توجد ذرة هيدروجين إلى يسار ذرة الكربون الأولى. (ب) في أعلى اليسار: ثلاث ذرات كربون في صف متصلة بروابط أحادية، فوق كل ذرة كربون ذرة هيدروجين وتحتها ذرة هيدروجين، وإلى يسار الذرة الأولى ذرة هيدروجين، وإلى يمين الذرة الأخيرة ذرة هيدروجين. (ج) في أسفل اليمين: مثل (ب) تمامًا، لكن ذرة الكربون الوسطى ترتبط بذرة هيدروجين إضافية بخط مائل. (د) في أسفل اليسار: ذرتا كربون فقط متصلتان برابطة أحادية، وترتبط كل منهما بثلاث ذرات هيدروجين."}]'::jsonb, '["الصيغة (أ)","الصيغة (ب)","الصيغة (ج)","الصيغة (د)"]'::jsonb, 'تحليل', 'تقويم صيغ بنائية', 'صعب', 'الكتاب ص 126 — الجدول 1-4 (الصيغ البنائية للإيثان والبروبان والبيوتان)'),
('mcq', 5, 'ما الصيغة الجزيئية للألكان الذي صيغته البنائية المكثفة CH₃(CH₂)₅CH₃؟', null, null, '["C₅H₁₂","C₇H₁₄","C₇H₁₆","C₆H₁₄"]'::jsonb, 'تطبيق', 'تحويل صيغة مكثفة إلى جزيئية', 'متوسط', 'الكتاب ص 127–128 — الجدول 2-4'),
('mcq', 6, 'ألكان ذو سلسلة مستقيمة يحتوي جزيئه على 22 ذرة هيدروجين. كم ذرة كربون في جزيئه؟', null, null, '["11","20","12","10"]'::jsonb, 'تطبيق', 'حساب من الصيغة العامة', 'صعب', 'الكتاب ص 127–128 — الجدول 2-4 والصيغة العامة'),
('mcq', 7, 'تُكتب صيغة البروبان البنائية المكثفة CH₃CH₂CH₃. بماذا تختلف هذه الصيغة عن صيغته البنائية الكاملة؟', null, null, '["لا تُظهر كل رابطة C–H بخط، بل تُكتب ذرات H مجتمعة مع ذرة الكربون المرتبطة بها","تُظهر الشكل الهندسي الثلاثي الأبعاد للجزيء والزوايا بين روابطه","تعطي عدد ذرات كل عنصر فقط دون أي معلومات عن ترتيبها","تحتوي على عدد من ذرات الهيدروجين أقل مما في الصيغة البنائية"]'::jsonb, 'فهم', 'مقارنة أنواع الصيغ', 'سهل', 'الكتاب ص 122 و127 — النماذج والصيغ البنائية المكثفة'),
('essay', 1, 'اكتب لكل من البروبان والهكسان: الصيغة الجزيئية، والصيغة البنائية (موضحًا ما ترتبط به كل ذرة كربون)، والصيغة البنائية المكثفة.', null, null, null, 'تطبيق', 'كتابة صيغ', 'سهل', 'الكتاب ص 159 — السؤالان 50 و51'),
('essay', 2, 'تمثل الصيغة البنائية الآتية أحد الألكانات. اكتب صيغته الجزيئية، وصيغته البنائية المكثفة، ثم تحقق من أن صيغته الجزيئية تحقق الصيغة العامة للألكانات، وقارنها بالصيغة الجزيئية للهكسان ذي السلسلة المستقيمة.', null, '[{"src":"qimg/chem22/c4-l2a-methylpentane-full.svg","alt":"صيغة بنائية كاملة: خمس ذرات كربون C في صف أفقي متصلة بروابط أحادية، وترتبط ذرة الكربون الثانية من اليسار بخط رأسي طويل بذرة كربون سادسة فوقها. ذرة الكربون الأولى (اليسرى) ترتبط بثلاث ذرات هيدروجين: فوقها وتحتها وإلى يسارها. ذرة الكربون الثانية ترتبط بذرة هيدروجين واحدة تحتها. ذرتا الكربون الثالثة والرابعة ترتبط كل منهما بذرة هيدروجين فوقها وأخرى تحتها. ذرة الكربون الخامسة (اليمنى) ترتبط بثلاث ذرات هيدروجين: فوقها وتحتها وإلى يمينها. ذرة الكربون السادسة (فوق الثانية) ترتبط بثلاث ذرات هيدروجين: إلى يسارها وإلى يمينها وفوقها."}]'::jsonb, null, 'تطبيق', 'تحويل بين الصيغ ومقارنة', 'متوسط', 'الكتاب ص 127–128 — الصيغ المكثفة والألكانات المتفرعة'),
('essay', 3, 'ما عدد ذرات الهيدروجين في جزيء ألكان يحتوي على 9 ذرات كربون؟ اكتب الصيغة البنائية المكثفة للنونان ذي السلسلة المستقيمة بطريقتين، ثم فسّر لماذا يستخدم الكيميائيون الصيغ البنائية بدلًا من الاكتفاء بالصيغ الجزيئية مثل C₅H₁₂.', null, null, null, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 162 — السؤالان 78 و83')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
