select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الصيغة العامة للألكانات CₙH₂ₙ₊₂؛ وعند n = 13 يكون عدد ذرات الهيدروجين 2(13) + 2 = 28، فالصيغة الجزيئية C₁₃H₂₈.', '["استُخدمت الصيغة CₙH₂ₙ بدلًا من CₙH₂ₙ₊₂ فنقصت ذرتا هيدروجين.","","استُخدمت 2n + 1 بدلًا من 2n + 2؛ وعدد ذرات الهيدروجين في الألكان عدد زوجي دائمًا.","استُخدمت 2n − 2 بدلًا من 2n + 2 فنقصت أربع ذرات هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb),
('mcq', 2, 3, 'في الصيغة خمس ذرات كربون في سلسلة مستقيمة: ذرتا الطرفين كل منهما CH₃، والذرات الثلاث الوسطى كل منها CH₂؛ فالصيغة المكثفة CH₃CH₂CH₂CH₂CH₃، وتُكتب بتكثيف أكبر CH₃(CH₂)₃CH₃ (البنتان C₅H₁₂).', '["هذه صيغة البيوتان (أربع ذرات كربون)؛ فقد عُدَّت وحدتا –CH₂– بدلًا من ثلاث وحدات.","هذه صيغة الهكسان (ست ذرات كربون)؛ فقد عُدَّت ذرات الكربون الخمس كلها وحدات –CH₂– ثم أضيفت إليها مجموعتا CH₃.","هذه صيغة الهبتان (سبع ذرات كربون)؛ وفيها ذرتا كربون زائدتان عما في الشكل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb),
('mcq', 3, 0, 'عدد ذرات الكربون 4 في السلسلة + 1 في الفرع = 5، وعدد ذرات الهيدروجين 3 + 1 + 2 + 3 + 3 = 12؛ فالصيغة الجزيئية C₅H₁₂، وهي تحقق CₙH₂ₙ₊₂ عند n = 5 رغم أن السلسلة متفرعة.', '["","أُهملت ذرة الكربون في الفرع ومعها ذرتا هيدروجين، فعُدَّت السلسلة الأفقية وحدها.","نقص عدّ ذرتي هيدروجين؛ والصيغة C₅H₁₀ لا تحقق CₙH₂ₙ₊₂ للألكانات.","زيدت ذرتا هيدروجين؛ فذرة الكربون الثانية لا ترتبط إلا بذرة هيدروجين واحدة لأنها ترتبط بثلاث ذرات كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb),
('mcq', 4, 1, 'في الصيغة الصحيحة للبروبان ثلاث ذرات كربون، وتكوّن كل ذرة كربون أربع روابط: ذرتا الطرفين ترتبط كل منهما بثلاث ذرات H، والذرة الوسطى بذرتي H، فيكون المجموع 8 ذرات هيدروجين (C₃H₈). وهذا متحقق في الصيغة (ب) فقط.', '["في (أ) تكوّن ذرة الكربون الأولى ثلاث روابط فقط، وعدد ذرات الهيدروجين 7؛ فالصيغة ليست C₃H₈.","","في (ج) تكوّن ذرة الكربون الوسطى خمس روابط، وذرة الكربون لا تكوّن إلا أربع روابط.","(د) صيغة الإيثان C₂H₆ لأن فيها ذرتي كربون فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.555Z"}'::jsonb),
('mcq', 5, 2, 'في الصيغة مجموعتا CH₃ وخمس وحدات CH₂؛ فعدد ذرات الكربون 2 + 5 = 7، وعدد ذرات الهيدروجين 2(3) + 5(2) = 16؛ فالصيغة الجزيئية C₇H₁₆ (الهبتان)، وتحقق CₙH₂ₙ₊₂.', '["عُدَّت وحدات CH₂ الخمس وحدها وأُهملت مجموعتا CH₃ في الطرفين.","عدد ذرات الكربون صحيح، لكن نقصت ذرتا هيدروجين؛ فالألكان ذو 7 ذرات كربون فيه 16 ذرة هيدروجين.","","عُدَّت إحدى مجموعتي الطرفين فقط؛ فالصيغة فيها 7 ذرات كربون لا 6."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.556Z"}'::jsonb),
('mcq', 6, 3, 'في الألكانات عدد ذرات الهيدروجين = 2n + 2؛ فإن 2n + 2 = 22، ومنها 2n = 20، أي n = 10؛ فالجزيء فيه 10 ذرات كربون (الديكان C₁₀H₂₂).', '["قُسم عدد ذرات الهيدروجين على 2 مباشرة (22 ÷ 2) دون طرح 2 أولًا.","طُرح 2 من عدد ذرات الهيدروجين دون القسمة على 2؛ فالناتج 20 يساوي 2n لا n.","أضيف 2 إلى عدد ذرات الهيدروجين قبل القسمة على 2 بدلًا من طرحه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.556Z"}'::jsonb),
('mcq', 7, 0, 'الصيغة البنائية المكثفة توفر الحيز؛ فهي لا تُظهر تفرع ذرات الهيدروجين عن ذرات الكربون بخطوط، بل تكتب ذرات H مع ذرة الكربون المرتبطة بها (CH₃ وCH₂)، وتُحذف فيها الخطوط بين ذرات الكربون، مع بقاء ترتيب الذرات وعددها كما هما.', '["","الصيغ البنائية لا تعطي الشكل الهندسي الثلاثي الأبعاد الدقيق؛ وهذا ما يُظهره نموذج الكرة والعصا.","هذا وصف الصيغة الجزيئية C₃H₈؛ أما الصيغة المكثفة فتُظهر ترتيب ذرات الكربون وما يرتبط بكل منها.","عدد ذرات الهيدروجين واحد في الصيغتين (8 ذرات)؛ فالتكثيف يغير طريقة الكتابة لا عدد الذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.556Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البروبان: الصيغة الجزيئية C₃H₈. الصيغة البنائية: ثلاث ذرات كربون في سلسلة متصلة بروابط أحادية (C–C–C)، ترتبط كل من ذرتي الطرفين بثلاث ذرات هيدروجين، والذرة الوسطى بذرتي هيدروجين، وتُرسم كل رابطة بخط: H₃C–CH₂–CH₃ مع إظهار كل رابطة C–H. الصيغة البنائية المكثفة: CH₃CH₂CH₃. الهكسان: الصيغة الجزيئية C₆H₁₄. الصيغة البنائية: ست ذرات كربون في سلسلة مستقيمة متصلة بروابط أحادية، ترتبط ذرتا الطرفين كل منهما بثلاث ذرات هيدروجين، وكل ذرة من الذرات الأربع الوسطى بذرتي هيدروجين، وتُرسم كل رابطة بخط. الصيغة البنائية المكثفة: CH₃CH₂CH₂CH₂CH₂CH₃ أو CH₃(CH₂)₄CH₃.', '["البروبان C₃H₈","صيغة البروبان البنائية: طرفان CH₃ ووسط CH₂ بروابط أحادية","CH₃CH₂CH₃","الهكسان C₆H₁₄","صيغة الهكسان البنائية: طرفان CH₃ وأربع وحدات CH₂","CH₃CH₂CH₂CH₂CH₂CH₃ أو CH₃(CH₂)₄CH₃"]'::jsonb, '["البروبان: n = 3، عدد ذرات H = 2(3) + 2 = 8","الهكسان: n = 6، عدد ذرات H = 2(6) + 2 = 14"]'::jsonb, '[{"element":"الصيغة الجزيئية للبروبان","marks":1},{"element":"الصيغة البنائية للبروبان","marks":1},{"element":"الصيغة المكثفة للبروبان","marks":1},{"element":"الصيغة الجزيئية للهكسان","marks":1},{"element":"الصيغة البنائية للهكسان","marks":1},{"element":"الصيغة المكثفة للهكسان","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"الصيغ الست صحيحة"},{"level":"3–5 درجات","description":"صيغ أحد المركبين صحيحة كاملة مع أخطاء في بعض صيغ الآخر"},{"level":"1–2 درجة","description":"صيغة أو صيغتان صحيحتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الهكسان C₆H₁₂","جعل ذرة كربون طرفية مرتبطة بذرتي هيدروجين فقط","كتابة الهكسان المكثف CH₃(CH₂)₆CH₃ وهي صيغة الأوكتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.556Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عدد ذرات الكربون: 5 في السلسلة الأفقية + 1 في الفرع = 6. عدد ذرات الهيدروجين: 3 + 1 + 2 + 2 + 3 + 3 = 14. الصيغة الجزيئية C₆H₁₄. الصيغة البنائية المكثفة: CH₃CH(CH₃)CH₂CH₂CH₃. التحقق: عند n = 6 يكون 2(6) + 2 = 14، فالصيغة تحقق CₙH₂ₙ₊₂. والهكسان المستقيم CH₃(CH₂)₄CH₃ صيغته الجزيئية C₆H₁₄ أيضًا؛ فللمركبين الصيغة الجزيئية نفسها مع اختلاف الصيغة البنائية، إذ إن هذا المركب متفرع والهكسان سلسلة مستقيمة.', '["عدد ذرات الكربون 6","عدد ذرات الهيدروجين 14 والصيغة C₆H₁₄","الصيغة المكثفة CH₃CH(CH₃)CH₂CH₂CH₃","التحقق من CₙH₂ₙ₊₂","الصيغة الجزيئية نفسها للهكسان مع اختلاف الصيغة البنائية"]'::jsonb, '["عدّ ذرات C: 5 + 1 = 6","عدّ ذرات H: 3 + 1 + 2 + 2 + 3 + 3 = 14","التحقق: 2n + 2 = 2(6) + 2 = 14 ✓"]'::jsonb, '[{"element":"الصيغة الجزيئية C₆H₁₄","marks":1},{"element":"الصيغة المكثفة الصحيحة","marks":1},{"element":"التحقق من الصيغة العامة","marks":1},{"element":"المقارنة بالهكسان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغتان صحيحتان، والتحقق صحيح، والمقارنة صحيحة"},{"level":"2–3 درجات","description":"الصيغة الجزيئية صحيحة مع خطأ أو نقص في المكثفة أو المقارنة"},{"level":"1 درجة","description":"عدّ صحيح لذرات الكربون فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال ذرة الكربون في الفرع وكتابة C₅H₁₂","كتابة المكثفة CH₃CH₂CH₂CH₂CH₂CH₃ وإغفال التفرع","القول إن المركب المتفرع لا يحقق الصيغة العامة للألكانات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.556Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد ذرات الهيدروجين = 2n + 2 = 2(9) + 2 = 20، فالصيغة الجزيئية C₉H₂₀. الصيغة المكثفة للنونان: CH₃CH₂CH₂CH₂CH₂CH₂CH₂CH₂CH₃، أو بتكثيف أكبر CH₃(CH₂)₇CH₃. ويستخدم الكيميائيون الصيغ البنائية لأن الصيغة الجزيئية تعطي عدد الذرات فقط ولا تبين ترتيبها، وقد تشترك مركبات مختلفة في الخصائص في الصيغة الجزيئية نفسها؛ فالصيغة C₅H₁₂ قد تمثل البنتان ذا السلسلة المستقيمة CH₃CH₂CH₂CH₂CH₃ أو ألكانًا متفرعًا مثل CH₃CH(CH₃)CH₂CH₃، وتنظيم الذرات وترتيبها في الجزيء يحدد هويته.', '["عدد ذرات H = 20 (C₉H₂₀)","CH₃CH₂CH₂CH₂CH₂CH₂CH₂CH₂CH₃","CH₃(CH₂)₇CH₃","الصيغة الجزيئية لا تبين ترتيب الذرات","أكثر من مركب له الصيغة الجزيئية نفسها (مثال C₅H₁₂)"]'::jsonb, '["n = 9","عدد ذرات H = 2(9) + 2 = 20","عدد وحدات CH₂ = 9 − 2 = 7"]'::jsonb, '[{"element":"حساب 20 ذرة هيدروجين","marks":1},{"element":"الصيغة المكثفة الممتدة","marks":1},{"element":"الصيغة CH₃(CH₂)₇CH₃","marks":1},{"element":"تفسير قصور الصيغة الجزيئية","marks":1},{"element":"مثال على صيغتين بنائيتين للصيغة C₅H₁₂","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحساب والصيغتان صحيحة، والتفسير صحيح مدعوم بمثال"},{"level":"3–4 درجات","description":"الحساب والصيغتان صحيحة مع تفسير ناقص أو دون مثال"},{"level":"1–2 درجة","description":"الحساب صحيح فقط أو إحدى الصيغتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة CH₃(CH₂)₉CH₃ بجعل عدد وحدات CH₂ يساوي عدد ذرات الكربون","حساب عدد ذرات الهيدروجين 18","القول إن الصيغة الجزيئية تحدد المركب تحديدًا كاملًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.556Z"}'::jsonb)
