from (values
('mcq', 1, 2, 'المجموعة CH₃CH₂CH₂– فيها ثلاث ذرات كربون، فهي مشتقة من البروبان، ويُشتق اسمها بتغيير المقطع الأخير «ان» إلى «يل»؛ فاسمها بروبيل.', '["الإيثيل CH₃CH₂– فيه ذرتا كربون فقط.","البروبان اسم الألكان CH₃CH₂CH₃ نفسه، أما المجموعة البديلة فينتهي اسمها بالمقطع «يل».","","البيوتيل CH₃CH₂CH₂CH₂– فيه أربع ذرات كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('mcq', 2, 1, 'أطول سلسلة متصلة فيها أربع ذرات كربون (بيوتان). نرقمها من الطرف الأقرب إلى التفرعات فتقع مجموعتا الميثيل على ذرة الكربون 2، ولأن مجموعة الميثيل تكررت مرتين نستخدم البادئة «ثنائي» ونكتب الرقم مرتين؛ فالاسم 2، 2-ثنائي ميثيل بيوتان.', '["رُقمت السلسلة من الطرف الأبعد عن التفرعات؛ والترقيم الصحيح يعطي أصغر الأرقام (2، 2).","","عند تكرار المجموعة يُكتب رقم موقع لكل مجموعة، فيلزم رقمان (2، 2) قبل «ثنائي ميثيل».","عُدَّت إحدى مجموعتي الميثيل ضمن السلسلة الرئيسة مع عدّها تفرعًا أيضًا؛ وأطول سلسلة فيها أربع ذرات كربون فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('mcq', 3, 3, 'أطول سلسلة متصلة فيها سبع ذرات كربون (هبتان). الترقيم من اليسار يضع مجموعتي الميثيل على 2 و5، ومن اليمين على 3 و6، فنختار الأصغر (2، 5). ولأن مجموعة الميثيل تكررت نستخدم «ثنائي»؛ فالاسم 2، 5-ثنائي ميثيل هبتان.', '["رُقمت السلسلة من الطرف الأبعد عن التفرعات؛ و(2، 5) أصغر من (3، 6).","السلسلة الرئيسة فيها سبع ذرات كربون لا ست؛ فاسمها هبتان.","عند تكرار المجموعة نفسها تُجمع بالبادئة «ثنائي» ولا يُكرر اسمها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('mcq', 4, 0, 'أطول سلسلة متصلة تبدأ من CH₃ في أعلى الفرع الرأسي (3 ذرات كربون) ثم ذرة CH ثم CH₂ وCH₂ وCH₃ الأفقية (3 ذرات)، فمجموعها 7 ذرات كربون (هبتان). وتبقى مجموعة CH₃ اليسرى تفرعًا ميثيلًا على ذرة CH، ورقمها 4 من أي طرف؛ فالاسم 4-ميثيل هبتان.', '["","عُدَّت السلسلة الأفقية (5 ذرات) سلسلة رئيسة، مع أن أطول سلسلة متصلة فيها 7 ذرات كربون.","عدد ذرات الكربون في أطول سلسلة 7 لا 6؛ فقد نقصت ذرة عند العدّ.","اختيرت السلسلة الأفقية القصيرة، ثم رُقمت من الطرف الأبعد عن التفرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('mcq', 5, 2, 'أطول سلسلة فيها 6 ذرات كربون (هكسان). الترقيم من اليسار يضع الميثيل على 2 والإيثيل على 4 (2، 4)، ومن اليمين يضعهما على 5 و3 (3، 5)، فنختار (2، 4). وتُرتب المجموعات هجائيًّا باللغة الإنجليزية: إيثيل (E) قبل ميثيل (M)؛ فالاسم 4-إيثيل-2-ميثيل هكسان.', '["الأرقام صحيحة، لكن المجموعات لم تُرتب هجائيًّا؛ فالإيثيل (E) يُكتب قبل الميثيل (M).","رُقمت السلسلة من الطرف الأبعد؛ فمجموعة الأرقام (3، 5) أكبر من (2، 4).","","أطول سلسلة متصلة فيها 6 ذرات كربون لا 7؛ فاسمها هكسان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('mcq', 6, 0, 'أطول سلسلة متصلة فيها 5 ذرات كربون (بنتان)، ومجموعتا الميثيل على ذرتي الكربون الثانية والثالثة من اليسار. الترقيم من اليسار يعطي (2، 3)، ومن اليمين (3، 4)؛ فنختار (2، 3)، ونجمع المجموعتين بالبادئة «ثنائي»؛ فالاسم 2، 3-ثنائي ميثيل بنتان.', '["","رُقمت السلسلة من الطرف الأبعد عن التفرعات؛ و(2، 3) أصغر من (3، 4).","أضيفت ذرتا كربون التفرعين إلى السلسلة الرئيسة؛ وهما مجموعتا ميثيل بديلتان لا جزء من السلسلة.","تكررت مجموعة الميثيل فيجب استخدام البادئة «ثنائي» لا تكرار الاسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('mcq', 7, 1, 'أطول سلسلة متصلة تمر بفرع البيوتيل (4 ذرات) ثم ذرة CH ثم ذرتين أفقيتين (2)، فمجموعها 7 ذرات (هبتان)، ويبقى تفرع من ذرتي كربون (إيثيل). الترقيم من الطرف الأقرب إلى التفرع يضعه على ذرة الكربون 3 (ومن الطرف الآخر على 5)؛ فالاسم الصحيح 3-إيثيل هبتان.', '["السلسلة الرئيسة صحيحة، لكنها رُقمت من الطرف الأبعد؛ والرقم الأصغر 3.","","سلسلة من 6 ذرات ليست أطول سلسلة متصلة؛ فأطول سلسلة فيها 7 ذرات كربون.","التفرع صحيح، لكن أطول سلسلة فيها 7 ذرات كربون لا 6."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخطوة 1: أطول سلسلة متصلة هي السلسلة الأفقية وفيها 7 ذرات كربون، فالاسم الرئيس هبتان (السلاسل التي تمر بفرع الإيثيل أقصر: 6 ذرات). الخطوة 2: الترقيم من اليسار يضع التفرعات على 2 و4 و5، ومن اليمين على 3 و4 و6، فنرقّم من اليسار لأنه يعطي أصغر الأرقام. الخطوة 3: التفرعات: مجموعة ميثيل على 2، ومجموعة إيثيل على 4، ومجموعة ميثيل على 5. الخطوة 4: تكررت مجموعة الميثيل مرتين فنستخدم «ثنائي» مع الرقمين 2، 5. الخطوة 5: الترتيب الهجائي: إيثيل (E) قبل ميثيل (M) مع إهمال البادئة «ثنائي». الخطوة 6: الاسم: 4-إيثيل-2، 5-ثنائي ميثيل هبتان.', '["أطول سلسلة 7 ذرات: هبتان","الترقيم من اليسار (2، 4، 5) أصغر من (3، 4، 6)","ميثيل على 2 و5، وإيثيل على 4","البادئة «ثنائي» لمجموعتي الميثيل","الترتيب الهجائي: إيثيل قبل ميثيل","الاسم: 4-إيثيل-2، 5-ثنائي ميثيل هبتان"]'::jsonb, '["تحديد أطول سلسلة: 7 ذرات كربون ← هبتان","مقارنة الترقيمين: (2، 4، 5) من اليسار و(3، 4، 6) من اليمين ← من اليسار","تسمية التفرعات: 2-ميثيل، 4-إيثيل، 5-ميثيل","جمع المتكرر: 2، 5-ثنائي ميثيل","الترتيب الهجائي: إيثيل ثم ميثيل","الاسم: 4-إيثيل-2، 5-ثنائي ميثيل هبتان"]'::jsonb, '[{"element":"تحديد السلسلة الرئيسة (هبتان)","marks":1},{"element":"الترقيم الصحيح مع التبرير","marks":1},{"element":"تسمية التفرعات ومواقعها","marks":1},{"element":"استخدام البادئة ثنائي","marks":1},{"element":"الترتيب الهجائي وكتابة الاسم كاملًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الاسم صحيح كاملًا مع خطوات مبررة"},{"level":"3–4 درجات","description":"السلسلة والترقيم صحيحان مع خطأ في البادئة أو الترتيب الهجائي"},{"level":"1–2 درجة","description":"تحديد السلسلة الرئيسة فقط أو ترقيم خاطئ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترقيم من اليمين والحصول على 4-إيثيل-3، 6-ثنائي ميثيل هبتان","كتابة الميثيل قبل الإيثيل","عدّ ذرتي الإيثيل ضمن السلسلة الرئيسة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطأ أن الطالب عدّ السلسلة الأفقية (5 ذرات) سلسلة رئيسة، مع أن أطول سلسلة متصلة تمر بفرع الإيثيل: CH₃ وCH₂ في الفرع، ثم ذرتا CH، ثم CH₂ وCH₃ في اليمين، فمجموعها 6 ذرات كربون (هكسان)؛ ولا يمكن أن يكون الإيثيل على ذرة الكربون 2 لأنه يطيل السلسلة. بعد اختيار هذه السلسلة تصبح مجموعة CH₃ اليسرى تفرعًا ميثيلًا على ذرة الكربون 3، والميثيل السفلي على ذرة الكربون 4، والترقيم من الطرف الآخر يعطي (3، 4) أيضًا. فالاسم الصحيح: 3، 4-ثنائي ميثيل هكسان.', '["الخطأ: لم تُختر أطول سلسلة متصلة","أطول سلسلة 6 ذرات تمر بفرع الإيثيل: هكسان","مجموعتا ميثيل على 3 و4","الاسم الصحيح: 3، 4-ثنائي ميثيل هكسان"]'::jsonb, '["عدّ السلسلة الأفقية: 5 ذرات","عدّ السلسلة المارة بالإيثيل: 2 + 2 + 2 = 6 ذرات ← هكسان","مواقع الميثيل: 3 و4 من أي طرف","الاسم: 3، 4-ثنائي ميثيل هكسان"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"تحديد أطول سلسلة (6 ذرات)","marks":1},{"element":"تحديد المواقع 3 و4","marks":1},{"element":"كتابة الاسم الصحيح بالبادئة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتصحيحه بالاسم الصحيح مع تبرير كامل"},{"level":"2–3 درجات","description":"تحديد الخطأ وأطول سلسلة مع خطأ في المواقع أو البادئة"},{"level":"1 درجة","description":"الإشارة إلى أن الاسم خطأ دون تصحيح صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول السلسلة الأفقية سلسلة رئيسة","تصحيح الاسم إلى 3-إيثيل-2-ميثيل بنتان","كتابة 3-ميثيل-4-ميثيل هكسان دون البادئة ثنائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) سلسلة مستقيمة من 5 ذرات كربون دون تفرعات: بنتان. (ب) أطول سلسلة 5 ذرات (بنتان)، ومجموعة الميثيل على ذرة الكربون 3 من أي طرف: 3-ميثيل بنتان. (ج) أطول سلسلة 5 ذرات (بنتان)؛ الترقيم من اليسار يضع مجموعات الميثيل على 2 و2 و4، ومن اليمين على 2 و4 و4، فنختار (2، 2، 4) لأنها الأصغر، وتتكرر مجموعة الميثيل ثلاث مرات فنستخدم «ثلاثي»: 2، 2، 4-ثلاثي ميثيل بنتان. ولا نحتاج إلى أرقام في اسم (أ) لأنه ألكان ذو سلسلة مستقيمة لا تفرعات فيه، فلا توجد مجموعات بديلة نحدد مواقعها.', '["(أ) بنتان","(ب) 3-ميثيل بنتان","(ج) 2، 2، 4-ثلاثي ميثيل بنتان","السلسلة المستقيمة لا مجموعات بديلة فيها فلا حاجة إلى أرقام"]'::jsonb, '["(ج): أطول سلسلة 5 ذرات","(ج): الترقيم من اليسار (2، 2، 4) ومن اليمين (2، 4، 4) ← من اليسار","(ج): ثلاث مجموعات ميثيل ← ثلاثي ميثيل"]'::jsonb, '[{"element":"اسم (أ)","marks":1},{"element":"اسم (ب)","marks":1},{"element":"اسم (ج)","marks":2},{"element":"تفسير عدم الحاجة إلى أرقام","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأسماء الثلاثة صحيحة والتفسير صحيح"},{"level":"3–4 درجات","description":"اسمان صحيحان مع خطأ في ترقيم (ج) أو نقص في التفسير"},{"level":"1–2 درجة","description":"اسم واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (ج) 2، 4، 4-ثلاثي ميثيل بنتان بالترقيم من الطرف الأبعد","تسمية (ب) 2-إيثيل بيوتان","كتابة 1-بنتان أو إضافة أرقام لا حاجة إليها في (أ)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.557Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L2-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
