from (values
('mcq', 1, 'ما الاسم النظامي (IUPAC) للألكان الحلقي الممثل بالصيغة الخطية الآتية؟', null, '[{"src":"qimg/chem22/c4-l2a-mcp.svg","alt":"صيغة خطية لحلقة خماسية (مخمس منتظم، كل رأس فيه يمثل ذرة كربون)، ويخرج من الرأس العلوي الأيمن خط ينتهي بمجموعة CH₃. لا توجد مجموعات أخرى."}]'::jsonb, '["ميثيل هكسان حلقي","2-ميثيل بنتان","ميثيل بنتان حلقي","ميثيل بيوتان حلقي"]'::jsonb, 'تطبيق', 'تسمية ألكان حلقي', 'سهل', 'الكتاب ص 134 — مسائل تدريبية 10 (a)'),
('mcq', 2, 'يمثل الشكل الآتي ألكانًا حلقيًّا يتصل بحلقته تفرع واحد. ما اسمه النظامي؟', null, '[{"src":"qimg/chem22/c4-l2a-ecb.svg","alt":"صيغة خطية لحلقة رباعية (مربع، كل رأس فيه يمثل ذرة كربون)، ويخرج من الرأس العلوي الأيمن خط ينتهي بمجموعة CH₂CH₃. لا توجد مجموعات أخرى."}]'::jsonb, '["إيثيل بيوتان حلقي","هكسان حلقي","إيثيل بنتان حلقي","إيثيل بروبان حلقي"]'::jsonb, 'تطبيق', 'تسمية ألكان حلقي', 'سهل', 'الكتاب ص 132 — تسمية الألكانات الحلقية المحتوية على مجموعات بديلة'),
('mcq', 3, 'ما الاسم النظامي (IUPAC) للمركب الحلقي الآتي؟', null, '[{"src":"qimg/chem22/c4-l2a-dmcp12.svg","alt":"صيغة خطية لحلقة خماسية (مخمس منتظم رأسه إلى الأعلى). يخرج من الرأس العلوي خط إلى الأعلى ينتهي بمجموعة CH₃، ويخرج من الرأس المجاور له على اليمين خط ينتهي بمجموعة CH₃ أخرى. أي أن مجموعتي الميثيل على ذرتي كربون متجاورتين."}]'::jsonb, '["1، 5-ثنائي ميثيل بنتان حلقي","2، 3-ثنائي ميثيل بنتان حلقي","1، 2-ثنائي ميثيل بنتان","1، 2-ثنائي ميثيل بنتان حلقي"]'::jsonb, 'تطبيق', 'تسمية ألكان حلقي مع الترقيم', 'متوسط', 'الكتاب ص 132–133 — ترقيم الحلقة (المثال 2-4)'),
('mcq', 4, 'استخدم قواعد IUPAC لتسمية الألكان الحلقي الآتي.', null, '[{"src":"qimg/chem22/c4-l2a-dmch13.svg","alt":"صيغة خطية لحلقة سداسية (مسدس منتظم رأسه إلى الأعلى). يخرج من الرأس العلوي الأيمن خط ينتهي بمجموعة CH₃، ويخرج من الرأس العلوي الأيسر خط ينتهي بمجموعة CH₃. بين هذين الرأسين الرأس العلوي للمسدس ولا يحمل أي مجموعة."}]'::jsonb, '["1، 5-ثنائي ميثيل هكسان حلقي","1، 3-ثنائي ميثيل هكسان حلقي","1، 4-ثنائي ميثيل هكسان حلقي","2، 6-ثنائي ميثيل هكسان حلقي"]'::jsonb, 'تطبيق', 'تسمية ألكان حلقي مع الترقيم', 'متوسط', 'الكتاب ص 132–133 — تسمية الألكانات الحلقية'),
('mcq', 5, 'تحمل الحلقة الخماسية الآتية ثلاث مجموعات ميثيل. ما الاسم النظامي للمركب؟', null, '[{"src":"qimg/chem22/c4-l2a-tmcp124.svg","alt":"صيغة خطية لحلقة خماسية (مخمس منتظم رأسه إلى الأعلى). تخرج مجموعة CH₃ من الرأس العلوي، ومجموعة CH₃ من الرأس العلوي الأيمن المجاور له، ومجموعة CH₃ من الرأس السفلي الأيسر. أما الرأس السفلي الأيمن والرأس العلوي الأيسر فلا يحملان أي مجموعة."}]'::jsonb, '["1، 3، 4-ثلاثي ميثيل بنتان حلقي","2، 3، 5-ثلاثي ميثيل بنتان حلقي","1، 2، 4-ثلاثي ميثيل بنتان حلقي","1، 2، 3-ثلاثي ميثيل بنتان حلقي"]'::jsonb, 'تطبيق', 'ترقيم حلقة بمجموعات متعددة', 'صعب', 'الكتاب ص 133 — المثال 2-4 (اختيار أقل مجموعة أرقام)'),
('mcq', 6, 'تحمل الحلقة السداسية الآتية مجموعتين بديلتين مختلفتين. ما اسم المركب وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l2a-e1m3ch.svg","alt":"صيغة خطية لحلقة سداسية (مسدس منتظم رأسه إلى الأعلى). يخرج من الرأس العلوي الأيمن خط ينتهي بمجموعة CH₂CH₃، ويخرج من الرأس السفلي خط ينتهي بمجموعة CH₃. بين الرأسين الحاملين للمجموعتين الرأس السفلي الأيمن فقط."}]'::jsonb, '["1-ميثيل-3-إيثيل هكسان حلقي","1-إيثيل-5-ميثيل هكسان حلقي","1-إيثيل-3-ميثيل بنتان حلقي","1-إيثيل-3-ميثيل هكسان حلقي"]'::jsonb, 'تطبيق', 'تسمية بمجموعات مختلفة', 'متوسط', 'الكتاب ص 134 — مسائل تدريبية 10؛ ص 135 — السؤال 15 (c)'),
('mcq', 7, 'ألكان حلقي صيغته الجزيئية C₆H₁₂، ولا يتصل بحلقته أي مجموعة بديلة. ما اسمه النظامي؟', null, null, '["ميثيل بنتان حلقي","هكسان حلقي","2-ميثيل بنتان","بنتان حلقي"]'::jsonb, 'فهم', 'استنتاج اسم من صيغة جزيئية', 'صعب', 'الكتاب ص 132 — الألكانات الحلقية (الهكسان الحلقي C₆H₁₂)'),
('essay', 1, 'سمِّ الألكان الحلقي الآتي وفق نظام IUPAC، مبينًا كيف اخترت ترقيم الحلقة، ثم اكتب صيغته الجزيئية.', null, '[{"src":"qimg/chem22/c4-l2a-tmch113.svg","alt":"صيغة خطية لحلقة سداسية (مسدس منتظم رأسه إلى الأعلى). يخرج من الرأس العلوي الأيمن خطان ينتهي كل منهما بمجموعة CH₃، أي أن ذرة الكربون نفسها تحمل مجموعتي ميثيل. ويخرج من الرأس السفلي خط ينتهي بمجموعة CH₃. بين الرأس العلوي الأيمن والرأس السفلي الرأس السفلي الأيمن فقط."}]'::jsonb, null, 'تطبيق', 'تسمية بخطوات', 'متوسط', 'الكتاب ص 132–133 — المثال 2-4'),
('essay', 2, 'رقّم طالب ذرات الحلقة في المركب الآتي كما هو مبين بالأرقام داخل الحلقة، ثم سمّاه «2، 5-ثنائي ميثيل بنتان حلقي». حدّد الخطأين في ترقيمه، ثم أعد الترقيم واكتب الاسم الصحيح.', null, '[{"src":"qimg/chem22/c4-l2a-wrongnum.svg","alt":"صيغة خطية لحلقة خماسية (مخمس منتظم رأسه إلى الأعلى) وداخلها أرقام ترقيم باللون الأحمر بجوار كل رأس. الرأس العلوي يحمل مجموعة CH₃ ورقمه 5. الرأس العلوي الأيمن لا يحمل مجموعة ورقمه 1. الرأس السفلي الأيمن يحمل مجموعة CH₃ ورقمه 2. الرأس السفلي الأيسر رقمه 3، والرأس العلوي الأيسر رقمه 4، ولا يحمل أي منهما مجموعة."}]'::jsonb, null, 'تحليل', 'تحليل خطأ في الترقيم', 'صعب', 'الكتاب ص 132 و162 — ترقيم الحلقة والسؤال 82'),
('essay', 3, 'قارن بين تسمية الألكانات الحلقية وتسمية الألكانات ذات السلاسل المفتوحة من حيث: تحديد السلسلة الرئيسة، ونقطة بدء الترقيم، والحاجة إلى الأرقام عند وجود مجموعة بديلة واحدة، مع مثال لكل ألكان حلقي.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 132 — تسمية الألكانات الحلقية المحتوية على مجموعات بديلة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
