from (values
('mcq', 1, 2, 'في الحلقة خمس ذرات كربون فاسمها الرئيس بنتان حلقي، ويتصل بها تفرع واحد هو مجموعة ميثيل؛ ولأن المجموعة البديلة واحدة فلا حاجة إلى الترقيم؛ فالاسم ميثيل بنتان حلقي.', '["عُدَّت ذرة كربون الميثيل ضمن الحلقة؛ والحلقة فيها خمس ذرات كربون فقط.","سُمي المركب على أنه ألكان ذو سلسلة مفتوحة، مع أن الكربون في حلقة فيجب استخدام البادئة «حلقي».","","عدد رؤوس الحلقة خمسة لا أربعة؛ فالحلقة بنتان حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('mcq', 2, 0, 'الحلقة مربعة فيها أربع ذرات كربون فاسمها بيوتان حلقي، والتفرع CH₂CH₃ مجموعة إيثيل، ولا حاجة إلى رقم لأن المجموعة البديلة واحدة؛ فالاسم إيثيل بيوتان حلقي.', '["","أُضيفت ذرتا كربون الإيثيل إلى الحلقة؛ والحلقة نفسها فيها أربع ذرات كربون فقط.","الحلقة رباعية لا خماسية؛ فاسمها بيوتان حلقي.","الحلقة فيها أربع ذرات كربون لا ثلاث؛ فاسمها بيوتان حلقي لا بروبان حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('mcq', 3, 3, 'الحلقة خماسية (بنتان حلقي)، ومجموعتا الميثيل على ذرتين متجاورتين. نبدأ الترقيم من إحداهما (1) ونتجه نحو الأخرى فتأخذ الرقم 2، وهي أصغر مجموعة أرقام ممكنة؛ فالاسم 1، 2-ثنائي ميثيل بنتان حلقي.', '["رُقمت الحلقة في الاتجاه البعيد عن المجموعة الثانية؛ والاتجاه الصحيح يعطي (1، 2).","بدأ الترقيم من ذرة كربون لا تحمل مجموعة بديلة؛ والترقيم يبدأ من ذرة الكربون المرتبطة بالمجموعة البديلة.","أُهملت البادئة «حلقي»، مع أن ذرات الكربون الخمس تكوّن حلقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('mcq', 4, 1, 'الحلقة سداسية (هكسان حلقي)، وبين ذرتي الكربون الحاملتين للميثيل ذرة كربون واحدة. نبدأ الترقيم من إحداهما (1) ونمر بالذرة الوسطى (2) فتأخذ الثانية الرقم 3؛ فالاسم 1، 3-ثنائي ميثيل هكسان حلقي.', '["رُقمت الحلقة في الاتجاه الأطول حول الحلقة؛ والاتجاه الآخر يعطي (1، 3) وهي الأصغر.","","الموقعان 1، 4 يعنيان وجود ذرتين بين المجموعتين؛ وفي الشكل ذرة واحدة فقط بينهما.","بدأ الترقيم من الرأس العلوي الذي لا يحمل مجموعة؛ والترقيم يبدأ من ذرة تحمل مجموعة بديلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('mcq', 5, 2, 'نبدأ الترقيم من إحدى الذرتين المتجاورتين الحاملتين للميثيل ونتجه نحو الأخرى: الرأس العلوي الأيمن (1)، ثم العلوي (2)، ثم العلوي الأيسر (3)، ثم السفلي الأيسر (4)؛ فتقع المجموعات على 1 و2 و4. أما البدء من الرأس السفلي الأيسر فيعطي (1، 3، 4) وهي أكبر. فالاسم 1، 2، 4-ثلاثي ميثيل بنتان حلقي.', '["بدأ الترقيم من الرأس السفلي الأيسر؛ فنتج (1، 3، 4) وهي أكبر من (1، 2، 4) عند أول اختلاف.","بدأ الترقيم من ذرة لا تحمل مجموعة بديلة؛ والترقيم يبدأ من ذرة تحمل مجموعة.","","المواقع 1، 2، 3 تعني ثلاث ذرات متتالية، وفي الشكل ذرة كربون فارغة بين الثانية والثالثة من المجموعات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('mcq', 6, 3, 'الحلقة سداسية (هكسان حلقي)، وبين ذرتي الكربون الحاملتين للمجموعتين ذرة واحدة، فموقعاهما 1 و3. وتُكتب المجموعات حسب الترتيب الهجائي باللغة الإنجليزية: إيثيل (E) قبل ميثيل (M)، فيأخذ الإيثيل الرقم 1؛ فالاسم 1-إيثيل-3-ميثيل هكسان حلقي.', '["الأرقام صحيحة لكن الترتيب الهجائي لم يُراعَ؛ فالإيثيل يُكتب قبل الميثيل.","رُقمت الحلقة في الاتجاه الأطول؛ والاتجاه الآخر يعطي الرقم الأصغر 3.","الحلقة فيها ست ذرات كربون لا خمس؛ فاسمها هكسان حلقي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('mcq', 7, 1, 'لا توجد مجموعات بديلة، فذرات الكربون الست كلها في الحلقة؛ والحلقة ذات الذرات الست اسمها هكسان حلقي، وصيغته C₆H₁₂ تقل عن الهكسان C₆H₁₄ بذرتي هيدروجين لأن ذرتي الطرفين ترتبطان معًا بدلًا من ارتباطهما بذرتي هيدروجين.', '["صيغة ميثيل بنتان حلقي C₆H₁₂ أيضًا، لكنه يحتوي على مجموعة بديلة (ميثيل)، والسؤال ينص على عدم وجود مجموعات بديلة.","","2-ميثيل بنتان ألكان ذو سلسلة مفتوحة صيغته C₆H₁₄ لا C₆H₁₂، وليس حلقيًّا.","البنتان الحلقي فيه خمس ذرات كربون وصيغته C₅H₁₀."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحلقة سداسية فالاسم الرئيس هكسان حلقي. نبدأ الترقيم من ذرة الكربون الحاملة لمجموعتي الميثيل (1، 1)، ونتجه نحو الرأس السفلي الأيمن (2) ثم السفلي (3)، فتكون المواقع (1، 1، 3). أما الترقيم في الاتجاه الآخر فيعطي (1، 1، 5)، والبدء من الرأس السفلي يعطي (1، 3، 3)؛ و(1، 1، 3) هي أقل مجموعة أرقام. ولوجود ثلاث مجموعات ميثيل نستخدم «ثلاثي»: 1، 1، 3-ثلاثي ميثيل هكسان حلقي. الصيغة الجزيئية: 6 ذرات كربون في الحلقة + 3 في المجموعات = 9 ذرات كربون، وهو ألكان حلقي صيغته CₙH₂ₙ؛ فالصيغة C₉H₁₈.', '["الاسم الرئيس هكسان حلقي","الترقيم يبدأ من ذرة الكربون الحاملة للمجموعتين","مقارنة (1، 1، 3) مع (1، 1، 5) و(1، 3، 3)","الاسم 1، 1، 3-ثلاثي ميثيل هكسان حلقي","الصيغة الجزيئية C₉H₁₈"]'::jsonb, '["عدد ذرات الحلقة 6 ← هكسان حلقي","الترقيمات الممكنة: (1، 1، 3) و(1، 1، 5) و(1، 3، 3) ← (1، 1، 3)","ثلاث مجموعات ميثيل ← ثلاثي ميثيل","عدد ذرات C = 6 + 3 = 9؛ وعدد ذرات H = 2(9) = 18"]'::jsonb, '[{"element":"تحديد الحلقة (هكسان حلقي)","marks":1},{"element":"الترقيم الصحيح مع المقارنة","marks":2},{"element":"الاسم كاملًا بالبادئة ثلاثي","marks":1},{"element":"الصيغة الجزيئية C₉H₁₈","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الاسم والترقيم المبرر والصيغة الجزيئية صحيحة"},{"level":"3–4 درجات","description":"الاسم صحيح مع نقص في تبرير الترقيم أو خطأ في الصيغة الجزيئية"},{"level":"1–2 درجة","description":"تحديد الحلقة فقط أو اسم بترقيم خاطئ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 1، 3-ثنائي ميثيل هكسان حلقي بإهمال المجموعة الثانية على الذرة نفسها","تسمية المركب 1، 3، 3-ثلاثي ميثيل هكسان حلقي","كتابة الصيغة الجزيئية C₉H₂₀ باستخدام صيغة الألكانات المفتوحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.558Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطأ الأول: بدأ الطالب الترقيم من ذرة كربون لا تحمل مجموعة بديلة (الرأس العلوي الأيمن)، والصحيح أن يبدأ الترقيم من ذرة كربون مرتبطة بمجموعة بديلة. الخطأ الثاني: نتج عن ترقيمه (2، 5)، وهي ليست أقل مجموعة أرقام ممكنة. الترقيم الصحيح: نبدأ من الرأس العلوي الحامل للميثيل (1)، ثم الرأس العلوي الأيمن (2)، ثم الرأس السفلي الأيمن الحامل للميثيل الثاني (3)؛ فالمواقع (1، 3)، وهي أصغر من أي ترقيم آخر. الاسم الصحيح: 1، 3-ثنائي ميثيل بنتان حلقي.', '["الخطأ 1: بدء الترقيم من ذرة لا تحمل مجموعة بديلة","الخطأ 2: الأرقام (2، 5) ليست الأصغر","الترقيم الصحيح يعطي (1، 3)","الاسم الصحيح 1، 3-ثنائي ميثيل بنتان حلقي"]'::jsonb, '["البدء من ذرة تحمل ميثيلًا = 1","الاتجاه نحو الميثيل الآخر عبر ذرة واحدة ← 3","المقارنة: (1، 3) أصغر من (1، 4) ومن (2، 5)","الاسم: 1، 3-ثنائي ميثيل بنتان حلقي"]'::jsonb, '[{"element":"تحديد خطأ نقطة البداية","marks":1},{"element":"تحديد أن الأرقام ليست الأصغر","marks":1},{"element":"الترقيم الصحيح (1، 3)","marks":1},{"element":"الاسم الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين، وترقيم صحيح، واسم صحيح"},{"level":"2–3 درجات","description":"اسم صحيح مع تحديد خطأ واحد فقط، أو تحديد الخطأين مع خطأ في الاسم"},{"level":"1 درجة","description":"الإشارة إلى أن الترقيم خطأ دون تصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الاسم إلى 1، 4-ثنائي ميثيل بنتان حلقي بالترقيم في الاتجاه الأطول","الاكتفاء بقول إن الترقيم خطأ دون بيان السبب","حذف البادئة «حلقي» من الاسم المصحح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('essay', 3, null::int, null, null, '1) السلسلة الرئيسة: في الألكانات المفتوحة نبحث عن أطول سلسلة كربونية متصلة، أما في الألكانات الحلقية فالحلقة تُعد دائمًا السلسلة الرئيسة فلا حاجة إلى البحث عن أطول سلسلة، ونضيف البادئة «حلقي» إلى اسم الألكان الذي له عدد ذرات الحلقة نفسه، مثل بنتان حلقي. 2) بدء الترقيم: في السلسلة المفتوحة نبدأ من الطرف الأقرب إلى المجموعة البديلة، أما الحلقة فليس لها أطراف، فنبدأ الترقيم من ذرة الكربون المرتبطة بمجموعة بديلة ونتجه في الاتجاه الذي يعطي أصغر مجموعة أرقام، مثل 1، 2-ثنائي ميثيل هكسان حلقي. 3) المجموعة الواحدة: في الحلقة إذا وُجدت مجموعة بديلة واحدة فلا ضرورة للترقيم، مثل ميثيل بنتان حلقي، أما في السلسلة المفتوحة فنحدد موقع المجموعة برقم، مثل 2-ميثيل بنتان.', '["الحلقة هي السلسلة الرئيسة دائمًا مع البادئة «حلقي»","الترقيم في الحلقة يبدأ من ذرة تحمل مجموعة بديلة","اتجاه الترقيم يعطي أصغر مجموعة أرقام","لا ترقيم في الحلقة عند وجود مجموعة بديلة واحدة","أمثلة صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في تحديد السلسلة الرئيسة","marks":1},{"element":"المقارنة في نقطة بدء الترقيم","marks":1},{"element":"المقارنة في حالة المجموعة الواحدة","marks":1},{"element":"أمثلة صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في النقاط الثلاث مع أمثلة صحيحة"},{"level":"2–3 درجات","description":"مقارنة صحيحة في نقطتين أو ثلاث دون أمثلة كافية"},{"level":"1 درجة","description":"مقارنة صحيحة في نقطة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["البحث عن أطول سلسلة خارج الحلقة","بدء ترقيم الحلقة من أي ذرة كربون","إضافة الرقم 1 لا ضرورة له، أو حذف البادئة «حلقي»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
