from (values
('mcq', 1, 0, '«بروبان حلقي» حلقة من ثلاث ذرات كربون، و«1، 1-ثنائي ميثيل» يعني مجموعتي ميثيل على ذرة الكربون نفسها (رقم 1). وهذا متحقق في الصيغة (أ) فقط.', '["","في (ب) مجموعتا الميثيل على ذرتين مختلفتين، فهي 1، 2-ثنائي ميثيل بروبان حلقي.","(ج) حلقة رباعية، فهي 1، 2-ثنائي ميثيل بيوتان حلقي.","(د) فيها مجموعة إيثيل واحدة، فهي إيثيل بروبان حلقي رغم أن عدد ذرات الكربون فيها 5 أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('mcq', 2, 2, '«هكسان حلقي» حلقة سداسية، والموقعان 1 و3 يعنيان أن بين ذرتي الكربون الحاملتين للميثيل ذرة كربون واحدة (رقم 2). وهذا متحقق في الصيغة (ج).', '["مجموعتا الميثيل في (أ) على ذرتين متجاورتين، فهي 1، 2-ثنائي ميثيل هكسان حلقي.","في (ب) بين المجموعتين ذرتا كربون، فهي 1، 4-ثنائي ميثيل هكسان حلقي.","","(د) حلقة خماسية، فهي 1، 3-ثنائي ميثيل بنتان حلقي لا هكسان حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('mcq', 3, 3, '«بيوتان حلقي» حلقة رباعية، ومجموعة الإيثيل على ذرة الكربون 1 ومجموعة الميثيل على ذرة الكربون 2 المجاورة لها. وهذا متحقق في الصيغة (د).', '["في (أ) المجموعتان على ذرتين متقابلتين بينهما ذرة كربون، فهي 1-إيثيل-3-ميثيل بيوتان حلقي.","في (ب) مجموعتا إيثيل، فهي 1، 2-ثنائي إيثيل بيوتان حلقي.","(ج) حلقة خماسية، فهي 1-إيثيل-2-ميثيل بنتان حلقي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('mcq', 4, 2, 'الاسم يعني حلقة رباعية (بيوتان حلقي) فيها مجموعتا ميثيل على ذرة الكربون 1، ومجموعة ميثيل ثالثة على ذرة الكربون 2 المجاورة لها. وهذا متحقق في الصيغة (ج).', '["في (أ) المجموعة الثالثة على الذرة المقابلة لا المجاورة، فهي 1، 1، 3-ثلاثي ميثيل بيوتان حلقي.","في (ب) كل مجموعة على ذرة مختلفة، فهي 1، 2، 3-ثلاثي ميثيل بيوتان حلقي.","","(د) حلقة خماسية، فهي 1، 1، 2-ثلاثي ميثيل بنتان حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('mcq', 5, 0, 'المركب حلقة سداسية (6 ذرات كربون) تتصل بها مجموعة ميثيل (ذرة كربون واحدة)، فعدد ذرات الكربون 7. وهو ألكان حلقي صيغته العامة CₙH₂ₙ، فعدد ذرات الهيدروجين 2(7) = 14؛ فالصيغة الجزيئية C₇H₁₄.', '["","استُخدمت صيغة الألكانات المفتوحة CₙH₂ₙ₊₂؛ والحلقة تقلل عدد ذرات الهيدروجين بمقدار ذرتين.","أُهملت مجموعة الميثيل، وهذه صيغة الهكسان الحلقي وحده.","نقصت ذرتا هيدروجين؛ فالألكان الحلقي ذو 7 ذرات كربون فيه 14 ذرة هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('mcq', 6, 1, '«بنتان حلقي» حلقة من 5 ذرات كربون. وتتصل بها مجموعتا إيثيل (2 × 2 = 4 ذرات) ومجموعة ميثيل (ذرة واحدة)؛ فالمجموع 5 + 4 + 1 = 10 ذرات كربون؛ أي 5 في الحلقة و10 في الجزيء كله.', '["عُدَّت مجموعة إيثيل واحدة فقط، مع أن البادئة «ثنائي» تعني مجموعتين.","","«بنتان» يعني خمس ذرات كربون في الحلقة لا ست.","ذرات المجموعات البديلة ليست جزءًا من الحلقة؛ فالحلقة في «بنتان حلقي» خمس ذرات فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.559Z"}'::jsonb),
('mcq', 7, 0, 'في الحلقة الخماسية تكون الذرة 4 مفصولة عن الذرة 1 بذرتين في اتجاه (2 و3) وبذرة واحدة في الاتجاه الآخر (5). فإذا رقّمنا في الاتجاه الأقصر أخذت المجموعة الثانية الرقم 3، فالاسم الصحيح 1، 3-ثنائي ميثيل بنتان حلقي.', '["","1، 2 تعني مجموعتين على ذرتين متجاورتين، وفي هذا المركب ذرة كربون بين المجموعتين.","الترقيم يبدأ من ذرة تحمل مجموعة بديلة، فلا يمكن أن يكون أصغر رقم 2.","تغيير الحلقة إلى سداسية يعطي مركبًا آخر؛ والمركب حلقته خماسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.560Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) «بنتان حلقي»: نرسم حلقة خماسية (مخمسًا)، كل رأس فيه ذرة كربون. 2) نرقّم ذرات الحلقة من 1 إلى 5 بالتتابع حول الحلقة. 3) نربط مجموعة إيثيل (CH₂CH₃) بذرة الكربون 1. 4) نربط مجموعة ميثيل (CH₃) بذرة الكربون 2 المجاورة للذرة 1، ومجموعة ميثيل أخرى بذرة الكربون 3 المجاورة للذرة 2؛ فتكون المجموعات الثلاث على ثلاث ذرات متتالية، والذرتان 4 و5 بلا تفرعات. الصيغة الجزيئية: ذرات الكربون 5 + 2 + 1 + 1 = 9، والمركب ألكان حلقي صيغته CₙH₂ₙ؛ فالصيغة C₉H₁₈.', '["رسم حلقة خماسية","ترقيم الحلقة","مجموعة إيثيل على الذرة 1","مجموعتا ميثيل على الذرتين 2 و3 المتتاليتين","الصيغة الجزيئية C₉H₁₈"]'::jsonb, '["عدد ذرات C = 5 (الحلقة) + 2 (إيثيل) + 2 × 1 (ميثيل) = 9","عدد ذرات H = 2n = 2(9) = 18","الصيغة: C₉H₁₈"]'::jsonb, '[{"element":"الحلقة الخماسية وترقيمها","marks":1},{"element":"موقع الإيثيل","marks":1},{"element":"موقعا الميثيل","marks":1},{"element":"الصيغة الجزيئية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح للحلقة والمجموعات ومواقعها، وصيغة جزيئية صحيحة"},{"level":"2–3 درجات","description":"حلقة صحيحة مع خطأ في موقع مجموعة أو في الصيغة الجزيئية"},{"level":"1 درجة","description":"رسم الحلقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم حلقة سداسية","وضع مجموعتي الميثيل على الذرة نفسها","كتابة الصيغة C₉H₂₀"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.560Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) حلقة رباعية رؤوسها بالترتيب: CH(CH₃) ثم CH₂ ثم CH(CH₃) ثم CH₂، أي أن مجموعتي CH₃ على ذرتين متقابلتين بينهما مجموعة CH₂ من كل جهة. عدد ذرات الكربون 4 + 2 = 6، والصيغة الجزيئية C₆H₁₂. (ب) حلقة خماسية رؤوسها: C(CH₂CH₃)₂ ثم أربع مجموعات CH₂، أي أن ذرة كربون واحدة في الحلقة ترتبط بمجموعتي إيثيل ولا ترتبط بأي ذرة هيدروجين. عدد ذرات الكربون 5 + 4 = 9، والصيغة الجزيئية C₉H₁₈.', '["(أ) حلقة رباعية: CH(CH₃)–CH₂–CH(CH₃)–CH₂","(أ) C₆H₁₂","(ب) حلقة خماسية: C(CH₂CH₃)₂ وأربع مجموعات CH₂","(ب) C₉H₁₈"]'::jsonb, '["(أ): C = 4 + 2 = 6، H = 2(6) = 12","(ب): C = 5 + 2 × 2 = 9، H = 2(9) = 18"]'::jsonb, '[{"element":"الصيغة المكثفة للمركب (أ)","marks":1},{"element":"الصيغة الجزيئية للمركب (أ)","marks":1},{"element":"الصيغة المكثفة للمركب (ب)","marks":1},{"element":"الصيغة الجزيئية للمركب (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغ الأربع صحيحة"},{"level":"2–3 درجات","description":"صيغتا مركب واحد صحيحتان أو أخطاء بسيطة في المركبين"},{"level":"1 درجة","description":"صيغة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مجموعتي الميثيل في (أ) على ذرتين متجاورتين","توزيع مجموعتي الإيثيل في (ب) على ذرتين مختلفتين","كتابة ذرة الكربون الحاملة لمجموعتين CH بدلًا من C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-07T17:19:00.560Z"}'::jsonb),
('essay', 3, null::int, null, null, 'للاسم الأول: حلقة سداسية، مجموعة ميثيل على الذرة 1 وأخرى على الذرة 3، وبينهما الذرة 2. للاسم الثاني: حلقة سداسية، ميثيل على الذرة 1 وأخرى على الذرة 5. وفي الحلقة السداسية تكون الذرة 5 مجاورة للذرة 6 المجاورة للذرة 1، أي أن بين الذرتين 1 و5 ذرة واحدة (6) إذا سرنا في الاتجاه الآخر. ففي الصيغتين مجموعتا ميثيل بينهما ذرة كربون واحدة، فهما المركب نفسه بترقيمين مختلفين. والاسم الصحيح 1، 3-ثنائي ميثيل هكسان حلقي؛ لأن الترقيم يبدأ من ذرة تحمل مجموعة بديلة ويسير في الاتجاه الذي يعطي أصغر مجموعة أرقام، و(1، 3) أصغر من (1، 5).', '["وصف صيغة 1، 3: بين المجموعتين ذرة واحدة","وصف صيغة 1، 5: بين المجموعتين ذرة واحدة (6) في الاتجاه الآخر","الصيغتان للمركب نفسه","الاسم الصحيح 1، 3-ثنائي ميثيل هكسان حلقي","التبرير: أصغر مجموعة أرقام"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الصيغة الأولى","marks":1},{"element":"وصف الصيغة الثانية","marks":1},{"element":"إثبات أنهما المركب نفسه","marks":1},{"element":"تحديد الاسم الصحيح وتبريره","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف الصيغتين، وإثبات تطابقهما، وتحديد الاسم الصحيح مع التبرير"},{"level":"2–3 درجات","description":"تحديد الاسم الصحيح مع نقص في إثبات التطابق أو في الوصف"},{"level":"1 درجة","description":"تحديد الاسم الصحيح دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الاسمين مركبين مختلفين","اختيار 1، 5 لأن الترقيم في اتجاه عقارب الساعة","رسم مجموعتي الميثيل على ذرتين متقابلتين (1، 4)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.560Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
