('mcq', 2, 'يقارن الجدول الآتي بين الماء والميثان. ما التفسير الصحيح للفرق الكبير في درجتي غليانهما رغم تقارب كتلتيهما الجزيئيتين؟', '{"headers":["الخاصية","الماء H₂O","الميثان CH₄"],"rows":[["الكتلة الجزيئية","18 amu","16 amu"],["الحالة عند درجة حرارة الغرفة","سائل","غاز"],["درجة الغليان","100°C","−162°C"],["درجة الانصهار","0°C","−182°C"]]}'::jsonb, null, '["لأن الكتلة الجزيئية للماء أكبر كثيرًا من الكتلة الجزيئية للميثان، فيحتاج إلى طاقة أكبر","لأن جزيئات الميثان أكبر حجمًا بكثير من جزيئات الماء، فتتحرك ببطء أكبر","لأن روابط C–H داخل جزيء الميثان أضعف من روابط O–H داخل جزيء الماء","لأن التجاذب بين جزيئات الميثان غير القطبية ضعيف، وجزيئات الماء القطبية تكوّن روابط هيدروجينية"]'::jsonb, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 134–135 — الجدول 4-4 مقارنة الخصائص الفيزيائية'),
('mcq', 3, 'خُلط الهكسان بالماء ورُجّ الخليط، ثم تُرك فانفصل إلى طبقتين كما في الشكل الآتي. ما سبب ذلك؟', null, '[{"src":"qimg/chem22/c4-l2a-layers.svg","alt":"كأس فيها سائلان منفصلان في طبقتين بينهما حد فاصل واضح: الطبقة العليا مكتوب بجانبها «هكسان»، والطبقة السفلى مكتوب بجانبها «ماء»."}]'::jsonb, '["قوى التجاذب بين جزيئات الهكسان نفسها أقوى من قوى التجاذب بين جزيئات الهكسان والماء","الهكسان يتفاعل كيميائيًّا مع الماء فيكوّن مادة جديدة تطفو فوقه","جزيئات الهكسان قطبية، فتتنافر مع جزيئات الماء القطبية","جزيئات الهكسان تكوّن روابط هيدروجينية قوية فيما بينها"]'::jsonb, 'فهم', 'تفسير مشاهدة', 'سهل', 'الكتاب ص 135 — عدم امتزاج الألكانات بالماء'),
('mcq', 4, 'تحتوي كثير من المذيبات المستخدمة في الدهانات وأحبار الطابعات والمواد اللاصقة على الألكانات والألكانات الحلقية. ما خاصية الألكانات التي تجعلها مناسبة لذلك؟', null, null, '["أنها تذوب في الماء بسهولة وتكوّن محاليل متجانسة","أنها قطبية ودرجات غليانها مرتفعة جدًّا","أنها شديدة النشاط وتتفاعل مع المواد الملوِّنة","أنها غير قطبية فهي مذيبات جيدة للمواد غير القطبية"]'::jsonb, 'تذكر', 'ربط خاصية باستخدام', 'سهل', 'الكتاب ص 134 — الشكل 11-4 والألكانات مذيبات'),
('mcq', 5, 'ما تفسير ضعف النشاط الكيميائي للألكانات؟', null, null, '["لأن جزيئاتها تحتوي على روابط ثنائية يصعب كسرها في معظم الظروف","لأن جزيئاتها قطبية فتتجاذب بقوة مع الأيونات وتحيط بها","لأنها غير قطبية فتنجذب إليها الأيونات والجزيئات القطبية ضعيفًا، وروابطها قوية نسبيًّا","لأنها جميعها غازات عند درجة حرارة الغرفة فلا تتلامس مع المواد الأخرى"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 135 — الخصائص الكيميائية للألكانات'),
('mcq', 6, 'يبين المنحنى الآتي درجات غليان بعض الألكانات ذات السلاسل المستقيمة مقابل عدد ذرات الكربون في جزيئاتها. ما العلاقة التي يُظهرها المنحنى؟', null, '[{"src":"qimg/chem22/c4-l2a-bp-graph.svg","alt":"رسم بياني: المحور الأفقي «عدد ذرات الكربون في الجزيء» من 1 إلى 8، والمحور الرأسي «درجة الغليان» بوحدة °C من −200 إلى 150، وعليه خط أفقي متقطع عند 0. خمس نقاط متصلة بخط صاعد: الميثان (1 ذرة) −162°C، والبروبان (3 ذرات) −42°C، والبيوتان (4 ذرات) −1°C، والهكسان (6 ذرات) 69°C، والأوكتان (8 ذرات) 126°C."}]'::jsonb, '["تنخفض درجة الغليان بزيادة عدد ذرات الكربون","ترتفع درجة الغليان بزيادة عدد ذرات الكربون","لا تتغير درجة الغليان بتغير عدد ذرات الكربون","ترتفع درجة الغليان حتى البيوتان ثم تنخفض"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 159 و162 — الجدول 7-4 والسؤال 91'),
('mcq', 7, 'يبين الجدول الآتي درجات غليان بعض الألكانات ذات السلاسل المستقيمة. أيّ القيم الآتية هي الأقرب إلى درجة غليان الهبتان C₇H₁₆؟', '{"headers":["الألكان","درجة الغليان (°C)"],"rows":[["الميثان CH₄","−161.7"],["البروبان C₃H₈","−42.1"],["البيوتان C₄H₁₀","−0.5"],["الهكسان C₆H₁₄","68.7"],["الأوكتان C₈H₁₈","125.7"]]}'::jsonb, null, '["30.2°C","145.0°C","68.7°C","98.5°C"]'::jsonb, 'تطبيق', 'تنبؤ من بيانات', 'صعب', 'الكتاب ص 159 و164 — الجدول 7-4 وبيانات الهبتان في الاختبار المقنن'),
