from (values
('mcq', 1, 0, 'تتكون جميع الروابط في الألكانات بين ذرة كربون وذرة هيدروجين أو بين ذرتي كربون، وهذه الروابط غير قطبية؛ لذا تُعد جزيئات الألكانات غير قطبية لأن جميع روابطها غير قطبية.', '["","الروابط الهيدروجينية تتكون بين الجزيئات القطبية مثل الماء، والألكانات لا تكوّنها.","الشكل المنحني لجزيء الماء ذي الروابط القطبية هو سبب قطبيته، والألكانات روابطها غير قطبية أصلًا.","الألكانات تحتوي على روابط أحادية فقط، ونوع الرابطة الكربونية ليس سبب عدم القطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.560Z"}'::jsonb),
('mcq', 2, 3, 'جزيئات الميثان غير قطبية ولا تكوّن روابط هيدروجينية، فالتجاذب بينها ضعيف، أما جزيئات الماء فقطبية وتكوّن روابط هيدروجينية؛ لذلك يحتاج الماء إلى طاقة أكبر ليغلي، فدرجة غليانه 100°C مقابل −162°C للميثان.', '["الكتلتان متقاربتان (18 amu و16 amu)، فلا يفسر فرق الكتلة هذا الفرق الكبير.","جزيئات الماء والميثان متقاربة في الحجم، فالحجم ليس سبب الفرق.","الغليان يتغلب على قوى التجاذب بين الجزيئات لا على الروابط داخل الجزيء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.560Z"}'::jsonb),
('mcq', 3, 0, 'الهكسان ألكان غير قطبي والماء قطبي، فلا يمتزجان؛ إذ إن قوى التجاذب بين جزيئات الألكان نفسها أقوى من قوى التجاذب بين جزيئات الألكان وجزيئات الماء، فينفصل السائلان فورًا إلى طبقتين.', '["","الألكانات ضعيفة النشاط الكيميائي ولا تتفاعل مع الماء؛ والانفصال فيزيائي لا كيميائي.","جزيئات الهكسان غير قطبية لا قطبية.","الألكانات لا تكوّن روابط هيدروجينية لأنها غير قطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('mcq', 4, 3, 'الألكانات غير قطبية لأن روابطها جميعًا غير قطبية، وهذا يجعلها مذيبات جيدة لمواد أخرى غير قطبية؛ لذلك تُستخدم في الدهانات والأحبار والمواد اللاصقة.', '["الألكانات لا تمتزج بالماء ولا تذوب فيه لأنها غير قطبية.","الألكانات غير قطبية، ودرجات غليانها منخفضة مقارنة بالمواد القطبية المشابهة لها في الكتلة.","النشاط الكيميائي للألكانات ضعيف، وهو خاصيتها الكيميائية الرئيسة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('mcq', 5, 2, 'تحدث كثير من التفاعلات عندما تنجذب مادة مشحونة (أيون) أو ذات شحنة جزئية (جزيء قطبي) إلى مادة أخرى. والألكانات غير قطبية، فيكون انجذاب الأيونات والجزيئات القطبية إليها ضعيفًا جدًّا، كما أن روابط C–C وC–H فيها قوية نسبيًّا؛ لذا نشاطها الكيميائي ضعيف.', '["الألكانات تحتوي على روابط أحادية فقط لا ثنائية.","جزيئات الألكانات غير قطبية، ولو كانت قطبية لانجذبت إليها الأيونات وزاد نشاطها.","","ليست الألكانات كلها غازات؛ فالهكسان والأوكتان سوائل، ومع ذلك نشاطها ضعيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('mcq', 6, 1, 'تزداد قيم درجة الغليان باستمرار من −162°C للميثان إلى 126°C للأوكتان كلما زاد عدد ذرات الكربون؛ فالعلاقة: ترتفع درجة الغليان بزيادة عدد ذرات الكربون.', '["هذا عكس ما يُظهره المنحنى؛ فالخط صاعد من الميثان إلى الأوكتان.","","القيم تتغير كثيرًا (من −162°C إلى 126°C)، فلا يمكن القول إنها ثابتة.","المنحنى يستمر في الصعود بعد البيوتان إلى الهكسان ثم الأوكتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('mcq', 7, 3, 'ترتفع درجة غليان الألكانات بزيادة عدد ذرات الكربون، والهبتان (7 ذرات) يقع بين الهكسان (6 ذرات، 68.7°C) والأوكتان (8 ذرات، 125.7°C)، فتكون درجة غليانه أعلى من 68.7°C وأقل من 125.7°C؛ والقيمة الوحيدة في هذا المدى 98.5°C.', '["30.2°C أقل من درجة غليان الهكسان، مع أن الهبتان فيه ذرة كربون أكثر.","145.0°C أعلى من درجة غليان الأوكتان، مع أن الهبتان فيه ذرة كربون أقل.","68.7°C درجة غليان الهكسان نفسه، والهبتان أكبر منه فدرجة غليانه أعلى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخصائص الفيزيائية: 1) جزيئات الألكانات غير قطبية لأن روابطها جميعها غير قطبية. 2) لا تمتزج بالماء ولا تذوب فيه، فتنفصل عنه في طبقة مستقلة. 3) مذيبات جيدة للمواد غير القطبية. 4) درجات غليانها وانصهارها منخفضة مقارنة بالمواد القطبية المشابهة لها في الكتلة الجزيئية (الميثان غاز يغلي عند −162°C)، وترتفع درجة الغليان بزيادة عدد ذرات الكربون. الخاصية الكيميائية الرئيسة: ضعف نشاطها الكيميائي، لأنها غير قطبية فتنجذب إليها الأيونات والجزيئات القطبية ضعيفًا، ولأن روابط C–C وC–H قوية نسبيًّا.', '["غير قطبية","لا تمتزج بالماء","مذيبات جيدة للمواد غير القطبية","درجات غليان وانصهار منخفضة وترتفع بزيادة عدد ذرات الكربون","ضعف النشاط الكيميائي"]'::jsonb, '[]'::jsonb, '[{"element":"عدم القطبية","marks":1},{"element":"عدم الامتزاج بالماء","marks":1},{"element":"مذيبات للمواد غير القطبية","marks":1},{"element":"درجات الغليان والانصهار","marks":1},{"element":"ضعف النشاط الكيميائي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ذكر الخصائص الخمس بصورة صحيحة"},{"level":"3–4 درجات","description":"ذكر ثلاث خصائص أو أربع صحيحة"},{"level":"1–2 درجة","description":"ذكر خاصية أو خاصيتين صحيحتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الألكانات تذوب في الماء","وصف الألكانات بأنها نشطة كيميائيًّا","القول إن درجات غليانها مرتفعة مقارنة بالماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكتلتان الجزيئيتان متقاربتان (18 amu و16 amu) والجزيئان متقاربان في الحجم، ومع ذلك فدرجتا غليان الماء وانصهاره (100°C و0°C) أعلى كثيرًا من درجتي الميثان (−162°C و−182°C). والسبب اختلاف قوى التجاذب بين الجزيئات: فجزيء الماء قطبي لأن رابطة O–H قطبية وشكله منحنٍ، فتتجاذب جزيئاته بقوة وتكوّن روابط هيدروجينية، أما جزيء الميثان فغير قطبي ولا يكوّن روابط هيدروجينية، فالتجاذب بين جزيئاته ضعيف. وكلما قويت قوى التجاذب بين الجزيئات احتاجت المادة إلى طاقة أكبر لفصل جزيئاتها، فترتفع درجتا غليانها وانصهارها. ولأن درجة غليان الميثان أقل كثيرًا من درجة حرارة الغرفة فهو غاز، أما الماء فدرجة انصهاره أقل من درجة حرارة الغرفة ودرجة غليانه أعلى منها فهو سائل.', '["تقارب الكتلتين الجزيئيتين لا يفسر الفرق","الماء قطبي ويكوّن روابط هيدروجينية","الميثان غير قطبي والتجاذب بين جزيئاته ضعيف","قوى التجاذب الأقوى تتطلب طاقة أكبر فترفع درجتي الغليان والانصهار","تفسير الحالة عند درجة حرارة الغرفة بمقارنتها بدرجتي الانصهار والغليان"]'::jsonb, '[]'::jsonb, '[{"element":"ملاحظة تقارب الكتلتين","marks":1},{"element":"قطبية الماء والروابط الهيدروجينية","marks":1},{"element":"عدم قطبية الميثان وضعف التجاذب","marks":1},{"element":"العلاقة بين قوى التجاذب والطاقة اللازمة","marks":1},{"element":"تفسير حالة كل مادة عند درجة حرارة الغرفة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل يربط البيانات بقوى التجاذب ويفسر حالة المادتين"},{"level":"3–4 درجات","description":"تفسير صحيح لقوى التجاذب مع نقص في الربط بالبيانات أو بالحالة الفيزيائية"},{"level":"1–2 درجة","description":"ذكر أن الماء قطبي والميثان غير قطبي دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق بالكتلة الجزيئية","الخلط بين الروابط داخل الجزيء وقوى التجاذب بين الجزيئات","القول إن الميثان يكوّن روابط هيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الهكسان والهكسان الحلقي ألكانان غير قطبيين، والشحوم والمواد الدهنية مواد غير قطبية أيضًا؛ والألكانات مذيبات جيدة للمواد غير القطبية، فتذيب الشحوم. أما الماء فقطبي وجزيئاته تتجاذب بروابط هيدروجينية، وقوى التجاذب بين جزيئات الألكان نفسها أقوى من قوى التجاذب بين جزيئات الألكان وجزيئات الماء؛ لذا لا يمتزجان وينفصلان في طبقتين. وتحدث كثير من التفاعلات عندما تنجذب مادة مشحونة كالأيون أو ذات شحنة جزئية كالجزيء القطبي إلى مادة أخرى، وجزيئات الألكانات غير قطبية فيكون انجذاب الأيونات والجزيئات القطبية إليها ضعيفًا جدًّا، كما أن روابط C–C وC–H فيها قوية نسبيًّا؛ لذا نشاطها الكيميائي ضعيف.', '["الألكانات والشحوم غير قطبية فتذيب الألكانات الشحوم","الماء قطبي ويكوّن روابط هيدروجينية","تجاذب جزيئات الألكان نفسها أقوى من تجاذبها مع الماء فلا يمتزجان","ضعف انجذاب الأيونات والجزيئات القطبية إلى الجزيئات غير القطبية","قوة روابط C–C وC–H نسبيًّا"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير إذابة الشحوم","marks":1},{"element":"قطبية الماء","marks":1},{"element":"تفسير عدم الامتزاج بالماء","marks":1},{"element":"تفسير ضعف الانجذاب للأيونات والجزيئات القطبية","marks":1},{"element":"ذكر قوة روابط C–C وC–H","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير صحيح وكامل للذوبان وعدم الامتزاج وضعف النشاط"},{"level":"3–4 درجات","description":"تفسير صحيح للذوبان وعدم الامتزاج مع نقص في تفسير ضعف النشاط أو العكس"},{"level":"1–2 درجة","description":"ذكر عدم القطبية دون ربط واضح بالمشاهدات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الهكسان يتفاعل مع الشحوم كيميائيًّا","القول إن الألكانات قطبية","تفسير ضعف النشاط بوجود روابط ثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.561Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
