('mcq', 1, 'ما الصيغة الجزيئية لألكان يحتوي جزيئه على 20 ذرة كربون؟', null, null, '["C₂₀H₄₀","C₂₀H₄₂","C₂₀H₃₈","C₂₀H₂₂"]'::jsonb, 'تطبيق', 'تطبيق الصيغة العامة', 'سهل', 'الكتاب ص 128 — الصيغة العامة للألكانات CnH2n+2'),
('mcq', 2, 'يمثل الشكل الآتي الهيكل الكربوني لألكان متفرع، رُسمت فيه ذرات الكربون وحدها دون ذرات الهيدروجين. ما الصيغة الجزيئية لهذا الألكان؟', null, '[{"src":"qimg/chem22/c4-l2b-skel-234tmh.svg","alt":"هيكل كربوني لألكان متفرع تظهر فيه ذرات الكربون وحدها (C) دون ذرات الهيدروجين، والروابط كلها أحادية: سلسلة أفقية من ست ذرات كربون. ترتبط بالذرة الثانية من اليسار ذرة كربون واحدة فوقها، وبالذرة الثالثة من اليسار ذرة كربون واحدة تحتها، وبالذرة الرابعة من اليسار ذرة كربون واحدة فوقها. مجموع ذرات الكربون المرسومة تسع ذرات."}]'::jsonb, '["C₆H₁₄","C₉H₁₈","C₉H₂₀","C₈H₁₈"]'::jsonb, 'تطبيق', 'تطبيق الصيغة العامة على شكل', 'متوسط', 'الكتاب ص 128 و165 — الصيغة العامة، والهيكل الكربوني في اختبار مقنن س9'),
('mcq', 3, 'الكتلة المولية لألكان 156.3 g/mol. ما صيغته الجزيئية؟ (H = 1.008، C = 12.01)', null, null, '["C₁₁H₂₄","C₁₃H₂₈","C₁₁H₂₂","C₁₂H₂₆"]'::jsonb, 'تحليل', 'مسألة حسابية', 'صعب', 'الكتاب ص 128 — الصيغة العامة للألكانات CnH2n+2'),
