('mcq', 5, 'ما العدد الكلي للذرات في جزيء ألكان يحتوي على 12 ذرة كربون؟', null, null, '["26","38","36","24"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 128 — الصيغة العامة للألكانات CnH2n+2'),
