('essay', 1, 'استخدم الصيغة العامة للألكانات CₙH₂ₙ₊₂ لإكمال الجدول الآتي، ثم بيّن هل يمكن أن يكون المركب C₁₅H₃₀ ألكانًا، مع التعليل. (H = 1.008، C = 12.01)', '{"headers":["المعطى","عدد ذرات الكربون n","الصيغة الجزيئية"],"rows":[["ألكان فيه 18 ذرة كربون","18","؟"],["ألكان فيه 40 ذرة هيدروجين","؟","؟"],["ألكان كتلته المولية 58.12 g/mol","؟","؟"]]}'::jsonb, null, null, 'تطبيق', 'إكمال جدول', 'متوسط', 'الكتاب ص 128 و162 — الصيغة العامة والسؤال 78'),
('essay', 2, 'الصيغة العامة للألكانات CₙH₂ₙ₊₂. (أ) اكتب الصيغة الجزيئية لكل من الهكسان والهكسان الحلقي. (ب) فسّر لماذا يحتوي الهكسان الحلقي على عدد أقل من ذرات الهيدروجين. (ج) استنتج الصيغة العامة للألكانات الحلقية، ثم استخدمها لكتابة الصيغة الجزيئية لألكان حلقي حلقته من 8 ذرات كربون ولا تتصل به مجموعات بديلة.', null, null, null, 'تحليل', 'استنتاج وتطبيق', 'صعب', 'الكتاب ص 128 و132 و162 — الصيغة العامة، والألكانات الحلقية، والسؤال 79'),
('essay', 3, 'يمثل الشكل الآتي الهيكل الكربوني لألكان متفرع، رُسمت فيه ذرات الكربون وحدها. أكمل الجزيء ذهنيًّا بذرات الهيدروجين بحيث تكوّن كل ذرة كربون أربع روابط، ثم: (أ) صنّف ذرات الكربون إلى CH₃ وCH₂ وCH وC مع عدد كل منها. (ب) احسب عدد ذرات الهيدروجين، واكتب الصيغة الجزيئية. (ج) تحقق من أن الصيغة الجزيئية تطابق الصيغة العامة للألكانات.', null, '[{"src":"qimg/chem22/c4-l2b-skel-4e22dmh.svg","alt":"هيكل كربوني لألكان متفرع تظهر فيه ذرات الكربون وحدها (C) دون ذرات الهيدروجين، والروابط كلها أحادية: سلسلة أفقية من ست ذرات كربون. ترتبط بالذرة الثانية من اليسار ذرتا كربون منفصلتان، إحداهما فوقها والأخرى تحتها. وترتبط بالذرة الرابعة من اليسار سلسلة رأسية إلى الأعلى من ذرتي كربون متصلتين ببعضهما."}]'::jsonb, null, 'تطبيق', 'تحليل صيغة وحساب', 'صعب', 'الكتاب ص 128 و165 — الصيغة العامة، والهيكل الكربوني في اختبار مقنن س9')
