select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الصيغة العامة للألكانات CₙH₂ₙ₊₂، وفيها n = 20؛ فعدد ذرات الهيدروجين 2(20) + 2 = 42، والصيغة C₂₀H₄₂.', '["استُخدمت العلاقة 2n دون إضافة 2؛ فعدد ذرات H يساوي 42 لا 40.","","طُرح 2 بدل إضافته؛ والصيغة العامة للألكانات تضيف 2 إلى 2n.","أُضيف 2 إلى n نفسه بدل مضاعفته؛ فعدد ذرات H يساوي 2n + 2 = 42."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.562Z"}'::jsonb),
('mcq', 2, 2, 'عدد ذرات الكربون في الهيكل كله 9 ذرات (6 في السلسلة الأفقية و3 في التفرعات). والألكانات المتفرعة تخضع أيضًا للصيغة العامة CₙH₂ₙ₊₂، فعدد ذرات H = 2(9) + 2 = 20، والصيغة C₉H₂₀.', '["عُدّت ذرات السلسلة الأفقية فقط وأُهملت ذرات التفرعات الثلاث.","استُخدمت العلاقة 2n دون إضافة 2؛ والصواب 2(9) + 2 = 20.","","أُغفلت إحدى ذرات التفرعات؛ فعدد ذرات الكربون في الهيكل 9 لا 8."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-07T17:19:00.562Z"}'::jsonb),
('mcq', 3, 0, 'كتلة ألكان صيغته CₙH₂ₙ₊₂ تساوي 12.01n + 1.008(2n + 2) = 14.026n + 2.016. بمساواتها بـ 156.3 g/mol: n = (156.3 − 2.016) ÷ 14.026 = 11.0؛ فالصيغة C₁₁H₂₄، وكتلتها 11(12.01) + 24(1.008) = 156.3 g/mol.', '["","قُسمت الكتلة كلها على كتلة الكربون (156.3 ÷ 12.01 ≈ 13) مع إهمال كتلة الهيدروجين؛ وكتلة C₁₃H₂₈ نحو 184.4 g/mol.","هذه صيغة CₙH₂ₙ لا صيغة ألكان، وكتلتها 154.3 g/mol لا 156.3 g/mol.","كتلة C₁₂H₂₆ تساوي 170.3 g/mol، فهي أكبر من الكتلة المعطاة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.562Z"}'::jsonb),
('mcq', 4, 3, 'في الصيغة CₙH₂ₙ₊₂ يكون 2n + 2 = 34، ومنها 2n = 32 وn = 16؛ فالصيغة C₁₆H₃₄.', '["قُسم عدد ذرات H على 2 دون طرح 2 أولًا؛ وC₁₇H₃₄ تحقق CₙH₂ₙ وليست ألكانًا.","أُضيف 1 بدل طرحه بعد القسمة؛ فالصحيح (34 − 2) ÷ 2 = 16.","عُدّ الرقم 34 عددًا لذرات الكربون لا لذرات الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb),
('mcq', 5, 1, 'صيغة الألكان الذي فيه 12 ذرة كربون C₁₂H₂₆ (2 × 12 + 2 = 26 ذرة H)، فالعدد الكلي للذرات 12 + 26 = 38 ذرة.', '["هذا عدد ذرات الهيدروجين وحدها؛ ويجب إضافة ذرات الكربون الاثنتي عشرة.","","حُسبت ذرات H بالعلاقة 2n (24) ثم أضيفت ذرات C؛ والصواب 2n + 2 = 26 ذرة H.","هذا ناتج 2n فقط، وليس عدد ذرات الجزيء كله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb),
('mcq', 6, 2, 'السلسلة الرئيسة بنتان (5 ذرات كربون) وتتصل بها ثلاث مجموعات ميثيل (3 ذرات كربون)؛ فعدد ذرات الكربون 8. وبما أنه ألكان: عدد ذرات H = 2(8) + 2 = 18، والصيغة C₈H₁₈.', '["هذه صيغة السلسلة الرئيسة وحدها؛ ولم تُحسب ذرات الكربون في مجموعات الميثيل الثلاث.","عدد ذرات الكربون صحيح، لكن استُخدمت العلاقة 2n دون إضافة 2.","","عُدّت مجموعتا ميثيل فقط بدل ثلاث؛ فالبادئة «ثلاثي» تعني ثلاث مجموعات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb),
('mcq', 7, 0, 'تربط الصيغة العامة CₙH₂ₙ₊₂ بين عدد ذرات الكربون والهيدروجين، وn فيها عدد ذرات الكربون في الألكان؛ فإذا عُرف n أمكن كتابة الصيغة الجزيئية لأي ألكان.', '["","عدد ذرات الهيدروجين يُمثَّل بـ 2n + 2 لا بـ n.","عدد الروابط C–C في السلسلة المستقيمة n − 1 لا n.","عدد وحدات –CH₂– في السلسلة المستقيمة n − 2، لا n."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الألكان الذي فيه 18 ذرة كربون: H = 2(18) + 2 = 38، فالصيغة C₁₈H₃₈. الألكان الذي فيه 40 ذرة هيدروجين: 2n + 2 = 40، فـ n = 19، والصيغة C₁₉H₄₀. الألكان الذي كتلته المولية 58.12 g/mol: 14.026n + 2.016 = 58.12، فـ n = 4.0، والصيغة C₄H₁₀ (4 × 12.01 + 10 × 1.008 = 58.12 g/mol). أما C₁₅H₃₀ فليس ألكانًا؛ لأن الألكان الذي فيه 15 ذرة كربون يجب أن يحتوي على 2(15) + 2 = 32 ذرة هيدروجين، وC₁₅H₃₀ ينقص ذرتي هيدروجين.', '["C₁₈H₃₈","n = 19 والصيغة C₁₉H₄₀","n = 4 والصيغة C₄H₁₀","C₁₅H₃₀ ليس ألكانًا لأن الألكان C₁₅ يحتوي على 32 ذرة H"]'::jsonb, '["18 ذرة C: H = 2(18) + 2 = 38 ← C₁₈H₃₈","40 ذرة H: 2n + 2 = 40 ← n = 19 ← C₁₉H₄₀","M = 14.026n + 2.016 = 58.12 ← n = (58.12 − 2.016) ÷ 14.026 = 4.0 ← C₄H₁₀","للألكان C₁₅: H = 32 ≠ 30 ← C₁₅H₃₀ ليس ألكانًا"]'::jsonb, '[{"element":"الصيغة C₁₈H₃₈","marks":1},{"element":"n = 19 والصيغة C₁₉H₄₀","marks":1},{"element":"حساب n = 4 من الكتلة المولية والصيغة C₄H₁₀","marks":1},{"element":"الحكم على C₁₅H₃₀ مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إكمال الصفوف الثلاثة صحيحًا والحكم على C₁₅H₃₀ بتعليل صحيح"},{"level":"2–3 درجات","description":"إكمال صفين أو ثلاثة مع خطأ في صف أو غياب التعليل"},{"level":"1 درجة","description":"إكمال صف واحد صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب عدد ذرات H بالعلاقة 2n","قسمة 40 على 2 مباشرة فيكون n = 20","قسمة الكتلة المولية على 12.01 وإهمال كتلة الهيدروجين","الحكم بأن C₁₅H₃₀ ألكان لأن عدد ذرات H زوجي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الهكسان: n = 6، فعدد ذرات H = 2(6) + 2 = 14، والصيغة C₆H₁₄؛ والهكسان الحلقي C₆H₁₂. (ب) في الألكان الحلقي ترتبط ذرتا الكربون الطرفيتان معًا لإغلاق الحلقة؛ فكل منهما تستعمل إلكترونًا تكافؤيًّا واحدًا لتكوين رابطة كربون–كربون بدل رابطة كربون–هيدروجين، فيفقد الجزيء ذرتي هيدروجين. (ج) بطرح ذرتي هيدروجين من الصيغة CₙH₂ₙ₊₂ تصبح الصيغة العامة للألكانات الحلقية CₙH₂ₙ. والألكان الحلقي الذي فيه 8 ذرات كربون: H = 2(8) = 16، فصيغته C₈H₁₆.', '["الهكسان C₆H₁₄ والهكسان الحلقي C₆H₁₂","إغلاق الحلقة يكوّن رابطة C–C بدل رابطتي C–H فتقل ذرتا H","الصيغة العامة للألكانات الحلقية CₙH₂ₙ","C₈H₁₆"]'::jsonb, '["الهكسان: H = 2(6) + 2 = 14 ← C₆H₁₄","الهكسان الحلقي: ذرتا H أقل ← C₆H₁₂","CₙH₂ₙ₊₂ − 2H ← CₙH₂ₙ","n = 8 ← H = 16 ← C₈H₁₆"]'::jsonb, '[{"element":"الصيغتان الجزيئيتان للهكسان والهكسان الحلقي","marks":1},{"element":"تفسير نقص ذرتي الهيدروجين","marks":1},{"element":"استنتاج الصيغة CₙH₂ₙ","marks":1},{"element":"الصيغة C₈H₁₆","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"صيغتان صحيحتان، وتفسير صحيح، واستنتاج الصيغة العامة وتطبيقها"},{"level":"2–3 درجات","description":"صيغتان صحيحتان مع نقص في التفسير أو الاستنتاج"},{"level":"1 درجة","description":"صيغة جزيئية واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة صيغة الهكسان الحلقي C₆H₁₄ مثل الهكسان","الاعتقاد أن الحلقة تحتوي على رابطة ثنائية","كتابة الصيغة العامة CₙH₂ₙ₋₂ للألكانات الحلقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عدد ذرات الكربون 10. مجموعات CH₃ خمس: طرفا السلسلة الأفقية، ومجموعتا الميثيل على الذرة الثانية، والذرة العليا في فرع الإيثيل. مجموعات CH₂ ثلاث: الذرة الثالثة والذرة الخامسة في السلسلة، وذرة الفرع المتصلة بالسلسلة. مجموعة CH واحدة: الذرة الرابعة (ترتبط بثلاث ذرات كربون). ذرة C واحدة دون هيدروجين: الذرة الثانية (ترتبط بأربع ذرات كربون). (ب) عدد ذرات H = 5 × 3 + 3 × 2 + 1 × 1 + 0 = 22؛ فالصيغة الجزيئية C₁₀H₂₂. (ج) بالصيغة العامة: n = 10، و2(10) + 2 = 22، وهو مطابق لما حُسب بالعدّ.', '["10 ذرات كربون","خمس CH₃ وثلاث CH₂ وCH واحدة وC واحدة","22 ذرة H والصيغة C₁₀H₂₂","التحقق: 2(10) + 2 = 22"]'::jsonb, '["عدّ ذرات الكربون: 6 + 2 + 2 = 10","CH₃ × 5 = 15 H، CH₂ × 3 = 6 H، CH × 1 = 1 H، C × 1 = 0","المجموع 15 + 6 + 1 + 0 = 22 ← C₁₀H₂₂","CₙH₂ₙ₊₂: 2(10) + 2 = 22 ✓"]'::jsonb, '[{"element":"تصنيف ذرات الكربون بأعدادها الصحيحة","marks":2},{"element":"حساب 22 ذرة H وكتابة C₁₀H₂₂","marks":1},{"element":"التحقق بالصيغة العامة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح كامل، وصيغة جزيئية صحيحة، وتحقق صحيح"},{"level":"2–3 درجات","description":"صيغة جزيئية صحيحة مع خطأ في تصنيف بعض الذرات أو غياب التحقق"},{"level":"1 درجة","description":"عدد ذرات الكربون صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات السلسلة الأفقية فقط","إعطاء الذرة الثانية ذرة هيدروجين مع أنها ترتبط بأربع ذرات كربون","عدّ ذرة الكربون الرابعة CH₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-07T17:19:00.563Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
