insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L2-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا تُسمّى سلسلة المركبات التي يختلف كل مركب فيها عن المركب الذي يليه في عدد الوحدة المتكررة –CH₂–؟', null, null, '["السلسلة الرئيسة","المجموعة البديلة","السلسلة المتماثلة","الهيدروكربونات الحلقية"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 127–128 — السلسلة المتماثلة والوحدة المتكررة'),
('mcq', 2, 'ما الوحدة المتكررة في سلسلة الألكانات؟', null, null, '["–CH₂–","–CH₃","–CH–","CH₄"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 127–128 — السلسلة المتماثلة والوحدة المتكررة'),
('mcq', 3, 'صيغة الأوكتان C₈H₁₈ وصيغة الديكان C₁₀H₂₂، وهما عضوان في سلسلة الألكانات المتماثلة. بماذا تزيد الصيغة الجزيئية للديكان على الصيغة الجزيئية للأوكتان؟', null, null, '["بوحدة –CH₂– واحدة","بمجموعتي ميثيل، أي C₂H₆","بذرتي كربون فقط، أي C₂","بوحدتي –CH₂–، أي C₂H₄"]'::jsonb, 'فهم', 'مقارنة صيغ', 'متوسط', 'الكتاب ص 127 — الجدول 4-2 والوحدة المتكررة'),
('mcq', 4, 'أيّ المجموعات الآتية تمثل ثلاثة مركبات متتالية في سلسلة متماثلة واحدة؟', null, null, '["CH₄، C₂H₄، C₂H₂","CH₄، C₂H₆، C₃H₈","C₂H₆، C₃H₆، C₄H₆","C₃H₈، C₅H₁₂، C₇H₁₆"]'::jsonb, 'فهم', 'تمييز', 'صعب', 'الكتاب ص 127–128 — السلسلة المتماثلة والوحدة المتكررة'),
('mcq', 5, 'جاءت كلمة «متماثل» Homologous من الكلمة الإغريقية homologos. ما معنى هذه الكلمة؟', null, null, '["مُتّفِق","مُتفرّع","مُشبَع","مُتكرِّر"]'::jsonb, 'تذكر', 'أصل مصطلح', 'سهل', 'الكتاب ص 128 — أصل الكلمة (متماثل)'),
('mcq', 6, 'أيّ العبارات الآتية تصف خاصية مشتركة لمركبات أي سلسلة متماثلة؟', null, null, '["لها جميعًا الصيغة الجزيئية نفسها","تختلف فيما بينها في عدد ذرات الهيدروجين فقط","تحتوي جميعها على العدد نفسه من ذرات الكربون","تربط بين أعداد ذراتها صيغة عامة ثابتة"]'::jsonb, 'فهم', 'خاصية مفهوم', 'متوسط', 'الكتاب ص 127–128 — السلسلة المتماثلة والوحدة المتكررة'),
('mcq', 7, 'أيّ المركبات الآتية لا ينتمي إلى السلسلة المتماثلة التي ينتمي إليها الميثان CH₄؟', null, null, '["C₄H₁₀","C₄H₈","C₆H₁₄","C₉H₂₀"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 127–128 — السلسلة المتماثلة والصيغة العامة'),
('essay', 1, 'عرّف السلسلة المتماثلة، وحدّد الوحدة المتكررة في سلسلة الألكانات. ثم اكتب الصيغتين البنائيتين المكثفتين للهكسان والهبتان بحيث تُكتب وحدات –CH₂– بين قوسين يتبعهما رقم سفلي، ووضّح كيف تُظهر الصيغتان معنى السلسلة المتماثلة.', null, null, null, 'فهم', 'تعريف وتوضيح بمثال', 'سهل', 'الكتاب ص 127–128 — الجدول 4-2 والسلسلة المتماثلة'),
('essay', 2, 'يبين الشكل الآتي الصيغ البنائية لأول ثلاثة مركبات بعد الميثان في سلسلة الألكانات. (أ) ما الذي يزيده كل مركب على المركب الذي قبله؟ (ب) كم وحدة –CH₂– في جزيء البيوتان؟ (ج) اكتب الصيغ الجزيئية للمركبات الثلاثة، وبيّن أنها تحقق صيغة عامة واحدة. (د) اكتب الصيغة الجزيئية للمركب الرابع بعد البيوتان في السلسلة نفسها.', null, '[{"src":"qimg/chem22/c4-l2b-c2c3c4.svg","alt":"ثلاث صيغ بنائية كاملة متجاورة، من اليسار إلى اليمين: (أ) إيثان: ذرتا كربون متصلتان برابطة أحادية، وترتبط كل ذرة كربون بثلاث ذرات هيدروجين. (ب) بروبان: ثلاث ذرات كربون في سلسلة أفقية، ترتبط كل من الذرتين الطرفيتين بثلاث ذرات هيدروجين، وترتبط الذرة الوسطى بذرتي هيدروجين (أعلى وأسفل). (ج) بيوتان: أربع ذرات كربون في سلسلة أفقية، ترتبط كل من الذرتين الطرفيتين بثلاث ذرات هيدروجين، وترتبط كل من الذرتين الوسطيين بذرتي هيدروجين (أعلى وأسفل). جميع الروابط أحادية."}]'::jsonb, null, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 126–128 — الجدول 4-1 والسلسلة المتماثلة'),
('essay', 3, 'الكتلة المولية للبروبان C₃H₈ تساوي 44.09 g/mol. (أ) احسب الكتلة المولية للوحدة المتكررة –CH₂–. (ب) استخدمها لتوقع الكتلتين الموليتين للبيوتان والبنتان دون كتابة صيغتيهما. (ج) تحقق من قيمة البنتان بحسابها من صيغته الجزيئية. (د) فسّر لماذا يكون الفرق في الكتلة المولية بين أي ألكانين متتاليين ثابتًا. (H = 1.008، C = 12.01)', null, null, null, 'تحليل', 'مسألة حسابية وتفسير', 'صعب', 'الكتاب ص 127–128 و159 — السلسلة المتماثلة والسؤال 48')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
