insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'السلسلة المتماثلة هي سلسلة المركبات التي يختلف بعضها عن بعض في عدد الوحدة المتكررة، ولها صيغة عامة ثابتة؛ والألكانات مثال عليها ووحدتها المتكررة –CH₂–.', '["السلسلة الرئيسة هي أطول سلسلة كربونية متصلة في جزيء ألكان متفرع، وليست مجموعة من المركبات.","المجموعة البديلة تفرع جانبي في الجزيء يحل محل ذرة هيدروجين، وليست سلسلة مركبات.","","الهيدروكربونات الحلقية مركبات تحتوي على حلقة كربونية، ولا يدل الاسم على الاختلاف بوحدة متكررة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('mcq', 2, 0, 'يزيد كل ألكان في السلسلة على الذي قبله بوحدة واحدة –CH₂– (ذرة كربون وذرتا هيدروجين)؛ فهي الوحدة المتكررة، فمثلًا يزيد البنتان على البيوتان بوحدة –CH₂– واحدة.', '["","–CH₃ مجموعة طرفية في السلسلة (ومجموعة الميثيل)، ولا تتكرر بين المركبات المتتالية.","–CH– ذرة كربون بذرة هيدروجين واحدة تظهر عند التفرع، ولا يزيد بها ألكان على الذي قبله.","CH₄ جزيء الميثان نفسه، وهو أول السلسلة لا وحدتها المتكررة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('mcq', 3, 3, 'الفرق بين الصيغتين C₁₀H₂₂ − C₈H₁₈ = C₂H₄، وهو يساوي وحدتين متكررتين –CH₂–؛ لأن بين الأوكتان والديكان في السلسلة مركبًا واحدًا هو النونان C₉H₂₀.', '["وحدة واحدة هي الفرق بين مركبين متتاليين، مثل الأوكتان والنونان؛ أما الديكان فيلي الأوكتان بخطوتين.","الفرق في الهيدروجين 4 ذرات لا 6؛ فالفرق C₂H₄ لا C₂H₆.","أُهمل الفرق في ذرات الهيدروجين؛ فالديكان يزيد أيضًا بأربع ذرات هيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('mcq', 4, 1, 'كل مركب في المجموعة CH₄، C₂H₆، C₃H₈ يزيد على الذي قبله بوحدة –CH₂– واحدة بالضبط، وجميعها تحقق الصيغة العامة CₙH₂ₙ₊₂؛ فهي ثلاثة ألكانات متتالية.', '["المركبات لا تختلف بوحدة –CH₂–؛ فـ C₂H₄ وC₂H₂ تختلفان في عدد ذرات الهيدروجين فقط وليستا ألكانين.","","المركبات تختلف بذرة كربون واحدة دون ذرتي هيدروجين، فليس الفرق وحدة –CH₂–.","هذه ألكانات من السلسلة نفسها، لكن كل مركب يزيد على الذي قبله بوحدتين –CH₂–؛ فهي غير متتالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('mcq', 5, 0, 'تعني الكلمة الإغريقية homologos «مُتّفِق»؛ ويناسب ذلك أن أعضاء السلسلة المتماثلة تتفق في صيغة عامة واحدة وتختلف فقط في عدد الوحدة المتكررة.', '["","«متفرّع» وصف للألكانات التي تحتوي على مجموعات بديلة، وليس معنى الكلمة.","«مُشبَع» وصف للهيدروكربونات ذات الروابط الأحادية فقط، وليس معنى الكلمة.","التكرار يصف الوحدة –CH₂– لا معنى الكلمة الإغريقية homologos."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('mcq', 6, 3, 'لكل سلسلة متماثلة صيغة رقمية ثابتة لأعداد الذرات (صيغة عامة)، مثل CₙH₂ₙ₊₂ للألكانات، ويختلف بعض أعضائها عن بعض في عدد الوحدة المتكررة.', '["المركبات التي لها الصيغة الجزيئية نفسها ليست أعضاء سلسلة متماثلة؛ فأعضاء السلسلة تختلف صيغها بوحدات –CH₂–.","الاختلاف في عدد الوحدة المتكررة –CH₂–، أي في الكربون والهيدروجين معًا.","عدد ذرات الكربون يزيد بواحد من مركب إلى الذي يليه، فلا يكون ثابتًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('mcq', 7, 1, 'الميثان أول الألكانات، وصيغتها العامة CₙH₂ₙ₊₂. المركب C₄H₈ يحتوي على 8 ذرات هيدروجين، والألكان ذو الذرات الكربونية الأربع يحتوي على 2(4) + 2 = 10؛ فـ C₄H₈ لا ينتمي إلى سلسلة الألكانات.', '["C₄H₁₀ (البيوتان) يحقق CₙH₂ₙ₊₂: 2(4) + 2 = 10، فهو من السلسلة نفسها.","","C₆H₁₄ (الهكسان) يحقق CₙH₂ₙ₊₂: 2(6) + 2 = 14، فهو من السلسلة نفسها.","C₉H₂₀ (النونان) يحقق CₙH₂ₙ₊₂: 2(9) + 2 = 20، فهو من السلسلة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السلسلة المتماثلة: سلسلة المركبات التي يختلف بعضها عن بعض في عدد الوحدة المتكررة، ولها صيغة رقمية ثابتة لأعداد الذرات (صيغة عامة). الوحدة المتكررة في الألكانات –CH₂–. الهكسان: CH₃(CH₂)₄CH₃، والهبتان: CH₃(CH₂)₅CH₃. تتكون الصيغتان من مجموعتي CH₃ طرفيتين وعدد من وحدات –CH₂– بينهما، ويزيد الهبتان على الهكسان بوحدة –CH₂– واحدة (يزيد الرقم السفلي من 4 إلى 5)، وصيغتاهما الجزيئيتان C₆H₁₄ وC₇H₁₆ تحققان الصيغة العامة نفسها CₙH₂ₙ₊₂.', '["تعريف السلسلة المتماثلة","الوحدة المتكررة –CH₂–","CH₃(CH₂)₄CH₃ وCH₃(CH₂)₅CH₃","الهبتان يزيد بوحدة –CH₂– واحدة والصيغتان تحققان صيغة عامة واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تحديد الوحدة المتكررة","marks":1},{"element":"الصيغتان المكثفتان صحيحتان","marks":1},{"element":"التوضيح بالمقارنة بين الصيغتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، ووحدة متكررة صحيحة، وصيغتان صحيحتان، وتوضيح مرتبط بهما"},{"level":"2–3 درجات","description":"تعريف ووحدة صحيحان مع خطأ في إحدى الصيغتين أو غياب التوضيح"},{"level":"1 درجة","description":"تحديد الوحدة المتكررة أو التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الهكسان CH₃(CH₂)₆CH₃ بعدّ ذرات الكربون كلها داخل القوسين","عدّ –CH₃ وحدة متكررة","تعريف السلسلة المتماثلة بأنها مركبات لها الصيغة الجزيئية نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.564Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يزيد كل مركب على الذي قبله بذرة كربون واحدة وذرتي هيدروجين، أي بوحدة متكررة واحدة –CH₂–. (ب) في البيوتان CH₃CH₂CH₂CH₃ وحدتان –CH₂– بين مجموعتي CH₃ الطرفيتين. (ج) الإيثان C₂H₆، والبروبان C₃H₈، والبيوتان C₄H₁₀؛ وفي كل منها عدد ذرات H = 2n + 2 (2(2) + 2 = 6، 2(3) + 2 = 8، 2(4) + 2 = 10)، فتحقق الصيغة العامة CₙH₂ₙ₊₂. (د) المركب الرابع بعد البيوتان يزيد عليه بأربع وحدات –CH₂–، أي فيه 8 ذرات كربون: C₈H₁₈ (الأوكتان).', '["يزيد كل مركب بوحدة –CH₂– (C وذرتا H)","وحدتا –CH₂– في البيوتان","C₂H₆ وC₃H₈ وC₄H₁₀ تحقق CₙH₂ₙ₊₂","C₈H₁₈"]'::jsonb, '["الفرق بين كل صيغتين متتاليتين: CH₂","البيوتان: CH₃–CH₂–CH₂–CH₃ ← وحدتان","n = 2، 3، 4 ← H = 6، 8، 10","n = 4 + 4 = 8 ← H = 18 ← C₈H₁₈"]'::jsonb, '[{"element":"تحديد الوحدة المتكررة","marks":1},{"element":"عدد وحدات –CH₂– في البيوتان","marks":1},{"element":"الصيغ الجزيئية والتحقق من الصيغة العامة","marks":1},{"element":"الصيغة C₈H₁₈","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة عن الأجزاء الأربعة"},{"level":"2–3 درجات","description":"إجابة صحيحة عن جزأين أو ثلاثة"},{"level":"1 درجة","description":"إجابة صحيحة عن جزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أربع وحدات –CH₂– في البيوتان بعدّ كل ذرات الكربون","كتابة الصيغة C₅H₁₂ للمركب الرابع بعد البيوتان (المركب التالي مباشرة)","القول إن كل مركب يزيد بذرة كربون فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.565Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كتلة –CH₂– = 12.01 + 2(1.008) = 14.03 g/mol. (ب) البيوتان يزيد على البروبان بوحدة واحدة: 44.09 + 14.03 = 58.12 g/mol، والبنتان يزيد بوحدتين: 44.09 + 2(14.03) = 72.15 g/mol. (ج) البنتان C₅H₁₂: 5(12.01) + 12(1.008) = 60.05 + 12.10 = 72.15 g/mol، وهي مطابقة للتوقع. (د) لأن الألكانات سلسلة متماثلة، يزيد كل مركب فيها على الذي قبله بوحدة متكررة واحدة –CH₂– بالضبط، فيكون الفرق في الكتلة المولية دائمًا كتلة هذه الوحدة (14.03 g/mol).', '["كتلة –CH₂– = 14.03 g/mol","البيوتان 58.12 g/mol والبنتان 72.15 g/mol","التحقق: C₅H₁₂ = 72.15 g/mol","التفسير: الفرق بين المتتاليين وحدة –CH₂– واحدة دائمًا"]'::jsonb, '["M(CH₂) = 12.01 + 2 × 1.008 = 14.026 ≈ 14.03 g/mol","M(بيوتان) = 44.09 + 14.03 = 58.12 g/mol","M(بنتان) = 44.09 + 2 × 14.03 = 72.15 g/mol","تحقق: 5 × 12.01 + 12 × 1.008 = 72.146 ≈ 72.15 g/mol"]'::jsonb, '[{"element":"حساب كتلة –CH₂–","marks":1},{"element":"توقع كتلتي البيوتان والبنتان","marks":1},{"element":"التحقق من كتلة البنتان","marks":1},{"element":"تفسير ثبات الفرق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة كاملة مع تفسير مرتبط بالوحدة المتكررة"},{"level":"2–3 درجات","description":"حساب كتلة الوحدة والتوقع صحيحان مع نقص في التحقق أو التفسير"},{"level":"1 درجة","description":"حساب كتلة –CH₂– فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب كتلة –CH₂– بذرة هيدروجين واحدة (13.02 g/mol)","إضافة كتلة وحدة واحدة فقط للوصول إلى البنتان","تفسير الفرق بزيادة ذرة كربون فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-07T17:19:00.565Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
