('mcq', 2, 'لماذا تُسمّى التفرعات الجانبية المتصلة بالسلسلة الرئيسة في الألكان المتفرع «مجموعات بديلة»؟', null, null, '["لأنها تُستبدل بذرات كربون عند تكسير الألكان","لأنها تحل محل السلسلة الرئيسة عند الترقيم","لأنها بديل عن الروابط الثنائية في الجزيء","لأنها تظهر كأنها بديلة لذرة هيدروجين في السلسلة المستقيمة"]'::jsonb, 'تذكر', 'تعليل تسمية', 'متوسط', 'الكتاب ص 129 — السلسلة الرئيسة والمجموعات البديلة والجدول 4-3'),
('mcq', 3, 'ما الصيغة البنائية المكثفة لمجموعة الإيثيل؟', null, null, '["CH₃CH₃","CH₃CH₂–","CH₃–","CH₃CH₂CH₂–"]'::jsonb, 'تذكر', 'صيغة مجموعة', 'سهل', 'الكتاب ص 129 — السلسلة الرئيسة والمجموعات البديلة والجدول 4-3'),
('mcq', 4, 'يبين الشكل الآتي الصيغ البنائية لأربع مجموعات ألكيل، والخط الذي لا ينتهي بذرة هو موضع اتصال المجموعة بالسلسلة الرئيسة. أيّها مجموعة الأيزوبروبيل؟', null, '[{"src":"qimg/chem22/c4-l2b-alkyl-four.svg","alt":"أربع صيغ بنائية كاملة لمجموعات ألكيل، مرتبة من اليمين إلى اليسار، وكل منها ذرات كربون في عمود رأسي متصلة بروابط أحادية، ولها رابطة حرة واحدة تتجه إلى اليمين ولا تنتهي بذرة. (أ) ثلاث ذرات كربون: العليا ترتبط بثلاث ذرات H، والوسطى بذرتي H (يمينها ويسارها)، والسفلى بذرتي H (يسارها وأسفلها) ومنها الرابطة الحرة. (ب) أربع ذرات كربون: العليا بثلاث ذرات H، والثانية والثالثة كل منهما بذرتي H، والسفلى بذرتي H (يسارها وأسفلها) ومنها الرابطة الحرة. (ج) ثلاث ذرات كربون: العليا بثلاث ذرات H، والسفلى بثلاث ذرات H، والوسطى بذرة H واحدة (يسارها) ومنها الرابطة الحرة. (د) ذرتا كربون: العليا بثلاث ذرات H، والسفلى بذرتي H (يسارها وأسفلها) ومنها الرابطة الحرة."}]'::jsonb, '["المجموعة (أ)","المجموعة (ب)","المجموعة (ج)","المجموعة (د)"]'::jsonb, 'فهم', 'تمييز من شكل', 'متوسط', 'الكتاب ص 129 — الجدول 4-3 الألكيلات البسيطة'),
('mcq', 5, 'كيف يُشتق اسم مجموعة الألكيل من اسم الألكان الذي يحتوي على عدد ذرات الكربون نفسه؟', null, null, '["بإضافة البادئة «حلقي» إلى اسم الألكان","بإضافة البادئة «ثنائي» قبل اسم الألكان","بتغيير المقطع الأخير «ين» إلى «ان»","بتغيير المقطع الأخير «ان» إلى «يل»"]'::jsonb, 'تذكر', 'قاعدة تسمية', 'سهل', 'الكتاب ص 129 — السلسلة الرئيسة والمجموعات البديلة والجدول 4-3'),
('mcq', 6, 'في الألكان الممثل بالصيغة البنائية المكثفة الآتية، كم ذرة كربون في السلسلة الرئيسة، وما المجموعات البديلة المتصلة بها؟', null, '[{"src":"qimg/chem22/c4-l2b-bent-24dmhep.svg","alt":"صيغة بنائية مكثفة: سلسلة أفقية من اليسار إلى اليمين: CH₃ ثم CH ثم CH₂ ثم CH ثم CH₃، متصلة بروابط أحادية. ترتبط المجموعة CH الثانية من اليسار بسلسلة رأسية تتجه إلى الأعلى مكونة من CH₂ ثم CH₂ ثم CH₃. وترتبط المجموعة CH الرابعة من اليسار بمجموعة CH₃ تحتها."}]'::jsonb, '["7 ذرات، ومجموعتا ميثيل","5 ذرات، ومجموعتا بروبيل وميثيل","6 ذرات، ومجموعتا إيثيل وميثيل","8 ذرات، ومجموعة ميثيل واحدة"]'::jsonb, 'فهم', 'تحديد السلسلة الرئيسة', 'صعب', 'الكتاب ص 129–130 — السلسلة الرئيسة والخطوة 1'),
('mcq', 7, 'ما اسم مجموعة الألكيل المشتقة من الأوكتان، وما صيغتها البنائية المكثفة؟', null, null, '["أوكتان، وصيغتها CH₃(CH₂)₆CH₃","أوكتيل، وصيغتها CH₃(CH₂)₆CH₂–","أوكتيل، وصيغتها CH₃(CH₂)₆CH₃","هبتيل، وصيغتها CH₃(CH₂)₅CH₂–"]'::jsonb, 'فهم', 'تطبيق قاعدة تسمية', 'متوسط', 'الكتاب ص 129 و159 — مجموعات الألكيل والسؤال 52'),
('essay', 1, 'عرّف كلًّا من السلسلة الرئيسة والمجموعة البديلة، ثم اكتب اسم مجموعة الألكيل المشتقة من كل من الميثان والإيثان والبيوتان مع صيغتها البنائية المكثفة، مبينًا القاعدة التي اتبعتها في التسمية.', null, null, null, 'تذكر', 'تعريف وتطبيق', 'سهل', 'الكتاب ص 129 و159 — الجدول 4-3 والسؤال 52'),
('essay', 2, 'تمثل الصيغة البنائية المكثفة الآتية ألكانًا متفرعًا. (أ) حدّد السلسلة الرئيسة، وعدد ذرات الكربون فيها، واسم الألكان المقابل لها. (ب) حدّد كل مجموعة بديلة: اسمها، والألكان الذي اشتُقت منه، وموقعها على السلسلة الرئيسة بعد الترقيم الصحيح. (ج) اكتب الاسم النظامي للمركب.', null, '[{"src":"qimg/chem22/c4-l2b-4ip2mhep.svg","alt":"صيغة بنائية مكثفة: سلسلة أفقية من اليسار إلى اليمين: CH₃ ثم CH ثم CH₂ ثم CH ثم CH₂ ثم CH₂ ثم CH₃، متصلة بروابط أحادية. ترتبط المجموعة CH الثانية من اليسار بمجموعة CH₃ تحتها. وترتبط المجموعة CH الرابعة من اليسار برابطة رأسية إلى الأعلى بمجموعة CH، وهذه المجموعة ترتبط بمجموعتي CH₃ إحداهما على يسارها والأخرى على يمينها."}]'::jsonb, null, 'فهم', 'تحليل صيغة', 'متوسط', 'الكتاب ص 129–131 و135 — المجموعات البديلة وخطوات التسمية والسؤال 15b'),
('essay', 3, 'تُشتق كل من مجموعتي البروبيل CH₃CH₂CH₂– والأيزوبروبيل CH₃CHCH₃ من البروبان. (أ) قارن بين المجموعتين من حيث عدد ذرات الكربون، وذرة الكربون التي تتصل بها المجموعة بالسلسلة الرئيسة. (ب) ارسم (صف) الصيغة البنائية للمركب الناتج عند اتصال كل مجموعة بذرة الكربون الثانية في البروبان بدل إحدى ذرتي الهيدروجين عليها، ثم بيّن ماذا تصبح السلسلة الرئيسة في كل حالة. (ج) فسّر لماذا لا تُسمى المجموعة البديلة «بروبان».', null, null, null, 'تحليل', 'مقارنة وتطبيق', 'صعب', 'الكتاب ص 129–130 — الجدول 4-3 والخطوة 1 في تسمية الألكانات المتفرعة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
