select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يُطلق على أطول سلسلة كربونية متصلة (مستمرة) عند تسمية الألكانات المتفرعة اسم السلسلة الرئيسة، ويُشتق منها الجزء الأخير من اسم المركب.', '["","المجموعة البديلة هي التفرع الجانبي المتصل بالسلسلة الرئيسة، لا السلسلة نفسها.","مجموعة الألكيل مجموعة بديلة مشتقة من ألكان، وهي تفرع لا أطول سلسلة.","السلسلة المتماثلة مجموعة مركبات تختلف بوحدة –CH₂–، لا جزء من جزيء واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-07T17:19:00.565Z"}'::jsonb),
('mcq', 2, 3, 'تُسمّى التفرعات الجانبية مجموعات بديلة لأنها تظهر كأنها بديلة لذرة الهيدروجين في السلسلة المستقيمة (غير المتفرعة)، فكل مجموعة بديلة تشغل موقعًا كانت تشغله ذرة H.', '["لا علاقة للتسمية بالتكسير؛ فالمجموعة البديلة تحل محل ذرة هيدروجين لا ذرة كربون.","السلسلة الرئيسة تبقى أطول سلسلة متصلة، والمجموعات البديلة لا تحل محلها.","الألكانات لا تحتوي على روابط ثنائية أصلًا؛ وكل روابطها أحادية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.565Z"}'::jsonb),
('mcq', 3, 1, 'تُشتق مجموعة الإيثيل من الإيثان CH₃CH₃ بنزع ذرة هيدروجين من إحدى ذرتي الكربون، فتصبح CH₃CH₂– ولها رابطة حرة تتصل بها بالسلسلة الرئيسة.', '["هذه صيغة الإيثان نفسه، وليس فيها رابطة حرة للاتصال بالسلسلة.","","هذه مجموعة الميثيل المشتقة من الميثان، وفيها ذرة كربون واحدة.","هذه مجموعة البروبيل، وفيها ثلاث ذرات كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.565Z"}'::jsonb),
('mcq', 4, 2, 'الأيزوبروبيل مشتقة من البروبان (3 ذرات كربون)، وتتصل بالسلسلة عن طريق ذرة الكربون الوسطى (CH₃CHCH₃)؛ وهذا ما تُظهره المجموعة (ج)، إذ تخرج الرابطة الحرة من الذرة الوسطى، وتحمل كل من الذرتين الطرفيتين ثلاث ذرات هيدروجين.', '["المجموعة (أ) فيها 3 ذرات كربون لكن الرابطة الحرة تخرج من ذرة طرفية، فهي البروبيل CH₃CH₂CH₂–.","المجموعة (ب) فيها 4 ذرات كربون متصلة في سلسلة والرابطة الحرة من الطرف، فهي البيوتيل.","","المجموعة (د) فيها ذرتا كربون فقط، فهي الإيثيل CH₃CH₂–."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb),
('mcq', 5, 3, 'يُنسب اسم المجموعة البديلة المشتقة من الألكان إلى اسم الألكان الذي يحتوي على عدد ذرات الكربون نفسه، مع تغيير المقطع الأخير «ان» إلى «يل»؛ فالميثان يعطي الميثيل، والبروبان يعطي البروبيل.', '["«حلقي» تُضاف لاسم الهيدروكربون الذي يحتوي على حلقة، لا لاسم مجموعة الألكيل.","«ثنائي» بادئة تدل على تكرار المجموعة نفسها مرتين في الجزيء.","الألكانات تنتهي أسماؤها بـ«ان» أصلًا، ولا يُشتق الألكيل بهذا التغيير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb),
('mcq', 6, 0, 'أطول سلسلة متصلة تبدأ من CH₃ في الفرع العلوي (3 ذرات) ثم ذرة CH الثانية، ثم CH₂، ثم CH الرابعة، ثم CH₃ في الطرف الأيمن (أو تحتها): 3 + 1 + 1 + 1 + 1 = 7 ذرات (هبتان). تبقى خارجها مجموعة CH₃ اليسرى المتصلة بذرة CH الثانية، ومجموعة CH₃ الأخرى المتصلة بذرة CH الرابعة؛ فهما مجموعتا ميثيل.', '["","عُدّت السلسلة الأفقية (5 ذرات) سلسلة رئيسة، مع أن السلسلة المارة بالفرع العلوي أطول.","لا توجد سلسلة متصلة من 6 ذرات هي الأطول؛ فالسلسلة المارة بالفرع العلوي فيها 7 ذرات.","لا يمكن أن تمر سلسلة متصلة بالطرفين الأيسر والأيمن وبالفرع العلوي معًا؛ فأطول سلسلة 7 ذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb),
('mcq', 7, 1, 'يتغير المقطع الأخير «ان» في الأوكتان إلى «يل» فتصبح المجموعة أوكتيل، وتُشتق بنزع ذرة هيدروجين من ذرة كربون طرفية في الأوكتان CH₃(CH₂)₆CH₃، فتصبح CH₃(CH₂)₆CH₂– بثماني ذرات كربون ورابطة حرة.', '["هذا اسم الألكان وصيغته، لا المجموعة البديلة المشتقة منه.","","الاسم صحيح لكن الصيغة صيغة الأوكتان نفسه؛ فلا رابطة حرة فيها ولم تُنزع ذرة الهيدروجين.","هذه مجموعة فيها 7 ذرات كربون مشتقة من الهبتان، لا من الأوكتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السلسلة الرئيسة: أطول سلسلة كربونية متصلة (مستمرة) في جزيء الألكان المتفرع. المجموعة البديلة: تفرع جانبي يتصل بالسلسلة الرئيسة، ويظهر كأنه بديل لذرة هيدروجين في السلسلة المستقيمة. الميثان CH₄ ← ميثيل CH₃–؛ الإيثان CH₃CH₃ ← إيثيل CH₃CH₂–؛ البيوتان CH₃CH₂CH₂CH₃ ← بيوتيل CH₃CH₂CH₂CH₂–. القاعدة: يُنسب اسم المجموعة إلى الألكان الذي يحتوي على عدد ذرات الكربون نفسه، ويتغير المقطع الأخير «ان» إلى «يل»، وتُنزع من الألكان ذرة هيدروجين فتبقى رابطة حرة يتصل بها بالسلسلة.', '["تعريف السلسلة الرئيسة","تعريف المجموعة البديلة","ميثيل CH₃– وإيثيل CH₃CH₂– وبيوتيل CH₃CH₂CH₂CH₂–","قاعدة «ان» ← «يل» ونزع ذرة H"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف السلسلة الرئيسة","marks":1},{"element":"تعريف المجموعة البديلة","marks":1},{"element":"الأسماء والصيغ الثلاث","marks":1},{"element":"قاعدة التسمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان، وثلاث مجموعات بأسمائها وصيغها، وقاعدة صحيحة"},{"level":"2–3 درجات","description":"تعريفان صحيحان مع خطأ في بعض الصيغ أو غياب القاعدة"},{"level":"1 درجة","description":"تعريف واحد أو أسماء المجموعات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة صيغة الألكان بدل صيغة المجموعة (CH₄ بدل CH₃–)","تعريف السلسلة الرئيسة بأنها السلسلة الأفقية في الرسم","تسمية مجموعة البيوتان «بيوتان» أو «بيوتين»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السلسلة الرئيسة هي السلسلة الأفقية: 7 ذرات كربون، والألكان المقابل الهبتان؛ ولا توجد سلسلة أطول، فالسلسلة المارة بالتفرع العلوي فيها 6 ذرات فقط. (ب) المجموعة CH₃ المتصلة بذرة CH الثانية من اليسار: ميثيل مشتقة من الميثان. المجموعة العلوية CH(CH₃)₂ المتصلة بذرة CH الرابعة: أيزوبروبيل مشتقة من البروبان، وتتصل بالسلسلة عن طريق ذرة الكربون الوسطى. الترقيم من اليسار يعطي الموقعين 2 و4، ومن اليمين 4 و6؛ فالترقيم الصحيح من اليسار: الميثيل على الذرة 2 والأيزوبروبيل على الذرة 4. (ج) 4-أيزوبروبيل-2-ميثيل هبتان.', '["السلسلة الرئيسة 7 ذرات: هبتان","ميثيل من الميثان على الذرة 2","أيزوبروبيل من البروبان متصلة بذرتها الوسطى على الذرة 4","الاسم: 4-أيزوبروبيل-2-ميثيل هبتان"]'::jsonb, '["عدّ السلسلة الأفقية: 7 ذرات","السلسلة المارة بالأيزوبروبيل: 2 + 1 + 3 = 6 ذرات فقط","الترقيم: من اليسار (2، 4) ومن اليمين (4، 6) ← نختار (2، 4)","الترتيب الهجائي: أيزوبروبيل (i) قبل ميثيل (m)"]'::jsonb, '[{"element":"تحديد السلسلة الرئيسة وعددها واسمها","marks":1},{"element":"تسمية المجموعتين البديلتين ومصدرهما","marks":1},{"element":"الموقعان الصحيحان","marks":1},{"element":"الاسم النظامي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح للسلسلة والمجموعات ومواقعها واسم صحيح"},{"level":"2–3 درجات","description":"تحديد السلسلة والمجموعات صحيح مع خطأ في المواقع أو الاسم"},{"level":"1 درجة","description":"تحديد السلسلة الرئيسة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية المجموعة العلوية بروبيل","الترقيم من اليمين فتكون المواقع 4 و6","عدّ مجموعات CH₃ في الأيزوبروبيل مجموعتي ميثيل منفصلتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كلتاهما فيها 3 ذرات كربون ومشتقة من البروبان. في البروبيل تتصل المجموعة بالسلسلة عن طريق ذرة كربون طرفية (CH₂)، أما في الأيزوبروبيل فتتصل عن طريق ذرة الكربون الوسطى (CH) المرتبطة بمجموعتي CH₃. (ب) البروبيل على الذرة الثانية في البروبان: CH₃CH(CH₂CH₂CH₃)CH₃؛ أطول سلسلة متصلة تمر بالبروبيل: 3 + 1 + 1 = 5 ذرات، فتبقى مجموعة ميثيل واحدة، والسلسلة الرئيسة بنتان (المركب 2-ميثيل بنتان). الأيزوبروبيل على الذرة الثانية: CH₃CH(CH(CH₃)₂)CH₃؛ أطول سلسلة 4 ذرات، فالسلسلة الرئيسة بيوتان ويبقى تفرعان من الميثيل (المركب 2، 3-ثنائي ميثيل بيوتان). أي إن السلسلة الرئيسة هي دائمًا أطول سلسلة متصلة، وقد تدخل فيها ذرات من المجموعة المضافة. (ج) لأن المجموعة البديلة ليست جزيئًا مستقلًا، بل جزء من ألكان نُزعت منه ذرة هيدروجين، فيتغير المقطع «ان» إلى «يل».', '["كلتاهما 3 ذرات كربون","البروبيل يتصل بذرة طرفية والأيزوبروبيل بالذرة الوسطى","البروبيل يطيل السلسلة إلى بنتان، والأيزوبروبيل يعطي سلسلة بيوتان بفرعي ميثيل","المجموعة البديلة ألكان نُزعت منه ذرة H فتنتهي بـ«يل»"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة بين المجموعتين","marks":1},{"element":"صيغة المركب الأول وسلسلته الرئيسة","marks":1},{"element":"صيغة المركب الثاني وسلسلته الرئيسة","marks":1},{"element":"تفسير تسمية «يل»","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة، وصيغتان مع تحديد صحيح للسلسلتين، وتفسير صحيح"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع خطأ في تحديد إحدى السلسلتين أو غياب التفسير"},{"level":"1 درجة","description":"المقارنة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأيزوبروبيل فيه 4 ذرات كربون لوجود الكلمة «أيزو»","عدّ البروبان سلسلة رئيسة بعد إضافة البروبيل","إغفال أن المجموعة تفقد ذرة هيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.566Z"}'::jsonb)
