('essay', 2, 'اكتب الصيغة البنائية الكاملة (بإظهار جميع ذرات الهيدروجين وجميع الروابط) للمركب 2، 3-ثنائي ميثيل بنتان، ثم اكتب صيغته البنائية المكثفة وصيغته الجزيئية، وبيّن عدد ذرات الهيدروجين المرتبطة بكل من ذرتي الكربون 2 و3 وسبب ذلك.', null, null, null, 'تطبيق', 'كتابة صيغة كاملة', 'سهل', 'الكتاب ص 160 — السؤال 56c'),
('essay', 3, '(أ) اكتب الصيغة البنائية المكثفة للمركب 2، 3-ثنائي ميثيل-5-بروبيل ديكان، ثم اكتب صيغته الجزيئية. (ب) يخشى طالب أن تُطيل مجموعة البروبيل السلسلة الرئيسة فيصبح الاسم خاطئًا. عُدّ ذرات أطول سلسلة تمر بمجموعة البروبيل، وبيّن هل مخاوفه في محلها.', null, null, null, 'تحليل', 'كتابة صيغة وتحقق', 'صعب', 'الكتاب ص 131 — مسألة 9a')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
