from (values
('mcq', 1, 2, 'الهبتان سلسلة رئيسة من 7 ذرات كربون، وتتصل مجموعتا الميثيل بذرتي الكربون 3 و4. الصيغة (ج) سلسلتها الأفقية 7 ذرات، ومجموعتا CH₃ على الذرتين الثالثة والرابعة من اليسار؛ فهي 3، 4-ثنائي ميثيل هبتان.', '["السلسلة 7 ذرات، لكن مجموعتي الميثيل على الذرتين 2 و3؛ فهي 2، 3-ثنائي ميثيل هبتان.","الموقعان 3 و4 صحيحان، لكن السلسلة الرئيسة 6 ذرات (هكسان) لا 7.","","السلسلة 7 ذرات، لكن مجموعتي الميثيل على الذرتين 3 و5؛ فهي 3، 5-ثنائي ميثيل هبتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.567Z"}'::jsonb),
('mcq', 2, 0, 'البروبان سلسلة من 3 ذرات كربون، وتتصل مجموعتا الميثيل كلتاهما بذرة الكربون 2 (الوسطى)، فتصبح هذه الذرة مرتبطة بأربع ذرات كربون دون هيدروجين: CH₃C(CH₃)₂CH₃.', '["","هذه صيغة 2-ميثيل بيوتان: فيها مجموعة ميثيل واحدة على سلسلة من 4 ذرات.","هذه صيغة 2، 3-ثنائي ميثيل بيوتان: سلسلتها 4 ذرات ومجموعتا الميثيل على ذرتين مختلفتين.","هذه صيغة 2، 2-ثنائي ميثيل بيوتان: سلسلتها الرئيسة 4 ذرات لا 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-07T17:19:00.567Z"}'::jsonb),
('mcq', 3, 1, 'في 2-ميثيل هكسان سلسلة رئيسة من 6 ذرات كربون، وتتصل مجموعة ميثيل بذرة الكربون الثانية. الهيكل (ب) سلسلته 6 ذرات وفرعه على الذرة الثانية من اليسار؛ وأطول سلسلة فيه 6 ذرات فعلًا.', '["الفرع على الذرة الثانية، لكن السلسلة الرئيسة 5 ذرات؛ فهو 2-ميثيل بنتان.","","وُضعت مجموعة الميثيل على الذرة الطرفية، فتصبح جزءًا من سلسلة مستقيمة من 7 ذرات؛ فهو الهبتان لا 2-ميثيل هكسان.","السلسلة 6 ذرات لكن الفرع على الذرة الثالثة؛ فهو 3-ميثيل هكسان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.567Z"}'::jsonb),
('mcq', 4, 3, 'سلسلة البيوتان 4 ذرات؛ على الذرة 2 مجموعتا ميثيل فتُكتب C دون هيدروجين: C(CH₃)₂، وعلى الذرة 3 مجموعة ميثيل واحدة فتُكتب CH(CH₃)؛ والذرتان الطرفيتان CH₃. فالصيغة CH₃C(CH₃)₂CH(CH₃)CH₃، وصيغتها الجزيئية C₇H₁₆ تحقق CₙH₂ₙ₊₂.', '["كُتبت الذرة 2 بالصيغة CH مع مجموعتي ميثيل، فتصبح لها خمس روابط؛ وذرة الكربون تكوّن أربع روابط فقط.","فيها مجموعتا الميثيل على الذرة 2 فقط، ونقصت مجموعة الميثيل على الذرة 3.","السلسلة الرئيسة فيها 5 ذرات (بنتان) لا 4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-07T17:19:00.567Z"}'::jsonb),
('mcq', 5, 0, 'الرقم 4 قبل «أيزوبروبيل» يعني أن مجموعة الأيزوبروبيل تتصل بذرة الكربون 4، والأيزوبروبيل CH₃CHCH₃ تتصل بالسلسلة عن طريق ذرة الكربون الوسطى، فتُكتب –CH(CH₃)₂. أما الذرة 3 فتحمل مجموعة الميثيل.', '["","هذه مجموعة البروبيل التي تتصل بذرة طرفية، لا الأيزوبروبيل.","مجموعتا ميثيل منفصلتان تُكتبان «4، 4-ثنائي ميثيل»، ولا تمثلان أيزوبروبيل.","الذرة 3 تحمل مجموعة الميثيل، أما الأيزوبروبيل فموقعه الذرة 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.567Z"}'::jsonb),
('mcq', 6, 3, 'الهبتان سلسلة من 7 ذرات: الذرة 2 تحمل ميثيل CH(CH₃)، والذرة 3 تحمل ميثيل CH(CH₃)، والذرة 4 تحمل إيثيل CH(CH₂CH₃)، ثم CH₂CH₂CH₃ تكمل الذرات 5 و6 و7؛ فالصيغة CH₃CH(CH₃)CH(CH₃)CH(CH₂CH₃)CH₂CH₂CH₃ (C₁₁H₂₄).', '["مجموعتا الميثيل كلتاهما على الذرة 2، والذرة 3 بلا تفرع؛ فهي 4-إيثيل-2، 2-ثنائي ميثيل هبتان.","تبادلت المجموعتان موقعيهما: الإيثيل على الذرة 3 والميثيل على الذرة 4.","بعد ذرة الكربون الرابعة ذرتان فقط، فالسلسلة الرئيسة 6 ذرات (هكسان) لا 7.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-07T17:19:00.567Z"}'::jsonb),
('mcq', 7, 1, 'في الرسم مجموعتا الميثيل كلتاهما على ذرة الكربون 2، فهو 2، 2-ثنائي ميثيل بيوتان. والمطلوب ميثيل على الذرة 2 وآخر على الذرة 3؛ فتُنقل إحدى المجموعتين إلى الذرة 3، فتصبح كل من الذرتين 2 و3 مرتبطة بذرة هيدروجين واحدة (CH)، والصيغة CH₃CH(CH₃)CH(CH₃)CH₃.', '["إضافة ذرة كربون تجعل السلسلة الرئيسة بنتان، والمطلوب بيوتان.","","نقل المجموعتين معًا إلى الذرة 3 يعطي المركب نفسه (2، 2-ثنائي ميثيل بيوتان) مرقمًا من الطرف الآخر.","حذف مجموعة يعطي 2-ميثيل بيوتان، والاسم يتطلب مجموعتي ميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.568Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السلسلة الرئيسة أوكتان: 8 ذرات كربون تُرقم من 1 إلى 8. تتصل مجموعة إيثيل (–CH₂CH₃) بكل من الذرات 3 و4 و5 (البادئة «ثلاثي» تعني ثلاث مجموعات). بعد إكمال الهيدروجين حتى تكوّن كل ذرة كربون أربع روابط: الذرتان 1 و8 CH₃، والذرات 2 و6 و7 CH₂، والذرات 3 و4 و5 CH. الصيغة: CH₃CH₂CH(CH₂CH₃)CH(CH₂CH₃)CH(CH₂CH₃)CH₂CH₂CH₃. عدد ذرات الكربون 8 + 3 × 2 = 14، فالصيغة الجزيئية C₁₄H₃₀؛ وبالصيغة العامة 2(14) + 2 = 30 ✓.', '["سلسلة رئيسة من 8 ذرات","ثلاث مجموعات إيثيل على الذرات 3 و4 و5","CH₃CH₂CH(CH₂CH₃)CH(CH₂CH₃)CH(CH₂CH₃)CH₂CH₂CH₃","C₁₄H₃₀ وتحقق 2(14) + 2 = 30"]'::jsonb, '["ارسم 8 ذرات كربون ورقمها","أضف –CH₂CH₃ على 3 و4 و5","أكمل H: CH₃ في الطرفين، وCH للذرات 3–5، وCH₂ للباقي","C = 8 + 6 = 14 ← H = 30 ← C₁₄H₃₀"]'::jsonb, '[{"element":"السلسلة الرئيسة والترقيم","marks":1},{"element":"المجموعات الثلاث في مواقعها","marks":1},{"element":"الصيغة المكثفة بذرات H صحيحة","marks":1},{"element":"الصيغة الجزيئية والتحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"صيغة مكثفة صحيحة بخطوات واضحة وصيغة جزيئية متحقق منها"},{"level":"2–3 درجات","description":"سلسلة ومواقع صحيحة مع خطأ في عدد ذرات H أو في الصيغة الجزيئية"},{"level":"1 درجة","description":"تحديد السلسلة الرئيسة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مجموعة إيثيل واحدة فقط وإهمال البادئة «ثلاثي»","كتابة CH₂ للذرات الحاملة للإيثيل فتصبح لها خمس روابط","حساب 8 ذرات كربون فقط في الصيغة الجزيئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.568Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السلسلة الرئيسة بنتان (5 ذرات كربون متصلة بروابط أحادية)، وعلى كل من الذرتين 2 و3 مجموعة ميثيل. في الصيغة الكاملة: ترتبط الذرة 1 بثلاث ذرات H، والذرة 2 بذرة H واحدة وبمجموعة CH₃ (ذرة كربون بثلاث ذرات H)، والذرة 3 بذرة H واحدة وبمجموعة CH₃، والذرة 4 بذرتي H، والذرة 5 بثلاث ذرات H. الصيغة المكثفة CH₃CH(CH₃)CH(CH₃)CH₂CH₃، والصيغة الجزيئية C₇H₁₆. ترتبط كل من الذرتين 2 و3 بذرة هيدروجين واحدة لأن كلًّا منهما ترتبط بثلاث ذرات كربون (ذرتين في السلسلة وذرة الميثيل)، فلا يبقى لها إلا رابطة واحدة من روابطها الأربع.', '["صيغة كاملة صحيحة بخمس ذرات في السلسلة ومجموعتي ميثيل على 2 و3","CH₃CH(CH₃)CH(CH₃)CH₂CH₃","C₇H₁₆","ذرة H واحدة على كل من الذرتين 2 و3 لأن كلًّا منهما ترتبط بثلاث ذرات كربون"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغة البنائية الكاملة","marks":2},{"element":"الصيغة المكثفة والجزيئية","marks":1},{"element":"عدد ذرات H على الذرتين 2 و3 مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"صيغة كاملة صحيحة، وصيغتان مكثفة وجزيئية صحيحتان، وتعليل صحيح"},{"level":"2–3 درجات","description":"صيغة كاملة صحيحة مع خطأ في الصيغة المكثفة أو غياب التعليل"},{"level":"1 درجة","description":"سلسلة رئيسة صحيحة مع أخطاء في ذرات H"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء الذرتين 2 و3 ذرتي هيدروجين فتصبح لكل منهما خمس روابط","وضع مجموعتي الميثيل على الذرة 2","كتابة الصيغة الجزيئية C₅H₁₂ للسلسلة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.568Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الديكان 10 ذرات كربون؛ على الذرة 2 ميثيل، وعلى الذرة 3 ميثيل، وعلى الذرة 5 بروبيل (–CH₂CH₂CH₃). الصيغة: CH₃CH(CH₃)CH(CH₃)CH₂CH(CH₂CH₂CH₃)CH₂CH₂CH₂CH₂CH₃. عدد ذرات الكربون 10 + 2 + 3 = 15، والصيغة الجزيئية C₁₅H₃₂ (2(15) + 2 = 32). (ب) أطول سلسلة تمر بالبروبيل: 3 ذرات البروبيل + الذرة 5 + الذرات 6 إلى 10 (5 ذرات) = 9 ذرات، أو 3 + الذرات من 5 إلى 1 (5 ذرات) = 8 ذرات؛ وكلاهما أقصر من 10. فالسلسلة الرئيسة تبقى الديكان (10 ذرات)، ومخاوف الطالب ليست في محلها؛ لأن على كل جانب من الذرة 5 أربع ذرات أو أكثر، وهو أكثر من ذرات البروبيل الثلاث.', '["الصيغة المكثفة الصحيحة","C₁₅H₃₂","أطول سلسلة عبر البروبيل 9 ذرات < 10","الديكان يبقى السلسلة الرئيسة والاسم صحيح"]'::jsonb, '["10 + 2 + 3 = 15 ذرة C ← H = 32","عبر البروبيل نحو الذرة 10: 3 + 1 + 5 = 9","عبر البروبيل نحو الذرة 1: 3 + 5 = 8","9 < 10 ← السلسلة الرئيسة ديكان"]'::jsonb, '[{"element":"الصيغة المكثفة","marks":2},{"element":"الصيغة الجزيئية","marks":1},{"element":"عدّ السلاسل المارة بالبروبيل","marks":1},{"element":"الحكم المبرر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"صيغة مكثفة وجزيئية صحيحتان، وعدّ صحيح، وحكم مبرر"},{"level":"3–4 درجات","description":"صيغة مكثفة صحيحة مع خطأ في الصيغة الجزيئية أو في العدّ"},{"level":"1–2 درجة","description":"سلسلة رئيسة ومواقع صحيحة مع أخطاء في ذرات H"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع البروبيل على الذرة 4 أو 6","كتابة الصيغة الجزيئية C₁₀H₂₂ للديكان وحده","الاكتفاء بالقول إن البروبيل قصير دون عدّ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.568Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
