('mcq', 1, 'رقّم طالب السلسلة الرئيسة في المركب الآتي كما تبين الأرقام الحمراء، ثم سمّاه «4-ميثيل هكسان». ما الخطأ في الاسم، وما الاسم الصحيح؟', null, '[{"src":"qimg/chem22/c4-l2b-3mhex-wrongnum.svg","alt":"صيغة بنائية مكثفة: سلسلة أفقية من اليسار إلى اليمين: CH₃ ثم CH₂ ثم CH₂ ثم CH ثم CH₂ ثم CH₃ متصلة بروابط أحادية، وترتبط المجموعة CH (الرابعة من اليسار) بمجموعة CH₃ تحتها. فوق ذرات السلسلة الأفقية أرقام حمراء كتبها الطالب من اليسار إلى اليمين: 1 فوق CH₃ اليسرى، ثم 2 و3، ثم 4 فوق CH، ثم 5، ثم 6 فوق CH₃ اليمنى."}]'::jsonb, '["لم يختر الطالب أطول سلسلة؛ والاسم الصحيح 2-إيثيل بنتان","بدأ الترقيم من الطرف الأبعد عن المجموعة البديلة؛ والاسم الصحيح 3-ميثيل هكسان","السلسلة الرئيسة فيها 7 ذرات؛ والاسم الصحيح هبتان","لا حاجة إلى رقم لوجود مجموعة واحدة؛ والاسم الصحيح ميثيل هكسان"]'::jsonb, 'تحليل', 'تحليل خطأ', 'متوسط', 'الكتاب ص 129–130 — قواعد IUPAC لتسمية الألكانات المتفرعة'),
('mcq', 2, 'رسم طالب ألكانًا وسمّاه «1، 3-ثنائي ميثيل بيوتان». ما الاسم الصحيح وفق نظام IUPAC للمركب الذي رسمه؟', null, null, '["2، 4-ثنائي ميثيل بيوتان","4-ميثيل بنتان","2-ميثيل هكسان","2-ميثيل بنتان"]'::jsonb, 'تحليل', 'تصحيح اسم خاطئ', 'صعب', 'الكتاب ص 129–130 و162 — الخطوتان 1 و2، والسؤال 87'),
