from (values
('mcq', 1, 1, 'أطول سلسلة هي السلسلة الأفقية (6 ذرات) فالسلسلة الرئيسة هكسان. لكن الترقيم يجب أن يبدأ من الطرف الأقرب إلى المجموعة البديلة ليعطيها أصغر رقم ممكن؛ والترقيم من اليمين يضع الميثيل على الذرة 3 بدل 4. فالاسم الصحيح 3-ميثيل هكسان.', '["أطول سلسلة 6 ذرات وقد اختارها الطالب؛ و«2-إيثيل بنتان» نفسه اسم خاطئ لأن الإيثيل على الذرة 2 يطيل السلسلة.","","مجموعة الميثيل متصلة بذرة وسطى لا طرفية، فلا تتكون سلسلة من 7 ذرات.","في الألكانات ذات السلاسل المفتوحة يلزم رقم موقع المجموعة؛ إذ يمكن أن يكون الميثيل على الذرة 2 أو 3 فيختلف المركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.568Z"}'::jsonb),
('mcq', 2, 3, 'مجموعة الميثيل على الذرة 1 تمتد بالسلسلة نفسها، فأطول سلسلة متصلة: CH₃–CH₂–CH₂–CH(CH₃)–CH₃ وفيها 5 ذرات (بنتان)، ويبقى فرع ميثيل واحد. الترقيم من الطرف الأقرب إليه يضعه على الذرة 2؛ فالاسم الصحيح 2-ميثيل بنتان.', '["ما زال الاسم يعدّ البيوتان سلسلة رئيسة، مع أن الميثيل الطرفي يجعل أطول سلسلة 5 ذرات.","السلسلة الرئيسة صحيحة، لكن الترقيم من الطرف الأبعد؛ والرقم الأصغر 2.","المركب فيه 6 ذرات كربون فقط (4 + 2)، فلا يمكن أن يكون اسمه ميثيل هكسان (7 ذرات).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('mcq', 3, 0, 'المجموعات الثلاث على ذرات الكربون 2 و4 و4 عند الترقيم من أحد الطرفين، وعلى 2 و2 و4 عند الترقيم من الطرف الآخر. يُختار الترقيم الذي يعطي المجموعات البديلة أصغر أرقام ممكنة، وعند مقارنة المجموعتين رقمًا برقم يكون أول اختلاف في الرقم الثاني (2 مقابل 4)، فالمجموعة (2، 2، 4) أصغر من (2، 4، 4)؛ فالاسم الصحيح 2، 2، 4-ثلاثي ميثيل بنتان.', '["","المجموعة المتكررة تُجمع في اسم واحد ببادئة «ثلاثي» مع أرقامها كلها، ولا يكرر اسمها.","لا تكون مجموعة ميثيل على الذرة 1؛ لأنها عندئذ جزء من السلسلة الرئيسة.","عدد ذرات السلسلة الرئيسة لا يتغير بتغيير اتجاه الترقيم؛ فهي بنتان لا بيوتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('mcq', 4, 2, 'عند اتصال مجموعات ألكيل مختلفة بالسلسلة الرئيسة تُرتب أسماؤها وفق الترتيب الهجائي باللغة الإنجليزية: إيثيل (Ethyl) قبل ميثيل (Methyl)؛ مع بقاء كل رقم مع مجموعته. فالاسم الصحيح 4-إيثيل-3-ميثيل هبتان.', '["تغيير الأرقام ينقل المجموعتين إلى موقعين آخرين فيتغير المركب؛ والمطلوب تغيير ترتيب الأسماء فقط.","نص السؤال أن السلسلة الرئيسة صحيحة؛ والخطأ في ترتيب أسماء المجموعات.","","البادئات (ثنائي، ثلاثي) تُستخدم لتكرار المجموعة نفسها، والمجموعتان هنا مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('mcq', 5, 1, 'إذا تكررت مجموعة الألكيل نفسها تُكتب مرة واحدة مسبوقة بالبادئة الدالة على عددها (ثنائي)، وتُكتب أرقام مواقعها كلها مفصولة بفواصل؛ فالاسم الصحيح 2، 3-ثنائي ميثيل هكسان.', '["تُكتب أرقام المواقع بترتيب تصاعدي: 2 ثم 3.","","نقصت البادئة «ثنائي» الدالة على وجود مجموعتين.","نقصت أرقام المواقع؛ فلا يتحدد مكان المجموعتين على السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('mcq', 6, 2, 'في «3-ميثيل بنتان» سلسلة رئيسة من 5 ذرات، ومجموعة الميثيل على الذرة الوسطى 3، وهو أصغر رقم ممكن من الطرفين، ولا تطيل المجموعة السلسلة؛ فالاسم صحيح.', '["الميثيل على الذرة 1 يطيل السلسلة إلى 5 ذرات مستقيمة؛ فهو البنتان.","الترقيم من الطرف الأبعد؛ والاسم الصحيح 2-ميثيل بنتان.","","الإيثيل على الذرة 2 يطيل السلسلة إلى 4 ذرات؛ والاسم الصحيح 2-ميثيل بيوتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('mcq', 7, 0, 'أطول سلسلة متصلة تمر بفرع الإيثيل: CH₃ اليسرى ثم CH ثم CH₂ ثم CH ثم CH₂ وCH₃ في الفرع، ففيها 6 ذرات (هكسان). تبقى مجموعتا ميثيل: السفلية على ذرة CH الثانية، واليمنى على ذرة CH الرابعة. الترقيم من الطرف الأيسر يعطي (2، 4) ومن طرف الفرع (3، 5)؛ فالاسم 2، 4-ثنائي ميثيل هكسان.', '["","السلسلة صحيحة لكن الترقيم من الطرف الأبعد؛ و(2، 4) أصغر من (3، 5).","المركب فيه 8 ذرات كربون فقط، وهذا الاسم لمركب فيه 9 ذرات؛ فالإيثيل صار جزءًا من السلسلة الرئيسة.","غُيّر ترتيب المجموعتين دون تصحيح الخطأ الأساسي: السلسلة الرئيسة 6 ذرات لا 5."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السلسلة الرئيسة التي اختارها الطالب صحيحة: السلسلة الأفقية فيها 7 ذرات (هبتان)، والسلاسل المارة بفرع الإيثيل أقصر (6 ذرات). الخطأ في الترقيم: رقّم من الطرف الأيسر فأعطى المجموعتين الموقعين 4 و6، أما الترقيم من الطرف الأيمن (الأقرب إلى مجموعة بديلة) فيعطي الميثيل الموقع 2 والإيثيل الموقع 4، و(2، 4) أصغر من (4، 6). ثم تُرتب المجموعتان هجائيًّا: إيثيل قبل ميثيل. فالاسم الصحيح: 4-إيثيل-2-ميثيل هبتان.', '["السلسلة الرئيسة 7 ذرات صحيحة","الخطأ: الترقيم من الطرف الأبعد","الترقيم الصحيح من اليمين: ميثيل 2 وإيثيل 4","الاسم: 4-إيثيل-2-ميثيل هبتان"]'::jsonb, '["أطول سلسلة: الأفقية 7 ذرات؛ عبر الإيثيل 2 + 1 + 3 = 6 فقط","الترقيم من اليسار: (4، 6)","الترقيم من اليمين: (2، 4) ← الأصغر","الترتيب الهجائي: إيثيل ثم ميثيل"]'::jsonb, '[{"element":"تأكيد صحة السلسلة الرئيسة","marks":1},{"element":"تحديد خطأ الترقيم","marks":1},{"element":"المواقع الصحيحة","marks":1},{"element":"الاسم الصحيح بالترتيب الهجائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ بدقة وكتابة الاسم الصحيح بخطوات كاملة"},{"level":"2–3 درجات","description":"تحديد الخطأ وتصحيح المواقع مع خطأ في ترتيب الاسم أو غياب الخطوات"},{"level":"1 درجة","description":"الإشارة إلى أن الاسم خطأ دون تصحيح صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير السلسلة الرئيسة لتمر بالإيثيل","كتابة 2-ميثيل-4-إيثيل هبتان بترتيب غير هجائي","الاكتفاء بأن الرقم 6 كبير دون تعليل بقاعدة أصغر الأرقام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الاسم يعدّ السلسلة الأفقية (4 ذرات) سلسلة رئيسة، مع أن مجموعة الإيثيل المتصلة بالذرة 2 تكوّن مع ذرات السلسلة سلسلة متصلة أطول؛ فالسلسلة الرئيسة لم تُختر وفق الخطوة الأولى (أطول سلسلة متصلة). (ب) أطول سلسلة: CH₃ اليسرى ثم الذرة الثانية ثم ذرتا الإيثيل = 4 ذرات في اتجاه، أو ذرتا الإيثيل ثم الذرة الثانية ثم الذرتان الثالثة والرابعة = 5 ذرات (بنتان). يبقى خارجها CH₃ اليسرى، فهي مجموعة ميثيل على الذرة 3 من أي طرف. الاسم الصحيح: 3-ميثيل بنتان. (ج) لا تقع مجموعة الإيثيل على الذرة 1 أو 2 من أي طرف؛ لأنها عندئذ تطيل السلسلة الرئيسة، فأقرب موقع ممكن لها الذرة 3.', '["الاسم خطأ لأن السلسلة الرئيسة ليست الأطول","أطول سلسلة 5 ذرات: بنتان","الاسم الصحيح 3-ميثيل بنتان","لا يقع الإيثيل على الذرة 1 أو 2"]'::jsonb, '["السلسلة الأفقية: 4 ذرات","السلسلة عبر الإيثيل: 2 + 1 + 2 = 5 ذرات","الفرع الباقي: CH₃ على الذرة 3","الاسم: 3-ميثيل بنتان"]'::jsonb, '[{"element":"تفسير الخطأ","marks":1},{"element":"تحديد أطول سلسلة","marks":1},{"element":"الاسم الصحيح","marks":1},{"element":"استنتاج القاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح، وسلسلة صحيحة، واسم صحيح، وقاعدة مستنتجة"},{"level":"2–3 درجات","description":"اسم صحيح مع نقص في التفسير أو القاعدة"},{"level":"1 درجة","description":"الإشارة إلى أن السلسلة ليست الأطول فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الاسم إلى 3-إيثيل بيوتان","تصحيح الاسم إلى 2-ميثيل بنتان","عدّ ذرات H ضمن طول السلسلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.569Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الألكان الحلقي الذي تتصل به مجموعة بديلة واحدة لا يحتاج إلى رقم؛ لأن ترقيم الحلقة يبدأ من ذرة الكربون المتصلة بالمجموعة، فتكون دائمًا 1. الاسم الصحيح: ميثيل هكسان حلقي. (ب) الإيثيل على الذرة 2 يطيل السلسلة؛ فأطول سلسلة متصلة: CH₃–C(CH₃)₂–CH₂–CH₃ فيها 4 ذرات (بيوتان) ويبقى عليها مجموعتا ميثيل على الذرة 2؛ الاسم الصحيح: 2، 2-ثنائي ميثيل بيوتان (مخالفة قاعدة أطول سلسلة). (ج) الترقيم بدأ من الطرف الأبعد: المجموعتان على 3 و4، والترقيم من الطرف الآخر يعطي 2 و3 وهما الأصغر؛ الاسم الصحيح: 2، 3-ثنائي ميثيل بنتان (مخالفة قاعدة أصغر الأرقام).', '["(أ) لا رقم مع مجموعة واحدة على الحلقة: ميثيل هكسان حلقي","(ب) مخالفة أطول سلسلة: 2، 2-ثنائي ميثيل بيوتان","(ج) مخالفة أصغر الأرقام: 2، 3-ثنائي ميثيل بنتان"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم الاسم (أ) وتصحيحه","marks":2},{"element":"تقويم الاسم (ب) وتصحيحه","marks":2},{"element":"تقويم الاسم (ج) وتصحيحه","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحديد القاعدة المخالفة وكتابة الاسم الصحيح في الحالات الثلاث"},{"level":"3–5 درجات","description":"تصحيح حالتين صحيحًا أو تصحيح الثلاث مع نقص في ذكر القواعد"},{"level":"1–2 درجة","description":"تصحيح حالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح (أ) إلى 1-ميثيل هكسان حلقي مع الإصرار على الرقم","تصحيح (ب) إلى 2-ميثيل بيوتان بإهمال إحدى المجموعتين","تصحيح (ج) إلى 2، 4-ثنائي ميثيل بنتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.570Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
