('mcq', 1, 'لماذا يُعد جزيء الماء H₂O جزيئًا قطبيًّا؟', null, null, '["لأن كتلته الجزيئية أكبر من كتلة جزيء الميثان","لأنه يحتوي على ذرتي هيدروجين فقط","لأن الرابطة O–H قطبية وللجزيء شكل هندسي منحنٍ","لأنه سائل عند درجة حرارة الغرفة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('mcq', 2, 'يُقارن الكيميائيون بين الماء (18 amu) والميثان (16 amu) لدراسة أثر القطبية في درجة الغليان. لماذا يُعد هذان المركبان مناسبين لهذه المقارنة؟', null, null, '["لتقارب كتلتيهما وحجميهما، فيُعزى الفرق إلى التجاذب بين الجزيئات","لأن كليهما يكوّن روابط هيدروجينية بين جزيئاته","لأن كليهما يوجد غازًا عند درجة حرارة الغرفة","لأن كليهما من الهيدروكربونات المشبعة البسيطة"]'::jsonb, 'فهم', 'تفسير منهج المقارنة', 'متوسط', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('mcq', 3, 'ما نوع التجاذب الموجود بين جزيئات الماء، ولا يوجد بين جزيئات الميثان؟', null, null, '["الروابط التساهمية الأحادية","الروابط الأيونية","التجاذب بين جزيئات غير قطبية","الروابط الهيدروجينية"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('mcq', 4, 'يمثل الشكل الآتي جزيئات من الماء (أ) وجزيئات من الميثان (ب). ماذا تمثل الخطوط الزرقاء المتقطعة بين جزيئات الماء؟', null, '[{"src":"qimg/chem22/c4-l2b-hbond.svg","alt":"رسم جزيئي من قسمين يفصل بينهما خط متقطع رأسي. القسم (أ) الماء، على اليسار: أربعة جزيئات ماء، كل جزيء ذرة أكسجين O (دائرة حمراء) ترتبط بخطين متصلين بذرتي هيدروجين H، والجزيء منحنٍ. الجزيئات الأربعة مرتبة على رؤوس مربع تقريبًا، وتتجه ذرة H من كل جزيء نحو ذرة O في الجزيء المجاور، ويصل بينهما خط أزرق متقطع؛ فهناك أربعة خطوط متقطعة تربط الجزيئات بعضها ببعض. القسم (ب) الميثان، على اليمين: أربعة جزيئات ميثان متباعدة، كل منها ذرة كربون C في الوسط ترتبط بخطوط متصلة بأربع ذرات H، ولا توجد أي خطوط متقطعة بين جزيئات الميثان."}]'::jsonb, '["روابط تساهمية بين ذرتي O وH داخل جزيء الماء الواحد","روابط هيدروجينية تجذب ذرة H في جزيء إلى ذرة O في جزيء آخر","روابط أيونية تنشأ بين جزيئات الماء المشحونة","روابط تساهمية تربط جزيئات الماء في جزيء واحد كبير"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('mcq', 5, 'يبين المخطط الآتي درجتي الغليان والانصهار للماء والميثان. ما الحالة الفيزيائية لكل من الميثان والماء عند −170°C؟', null, '[{"src":"qimg/chem22/c4-l2b-bars.svg","alt":"مخطط أعمدة رأسية لدرجات الحرارة بوحدة °C، ومحوره الرأسي مدرج من −200 إلى 120، وفيه خط أفقي عند الصفر. للماء H₂O عمودان: عمود درجة الغليان (أحمر) يرتفع فوق الصفر حتى 100°C، وعمود درجة الانصهار (أزرق) عند 0°C. للميثان CH₄ عمودان أسفل الصفر: عمود درجة الغليان (أحمر) ينزل حتى −162°C، وعمود درجة الانصهار (أزرق) ينزل حتى −182°C. مفتاح الألوان: الأحمر درجة الغليان، والأزرق درجة الانصهار."}]'::jsonb, '["الميثان سائل، والماء صلب","الميثان غاز، والماء صلب","الميثان صلب، والماء صلب","الميثان سائل، والماء سائل"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('mcq', 6, 'لو افترضنا أن جزيئات الماء غير قطبية ولا تكوّن روابط هيدروجينية، فكيف تتوقع أن تكون درجة غليان الماء؟', null, null, '["أعلى من 100°C لأن كتلته الجزيئية أكبر من كتلة الميثان","تبقى 100°C لأن كتلته الجزيئية لا تتغير","مساوية لدرجة انصهاره 0°C","منخفضة جدًّا وقريبة من درجة غليان الميثان"]'::jsonb, 'تحليل', 'توقع واستنتاج', 'صعب', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('mcq', 7, 'الغليان تغير فيزيائي لا تتغير فيه هوية المادة. عند غليان الميثان السائل، ما الذي يجب التغلب عليه حتى تتحول جزيئاته إلى الحالة الغازية؟', null, null, '["روابط C–H التساهمية داخل جزيئات الميثان","روابط هيدروجينية قوية بين جزيئات الميثان","قوى تجاذب ضعيفة بين جزيئات الميثان غير القطبية","روابط أيونية بين ذرات الكربون والهيدروجين"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 134–135 — الخصائص الفيزيائية للألكانات والجدول 4-4'),
('essay', 1, 'يبين الشكل الآتي الصيغتين البنائيتين للماء والميثان، علمًا بأن درجة غليان الماء 100°C ودرجة غليان الميثان −162°C. قارن بين المادتين من حيث: (أ) قطبية الروابط في الجزيء، (ب) قطبية الجزيء كله، (ج) نوع التجاذب بين الجزيئات وقوته، ثم (د) استخدم المقارنة لتفسير الفرق في درجتي الغليان.', null, '[{"src":"qimg/chem22/c4-l2b-shapes.svg","alt":"صيغتان بنائيتان يفصل بينهما خط متقطع رأسي. على اليسار الماء: ذرة O في الأعلى ترتبط بذرتي H برابطتين أحاديتين تتجه إحداهما إلى أسفل اليسار والأخرى إلى أسفل اليمين، فيظهر الجزيء منحنيًا. على اليمين الميثان: ذرة C في الوسط ترتبط بأربع ذرات H، برابطة أحادية لكل منها (أعلى وأسفل ويمين ويسار)."}]'::jsonb, null, 'فهم', 'مقارنة وتفسير', 'سهل', 'الكتاب ص 134–135 و160 — الخصائص الفيزيائية والسؤال 54'),
('essay', 2, 'ادّعى طالب أن «درجة غليان الميثان أقل كثيرًا من درجة غليان الماء لأن كتلته الجزيئية أصغر». (أ) استخدم بيانات البيوتان والهكسان في الجدول الآتي لتقويم هذا الادعاء. (ب) اكتب التفسير الصحيح للفرق بين درجتي غليان الماء والميثان. (ج) ماذا تُظهر بيانات الألكانات الثلاثة عن العلاقة بين الكتلة الجزيئية ودرجة الغليان، ولماذا لا تصلح هذه العلاقة للمقارنة بين الماء والميثان؟', '{"headers":["المادة","الكتلة الجزيئية","قطبية الجزيء","درجة الغليان"],"rows":[["الماء H₂O","18 amu","قطبي","100°C"],["الميثان CH₄","16 amu","غير قطبي","−162°C"],["البيوتان C₄H₁₀","58 amu","غير قطبي","−0.5°C"],["الهكسان C₆H₁₄","86 amu","غير قطبي","68.7°C"]]}'::jsonb, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 134–135 و159 — الجدول 4-4 والجدول 4-7 درجات غليان الألكانات'),
('essay', 3, 'صف ما يحدث على مستوى الجزيئات عند غليان كل من الماء والميثان، ثم فسّر: (أ) لماذا يحتاج الماء إلى درجة حرارة أعلى بكثير ليغلي؟ (ب) الغليان تغير فيزيائي؛ فهل تتكسر الروابط التساهمية O–H وC–H في أثناء الغليان، أم يُتغلب على شيء آخر؟ علّل. (ج) لماذا تكون درجة انصهار الماء (0°C) أيضًا أعلى بكثير من درجة انصهار الميثان (−182°C)؟', null, null, null, 'فهم', 'وصف وتفسير', 'متوسط', 'الكتاب ص 134–135 و160 — الخصائص الفيزيائية والسؤال 54')
