from (values
('mcq', 1, 2, 'الرابطة O–H في الماء رابطة قطبية، ولأن جزيء H–O–H منحني الشكل لا تلغي قطبية الرابطتين إحداهما الأخرى؛ فيكون الجزيء نفسه قطبيًّا.', '["الكتلة الجزيئية لا تحدد القطبية؛ والكتلتان متقاربتان (18 amu و16 amu).","عدد ذرات الهيدروجين لا يجعل الجزيء قطبيًّا؛ فالقطبية تنتج عن قطبية الروابط وشكل الجزيء.","","الحالة الفيزيائية نتيجة لقوى التجاذب الناتجة عن القطبية، لا سبب لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.570Z"}'::jsonb),
('mcq', 2, 0, 'تقارب الكتلة الجزيئية (16 amu و18 amu) وتقارب حجم الجزيئين يستبعدان أثر الكتلة والحجم، فيبقى الفرق الكبير في درجتي الغليان (−162°C و100°C) دليلًا على اختلاف قوى التجاذب بين الجزيئات الناتج عن القطبية والروابط الهيدروجينية.', '["","جزيئات الميثان غير القطبية لا تكوّن روابط هيدروجينية بينها؛ والماء فقط يكوّنها.","الماء سائل عند درجة حرارة الغرفة، والميثان وحده غاز.","الماء ليس هيدروكربونًا؛ فهو لا يحتوي على كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.570Z"}'::jsonb),
('mcq', 3, 3, 'جزيئات الماء قطبية فتنجذب بعضها إلى بعض وتكوّن روابط هيدروجينية، أما جزيئات الميثان فغير قطبية ولا تكوّن روابط هيدروجينية بينها.', '["الروابط التساهمية الأحادية موجودة داخل الجزيئين معًا (O–H وC–H)، وليست تجاذبًا بين الجزيئات.","لا يحتوي الماء ولا الميثان على أيونات، فلا روابط أيونية بينها.","هذا وصف للتجاذب الضعيف بين جزيئات الميثان نفسها، لا ما يميز الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.570Z"}'::jsonb),
('mcq', 4, 1, 'الخطوط المتقطعة تصل ذرة H في جزيء ماء بذرة O في جزيء ماء مجاور، فهي تمثل الروابط الهيدروجينية (تجاذب بين الجزيئات القطبية)، ولا تظهر مثلها بين جزيئات الميثان غير القطبية. أما الروابط التساهمية O–H فهي الخطوط المتصلة داخل كل جزيء.', '["الروابط التساهمية O–H داخل الجزيء مرسومة بخطوط متصلة، أما المتقطعة فتصل بين جزيئين مختلفين.","","جزيئات الماء متعادلة كهربائيًّا وليست أيونات، فالتجاذب بينها ليس أيونيًّا.","التجاذب بين الجزيئات أضعف من الرابطة التساهمية، ولا تتحد الجزيئات في جزيء واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.570Z"}'::jsonb),
('mcq', 5, 0, 'تقع −170°C بين درجة انصهار الميثان (−182°C) ودرجة غليانه (−162°C)، فيكون الميثان سائلًا. وهي أقل بكثير من درجة انصهار الماء (0°C)، فيكون الماء صلبًا.', '["","−170°C أقل من درجة غليان الميثان (−162°C)، فلم يصل إلى الغليان بعد ولا يكون غازًا.","−170°C أعلى من درجة انصهار الميثان (−182°C)، فقد انصهر وأصبح سائلًا.","−170°C أقل كثيرًا من درجة انصهار الماء (0°C)، فالماء صلب لا سائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.571Z"}'::jsonb),
('mcq', 6, 3, 'كتلة جزيء الماء وحجمه قريبان من كتلة جزيء الميثان وحجمه؛ فلو كانت جزيئاته غير قطبية بلا روابط هيدروجينية لكان التجاذب بينها ضعيفًا كما في الميثان، ولكانت درجة غليانه منخفضة جدًّا قريبة من −162°C. فارتفاع درجة غليان الماء يرجع إلى قطبيته وروابطه الهيدروجينية.', '["فرق الكتلة صغير (2 amu)، ولا يرفع درجة الغليان؛ والسبب الحقيقي لارتفاعها هو الروابط الهيدروجينية.","درجة الغليان العالية للماء ناتجة عن الروابط الهيدروجينية لا عن الكتلة؛ فزوالها يخفضها.","لا علاقة مباشرة لذلك بدرجة الانصهار؛ فكلتا الدرجتين ستنخفض انخفاضًا كبيرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.571Z"}'::jsonb),
('mcq', 7, 2, 'الغليان تغير فيزيائي تتباعد فيه الجزيئات دون أن تتكسر روابطها الداخلية. والتجاذب بين جزيئات الميثان غير القطبية ضعيف، فيكفي قدر قليل من الطاقة للتغلب عليه؛ ولهذا يغلي الميثان عند −162°C.', '["روابط C–H لا تتكسر عند الغليان؛ ولو تكسرت لتحول الميثان إلى مواد أخرى.","جزيئات الميثان غير قطبية فلا تكوّن روابط هيدروجينية بينها.","","الروابط في الميثان تساهمية لا أيونية، وهي لا تتكسر عند الغليان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.571Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الرابطة O–H في الماء قطبية، أما الروابط C–H في الميثان فغير قطبية. (ب) جزيء الماء قطبي لأن روابطه قطبية وشكله منحنٍ، وجزيء الميثان غير قطبي لأن جميع روابطه غير قطبية. (ج) جزيئات الماء القطبية تتجاذب بقوة وتكوّن روابط هيدروجينية، أما جزيئات الميثان فالتجاذب بينها ضعيف ولا تكوّن روابط هيدروجينية. (د) لفصل جزيئات الماء بعضها عن بعض عند الغليان يجب التغلب على الروابط الهيدروجينية القوية، فيحتاج إلى طاقة أكبر ودرجة حرارة أعلى (100°C)، في حين يكفي قدر قليل من الطاقة لفصل جزيئات الميثان، فيغلي عند −162°C؛ مع أن كتلتيهما الجزيئيتين متقاربتان.', '["O–H قطبية وC–H غير قطبية","الماء جزيء قطبي (منحنٍ) والميثان غير قطبي","روابط هيدروجينية قوية في الماء وتجاذب ضعيف في الميثان","التجاذب الأقوى يتطلب طاقة أكبر فدرجة الغليان أعلى"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية الروابط","marks":1},{"element":"قطبية الجزيئين","marks":1},{"element":"نوع التجاذب وقوته","marks":1},{"element":"تفسير الفرق في درجتي الغليان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في البنود الثلاثة وتفسير مرتبط بها"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع تفسير ناقص أو خطأ في أحد البنود"},{"level":"1 درجة","description":"ذكر الروابط الهيدروجينية في الماء فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن روابط O–H تتكسر عند غليان الماء","وصف جزيء الماء بأنه خطي","تفسير الفرق بالكتلة الجزيئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.571Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الادعاء غير صحيح: فالبيوتان كتلته الجزيئية 58 amu (أكثر من ثلاثة أمثال كتلة الماء) ودرجة غليانه −0.5°C، والهكسان كتلته 86 amu (نحو خمسة أمثال كتلة الماء) ودرجة غليانه 68.7°C؛ وكلتاهما أقل من درجة غليان الماء 100°C. فلو كانت الكتلة الأكبر هي سبب ارتفاع درجة الغليان لغلى البيوتان والهكسان عند درجة أعلى من الماء. كما أن فرق الكتلة بين الماء والميثان 2 amu فقط مقابل فرق 262°C في درجتي الغليان. (ب) جزيئات الميثان غير قطبية والتجاذب بينها ضعيف، أما جزيئات الماء فقطبية (الرابطة O–H قطبية والجزيء منحنٍ) وتكوّن روابط هيدروجينية قوية بينها، فيلزم الماء طاقة أكبر بكثير لفصل جزيئاته عند الغليان. (ج) بين الألكانات غير القطبية ترتفع درجة الغليان بزيادة الكتلة الجزيئية (−162°C ثم −0.5°C ثم 68.7°C)؛ أي إن الكتلة تُقارَن عندما تكون الجزيئات من النوع نفسه في التجاذب. أما الماء والميثان فيختلفان في القطبية ونوع التجاذب بين الجزيئات، فلا تصلح الكتلة لتفسير الفرق بينهما.', '["الحكم: الادعاء غير صحيح","الاستدلال بالبيوتان (58 amu، −0.5°C) والهكسان (86 amu، 68.7°C): كتلة أكبر من الماء ودرجة غليان أقل","الماء قطبي ويكوّن روابط هيدروجينية، والميثان غير قطبي والتجاذب بين جزيئاته ضعيف","بين الألكانات ترتفع درجة الغليان بزيادة الكتلة، والمقارنة بالكتلة لا تصلح بين مادتين مختلفتين في القطبية"]'::jsonb, '["البيوتان: 58 amu > 18 amu، ودرجة غليانه −0.5°C < 100°C","الهكسان: 86 amu > 18 amu، ودرجة غليانه 68.7°C < 100°C","الماء والميثان: فرق الكتلة 18 − 16 = 2 amu، وفرق درجتي الغليان 100 − (−162) = 262°C","الألكانات: −162°C < −0.5°C < 68.7°C بزيادة الكتلة"]'::jsonb, '[{"element":"الحكم على الادعاء مدعومًا ببيانات البيوتان والهكسان","marks":2},{"element":"التفسير الصحيح بالقطبية والروابط الهيدروجينية","marks":1},{"element":"العلاقة بين الكتلة ودرجة الغليان بين الألكانات وحدود استخدامها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعوم ببيانات البيوتان والهكسان، وتفسير صحيح بالقطبية والروابط الهيدروجينية، وتحديد صحيح لحدود أثر الكتلة"},{"level":"2–3 درجات","description":"حكم صحيح مع استدلال ناقص بالبيانات، أو تفسير صحيح دون الجزء (ج)"},{"level":"1 درجة","description":"حكم صحيح دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الادعاء لأن درجة غليان الألكانات ترتفع بزيادة الكتلة","إهمال بيانات البيوتان والهكسان والاكتفاء بالماء والميثان","حساب فرق درجتي الغليان 62°C بإهمال الإشارة السالبة","ذكر الروابط الهيدروجينية بين جزيئات الألكانات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.571Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عند الغليان تكتسب الجزيئات طاقة كافية للتغلب على قوى التجاذب بينها فتتباعد وتنتقل إلى الحالة الغازية. (أ) جزيئات الماء قطبية ومرتبط بعضها ببعض بروابط هيدروجينية قوية، فيلزم قدر أكبر من الطاقة (درجة حرارة 100°C) للتغلب عليها، أما جزيئات الميثان غير القطبية فالتجاذب بينها ضعيف فتتباعد عند −162°C. (ب) لا؛ فالغليان تغير فيزيائي تبقى فيه الجزيئات كما هي (H₂O وCH₄ في الحالة الغازية)، وتُتغلب فقط على قوى التجاذب بين الجزيئات لا الروابط داخلها. (ج) الانصهار أيضًا يتطلب التغلب جزئيًّا على قوى التجاذب بين الجزيئات لتتحرك بحرية أكبر؛ ولأن التجاذب بين جزيئات الماء (الروابط الهيدروجينية) أقوى بكثير منه بين جزيئات الميثان، يلزم الماء درجة حرارة أعلى لينصهر.', '["الغليان: تغلب الجزيئات على التجاذب بينها وتتباعد","الروابط الهيدروجينية القوية في الماء تتطلب طاقة أكبر","الروابط التساهمية لا تتكسر لأن الغليان تغير فيزيائي","درجة الانصهار أعلى للسبب نفسه: تجاذب أقوى بين جزيئات الماء"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الغليان على مستوى الجزيئات","marks":1},{"element":"تفسير (أ)","marks":1},{"element":"الإجابة عن (ب) مع التعليل","marks":1},{"element":"تفسير (ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح وإجابات صحيحة معللة عن الأجزاء الثلاثة"},{"level":"2–3 درجات","description":"وصف صحيح مع خطأ أو نقص في أحد الأجزاء"},{"level":"1 درجة","description":"ذكر الروابط الهيدروجينية دون ربط بالغليان والانصهار"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء يتحلل إلى H₂ وO₂ عند الغليان","الخلط بين الروابط الهيدروجينية والروابط التساهمية O–H","تفسير ارتفاع درجة الانصهار بكتلة الجزيء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.572Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L2-O13') and x.type = v.type and x.number = v.number
