from (values
('mcq', 1, 'ما التعريف الصحيح للألكينات؟', null, null, '["هيدروكربونات غير مشبعة تحتوي على الأقل على رابطة ثنائية واحدة بين ذرتي كربون","هيدروكربونات مشبعة تحتوي على روابط أحادية فقط بين ذرات الكربون","هيدروكربونات غير مشبعة تحتوي على الأقل على رابطة ثلاثية واحدة بين ذرتي كربون","هيدروكربونات تحتوي على حلقة كربونية مغلقة بروابط أحادية فقط"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 136 — الألكينات (التعريف والصيغة العامة)'),
('mcq', 2, 'ما الصيغة العامة للألكينات التي تحتوي على رابطة ثنائية واحدة؟', null, null, '["CₙH₂ₙ₊₂","CₙH₂ₙ₋₂","CₙH₂ₙ","CₙHₙ"]'::jsonb, 'تذكر', 'تذكر صيغة عامة', 'سهل', 'الكتاب ص 136 — الألكينات (التعريف والصيغة العامة)'),
('mcq', 3, 'تمثل الصيغ الآتية أربعة مركبات يحتوي كل منها على ثلاث ذرات كربون. أيّ هذه المركبات ألكين؟', null, '[{"src":"qimg/chem22/c4-l3a-o1-four.svg","alt":"أربع صيغ بنائية مرقمة لمركبات تحتوي كل منها على ثلاث ذرات كربون. المركب (1): CH₃–CH₂–CH₃ وكل الروابط بين ذرات الكربون أحادية. المركب (2): CH≡C–CH₃ وفيه رابطة ثلاثية بين ذرتي الكربون الأولى والثانية. المركب (3): صيغة هيكلية على شكل مثلث، أي حلقة من ثلاث ذرات كربون بروابط أحادية فقط. المركب (4): CH₂=CH–CH₃ وفيه رابطة ثنائية بين ذرتي الكربون الأولى والثانية."}]'::jsonb, '["المركب (1)","المركب (2)","المركب (3)","المركب (4)"]'::jsonb, 'فهم', 'تصنيف من الصيغة البنائية', 'متوسط', 'الكتاب ص 136، 140 — الألكينات والألكاينات'),
('mcq', 4, 'لماذا لا يوجد ألكين يحتوي على ذرة كربون واحدة؟', null, null, '["لأن ذرة الكربون الواحدة لا تكوّن إلا ثلاث روابط تساهمية","لأن الرابطة الثنائية في الألكين تكون بين ذرتي كربون، فأبسط ألكين فيه ذرتا كربون","لأن المركب ذا ذرة الكربون الواحدة يتحلل فور تكوّنه في الطبيعة","لأن الرابطة الثنائية في الألكين تكون بين ذرة كربون وذرة هيدروجين"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 136 — الألكينات (التعريف والصيغة العامة)'),
('mcq', 5, 'ما الصيغة الجزيئية لألكين ذي سلسلة مستقيمة يحتوي على 6 ذرات كربون ورابطة ثنائية واحدة؟', null, null, '["C₆H₁₂","C₆H₁₄","C₆H₁₀","C₆H₆"]'::jsonb, 'تطبيق', 'تطبيق الصيغة العامة', 'سهل', 'الكتاب ص 136 — الصيغة العامة للألكينات'),
('mcq', 6, 'يقل عدد ذرات الهيدروجين في الألكين ذي الرابطة الثنائية الواحدة عن الألكان المناظر له بذرتين. ما سبب ذلك؟', null, null, '["لأن الألكين يحتوي على ذرة كربون واحدة أقل من الألكان المناظر له","لأن ذرات الكربون في الألكين تكوّن ثلاث روابط فقط بدل أربع","لأن الإلكترونين المكوّنين للرابطة الثانية بين ذرتي الكربون لا يتوافران للارتباط بالهيدروجين","لأن الرابطة الثنائية تتكون بين ذرة كربون وذرة هيدروجين فتستهلك ذرتين"]'::jsonb, 'فهم', 'تفسير الصيغة العامة', 'صعب', 'الكتاب ص 136 — الألكينات (التعريف والصيغة العامة)'),
('mcq', 7, 'أيّ العبارات الآتية عن الألكينات صحيحة؟', null, null, '["كل هيدروكربون غير مشبع يُعدّ ألكينًا","كل ألكين يُعدّ هيدروكربونًا غير مشبع","الألكينات مشبعة لاحتوائها على أكبر عدد ممكن من ذرات الهيدروجين","يمكن أن يحتوي الألكين على ذرة كربون واحدة فقط"]'::jsonb, 'فهم', 'تمييز عبارة صحيحة', 'متوسط', 'الكتاب ص 136 — الألكينات (التعريف والصيغة العامة)'),
('essay', 1, 'عرّف الألكينات، واكتب صيغتها العامة، ثم بيّن لماذا تُصنَّف ضمن الهيدروكربونات غير المشبعة، واذكر اسم أبسط ألكين وصيغته الجزيئية.', null, null, null, 'فهم', 'تعريف وتفسير', 'سهل', 'الكتاب ص 136 — الألكينات (التعريف والصيغة العامة)'),
('essay', 2, 'ألكين ذو سلسلة مستقيمة يحتوي على 9 ذرات كربون ورابطة ثنائية واحدة. اكتب صيغته الجزيئية، واكتب الصيغة الجزيئية للألكان الذي له عدد ذرات الكربون نفسه، ثم فسّر الفرق في عدد ذرات الهيدروجين بينهما.', null, null, null, 'تطبيق', 'حساب صيغة جزيئية وتفسير', 'متوسط', 'الكتاب ص 136، 162 — الصيغة العامة للألكينات (س78)'),
('essay', 3, 'تمثل الصيغ الآتية ثلاثة مركبات يحتوي كل منها على أربع ذرات كربون. اكتب الصيغة الجزيئية لكل منها، وصنّف كلًّا منها (ألكان، ألكان حلقي، ألكين)، ثم فسّر لماذا لا تكفي مطابقة الصيغة الجزيئية للصيغة CₙH₂ₙ للحكم بأن المركب ألكين.', null, '[{"src":"qimg/chem22/c4-l3a-o1-c4.svg","alt":"ثلاث صيغ لمركبات تحتوي كل منها على أربع ذرات كربون. (أ): الصيغة البنائية المكثفة CH₂=CH–CH₂–CH₃ وفيها رابطة ثنائية واحدة بين ذرتي الكربون الأولى والثانية. (ب): صيغة هيكلية على شكل مربع، أي حلقة من أربع ذرات كربون بينها روابط أحادية فقط. (ج): الصيغة البنائية المكثفة CH₃–CH₂–CH₂–CH₃ وكل روابطها أحادية."}]'::jsonb, null, 'تحليل', 'تصنيف وتفسير', 'صعب', 'الكتاب ص 136، 162 — الألكينات وصيغة الألكانات الحلقية (س79)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
