insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الألكينات هيدروكربونات غير مشبعة تحتوي على الأقل على رابطة تساهمية ثنائية واحدة بين ذرتي كربون.', '["","هذا تعريف الألكانات، وهي هيدروكربونات مشبعة.","الرابطة الثلاثية تميّز الألكاينات لا الألكينات.","هذا وصف الألكانات الحلقية، وليس فيها رابطة ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('mcq', 2, 2, 'يحتوي كل ألكين ذي رابطة ثنائية واحدة على عدد من ذرات الهيدروجين يساوي ضعف عدد ذرات الكربون، فصيغته العامة CₙH₂ₙ.', '["هذه الصيغة العامة للألكانات، وفيها ذرتا هيدروجين زيادة على الألكين المناظر.","هذه الصيغة العامة للألكاينات ذات الرابطة الثلاثية الواحدة.","","عدد ذرات الهيدروجين في الألكين ضعف عدد ذرات الكربون لا مساوٍ له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('mcq', 3, 3, 'المركب (4) CH₂=CHCH₃ (البروبين) يحتوي على رابطة ثنائية بين ذرتي كربون، فهو ألكين.', '["المركب (1) هو البروبان، وكل روابطه أحادية فهو ألكان مشبع.","المركب (2) يحتوي على رابطة ثلاثية، فهو ألكاين (بروباين).","المركب (3) حلقة بروابط أحادية فقط (بروبان حلقي)؛ صيغته C₃H₆ تشبه صيغة البروبين لكنه لا يحتوي على رابطة ثنائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('mcq', 4, 1, 'يجب أن يحتوي الألكين على رابطة ثنائية بين ذرتي كربون؛ لذا لا يوجد ألكين بذرة كربون واحدة، وأبسط الألكينات الإيثين C₂H₄ بذرتي كربون.', '["ذرة الكربون تكوّن أربع روابط تساهمية، والسبب الحقيقي حاجة الرابطة الثنائية إلى ذرتي كربون.","","لا علاقة للثبات بالأمر؛ فالسبب بنائي، إذ تحتاج الرابطة الثنائية إلى ذرتي كربون.","ذرة الهيدروجين تكوّن رابطة أحادية واحدة فقط، والرابطة الثنائية في الألكين بين ذرتي كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('mcq', 5, 0, 'بالتعويض في الصيغة العامة للألكينات CₙH₂ₙ حيث n = 6: عدد ذرات الهيدروجين 2 × 6 = 12، فالصيغة C₆H₁₂.', '["","استُعملت الصيغة العامة للألكانات CₙH₂ₙ₊₂، فهذه صيغة الهكسان.","استُعملت الصيغة العامة للألكاينات CₙH₂ₙ₋₂.","جُعل عدد ذرات الهيدروجين مساويًا لعدد ذرات الكربون، وهذا لا يطابق الصيغة العامة للألكينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('mcq', 6, 2, 'تكوّن الرابطة التساهمية الثانية بين ذرتي الكربون يستهلك إلكترونين كانا سيرتبطان بذرتي هيدروجين؛ لذا يقل الألكين عن الألكان المناظر بذرتي هيدروجين.', '["الألكين والألكان المناظر له لهما العدد نفسه من ذرات الكربون.","كل ذرة كربون في الألكين تبقى مكوّنة لأربع روابط؛ وتُحسب الرابطة الثنائية رابطتين.","","الرابطة الثنائية بين ذرتي كربون، والهيدروجين لا يكوّن إلا رابطة أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('mcq', 7, 1, 'الألكين يحتوي على رابطة ثنائية واحدة على الأقل بين ذرتي كربون، فهو هيدروكربون غير مشبع دائمًا.', '["الهيدروكربونات غير المشبعة تشمل الألكينات والألكاينات أيضًا، فليس كل غير مشبع ألكينًا.","","الألكينات غير مشبعة؛ فالمشبع يحتوي على روابط أحادية فقط وأكبر عدد ممكن من ذرات الهيدروجين.","الرابطة الثنائية تحتاج إلى ذرتي كربون على الأقل، فأبسط ألكين هو الإيثين C₂H₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الألكينات: هيدروكربونات غير مشبعة تحتوي على الأقل على رابطة تساهمية ثنائية واحدة بين ذرتي كربون. صيغتها العامة (لرابطة ثنائية واحدة) CₙH₂ₙ. تُعدّ غير مشبعة لأنها تحتوي على رابطة ثنائية بين ذرتي كربون، فلا تحتوي على أكبر عدد ممكن من ذرات الهيدروجين كما في الألكانات ذات الروابط الأحادية. أبسط ألكين هو الإيثين وصيغته C₂H₄.', '["تعريف الألكينات: هيدروكربونات تحتوي على الأقل على رابطة ثنائية واحدة بين ذرتي كربون","الصيغة العامة CₙH₂ₙ","سبب عدم التشبع: وجود الرابطة الثنائية","أبسط ألكين الإيثين C₂H₄"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الصيغة العامة","marks":1},{"element":"تفسير عدم التشبع","marks":1},{"element":"أبسط ألكين وصيغته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق، وصيغة عامة صحيحة، وتفسير سليم لعدم التشبع، وذكر الإيثين C₂H₄"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة العامة CₙH₂ₙ₊₂ الخاصة بالألكانات","القول إن الرابطة الثنائية بين الكربون والهيدروجين","ذكر الميثين أو الإيثاين أبسطَ ألكين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الألكين: CₙH₂ₙ مع n = 9 ← C₉H₁₈. الألكان: CₙH₂ₙ₊₂ مع n = 9 ← C₉H₂₀. يزيد الألكان بذرتي هيدروجين؛ لأن الإلكترونين اللذين يكوّنان الرابطة التساهمية الثانية بين ذرتي الكربون في الألكين لا يتوافران للارتباط بذرتي هيدروجين.', '["صيغة الألكين C₉H₁₈","صيغة الألكان C₉H₂₀","الفرق ذرتا هيدروجين","التفسير بالإلكترونين المستعملين في الرابطة الثانية"]'::jsonb, '["الألكين: n = 9 ، عدد H = 2 × 9 = 18 ← C₉H₁₈","الألكان: عدد H = 2 × 9 + 2 = 20 ← C₉H₂₀","الفرق = 20 − 18 = 2 ذرة هيدروجين"]'::jsonb, '[{"element":"صيغة الألكين","marks":1},{"element":"صيغة الألكان","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الصيغتان صحيحتان مع تفسير الفرق بالرابطة الثانية بين ذرتي الكربون"},{"level":"2–3 درجات","description":"الصيغتان صحيحتان مع تفسير ناقص، أو صيغة واحدة مع تفسير صحيح"},{"level":"1 درجة","description":"صيغة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الصيغتين العامتين للألكانات والألكينات","كتابة C₉H₁₆ للألكين باستعمال صيغة الألكاينات","تفسير الفرق بنقص ذرة كربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) CH₂=CHCH₂CH₃ صيغته C₄H₈، وهو ألكين (1-بيوتين) لاحتوائه على رابطة ثنائية. (ب) الحلقة الرباعية صيغتها C₄H₈، وهي ألكان حلقي (بيوتان حلقي) روابطه أحادية فقط. (ج) CH₃CH₂CH₂CH₃ صيغته C₄H₁₀، وهو ألكان (بيوتان). المركبان (أ) و(ب) لهما الصيغة C₄H₈ التي تطابق CₙH₂ₙ، لكن (ب) ليس ألكينًا؛ لأن التعريف يشترط وجود رابطة ثنائية بين ذرتي كربون، والصيغة الجزيئية لا تبيّن نوع الروابط ولا ترتيب الذرات؛ لذا نحتاج إلى الصيغة البنائية للحكم.', '["(أ) C₄H₈ ألكين","(ب) C₄H₈ ألكان حلقي","(ج) C₄H₁₀ ألكان","الألكان الحلقي يطابق CₙH₂ₙ دون رابطة ثنائية","الحكم يحتاج إلى الصيغة البنائية لأن التعريف قائم على الرابطة الثنائية"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغ الجزيئية الثلاث","marks":1.5},{"element":"التصنيف الصحيح للثلاثة","marks":1.5},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"صيغ وتصنيفات صحيحة، وتفسير يربط تعريف الألكين بالرابطة الثنائية ويبين قصور الصيغة الجزيئية"},{"level":"3–4 درجات","description":"صيغ وتصنيفات صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"بعض الصيغ أو التصنيفات صحيحة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الحلقة الرباعية ألكينًا لأن صيغتها C₄H₈","عدّ ذرات الهيدروجين في الحلقة خطأً (C₄H₁₀)","الاكتفاء بالصيغة الجزيئية في الحكم على نوع المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.573Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O01') and x.type = v.type and x.number = v.number
