select (select id from public.objectives where code = 'K22-C4-L3-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الاسم النظامي (IUPAC) للألكين غير المتفرع الممثل بالصيغة الآتية؟', null, '[{"src":"qimg/chem22/c4-l3a-1-butene.svg","alt":"صيغة بنائية مكثفة مكتوبة من اليسار إلى اليمين: CH₃–CH₂–CH=CH₂؛ سلسلة مستقيمة من أربع ذرات كربون، والرابطة الثنائية بين ذرتي الكربون الثالثة والرابعة عند العد من اليسار، أي بين ذرة الكربون الطرفية في اليمين والذرة المجاورة لها."}]'::jsonb, '["3-بيوتين","1-بيوتين","2-بيوتين","بيوتان"]'::jsonb, 'تطبيق', 'تسمية من الصيغة', 'سهل', 'الكتاب ص 137 — تسمية الألكينات'),
('mcq', 2, 'يحتوي المركب الممثل بالصيغة الآتية على رابطة ثنائية ومجموعة ميثيل واحدة. ما اسمه وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3a-4m2pentene.svg","alt":"صيغة بنائية مكثفة: سلسلة أفقية من خمس مجموعات من اليسار إلى اليمين: CH₃–CH=CH–CH–CH₃، والرابطة الثنائية بين المجموعتين الثانية والثالثة من اليسار، وتتفرع من المجموعة الرابعة من اليسار (CH) مجموعة CH₃ إلى الأسفل."}]'::jsonb, '["4-ميثيل-2-بنتين","2-ميثيل-3-بنتين","4-ميثيل-2-بنتان","4-ميثيل-2-بيوتين"]'::jsonb, 'تطبيق', 'تسمية ألكين متفرع', 'متوسط', 'الكتاب ص 137–138 — تسمية الألكينات المتفرعة (مثال 4-3)'),
('mcq', 3, 'في الصيغة الآتية ألكين متفرع رُسمت فيه مجموعة إيثيل وثلاث مجموعات ميثيل. أيّ الأسماء الآتية هو اسمه الصحيح وفق قواعد الأيوباك؟', null, '[{"src":"qimg/chem22/c4-l3a-226tm3octene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–CH–CH₂–CH=CH–C–CH₃، والرابطة الثنائية بين المجموعتين الرابعة (CH) والخامسة (CH) من اليسار. تتفرع من المجموعة الثانية (CH) إلى الأعلى مجموعة CH₂ مرتبطة بدورها بمجموعة CH₃ فوقها (مجموعة إيثيل). وترتبط بذرة الكربون السادسة (C) مجموعتا CH₃: إحداهما إلى الأعلى والأخرى إلى الأسفل."}]'::jsonb, '["3، 7، 7-ثلاثي ميثيل-5-أوكتين","6-إيثيل-2، 2-ثنائي ميثيل-3-هبتين","2، 2، 6-ثلاثي ميثيل-4-أوكتين","2، 2، 6-ثلاثي ميثيل-3-أوكتين"]'::jsonb, 'تطبيق', 'تسمية ألكين متفرع', 'صعب', 'الكتاب ص 137–138 — تسمية الألكينات المتفرعة (مثال 4-3) ومسألة 17'),
('mcq', 4, 'ما الاسم النظامي (IUPAC) للألكين الحلقي الممثل بالصيغة الهيكلية الآتية؟', null, '[{"src":"qimg/chem22/c4-l3a-3mcyclohexene.svg","alt":"صيغة هيكلية لحلقة سداسية من ست ذرات كربون (كل رأس ذرة كربون). بين الرأس العلوي والرأس المجاور له من جهة اليمين رابطة ثنائية (خط داخلي ثانٍ)، وبقية روابط الحلقة أحادية. ترتبط مجموعة CH₃ بالرأس العلوي الأيسر، وهو الرأس المجاور للرأس العلوي من الجهة الأخرى، أي أن مجموعة الميثيل على ذرة مجاورة لإحدى ذرتي الرابطة الثنائية وليست عليها."}]'::jsonb, '["1-ميثيل هكسين حلقي","6-ميثيل هكسين حلقي","3-ميثيل هكسين حلقي","3-ميثيل هكسان حلقي"]'::jsonb, 'تطبيق', 'تسمية ألكين حلقي', 'متوسط', 'الكتاب ص 137 — تسمية الألكينات الحلقية (الشكل 4-12b)'),
('mcq', 5, 'تحتوي السلسلة الكربونية في الصيغة الآتية على رابطتين ثنائيتين. كيف يُسمّى هذا المركب وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3a-13pentadiene.svg","alt":"صيغة بنائية مكثفة من اليسار إلى اليمين: CH₂=CH–CH=CH–CH₃؛ سلسلة مستقيمة من خمس ذرات كربون فيها رابطتان ثنائيتان: الأولى بين المجموعتين الأولى والثانية من اليسار، والثانية بين المجموعتين الثالثة والرابعة من اليسار."}]'::jsonb, '["1، 3-بنتادايين","2، 4-بنتادايين","1، 3-بنتين","1، 3-ثنائي بنتين"]'::jsonb, 'تطبيق', 'تسمية ألكين برابطتين ثنائيتين', 'متوسط', 'الكتاب ص 137 — الألكينات ذات أكثر من رابطة ثنائية (الشكل 4-13b)'),
('mcq', 6, 'لماذا يُعدّ الاسم «3-بيوتين» اسمًا غير صحيح؟', null, null, '["لأن السلسلة ذات الأربع ذرات لا يمكن أن تحتوي على رابطة ثنائية","لأن موقع الرابطة الثنائية لا يُكتب في أسماء الألكينات","لأن الرابطة الثنائية لا تقع أبدًا عند طرف السلسلة الكربونية","لأنه البناء نفسه المسمّى 1-بيوتين، والترقيم يبدأ من الطرف الأقرب إلى الرابطة الثنائية"]'::jsonb, 'فهم', 'تفسير قاعدة الترقيم', 'سهل', 'الكتاب ص 137 — تسمية الألكينات'),
('mcq', 7, 'عند تسمية المركب الآتي يجب أولًا تحديد أطول سلسلة تحتوي على الرابطة الثنائية. ما اسمه الصحيح وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3a-2e1hexene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₂=C–CH₂–CH₂–CH₂–CH₃، والرابطة الثنائية بين المجموعة الأولى (CH₂) والثانية (C). وتتفرع من ذرة الكربون الثانية (C) إلى الأعلى مجموعة CH₂ مرتبطة بمجموعة CH₃ فوقها (مجموعة إيثيل)."}]'::jsonb, '["5-إيثيل-5-هكسين","2-إيثيل-1-هكسين","2-بيوتيل-1-بيوتين","2-إيثيل-2-هكسين"]'::jsonb, 'تحليل', 'تحديد السلسلة الرئيسة وتسمية', 'صعب', 'الكتاب ص 137 — تسمية الألكينات ذات السلاسل المتفرعة (الشكل 4-13a)'),
('essay', 1, 'سمِّ المركب الممثل بالصيغة الآتية وفق نظام IUPAC، موضحًا خطوات التسمية، ولا سيما كيف تختار اتجاه الترقيم.', null, '[{"src":"qimg/chem22/c4-l3a-24dm3hexene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–CH₂–C=CH–CH–CH₃، والرابطة الثنائية بين المجموعة الثالثة (C) والرابعة (CH) من اليسار. تتفرع مجموعة CH₃ إلى الأسفل من المجموعة الثالثة (C)، ومجموعة CH₃ أخرى إلى الأسفل من المجموعة الخامسة (CH)."}]'::jsonb, null, 'تطبيق', 'تسمية بخطوات', 'صعب', 'الكتاب ص 137–138 — تسمية الألكينات المتفرعة (مثال 4-3)'),
('essay', 2, 'سمِّ المركبين (أ) و(ب) الممثلين بالصيغتين الآتيتين وفق نظام IUPAC، وبيّن في كل منهما سبب اختيار اتجاه الترقيم.', null, '[{"src":"qimg/chem22/c4-l3a-two-alkenes.svg","alt":"صيغتان بنائيتان مكثفتان. (أ): سلسلة أفقية من اليسار إلى اليمين CH₃–C=CH–CH₃ والرابطة الثنائية بين المجموعتين الثانية والثالثة، وتتفرع من المجموعة الثانية (C) مجموعة CH₃ إلى الأعلى. (ب): سلسلة أفقية من اليسار إلى اليمين CH₂=C–CH=CH₂ فيها رابطتان ثنائيتان: بين المجموعتين الأولى والثانية، وبين الثالثة والرابعة، وتتفرع من المجموعة الثانية (C) مجموعة CH₃ إلى الأعلى."}]'::jsonb, null, 'تطبيق', 'تسمية مع تبرير', 'متوسط', 'الكتاب ص 137، 160 — تسمية الألكينات (س61)'),
('essay', 3, 'سمّى طالب المركب الممثل بالصيغة الآتية «2-إيثيل-3-بنتين». قوّم هذا الاسم: حدّد الأخطاء التي وقع فيها، ثم اكتب الاسم الصحيح وفق نظام IUPAC مع التبرير.', null, '[{"src":"qimg/chem22/c4-l3a-4m2hexene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–CH=CH–CH–CH₃، والرابطة الثنائية بين المجموعتين الثانية والثالثة من اليسار. وتتفرع من المجموعة الرابعة (CH) إلى الأسفل مجموعة CH₂ مرتبطة بمجموعة CH₃ تحتها (مجموعة إيثيل)."}]'::jsonb, null, 'تقويم', 'تقويم اسم وتصحيحه', 'صعب', 'الكتاب ص 137–138 — قواعد تسمية الألكينات المتفرعة')
