from (values
('mcq', 1, 1, 'السلسلة أربع ذرات كربون (بيوت-) وفيها رابطة ثنائية فالمقطع «ين». نرقّم من الطرف الأيمن الأقرب إلى الرابطة الثنائية فتبدأ عند ذرة الكربون 1، فالاسم 1-بيوتين.', '["رُقّمت السلسلة من الطرف الأبعد عن الرابطة الثنائية؛ والصحيح أن تأخذ الرابطة الثنائية أصغر رقم.","","2-بيوتين تكون فيه الرابطة الثنائية بين ذرتي الكربون الوسطيين، وفي الصيغة هي عند الطرف.","المقطع «ان» للألكانات، والمركب يحتوي على رابطة ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('mcq', 2, 0, 'أطول سلسلة تحتوي على الرابطة الثنائية خمس ذرات (بنتين). نرقّم من اليسار فتأخذ الرابطة الثنائية الرقم 2 (لا 3)، وتقع مجموعة الميثيل على ذرة الكربون 4، فالاسم 4-ميثيل-2-بنتين.', '["","رُقّمت السلسلة لتعطي المجموعة البديلة أصغر رقم؛ والقاعدة أن تأخذ الرابطة الثنائية أصغر رقم.","المقطع «ان» للألكانات، والمركب يحتوي على رابطة ثنائية فينتهي اسمه بـ«ين».","السلسلة الرئيسة خمس ذرات كربون لا أربع؛ فمجموعة CH₃ الطرفية جزء من السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('mcq', 3, 3, 'أطول سلسلة تحتوي على الرابطة الثنائية تمر بمجموعة الإيثيل فتضم ثماني ذرات (أوكتين). نرقّم من الطرف الأيمن فتأخذ الرابطة الثنائية الرقم 3، وتقع مجموعتا ميثيل على الذرة 2 ومجموعة ميثيل على الذرة 6، فالاسم 2، 2، 6-ثلاثي ميثيل-3-أوكتين.', '["رُقّمت السلسلة من الطرف الأبعد عن الرابطة الثنائية فأخذت الرقم 5 بدل 3.","اختيرت السلسلة الأفقية المرسومة (سبع ذرات)، مع أن أطول سلسلة تحتوي على الرابطة الثنائية تمر بمجموعة الإيثيل وفيها ثماني ذرات.","رقم موقع الرابطة الثنائية هو رقم أول ذرة كربون فيها (3) لا الذرة الثانية (4).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('mcq', 4, 2, 'الحلقة سداسية فيها رابطة ثنائية (هكسين حلقي). تأخذ ذرتا الرابطة الثنائية الرقمين 1 و2، ونكمل الترقيم في الاتجاه الذي يعطي مجموعة الميثيل أصغر رقم، فتقع على الذرة 3: 3-ميثيل هكسين حلقي.', '["مجموعة الميثيل ليست على إحدى ذرتي الرابطة الثنائية، بل على ذرة مجاورة لها.","رُقّمت الحلقة في الاتجاه الذي يعطي المجموعة البديلة رقمًا أكبر؛ والصحيح 3 لا 6.","","الحلقة تحتوي على رابطة ثنائية، فهي هكسين حلقي لا هكسان حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('mcq', 5, 0, 'السلسلة خمس ذرات (بنت-) فيها رابطتان ثنائيتان، فتُضاف البادئة «داي» قبل المقطع «ين»: بنتادايين. نرقّم من اليسار فتأخذ الرابطتان الرقمين 1 و3 (وهي أصغر مجموعة أرقام)، فالاسم 1، 3-بنتادايين.', '["","رُقّمت السلسلة من الطرف الأبعد فأعطت 2 و4 بدل 1 و3.","أُهملت البادئة «داي» التي تبين وجود رابطتين ثنائيتين.","تُستعمل «ثنائي» لعدد المجموعات البديلة المتماثلة؛ أما عدد الروابط الثنائية فيُبيَّن بالبادئة «داي» قبل «ين»."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('mcq', 6, 3, 'البناء الذي يُسمّى خطأً 3-بيوتين يطابق 1-بيوتين عند ترقيمه من الطرف الآخر، والقاعدة أن تُرقّم السلسلة من الطرف الذي يعطي الرابطة الثنائية أصغر رقم.', '["البيوتين نفسه سلسلة من أربع ذرات تحتوي على رابطة ثنائية.","يجب كتابة موقع الرابطة الثنائية للألكينات ذات الأربع ذرات أو أكثر، فـ1-بيوتين و2-بيوتين مادتان مختلفتان.","الرابطة الثنائية قد تقع عند الطرف كما في 1-بيوتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('mcq', 7, 1, 'السلسلة الرئيسة هي أطول سلسلة تحتوي على الرابطة الثنائية: CH₂=C ثم ذرات السلسلة الأفقية الأربع، أي ست ذرات (هكسين). نرقّم من طرف CH₂ فتأخذ الرابطة الثنائية الرقم 1، وتقع مجموعة الإيثيل على الذرة 2، فالاسم 2-إيثيل-1-هكسين.', '["رُقّمت السلسلة من الطرف الأبعد عن الرابطة الثنائية.","","اختيرت سلسلة من أربع ذرات تمر بمجموعة الإيثيل، مع أن السلسلة الأطول المحتوية على الرابطة الثنائية فيها ست ذرات.","الرابطة الثنائية بين الذرتين 1 و2، فموقعها 1 لا 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.574Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أطول سلسلة تحتوي على الرابطة الثنائية ست ذرات (هكسين). الترقيم من اليمين ومن اليسار يعطي الرابطة الثنائية الرقم 3 في الحالتين، فنختار الاتجاه الذي يعطي المجموعات البديلة أصغر الأرقام: من اليمين تقع مجموعتا الميثيل على الذرتين 2 و4، ومن اليسار على 3 و5؛ فنرقّم من اليمين. المجموعتان متماثلتان فنستعمل «ثنائي». الاسم: 2، 4-ثنائي ميثيل-3-هكسين.', '["السلسلة الرئيسة ست ذرات: هكسين","الرابطة الثنائية تأخذ الرقم 3 من الاتجاهين","الحسم بأصغر أرقام للمجموعات البديلة: 2 و4","البادئة ثنائي ميثيل","الاسم 2، 4-ثنائي ميثيل-3-هكسين"]'::jsonb, '["تحديد أطول سلسلة تحتوي على الرابطة الثنائية: 6 ذرات ← هكسين","الترقيم من اليمين: الرابطة الثنائية عند 3، والميثيل عند 2 و4","الترقيم من اليسار: الرابطة الثنائية عند 3، والميثيل عند 3 و5","التعادل في موقع الرابطة الثنائية، فنختار الترقيم الذي يعطي المجموعات البديلة الرقمين 2 و4","كتابة الاسم: 2، 4-ثنائي ميثيل-3-هكسين"]'::jsonb, '[{"element":"تحديد السلسلة الرئيسة","marks":1},{"element":"موقع الرابطة الثنائية","marks":1},{"element":"اختيار اتجاه الترقيم بالمجموعات البديلة","marks":1},{"element":"الاسم كاملًا بصيغته الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات صحيحة كاملة واسم صحيح مع تبرير اتجاه الترقيم"},{"level":"2–3 درجات","description":"اسم صحيح دون تبرير، أو خطوات صحيحة مع خطأ في الأرقام"},{"level":"1 درجة","description":"تحديد السلسلة الرئيسة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 3، 5-ثنائي ميثيل-3-هكسين بالترقيم من اليسار","إعطاء المجموعات البديلة الأولوية على الرابطة الثنائية عمومًا","نسيان البادئة «ثنائي»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السلسلة الرئيسة أربع ذرات فيها رابطة ثنائية (بيوتين). الترقيم من اليسار يعطي الرابطة الثنائية الرقم 2، ومن اليمين الرقم 2 أيضًا؛ فنختار الاتجاه الذي يعطي مجموعة الميثيل الرقم الأصغر (2 لا 3): 2-ميثيل-2-بيوتين. (ب) السلسلة أربع ذرات فيها رابطتان ثنائيتان (بيوتادايين). الرابطتان تأخذان 1 و3 من الاتجاهين، ونرقّم من اليسار لتأخذ مجموعة الميثيل الرقم 2 (لا 3): 2-ميثيل-1، 3-بيوتادايين.', '["(أ) 2-ميثيل-2-بيوتين","تبرير ترقيم (أ): تعادل موقع الرابطة فنعطي الميثيل الرقم الأصغر","(ب) 2-ميثيل-1، 3-بيوتادايين","تبرير ترقيم (ب) واستعمال البادئة «داي»"]'::jsonb, '[]'::jsonb, '[{"element":"اسم (أ)","marks":1},{"element":"تبرير (أ)","marks":1},{"element":"اسم (ب)","marks":1},{"element":"تبرير (ب) والبادئة داي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاسمان صحيحان مع تبرير الترقيم في كل منهما"},{"level":"2–3 درجات","description":"اسم صحيح مع تبريره، أو الاسمان دون تبرير"},{"level":"1 درجة","description":"اسم واحد صحيح دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (أ) 3-ميثيل-2-بيوتين","إهمال البادئة «داي» في (ب) أو كتابة «ثنائي بيوتين»","كتابة 3-ميثيل-1، 3-بيوتادايين في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاسم خاطئ لسببين: (1) اختار الطالب السلسلة الأفقية المرسومة (خمس ذرات) مع أن أطول سلسلة تحتوي على الرابطة الثنائية تمر بمجموعة الإيثيل وفيها ست ذرات، فلا توجد مجموعة إيثيل بل مجموعة ميثيل. (2) رقّم من الطرف الأبعد عن الرابطة الثنائية، فأعطاها الرقم 3 بدل 2. الصحيح: السلسلة CH₃–CH=CH–CH(CH₃)–CH₂–CH₃ ست ذرات (هكسين)، نرقّم من الطرف الأقرب إلى الرابطة الثنائية فتأخذ الرقم 2، وتقع مجموعة الميثيل على الذرة 4: 4-ميثيل-2-هكسين.', '["خطأ اختيار السلسلة: الأطول ست ذرات عبر مجموعة الإيثيل","خطأ الترقيم: الرابطة الثنائية تأخذ 2 لا 3","الاسم الصحيح 4-ميثيل-2-هكسين"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ السلسلة الرئيسة","marks":1.5},{"element":"تحديد خطأ الترقيم","marks":1.5},{"element":"الاسم الصحيح","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الخطأين مع تبريرهما وكتابة الاسم الصحيح"},{"level":"3–4 درجات","description":"الاسم الصحيح مع تحديد خطأ واحد"},{"level":"1–2 درجة","description":"تحديد خطأ واحد دون اسم صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بتصحيح الرقم وكتابة 2-إيثيل-2-بنتين","كتابة 3-ميثيل-4-هكسين بالترقيم من الطرف الأبعد","عدم ملاحظة أن السلسلة الأطول تمر بالتفرع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
