('mcq', 5, 'أيّ الصيغ الآتية تمثل المركب 2، 4-ثنائي ميثيل-2-بنتين؟', null, '[{"src":"qimg/chem22/c4-l3a-o3-four.svg","alt":"أربع صيغ بنائية مكثفة مرقمة، في كل منها سلسلة أفقية من خمس مجموعات تُقرأ من اليسار إلى اليمين. الصيغة (1): CH₂=C–CH₂–CH–CH₃ والرابطة الثنائية بين المجموعتين الأولى والثانية، ومجموعة CH₃ إلى الأعلى من المجموعة الثانية (C) وأخرى إلى الأسفل من المجموعة الرابعة (CH). الصيغة (2): CH₃–CH=C–CH–CH₃ والرابطة الثنائية بين المجموعتين الثانية والثالثة، ومجموعة CH₃ إلى الأعلى من المجموعة الثالثة (C) وأخرى إلى الأسفل من المجموعة الرابعة (CH). الصيغة (3): CH₃–C=CH–CH–CH₃ والرابطة الثنائية بين المجموعتين الثانية والثالثة، ومجموعة CH₃ إلى الأعلى من المجموعة الثانية (C) وأخرى إلى الأسفل من المجموعة الرابعة (CH). الصيغة (4): CH₃–C=CH–CH₂–CH₃ والرابطة الثنائية بين المجموعتين الثانية والثالثة، ومجموعة CH₃ واحدة فقط إلى الأعلى من المجموعة الثانية (C)."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'تطبيق', 'اختيار الصيغة المطابقة للاسم', 'متوسط', 'الكتاب ص 138–139 — تسمية الألكينات المتفرعة'),
('mcq', 6, 'رسم طالب الصيغة الآتية على أنها صيغة المركب 1، 3-بنتادايين. ما الخطأ في رسمه؟', null, '[{"src":"qimg/chem22/c4-l3a-14pentadiene.svg","alt":"صيغة بنائية مكثفة من اليسار إلى اليمين: CH₂=CH–CH₂–CH=CH₂؛ سلسلة مستقيمة من خمس ذرات كربون فيها رابطتان ثنائيتان: الأولى بين ذرتي الكربون الأولى والثانية، والثانية بين ذرتي الكربون الرابعة والخامسة، وبينهما مجموعة CH₂."}]'::jsonb, '["السلسلة خمس ذرات كربون والصحيح أن تكون أربع ذرات","الرابطة الثنائية الثانية بين الذرتين 4 و5، والصحيح أن تكون بين 3 و4","الصيغة الجزيئية للرسم تختلف عن الصيغة الصحيحة C₅H₈","كان يجب أن تبدأ الرابطتان الثنائيتان كلتاهما عند ذرة الكربون 1"]'::jsonb, 'تحليل', 'اكتشاف خطأ في صيغة', 'صعب', 'الكتاب ص 137، 162 — الألكينات ذات الرابطتين الثنائيتين (س86)'),
('mcq', 7, 'ما الصيغة الجزيئية للمركب 2، 4-ثنائي ميثيل-1-أوكتين؟', null, null, '["C₁₀H₂₂","C₈H₁₆","C₁₀H₁₈","C₁₀H₂₀"]'::jsonb, 'تطبيق', 'صيغة جزيئية من اسم متفرع', 'صعب', 'الكتاب ص 160 — س62'),
('essay', 1, 'اكتب الصيغة البنائية المكثفة والصيغة الجزيئية لكل من المركبين: (أ) 3-ميثيل-2-بنتين، (ب) 2، 3-ثنائي ميثيل-2-بيوتين.', null, null, null, 'تطبيق', 'كتابة صيغ من الاسم', 'متوسط', 'الكتاب ص 142 — س22'),
('essay', 2, 'اكتب الصيغة الجزيئية لكل من المركبين الآتيين، وصف صيغة كل منهما البنائية وصفًا دقيقًا (السلسلة أو الحلقة، وموقع الروابط الثنائية، ومواقع المجموعات البديلة): (أ) 1، 4-ثنائي إيثيل هكسين حلقي، (ب) 4-ميثيل-1، 3-بنتادايين.', null, null, null, 'تطبيق', 'كتابة صيغ من الاسم', 'صعب', 'الكتاب ص 142، 160 — س22 وس62'),
('essay', 3, 'سُمّي مركب خطأً «2-إيثيل-1-بروبين». اكتب الصيغة البنائية المكثفة التي يدل عليها هذا الاسم، ثم بيّن الخطأ في التسمية، واكتب الاسم الصحيح وصيغته الجزيئية.', null, null, null, 'تقويم', 'رسم من اسم وتقويمه', 'صعب', 'الكتاب ص 137، 162 — قواعد التسمية (س87)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
