('mcq', 1, 2, 'في 2-بيوتين سلسلة من أربع ذرات كربون، والرابطة الثنائية تبدأ عند الذرة 2، أي بين الذرتين 2 و3: CH₃CH=CHCH₃.', '["هذه صيغة 1-بيوتين؛ فالرابطة الثنائية فيها بين الذرتين 1 و2.","هذه صيغة البيوتان، وليس فيها رابطة ثنائية.","","هذه صيغة 2-بيوتاين؛ ففيها رابطة ثلاثية لا ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('mcq', 2, 1, 'المقطع «أوكت» يعني ثماني ذرات كربون، والمقطع «ين» يعني ألكينًا برابطة ثنائية واحدة صيغته CₙH₂ₙ؛ فالصيغة C₈H₁₆.', '["هذه صيغة الأوكتان؛ استُعملت الصيغة العامة للألكانات.","","هذه صيغة ألكاين (أوكتاين)؛ استُعملت CₙH₂ₙ₋₂.","جُعل عدد ذرات الهيدروجين مساويًا لعدد ذرات الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('mcq', 3, 3, 'الصيغة CH₃C(CH₃)=CHCH₃. ذرة الكربون 2 ترتبط بالذرة 1 والذرة 3 (برابطة ثنائية تُحسب رابطتين) ومجموعة الميثيل، فتكتمل روابطها الأربع ولا يبقى مكان لأي ذرة هيدروجين.', '["ثلاث ذرات هيدروجين تكون لذرة كربون طرفية (CH₃) لا لذرة الكربون 2.","هذا عدد ذرات هيدروجين ذرة كربون ترتبط بذرتي كربون برابطتين أحاديتين فقط.","لم تُحسب الرابطة الثنائية رابطتين، أو أُهملت مجموعة الميثيل المرتبطة بالذرة 2.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('mcq', 4, 0, 'السلسلة خمس ذرات (بنتين)، والرابطة الثنائية بين الذرتين 1 و2، ومجموعة الميثيل على الذرة 3: CH₂=CHCH(CH₃)CH₂CH₃.', '["","وُضعت الرابطة الثنائية بين الذرتين 2 و3، فهذه صيغة 3-ميثيل-2-بنتين.","وُضعت مجموعة الميثيل على الذرة 4، فهذه صيغة 4-ميثيل-1-بنتين.","وُضعت مجموعة الميثيل على الذرة 2، فهذه صيغة 2-ميثيل-1-بنتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('mcq', 5, 2, 'في 2، 4-ثنائي ميثيل-2-بنتين سلسلة من خمس ذرات، والرابطة الثنائية بين الذرتين 2 و3، ومجموعتا ميثيل على الذرتين 2 و4. هذا ما تمثله الصيغة (3): CH₃C(CH₃)=CHCH(CH₃)CH₃.', '["الصيغة (1) فيها الرابطة الثنائية بين الذرتين 1 و2، فهي 2، 4-ثنائي ميثيل-1-بنتين.","الصيغة (2) فيها مجموعتا الميثيل على الذرتين 3 و4، فهي 3، 4-ثنائي ميثيل-2-بنتين.","","الصيغة (4) فيها مجموعة ميثيل واحدة فقط، فهي 2-ميثيل-2-بنتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.575Z"}'::jsonb),
('mcq', 6, 1, 'الرقمان 1 و3 يعنيان أن الرابطتين الثنائيتين تبدآن عند الذرتين 1 و3، أي بين 1 و2 وبين 3 و4: CH₂=CHCH=CHCH₃. أما الرسم ففيه الرابطة الثانية بين الذرتين 4 و5، فهو 1، 4-بنتادايين.', '["المقطع «بنت» يعني خمس ذرات كربون، فطول السلسلة صحيح.","","الرسم CH₂=CHCH₂CH=CH₂ صيغته C₅H₈ أيضًا، فالخطأ في موقع الرابطة لا في الصيغة الجزيئية.","الرقمان 1 و3 يدلان على ذرتين مختلفتين تبدأ عند كل منهما رابطة ثنائية، لا على ذرة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.576Z"}'::jsonb),
('mcq', 7, 3, 'السلسلة الرئيسة ثماني ذرات كربون ومجموعتا الميثيل تضيفان ذرتين، فعدد ذرات الكربون 10. المركب ألكين برابطة ثنائية واحدة صيغته CₙH₂ₙ، فالصيغة C₁₀H₂₀ (الصيغة المكثفة CH₂=C(CH₃)CH₂CH(CH₃)CH₂CH₂CH₂CH₃).', '["استُعملت الصيغة العامة للألكانات CₙH₂ₙ₊₂.","أُهملت ذرتا كربون مجموعتي الميثيل، فهذه صيغة الأوكتين غير المتفرع.","استُعملت الصيغة العامة للألكاينات CₙH₂ₙ₋₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-07T17:19:00.576Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) سلسلة خمس ذرات، والرابطة الثنائية بين 2 و3، والميثيل على الذرة 3: CH₃CH=C(CH₃)CH₂CH₃، وصيغته الجزيئية C₆H₁₂. (ب) سلسلة أربع ذرات، والرابطة الثنائية بين 2 و3، ومجموعتا ميثيل على الذرتين 2 و3: CH₃C(CH₃)=C(CH₃)CH₃، وصيغته الجزيئية C₆H₁₂.', '["(أ) CH₃CH=C(CH₃)CH₂CH₃","(أ) C₆H₁₂","(ب) CH₃C(CH₃)=C(CH₃)CH₃","(ب) C₆H₁₂"]'::jsonb, '["(أ) نرسم 5 ذرات كربون، ونضع الرابطة الثنائية بين C2 وC3، ونضيف CH₃ على C3، ثم نكمل كل ذرة بالهيدروجين حتى أربع روابط","(أ) عدد C = 6 ، عدد H = 12","(ب) نرسم 4 ذرات، ونضع الرابطة الثنائية بين C2 وC3، ونضيف CH₃ على كل منهما","(ب) عدد C = 6 ، عدد H = 12"]'::jsonb, '[{"element":"الصيغة المكثفة لـ(أ)","marks":1},{"element":"الصيغة الجزيئية لـ(أ)","marks":1},{"element":"الصيغة المكثفة لـ(ب)","marks":1},{"element":"الصيغة الجزيئية لـ(ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغ الأربع صحيحة"},{"level":"2–3 درجات","description":"صيغتان أو ثلاث صحيحة"},{"level":"1 درجة","description":"صيغة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الرابطة الثنائية بين الذرتين 3 و4 في (أ)","ترك ذرة هيدروجين على ذرة كربون مرتبطة بأربع روابط","إهمال ذرات كربون مجموعات الميثيل عند كتابة الصيغة الجزيئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.576Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) حلقة سداسية من ست ذرات كربون فيها رابطة ثنائية بين الذرتين 1 و2، وترتبط مجموعة إيثيل (–CH₂CH₃) بالذرة 1 وأخرى بالذرة 4. الهكسين الحلقي C₆H₁₀، وكل مجموعة إيثيل تحل محل ذرة هيدروجين وتضيف C₂H₄، فالصيغة C₁₀H₁₈. (ب) سلسلة خمس ذرات فيها رابطتان ثنائيتان بين 1 و2 وبين 3 و4، ومجموعة ميثيل على الذرة 4: CH₂=CHCH=C(CH₃)CH₃، وصيغته الجزيئية C₆H₁₀.', '["(أ) حلقة سداسية برابطة ثنائية بين 1 و2","(أ) مجموعتا إيثيل على 1 و4","(أ) C₁₀H₁₈","(ب) CH₂=CHCH=C(CH₃)CH₃","(ب) C₆H₁₀"]'::jsonb, '["(أ) الهكسين الحلقي C₆H₁₀؛ إضافة مجموعتي إيثيل: C = 6 + 4 = 10 ، H = 10 − 2 + 10 = 18 ← C₁₀H₁₈","(ب) عدد C = 5 + 1 = 6 ، وبعدّ الهيدروجين في CH₂=CHCH=C(CH₃)CH₃: 2 + 1 + 1 + 3 + 3 = 10 ← C₆H₁₀"]'::jsonb, '[{"element":"بناء (أ)","marks":1.5},{"element":"صيغة (أ) الجزيئية","marks":1},{"element":"بناء (ب)","marks":1.5},{"element":"صيغة (ب) الجزيئية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف البناءين صحيح والصيغتان الجزيئيتان صحيحتان"},{"level":"3–4 درجات","description":"بناء صحيح مع خطأ في إحدى الصيغتين أو نقص في الوصف"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مجموعة الإيثيل الثانية على الذرة 3 أو 5","استعمال CₙH₂ₙ للألكين الحلقي ثنائي الإيثيل (C₁₀H₂₀)","وضع الرابطة الثنائية الثانية في (ب) بين الذرتين 4 و5"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.576Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يدل الاسم على سلسلة بروبين CH₂=C–CH₃ ترتبط بذرتها الثانية مجموعة إيثيل: CH₂=C(CH₂CH₃)CH₃. الخطأ أن السلسلة المختارة ليست أطول سلسلة تحتوي على الرابطة الثنائية؛ فمجموعة الإيثيل تطيل السلسلة إلى أربع ذرات: CH₂=C(CH₃)CH₂CH₃. نرقّم من الطرف الأقرب إلى الرابطة الثنائية فتأخذ الرقم 1، وتقع مجموعة الميثيل على الذرة 2، فالاسم الصحيح 2-ميثيل-1-بيوتين، وصيغته الجزيئية C₅H₁₀.', '["الصيغة CH₂=C(CH₂CH₃)CH₃","الخطأ: لم تُختر أطول سلسلة تحتوي على الرابطة الثنائية","الاسم الصحيح 2-ميثيل-1-بيوتين","الصيغة الجزيئية C₅H₁₀"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة الصيغة","marks":1},{"element":"تحديد الخطأ","marks":1},{"element":"الاسم الصحيح","marks":1},{"element":"الصيغة الجزيئية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"صيغة صحيحة وتحديد الخطأ واسم صحيح وصيغة جزيئية صحيحة"},{"level":"2–3 درجات","description":"صيغة صحيحة مع اسم صحيح دون تفسير، أو تفسير دون اسم"},{"level":"1 درجة","description":"كتابة الصيغة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الاسم لأن الصيغة تُرسم منه","تسمية المركب 3-ميثيل-1-بيوتين","كتابة الصيغة الجزيئية C₅H₁₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.576Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
